'use client';

import React, { useLayoutEffect, useRef, useState } from 'react';
import { Progress } from 'antd';
import { formatScore } from '@/utils/bsc/rollup';

/** Shared KPI tile height and chrome (dashboard-aligned). */
export const bscKpiMetricCardHeightClass = 'h-[122px]';

export const bscKpiMetricCardBorderClass =
  'shadow-none rounded-lg border border-[#D9D9D9] bg-white px-3 pt-3 pb-5';

/** Vertical metric tile (Recent Score, roll-ups). */
export const bscKpiMetricCardShellClass = `flex ${bscKpiMetricCardHeightClass} flex-none flex-col gap-4 ${bscKpiMetricCardBorderClass}`;

/** Horizontal summary tile (KPI name + donut). */
export const bscKpiSummaryCardShellClass = `flex ${bscKpiMetricCardHeightClass} min-w-0 flex-1 flex-none items-center gap-3 ${bscKpiMetricCardBorderClass}`;

const kpiIcon = (
  <svg
    data-cy="bsckpimetriccard-svg-20"
    xmlns="http://www.w3.org/2000/svg"
    height="24px"
    viewBox="0 -960 960 960"
    width="24px"
    fill="#1677FF"
    aria-hidden
  >
    <path
      data-cy="bsckpimetriccard-path-28"
      d="M160-160v-320h160v320H160Zm240 0v-560h160v560H400Zm240 0v-200h160v200H640Z"
    />
  </svg>
);

type Props = {
  label: string;
  percent: number;
  dataCy: string;
  onClick?: () => void;
  className?: string;
};

export default function BscKpiMetricCard({
  label,
  percent,
  dataCy,
  onClick,
  className = '',
}: Props) {
  const value = Math.min(Math.max(Number(percent) || 0, 0), 100);
  const display = `${formatScore(value)}%`;
  const clickable = Boolean(onClick);

  const shellClass = `${bscKpiMetricCardShellClass} ${className} ${
    clickable ? 'cursor-pointer text-left' : 'cursor-default'
  }`;

  const content = (
    <>
      <div
        className="flex items-center justify-between"
        data-cy={`${dataCy}-header`}
      >
        <div
          className="flex h-[34px] w-[34px] items-center justify-center rounded-[4px] bg-[#E6F4FF]"
          data-cy={`${dataCy}-icon`}
        >
          {kpiIcon}
        </div>
        <div
          className="font-semibold text-[27px] leading-7 tracking-normal text-gray-900"
          data-cy={`${dataCy}-value`}
        >
          {display}
        </div>
      </div>
      <div className="mt-3 flex flex-col" data-cy={`${dataCy}-body`}>
        <div
          className="w-full text-start text-base font-normal text-gray-500"
          data-cy={`${dataCy}-label`}
        >
          {label}
        </div>
        <div className="flex items-center gap-2" data-cy={`${dataCy}-progress`}>
          <Progress
            size="small"
            percent={value}
            showInfo={false}
            strokeColor="#1f4fd8"
            trailColor="#e5e7eb"
            className="!m-0 w-full [&_.ant-progress-outer]:!w-full"
          />
        </div>
      </div>
    </>
  );

  if (clickable) {
    return (
      <button
        type="button"
        onClick={onClick}
        className={shellClass}
        data-cy={dataCy}
      >
        {content}
      </button>
    );
  }

  return (
    <div className={shellClass} data-cy={dataCy}>
      {content}
    </div>
  );
}

const chipClassName =
  'm-0 inline-flex h-5 max-w-[148px] shrink-0 truncate rounded border border-[#91caff] bg-[#e6f4ff] px-1.5 text-[11px] font-normal leading-5 text-[#1677ff]';

type OverflowChipRowProps = {
  items: string[];
  onViewMore?: () => void;
  dataCy: string;
};

function OverflowChipRow({ items, onViewMore, dataCy }: OverflowChipRowProps) {
  const visibleRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  const moreMeasureRef = useRef<HTMLButtonElement>(null);
  const [visibleCount, setVisibleCount] = useState(items.length);

  useLayoutEffect(() => {
    const visible = visibleRef.current;
    const measure = measureRef.current;
    if (!visible || !measure) return;

    const update = () => {
      const available = visible.clientWidth;
      const chips = Array.from(
        measure.querySelectorAll<HTMLElement>('[data-name-chip]'),
      );
      const moreWidth = moreMeasureRef.current?.offsetWidth ?? 72;
      const gap = 6;
      let used = 0;
      let count = 0;

      for (let i = 0; i < chips.length; i += 1) {
        const width = chips[i].offsetWidth;
        const isLast = i === chips.length - 1;
        const extra = isLast ? 0 : moreWidth + gap;
        const next = used + width + (count > 0 ? gap : 0) + extra;
        if (next > available) break;
        used += width + (count > 0 ? gap : 0);
        count += 1;
      }

      setVisibleCount(count);
    };

    update();
    const observer = new ResizeObserver(update);
    observer.observe(visible);
    return () => observer.disconnect();
  }, [items]);

  if (!items.length) {
    return (
      <span className="text-[12px] text-[#8F94A3]" data-cy={`${dataCy}-empty`}>
        None assigned
      </span>
    );
  }

  const hasMore = visibleCount < items.length;
  const shown = items.slice(0, Math.max(visibleCount, 0));

  return (
    <div className="relative min-w-0" data-cy={`${dataCy}-chips`}>
      <div
        ref={measureRef}
        className="pointer-events-none invisible absolute left-0 top-0 flex h-5 items-center gap-1.5 whitespace-nowrap"
        aria-hidden
      >
        {items.map((item, index) => (
          <span
            key={`${item}-${index}`}
            data-name-chip
            className={chipClassName}
          >
            {item}
          </span>
        ))}
        <button
          ref={moreMeasureRef}
          type="button"
          tabIndex={-1}
          className="shrink-0 border-none bg-transparent p-0 text-[12px] font-medium text-[#1677ff]"
        >
          View more
        </button>
      </div>
      <div
        ref={visibleRef}
        className="flex min-w-0 items-center gap-1.5 overflow-hidden"
      >
        {shown.map((item, index) => (
          <span
            key={`${item}-${index}`}
            data-name-chip
            className={chipClassName}
            title={item}
          >
            {item}
          </span>
        ))}
        {hasMore ? (
          <button
            type="button"
            onClick={onViewMore}
            className="shrink-0 cursor-pointer border-none bg-transparent p-0 text-[12px] font-medium text-[#1677ff] hover:underline"
            data-cy={`${dataCy}-view-more`}
          >
            View more
          </button>
        ) : null}
      </div>
    </div>
  );
}

type CountCardProps = {
  label: string;
  items: string[];
  dataCy: string;
  onViewMore?: () => void;
  className?: string;
};

/** Count tile matching KPI card chrome (Departments, Roles, People). */
export function BscKpiCountCard({
  label,
  items,
  dataCy,
  onViewMore,
  className = '',
}: CountCardProps) {
  return (
    <div
      className={`${bscKpiMetricCardShellClass} justify-between ${className}`}
      data-cy={dataCy}
    >
      <div
        className="flex items-center justify-between gap-2"
        data-cy={`${dataCy}-header`}
      >
        <div className="flex min-w-0 items-center gap-2">
          <div
            className="flex h-[34px] w-[34px] shrink-0 items-center justify-center rounded-[4px] bg-[#E6F4FF]"
            data-cy={`${dataCy}-icon`}
          >
            {kpiIcon}
          </div>
          <span
            className="truncate text-base font-normal text-gray-500"
            data-cy={`${dataCy}-label`}
          >
            {label}
          </span>
        </div>
        <div
          className="shrink-0 font-semibold text-[27px] leading-7 tracking-normal text-gray-900"
          data-cy={`${dataCy}-value`}
        >
          {items.length}
        </div>
      </div>
      <OverflowChipRow items={items} onViewMore={onViewMore} dataCy={dataCy} />
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { Input, Tooltip } from 'antd';
import {
  CheckOutlined,
  CloseOutlined,
  EditOutlined,
  LinkOutlined,
} from '@ant-design/icons';

function dataSourceHref(value: string): string | null {
  const source = value.trim();
  if (!source) return null;
  if (/^https?:\/\//i.test(source)) return source;
  if (/^[\w.-]+\.[a-z]{2,}([/:].*)?$/i.test(source)) {
    return `https://${source}`;
  }
  return null;
}

function truncate(text: string, max = 42): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

export default function CheckinDataSourceCell({
  value,
  onChange,
  dataCy,
  disabled = false,
}: {
  value: string;
  onChange: (next: string) => void;
  dataCy: string;
  disabled?: boolean;
}) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);

  useEffect(() => {
    if (!editing) setDraft(value);
  }, [value, editing]);

  const commit = () => {
    onChange(draft.trim());
    setEditing(false);
  };

  const cancel = () => {
    setDraft(value);
    setEditing(false);
  };

  if (editing) {
    return (
      <div className="flex min-w-[240px] items-center gap-1">
        <Input
          className="h-8 flex-1 text-sm"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onPressEnter={commit}
          autoFocus
          disabled={disabled}
          data-cy={`${dataCy}-input`}
        />
        <button
          type="button"
          className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded border border-gray-200 text-[#1677ff] hover:bg-gray-50"
          onClick={commit}
          aria-label="Save data source"
          data-cy={`${dataCy}-save`}
        >
          <CheckOutlined className="text-xs" />
        </button>
        <button
          type="button"
          className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded border border-gray-200 text-gray-500 hover:bg-gray-50"
          onClick={cancel}
          aria-label="Cancel edit"
          data-cy={`${dataCy}-cancel`}
        >
          <CloseOutlined className="text-xs" />
        </button>
      </div>
    );
  }

  const trimmed = value.trim();
  const href = dataSourceHref(trimmed);

  return (
    <div className="flex min-w-0 items-center gap-1.5">
      {trimmed ? (
        href ? (
          <Tooltip title={trimmed}>
            <a
              href={href}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex min-w-0 max-w-[240px] items-center gap-1 text-sm font-medium text-[#1677ff] hover:underline"
              data-cy={`${dataCy}-link`}
            >
              <LinkOutlined className="shrink-0 text-xs" />
              <span className="truncate">{truncate(trimmed)}</span>
            </a>
          </Tooltip>
        ) : (
          <Tooltip title={trimmed}>
            <span
              className="inline-block max-w-[240px] truncate text-sm text-gray-700"
              data-cy={`${dataCy}-label`}
            >
              {truncate(trimmed)}
            </span>
          </Tooltip>
        )
      ) : (
        <span className="text-sm text-gray-400" data-cy={`${dataCy}-empty`}>
          No data source
        </span>
      )}
      {!disabled ? (
        <button
          type="button"
          className="inline-flex h-7 w-7 shrink-0 items-center justify-center rounded border border-gray-200 text-gray-600 hover:bg-gray-50"
          onClick={() => {
            setDraft(value);
            setEditing(true);
          }}
          aria-label="Edit data source"
          data-cy={`${dataCy}-edit`}
        >
          <EditOutlined className="text-xs" />
        </button>
      ) : null}
    </div>
  );
}

'use client';

import React from 'react';
import { InputNumber, Select } from 'antd';
import { TargetLogic } from '@/types/bsc';
import { KPI_DATA_SOURCE_OPTIONS } from '@/utils/bsc/measurementUnit';
import { validateAcceptableThreshold } from '@/utils/bsc/scoring';

type Props = {
  kpiKey: string;
  targetLogic: TargetLogic;
  targetValue?: number | null;
  dataSource?: string | null;
  acceptableThreshold?: number | null;
  onDataSourceChange: (value: string | null) => void;
  onThresholdChange: (value: number | null) => void;
};

export default function KpiAssignmentMetricFields({
  kpiKey,
  targetLogic,
  targetValue,
  dataSource,
  acceptableThreshold,
  onDataSourceChange,
  onThresholdChange,
}: Props) {
  const thresholdCheck =
    targetValue != null &&
    acceptableThreshold != null &&
    Number.isFinite(targetValue) &&
    Number.isFinite(acceptableThreshold)
      ? validateAcceptableThreshold(
          Number(targetValue),
          Number(acceptableThreshold),
          targetLogic,
        )
      : { valid: true as const };

  const thresholdHelper =
    targetLogic === TargetLogic.HigherBetter
      ? 'Threshold must be less than or equal to target (minimum acceptable result).'
      : targetLogic === TargetLogic.LowerBetter
        ? 'Threshold must be greater than or equal to target (maximum acceptable result).'
        : 'Only available for higher/lower KPIs.';

  return (
    <div
      className="mt-2 flex flex-wrap items-start gap-3"
      data-cy={`bsc-kpi-assignment-fields-${kpiKey}`}
    >
      <div className="flex min-w-[180px] flex-col gap-1">
        <span className="text-[11px] text-[#595959]">Data source</span>
        <Select
          className="w-[180px]"
          placeholder="Select source"
          value={dataSource ?? undefined}
          options={KPI_DATA_SOURCE_OPTIONS}
          onChange={(value) => onDataSourceChange(value || null)}
          data-cy={`bsc-kpi-assignment-data-source-${kpiKey}`}
        />
      </div>
      {(targetLogic === TargetLogic.HigherBetter ||
        targetLogic === TargetLogic.LowerBetter) && (
        <div className="flex min-w-[180px] flex-col gap-1">
          <span className="text-[11px] text-[#595959]">
            Acceptable threshold
          </span>
          <InputNumber
            className="w-[180px]"
            placeholder="Threshold"
            value={acceptableThreshold ?? undefined}
            onChange={(value) =>
              onThresholdChange(value == null ? null : Number(value))
            }
            data-cy={`bsc-kpi-assignment-threshold-${kpiKey}`}
          />
          <span
            className={`text-[11px] ${thresholdCheck.valid ? 'text-[#8F94A3]' : 'text-[#CF1322]'}`}
          >
            {!thresholdCheck.valid ? thresholdCheck.message : thresholdHelper}
          </span>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useCallback, useMemo, useState } from 'react';
import { Button, Modal, Table, Tag, Upload } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  CloseOutlined,
  DownloadOutlined,
  InboxOutlined,
} from '@ant-design/icons';
import NotificationMessage from '@/components/common/notification/notificationMessage';
import CustomButton from '@/components/common/buttons/customButton';
import { useBscUiStore } from '@/store/uistate/features/bsc';
import { useImportBscKpis } from '@/store/server/features/bsc/mutation';
import { useGetBscCycles } from '@/store/server/features/bsc/queries';
import { CycleStatus, KpiImportRowResult } from '@/types/bsc';
import {
  buildKpiImportTemplateBuffer,
  parseKpiImportFile,
} from '@/utils/bsc/kpiImport';

function pickUploadFile(fileField: unknown): File | undefined {
  const raw = fileField as
    | { file?: { originFileObj?: File }; originFileObj?: File }
    | Array<{ originFileObj?: File }>
    | undefined;
  if (!raw) return undefined;
  if (Array.isArray(raw)) return raw[0]?.originFileObj;
  return raw.file?.originFileObj ?? raw.originFileObj;
}

export default function KpiImportModal() {
  const { kpiImportModalOpen, closeKpiImportModal } = useBscUiStore();
  const { data: configs } = useGetBscCycles();
  const importKpis = useImportBscKpis();
  const [file, setFile] = useState<File | undefined>();
  const [parsedRows, setParsedRows] = useState<KpiImportRowResult[]>([]);
  const [downloadLoading, setDownloadLoading] = useState(false);
  const [parseLoading, setParseLoading] = useState(false);

  const evaluationConfigId = useMemo(() => {
    const openConfig = (configs || []).find(
      (c) => c.status === CycleStatus.Open,
    );
    return openConfig?.id || configs?.[0]?.id || 'library';
  }, [configs]);

  const validRows = parsedRows.filter((row) => row.input);
  const invalidRows = parsedRows.filter((row) => row.error);

  const previewColumns: ColumnsType<KpiImportRowResult> = [
    { title: 'Row', dataIndex: 'row', width: 70 },
    {
      title: 'Status',
      key: 'status',
      width: 110,
      render: (_, row) =>
        row.error ? (
          <Tag color="red">Invalid</Tag>
        ) : (
          <Tag color="green">Valid</Tag>
        ),
    },
    {
      title: 'Name',
      key: 'name',
      render: (_, row) => row.input?.name || '—',
    },
    {
      title: 'Perspective',
      key: 'perspective',
      render: (_, row) => row.input?.perspective || '—',
    },
    {
      title: 'Details',
      key: 'details',
      render: (_, row) => row.error || row.input?.measurementUnit || '—',
    },
  ];

  const reset = useCallback(() => {
    setFile(undefined);
    setParsedRows([]);
  }, []);

  const handleClose = () => {
    reset();
    closeKpiImportModal();
  };

  const handleDownloadTemplate = async () => {
    setDownloadLoading(true);
    try {
      const buffer = await buildKpiImportTemplateBuffer();
      const blob = new Blob([buffer], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'kpi-import-template.xlsx';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      NotificationMessage.success({ message: 'Template downloaded' });
    } catch {
      NotificationMessage.error({ message: 'Failed to download template' });
    } finally {
      setDownloadLoading(false);
    }
  };

  const handleParse = async (nextFile?: File) => {
    const upload = nextFile || file;
    if (!upload) {
      NotificationMessage.error({ message: 'Upload an Excel file first' });
      return;
    }
    setParseLoading(true);
    try {
      const rows = await parseKpiImportFile(upload);
      setParsedRows(rows);
      if (!rows.length) {
        NotificationMessage.warning({ message: 'No rows found in the file' });
      }
    } catch {
      NotificationMessage.error({ message: 'Could not read the Excel file' });
    } finally {
      setParseLoading(false);
    }
  };

  const handleImport = async () => {
    if (!validRows.length) {
      NotificationMessage.error({ message: 'No valid rows to import' });
      return;
    }
    await importKpis.mutateAsync({
      rows: validRows.map((row) => row.input!),
      evaluationConfigId,
    });
    handleClose();
  };

  return (
    <Modal
      open={kpiImportModalOpen}
      onCancel={handleClose}
      footer={null}
      width={760}
      centered
      destroyOnClose
      closeIcon={<CloseOutlined />}
      title="Import KPIs"
      data-cy="bsc-kpi-import-modal"
    >
      <div className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center gap-2">
          <Button
            icon={<DownloadOutlined />}
            loading={downloadLoading}
            onClick={handleDownloadTemplate}
            data-cy="bsc-kpi-import-download-template"
          >
            Download template
          </Button>
        </div>

        <Upload.Dragger
          accept=".xlsx,.xls"
          maxCount={1}
          beforeUpload={(uploadFile) => {
            setFile(uploadFile);
            void handleParse(uploadFile);
            return false;
          }}
          onRemove={() => {
            reset();
          }}
          fileList={
            file ? [{ uid: '1', name: file.name, status: 'done' as const }] : []
          }
          data-cy="bsc-kpi-import-upload"
        >
          <p className="ant-upload-drag-icon">
            <InboxOutlined />
          </p>
          <p className="ant-upload-text">Click or drag Excel file to upload</p>
          <p className="ant-upload-hint">
            Use the template format. Valid and invalid rows will be previewed
            before import.
          </p>
        </Upload.Dragger>

        {parsedRows.length ? (
          <>
            <div className="flex flex-wrap gap-3 text-sm text-gray-600">
              <span data-cy="bsc-kpi-import-valid-count">
                Valid: {validRows.length}
              </span>
              <span data-cy="bsc-kpi-import-invalid-count">
                Invalid: {invalidRows.length}
              </span>
            </div>
            <Table
              size="small"
              rowKey={(row) => `${row.row}-${row.input?.name || row.error}`}
              columns={previewColumns}
              dataSource={parsedRows}
              pagination={{ pageSize: 5, hideOnSinglePage: true }}
              scroll={{ x: true }}
              data-cy="bsc-kpi-import-preview-table"
            />
          </>
        ) : null}

        <div className="flex justify-end gap-2">
          <CustomButton
            type="default"
            title="Cancel"
            onClick={handleClose}
            className="h-10 px-6 rounded-lg bg-white"
            textClassName="text-sm font-medium"
            data-cy="bsc-kpi-import-cancel"
          />
          <CustomButton
            type="primary"
            title="Import"
            loading={importKpis.isLoading || parseLoading}
            disabled={!validRows.length}
            onClick={handleImport}
            data-cy="bsc-kpi-import-confirm"
          />
        </div>
      </div>
    </Modal>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { Input, Modal } from 'antd';
import CustomButton from '@/components/common/buttons/customButton';

const { TextArea } = Input;

export type KpiRejectModalMode = 'default' | 'pep-reject' | 'pep-unrealistic';

type Props = {
  open: boolean;
  kpiName?: string;
  loading?: boolean;
  mode?: KpiRejectModalMode;
  onClose: () => void;
  onConfirm: (comment: string) => void;
};

const COPY: Record<
  KpiRejectModalMode,
  {
    title: string;
    body: (name?: string) => string;
    placeholder: string;
    confirm: string;
  }
> = {
  default: {
    title: 'Reject & return KPI result',
    body: (name) =>
      name
        ? `Reject the reported result for ${name}. The employee will need to resubmit.`
        : 'Reject this reported KPI result. The employee will need to resubmit.',
    placeholder: 'Explain why this result is being returned',
    confirm: 'Reject & return',
  },
  'pep-reject': {
    title: 'Reject KPI result',
    body: (name) =>
      name
        ? `Reject ${name} and reset progress to zero. The employee must re-report from scratch.`
        : 'Reject this KPI and reset progress to zero. The employee must re-report from scratch.',
    placeholder: 'Explain why this result is being rejected',
    confirm: 'Reject & reset',
  },
  'pep-unrealistic': {
    title: 'Return as unrealistic',
    body: (name) =>
      name
        ? `Return ${name} to the manager for revision. Your comment will appear on their Check-in queue.`
        : 'Return this KPI to the manager for revision. Your comment will appear on their Check-in queue.',
    placeholder: 'Explain why this result is unrealistic',
    confirm: 'Return to manager',
  },
};

export default function KpiRejectModal({
  open,
  kpiName,
  loading,
  mode = 'default',
  onClose,
  onConfirm,
}: Props) {
  const [comment, setComment] = useState('');
  const copy = COPY[mode];

  useEffect(() => {
    if (!open) setComment('');
  }, [open]);

  return (
    <Modal
      open={open}
      onCancel={onClose}
      footer={null}
      centered
      destroyOnClose
      title={copy.title}
      data-cy="bsc-kpi-reject-modal"
    >
      <p className="mb-3 text-sm text-gray-600">{copy.body(kpiName)}</p>
      <TextArea
        rows={4}
        value={comment}
        onChange={(e) => setComment(e.target.value)}
        placeholder={copy.placeholder}
        data-cy="bsc-kpi-reject-comment"
      />
      <div className="mt-4 flex justify-end gap-2">
        <CustomButton
          type="default"
          onClick={onClose}
          title="Cancel"
          className="h-10 px-6 rounded-lg bg-white"
          textClassName="text-sm font-medium"
          data-cy="bsc-kpi-reject-cancel"
        />
        <CustomButton
          type="primary"
          title={copy.confirm}
          loading={loading}
          disabled={!comment.trim()}
          onClick={() => onConfirm(comment.trim())}
          data-cy="bsc-kpi-reject-confirm"
        />
      </div>
    </Modal>
  );
}

'use client';

import React from 'react';
import { Avatar, Tooltip } from 'antd';
import { CheckOutlined, CloseOutlined, UserOutlined } from '@ant-design/icons';
import { PepAuditRow } from '@/types/bsc';
import {
  resolveAggregatePepWorkflowSteps,
  resolvePepWorkflowSteps,
  type PepWorkflowStepState,
} from '@/utils/bsc/pepAuditWorkflow';

type StepDisplayStatus = 'Approved' | 'Pending' | 'Rejected' | 'Waiting';

export type PepAuditStepParticipant = {
  name: string;
  profileImage?: string | null;
};

export type PepAuditBarParticipants = {
  reporter: PepAuditStepParticipant;
  manager: PepAuditStepParticipant;
  pep: PepAuditStepParticipant;
};

const STATUS_LABEL: Record<StepDisplayStatus, string> = {
  Approved: 'Approved',
  Pending: 'Pending',
  Rejected: 'Rejected',
  Waiting: 'Waiting',
};

function mapStepState(state: PepWorkflowStepState): StepDisplayStatus {
  if (state === 'done') return 'Approved';
  if (state === 'active') return 'Pending';
  if (state === 'rejected') return 'Rejected';
  return 'Waiting';
}

function participantInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return '?';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}

function PepApprovalStepItem({
  participant,
  status,
  roleLabel,
  dataCy,
}: {
  participant: PepAuditStepParticipant;
  status: StepDisplayStatus;
  roleLabel: string;
  dataCy: string;
}) {
  const isApproved = status === 'Approved';
  const isPending = status === 'Pending';
  const isRejected = status === 'Rejected';
  const isWaiting = status === 'Waiting';

  let circleClass = 'border-[#D9D9D9] bg-[#FAFAFA] text-gray-400';
  if (isApproved) {
    circleClass = 'border-[#16A34A] bg-[#F6FFED] text-[#16A34A]';
  } else if (isPending) {
    circleClass = 'border-[#1677ff] bg-[#E6F4FF] text-[#1677ff]';
  } else if (isRejected) {
    circleClass = 'border-[#DC2626] bg-[#FFF2F0] text-[#DC2626]';
  }

  const displayName = participant.name.trim() || '—';
  const statusColor = isApproved
    ? 'text-[#16A34A]'
    : isPending
      ? 'text-[#1677ff]'
      : isRejected
        ? 'text-[#DC2626]'
        : 'text-gray-400';

  return (
    <Tooltip title={`${roleLabel}: ${displayName} · ${STATUS_LABEL[status]}`}>
      <div
        className="flex w-[72px] shrink-0 flex-col items-center gap-0.5 text-center"
        data-cy={dataCy}
      >
        <div
          className={`flex h-7 w-7 shrink-0 items-center justify-center overflow-hidden rounded-full border-2 ${circleClass}`}
          data-cy={`${dataCy}-circle`}
        >
          {isApproved ? (
            <CheckOutlined className="text-xs font-bold" />
          ) : isRejected ? (
            <CloseOutlined className="text-[10px]" />
          ) : participant.profileImage ? (
            <Avatar
              size={24}
              src={participant.profileImage}
              icon={<UserOutlined />}
              className="border-0 bg-transparent"
            />
          ) : isPending ? (
            <span className="text-[9px] font-semibold leading-none">
              {participantInitials(displayName)}
            </span>
          ) : (
            <UserOutlined className="text-[10px]" />
          )}
        </div>
        <p
          className={`m-0 w-full truncate text-[10px] leading-tight ${
            isWaiting ? 'text-gray-400' : 'font-medium text-gray-800'
          }`}
          title={displayName}
          data-cy={`${dataCy}-name`}
        >
          {displayName}
        </p>
        <span
          className={`text-[9px] leading-none ${statusColor}`}
          data-cy={`${dataCy}-status`}
        >
          {STATUS_LABEL[status]}
        </span>
      </div>
    </Tooltip>
  );
}

function PepApprovalConnector({
  active,
  rejected,
  dataCy,
}: {
  active: boolean;
  rejected: boolean;
  dataCy: string;
}) {
  const color = rejected ? '#DC2626' : active ? '#16A34A' : '#D9D9D9';
  return (
    <div
      className="mx-1 h-px min-w-[8px] flex-1 self-center"
      style={{ backgroundColor: color }}
      data-cy={dataCy}
    />
  );
}

type BarProps = {
  steps: [PepWorkflowStepState, PepWorkflowStepState, PepWorkflowStepState];
  participants: PepAuditBarParticipants;
  dataCy?: string;
  className?: string;
};

export function PepAuditApprovalStatusBar({
  steps,
  participants,
  dataCy = 'bsc-pep-audit-approval-bar',
  className = '',
}: BarProps) {
  const displayStatuses = steps.map(mapStepState);
  const stepParticipants = [
    participants.reporter,
    participants.manager,
    participants.pep,
  ] as const;
  const roleLabels = ['Employee', 'Manager', 'PEP'] as const;

  return (
    <div
      className={`flex w-full min-w-0 items-center ${className}`}
      data-cy={dataCy}
    >
      <div
        className="flex w-full min-w-0 items-center"
        data-cy={`${dataCy}-levels`}
      >
        {stepParticipants.map((participant, idx) => {
          const status = displayStatuses[idx];
          const previousStatus = idx > 0 ? displayStatuses[idx - 1] : null;
          const connectorActive =
            previousStatus === 'Approved' && status !== 'Waiting';
          const connectorRejected =
            previousStatus === 'Rejected' || status === 'Rejected';

          return (
            <React.Fragment key={`${participant.name}-${idx}`}>
              {idx > 0 ? (
                <PepApprovalConnector
                  active={connectorActive}
                  rejected={connectorRejected}
                  dataCy={`${dataCy}-connector-${idx}`}
                />
              ) : null}
              <PepApprovalStepItem
                participant={participant}
                status={status}
                roleLabel={roleLabels[idx]}
                dataCy={`${dataCy}-step-${idx}`}
              />
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
}

function defaultParticipantsFromRow(row: PepAuditRow): PepAuditBarParticipants {
  return {
    reporter: { name: row.employeeName || 'Employee' },
    manager: { name: 'Manager' },
    pep: { name: 'PEP' },
  };
}

type SingleRowProps = {
  row: PepAuditRow;
  participants?: Partial<PepAuditBarParticipants>;
  dataCy?: string;
  className?: string;
};

export function PepAuditApprovalStatusBarForRow({
  row,
  participants,
  dataCy,
  className,
}: SingleRowProps) {
  const steps = resolvePepWorkflowSteps(row);
  const defaults = defaultParticipantsFromRow(row);
  return (
    <PepAuditApprovalStatusBar
      steps={steps}
      participants={{
        reporter: participants?.reporter ?? defaults.reporter,
        manager: participants?.manager ?? defaults.manager,
        pep: participants?.pep ?? defaults.pep,
      }}
      dataCy={dataCy}
      className={className}
    />
  );
}

type AggregateProps = {
  rows: PepAuditRow[];
  participants: PepAuditBarParticipants;
  dataCy?: string;
  className?: string;
};

export function PepAuditApprovalStatusBarAggregate({
  rows,
  participants,
  dataCy = 'bsc-results-approval-bar',
  className,
}: AggregateProps) {
  if (!rows.length) {
    return <span className="text-sm text-gray-400">—</span>;
  }
  const steps = resolveAggregatePepWorkflowSteps(rows);
  return (
    <PepAuditApprovalStatusBar
      steps={steps}
      participants={participants}
      dataCy={dataCy}
      className={className}
    />
  );
}

