            className="border-t border-gray-200 px-3 py-6 text-center text-sm text-gray-400 sm:px-6"
            data-cy={`bsc-perspective-kpi-empty-${slug}`}
          >
            No KPIs assigned yet
          </div>
        )}
      </div>
    </div>
  );
}

