            overflowY: 'auto',
          },
          footer: { borderTop: 'none' },
        }}
      >
        <Spin
          spinning={isSubmitting}
          data-cy="compensation-settings-benefit-sidebar-loading"
        >
          <div
            className="rounded-lg border border-solid border-[#D9D9D9] bg-white px-6 py-5"
