                      >
                        Rate
                      </Radio>
                    </Radio.Group>
                  </Form.Item>
                  {hasSelectedBenefitRateMode && (
                    <div
                      id="compensation-settings-benefit-sidebar-amount-container"
                      data-cy="compensation-settings-benefit-sidebar-amount-container"
                      className="w-full"
