                  )}
                  <Form.Item
                    name="isAllEmployee"
                    id="compensation-settings-benefit-sidebar-all-employee-item"
                    data-cy="compensation-settings-benefit-sidebar-all-employee-item"
                    label="All Employees are entitled"
