import AccessGuard from '@/utils/permissionGuard';
import { Permissions } from '@/types/commons/permissionEnum';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import dayjs from 'dayjs';
import { LuPencil } from 'react-icons/lu';
import { UserOutlined } from '@ant-design/icons';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import { validateEmail } from '@/utils/validation';
import { useUpdateEmployeeEmail } from '@/store/server/features/employees/employeeManagment/mutations';

const { Dragger } = Upload;

function formatServiceYear(joinedDate: string | null | undefined): string {
  if (!joinedDate) return '-';
  const start = dayjs(joinedDate);
  const now = dayjs();
  const years = now.diff(start, 'year');
  const months = now.diff(start.add(years, 'year'), 'month');
  if (years === 0) return `${months} month${months !== 1 ? 's' : ''}`;
  return `${years} year${years !== 1 ? 's' : ''}, ${months} month${months !== 1 ? 's' : ''}`;
}

function formatAddress(
  addresses: Record<string, unknown> | null | undefined,
): string {
  if (!addresses || typeof addresses !== 'object') return '-';
  const parts = [
    (addresses as any).subCity,
    (addresses as any).city,
    (addresses as any).country,
  ].filter(Boolean);
  return parts.length ? parts.join(' ') : '-';
}

function BasicInfo({ id }: { id: string }) {
  const { isLoading, data: employeeData } = useGetEmployee(id);
  const { profileFileList, setProfileFileList } = useEmployeeManagementStore();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newEmail, setNewEmail] = useState('');
  const { userId } = useAuthenticationStore();
  const queryClient = useQueryClient();
  const [isProfileDeleted, setIsProfileDeleted] = useState(false);

  const { mutate: updateProfileImage, isLoading: isUploading } =
    useUpdateProfileImage();

  const { mutate: updateEmployeeEmail, isLoading: isUpdatingEmail } =
    useUpdateEmployeeEmail();

  const { mutate: deleteProfileImage, isLoading: isDeleting } =
    useDeleteProfileImage();

  const buildExistingProfileFileList = (): UploadFile[] => {
    if (isProfileDeleted || !employeeData?.profileImage) return [];

    return [
      {
        uid: 'existing-profile-image',
        name: 'profile-image',
        status: 'done',
        url: employeeData.profileImage,
      },
    ];
  };

  const showModal = () => {
    setNewEmail(employeeData?.email ?? '');
    setProfileFileList(buildExistingProfileFileList());
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setNewEmail('');
    setProfileFileList([]);
  };

  const getEmailChangeContinueUrl = () =>
    `${window.location.origin}/authentication/login`;

  const requestEmailChange = (onComplete?: () => void) => {
    const trimmedEmail = newEmail.trim().toLowerCase();
    const emailError = validateEmail(trimmedEmail);

    if (emailError) {
      message.error(emailError);
      return;
    }

    updateEmployeeEmail(
      {
        userId: id,
        values: {
          newEmail: trimmedEmail,
          continueUrl: getEmailChangeContinueUrl(),
        },
      },
      {
        onSuccess: () => {
          onComplete?.();
        },
      },
    );
  };

  const handleSaveChange = () => {
    const hasNewImage = profileFileList.some((file: UploadFile) =>
      Boolean(file.originFileObj),
    );
    const trimmedEmail = newEmail.trim().toLowerCase();
    const currentEmail = (employeeData?.email ?? '').trim().toLowerCase();
    const hasEmailChange =
      Boolean(trimmedEmail) && trimmedEmail !== currentEmail;

    if (!hasNewImage && !hasEmailChange) {
      handleCloseModal();
      return;
    }

    const finishSave = () => {
      handleCloseModal();
    };

    if (hasNewImage) {
      const newImageFile = profileFileList.find(
        (file: UploadFile) => file.originFileObj,
      );
      const formData = new FormData();
      const file = newImageFile?.originFileObj as RcFile;
      formData.append('profileImage', file);

      updateProfileImage(
        { id, formData },
        {
          onSuccess: () => {
            message.success(
              'Your profile image has been successfully updated.',
            );
            setIsProfileDeleted(false);
            const previewUrl = getImageUrl([
              { ...(newImageFile as any) } as UploadFile,
            ]);
            if (previewUrl) {
              queryClient.setQueryData(['employee', id], (oldData: any) => {
                if (!oldData) return oldData;
                return { ...oldData, profileImage: previewUrl };
              });
              if (userId) {
                queryClient.setQueryData(
                  ['employee', userId],
                  (oldData: any) => {
                    if (!oldData) return oldData;
                    return { ...oldData, profileImage: previewUrl };
                  },
                );
              }
            }

            if (hasEmailChange) {
              requestEmailChange(finishSave);
              return;
            }

            finishSave();
          },
          onError: () => {
            message.error(
              'Failed to update the profile image. Please try again.',
            );
          },
        },
      );
      return;
    }

    if (hasEmailChange) {
      requestEmailChange(finishSave);
    }
  };

  const handleDeleteProfileImage = () => {
    Modal.confirm({
      title: 'Delete Profile Picture',
      content: 'Are you sure you want to delete your profile picture?',
      okText: 'Delete',
      okType: 'danger',
      cancelText: 'Cancel',
      onOk() {
        deleteProfileImage(
          { id },
          {
            onSuccess: () => {
              message.success(
                'Your profile image has been successfully deleted.',
              );
              setProfileFileList([]);
              setIsProfileDeleted(true);
              queryClient.setQueryData(['employee', id], (oldData: any) => {
                if (!oldData) return oldData;
                return { ...oldData, profileImage: null };
              });
              if (userId) {
                queryClient.setQueryData(
                  ['employee', userId],
                  (oldData: any) => {
                    if (!oldData) return oldData;
                    return { ...oldData, profileImage: null };
                  },
                );
              }
            },
            onError: () => {
              message.error(
                'Failed to delete the profile image. Please try again.',
              );
            },
          },
        );
      },
    });
  };

  const beforeProfileUpload = (file: RcFile): boolean => {
    const isImage = file.type.startsWith('image/');
    if (!isImage) {
      message.error('You can only upload image files!');
      return false;
    }
    return false;
  };

  const handleProfileChange = (info: {
    file: UploadFile;
    fileList: UploadFile[];
  }) => {
    setProfileFileList(info.fileList.slice(-1));
  };

  const handleProfileRemove = (file: UploadFile) => {
    const updatedFileList = profileFileList.filter(
      (item: any) => item.uid !== file.uid,
    );
    setProfileFileList(updatedFileList);
  };

  const getImageUrl = (fileList: UploadFile[]): string => {
    if (fileList.length > 0) {
      const imageFile = fileList[0];
      return (
        imageFile?.url ||
        imageFile?.thumbUrl ||
        URL.createObjectURL(imageFile.originFileObj as RcFile) ||
        ''
      );
    }
    return '';
  };

  const getDisplayImageUrl = (): string => {
    const preview = getImageUrl(profileFileList);
    if (preview) return preview;
    // When there is no profile image, don't pass a broken/default src.
    // Let Ant Design Avatar render the `icon` fallback.
    if (isProfileDeleted || !employeeData?.profileImage) return '';
    return employeeData?.profileImage as string;
  };

  const isDefaultAvatar =
    !getImageUrl(profileFileList) &&
    (isProfileDeleted || !employeeData?.profileImage);

  const hasAccess = AccessGuard.checkAccess({
    permissions: [Permissions.ChangeManagerProfile],
  });

  const activeJob = employeeData?.employeeJobInformation?.find(
    (e: any) => e.isPositionActive === true,
  );
  const isActive = !employeeData?.deletedAt;
  const joinedDate = employeeData?.employeeInformation?.joinedDate;
  const addresses = employeeData?.employeeInformation?.addresses;
  const officeName = activeJob?.branch?.name || '-';

  return (
    <Card
      loading={isLoading}
      className="mb-3 rounded-lg bg-[#F9FAFB]"
      id="basic-info-card"
      data-cy="basic-info-card"
    >
      {/* Top section: Avatar | Name + Email | Status + Edit */}
      <div
        className="flex flex-wrap gap-4 items-start mb-6"
        id="basic-info-content"
        data-cy="basic-info-content"
      >
        {/* Profile Image Section */}
        <div
          className="relative shrink-0"
          id="basic-info-avatar-wrapper"
          data-cy="basic-info-avatar-wrapper"
        >
          <Avatar
            size={48}
            src={getDisplayImageUrl() || undefined}
            className="relative z-0"
            data-cy="basic-info-avatar"
            icon={<UserOutlined />}
          />
          {userId === id || hasAccess ? (
            <>
              {!isDefaultAvatar && (
                <button
                  onClick={handleDeleteProfileImage}
                  disabled={isDeleting}
                  className="absolute z-10 text-red-500 bg-white rounded-full p-1.5 shadow border border-gray-200 top-0 left-0.1 right-0 w-5 h-5 flex items-center justify-center"
                  id="basic-info-delete-image-btn"
                  data-cy="basic-info-delete-image-btn"
                >
                  <FiTrash2 size={14} />
                </button>
              )}
              <button
                onClick={showModal}
                className="absolute -bottom-1 -right-1 z-10 bg-white rounded-full p-1.5 shadow border border-gray-200 w-5 h-5 flex items-center justify-center text-gray-600 hover:bg-gray-50"
                id="basic-info-edit-profile-btn"
                data-cy="basic-info-edit-profile-btn"
              >
                <LuPencil size={16} />
              </button>
            </>
          ) : null}
        </div>
        <div
          className="flex-1 min-w-0 flex flex-col gap-0.5"
          data-cy="basic-info-name-block"
        >
          <h5
            id="basic-info-name"
            data-cy="basic-info-name"
            className="text-sm font-normal text-[#4d4d4d] m-0"
          >
            {employeeData?.firstName} {employeeData?.middleName}{' '}
          </h5>
          <p
            id="basic-info-email-text"
            data-cy="basic-info-email-text"
            className="text-sm text-[#bababa] font-normal m-0"
          >
            {employeeData?.email}
          </p>
        </div>
        <div
          className="flex items-center gap-2 shrink-0"
          data-cy="basic-info-status-block"
        >
          <Tag
            className={`m-0 ${
              isActive
                ? 'bg-[#e6f4ff] text-[#1677ff] border border-[#91caff]'
                : 'bg-red-50 text-red-500 border border-red-500'
            }`}
            id="basic-info-status"
            data-cy="basic-info-status"
          >
            {isActive ? 'Active' : 'Deactivated'}
          </Tag>
        </div>
      </div>

      {/* Bottom section: Joined at, Address, Service Year, Office */}
      <div
        className="grid grid-cols-2 sm:grid-cols-4 gap-6 pt-4 border-gray-100"
        id="basic-info-details-row"
        data-cy="basic-info-details-row"
      >
        <div id="basic-info-joined" data-cy="basic-info-joined">
          <p
            className="text-sm text-[#bababa] font-normal m-0 mb-0.5"
            data-cy="basic-info-joined-label"
          >
            Joined at
          </p>
          <p
            className="text-sm font-normal text-[#4d4d4d] m-0"
            data-cy="basic-info-joined-value"
          >
            {joinedDate ? dayjs(joinedDate).format('DD MMMM, YYYY') : '-'}
          </p>
        </div>
        <div id="basic-info-address" data-cy="basic-info-address">
          <p
            className="text-sm text-[#bababa] font-normal m-0 mb-0.5"
            data-cy="basic-info-address-label"
          >
            Address
          </p>
          <p
            className="text-sm font-normal text-[#4d4d4d] m-0"
            data-cy="basic-info-address-value"
          >
            {formatAddress(addresses)}
          </p>
        </div>
        <div id="basic-info-service-year" data-cy="basic-info-service-year">
          <p
            className="text-sm text-[#bababa] font-normal m-0 mb-0.5"
            data-cy="basic-info-service-year-label"
          >
            Service Year
          </p>
          <p
            className="text-sm font-normal text-[#4d4d4d] m-0"
            data-cy="basic-info-service-year-value"
          >
            {formatServiceYear(joinedDate)}
          </p>
        </div>
        <div id="basic-info-office" data-cy="basic-info-office">
          <p
            className="text-sm text-[#bababa] font-normal m-0 mb-0.5"
            data-cy="basic-info-office-label"
          >
            Office
          </p>
          <p
            className="text-sm font-normal text-[#4d4d4d] m-0"
            data-cy="basic-info-office-value"
          >
            {officeName}
          </p>
        </div>
      </div>

      {/* Modal for Changing Image */}
      <Modal
        data-cy="basic-info-change-profile-image-modal"
        title="Update Profile"
        open={isModalOpen}
        onCancel={handleCloseModal}
        footer={[
          <Button
            key="cancel"
            onClick={handleCloseModal}
            id="basic-info-change-image-cancel-btn"
            data-cy="basic-info-change-image-cancel-btn"
          >
            Cancel
          </Button>,
          <Button
            key="save"
            type="primary"
            onClick={handleSaveChange}
            loading={isUploading || isUpdatingEmail}
            id="basic-info-change-image-save-btn"
            data-cy="basic-info-change-image-save-btn"
          >
            Update
          </Button>,
        ]}
        centered
      >
        <Dragger
          name="files"
          fileList={profileFileList}
          beforeUpload={beforeProfileUpload}
          customRequest={({ onSuccess }) => {
            setTimeout(() => onSuccess?.('ok'), 0);
          }}
          onChange={handleProfileChange}
          onRemove={handleProfileRemove}
          accept="image/*"
          maxCount={1}
          showUploadList={{
            showPreviewIcon: true,
            showRemoveIcon: true,
          }}
          id="basic-info-change-profile-image-modal-dragger"
          data-cy="basic-info-change-profile-image-modal-dragger"
        >
          {profileFileList.length > 0 ? (
            <img
              src={
                getImageUrl(profileFileList) ||
                employeeData?.profileImage ||
                '/placeholder.svg'
              }
              alt="Uploaded Preview"
              width={400}
              height={256}
              className="w-full h-auto max-h-64 object-cover rounded-xl"
              id="basic-info-change-profile-image-modal-dragger-image"
              data-cy="basic-info-change-profile-image-modal-dragger-image"
            />
          ) : (
            <>
              <p
                className="ant-upload-drag-icon"
                id="basic-info-change-profile-image-modal-dragger-icon"
                data-cy="basic-info-change-profile-image-modal-dragger-icon"
              >
                <InboxOutlined
                  id="basic-info-change-profile-image-modal-dragger-icon-inbox-outlined"
                  data-cy="basic-info-change-profile-image-modal-dragger-icon-inbox-outlined"
                />
              </p>
              <p
                className="ant-upload-drag-text font-semibold text-xs"
                id="basic-info-change-profile-image-modal-dragger-text"
                data-cy="basic-info-change-profile-image-modal-dragger-text"
              >
                Drag and drop your image here or click to upload.
              </p>
            </>
          )}
        </Dragger>
        <AccessGuard
          permissions={[Permissions.ChangeEmployeeEmail]}
          id="basic-info-change-email-guard"
          data-cy="basic-info-change-email-guard"
        >
          <div
            className="text-sm text-[#030712] font-normal py-1"
            data-cy="basic-info-change-email-label"
          >
            Update Email
          </div>
          <div
            className="text-sm text-black opacity-70 font-normal py-1"
            data-cy="basic-info-change-email-input"
          >
            <Input
              type="email"
              placeholder="Enter email"
              value={newEmail}
              onChange={(event) => setNewEmail(event.target.value)}
              className="w-full h-10"
              data-cy="basic-info-change-email-input-field"
            />
            <InfoOutlinedIcon className="text-black opacity-70 text-base pr-1" />
            <span
              data-cy="basic-info-change-email-info"
              className="text-sm text-black opacity-70 font-normal"
            >
              You must verify your new email before it updates.
            </span>
          </div>
        </AccessGuard>
      </Modal>
    </Card>
  );
}

export default BasicInfo;

import { useGetEmployee } from '@/store/server/features/employees/employeeManagment/queries';
import {
  EditState,
  useEmployeeManagementStore,
} from '@/store/uistate/features/employees/employeeManagment';
import {
  BANK_DEFAULT_FIELD_KEYS,
  BANK_DEFAULT_FIELDS,
  bankInformationMatchesSnapshot,
  buildBankFieldsForDisplay,
} from '@/utils/employeeBankInformation';
import { Card, Col, Input, Form, Row, Button } from 'antd';
import React, { useEffect, useMemo, useRef } from 'react';
import AccessGuard from '@/utils/permissionGuard';
import { Permissions } from '@/types/commons/permissionEnum';
import { validateField } from '../../../../_components/formValidator';
import dayjs from 'dayjs';
import CheckIcon from '@mui/icons-material/Check';
import CloseIcon from '@mui/icons-material/Close';
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';

const BankInformationComponent = ({
  mergedFields,
  handleSaveChanges,
  id,
}: any) => {
  const { setEdit, edit, savedBankSnapshot, setSavedBankSnapshot } =
    useEmployeeManagementStore();
  const { isLoading, data: employeeData } = useGetEmployee(id);

  const [form] = Form.useForm();

  useEffect(() => {
    setSavedBankSnapshot(null);
  }, [id, setSavedBankSnapshot]);

  const bankInformationFields = useMemo(
    () =>
      mergedFields?.filter(
        (field: any) => field?.formTitle === 'bankInformation',
      ) || [],
    [mergedFields],
  );

  const customBankFieldsOnly = useMemo(
    () =>
      bankInformationFields.filter(
        (field: any) => !BANK_DEFAULT_FIELD_KEYS.has(field.fieldName),
      ),
    [bankInformationFields],
  );

  const allFields = useMemo(
    () =>
      buildBankFieldsForDisplay(
        employeeData,
        bankInformationFields,
        savedBankSnapshot,
      ),
    [employeeData, bankInformationFields, savedBankSnapshot],
  );

  const wasEditingBankRef = useRef(false);

  // Drop local snapshot once GET /users + employee-information reflects the same bank values.
  useEffect(() => {
    if (
      savedBankSnapshot &&
      bankInformationMatchesSnapshot(
        employeeData?.employeeInformation,
        savedBankSnapshot,
      )
    ) {
      setSavedBankSnapshot(null);
    }
  }, [employeeData?.employeeInformation, savedBankSnapshot]);

  // Only seed the form when entering edit mode — not on every allFields/query change.
  useEffect(() => {
    const justOpened = edit.bankInformation && !wasEditingBankRef.current;
    wasEditingBankRef.current = edit.bankInformation;
    if (justOpened) {
      form.setFieldsValue(
        buildBankFieldsForDisplay(
          employeeData,
          bankInformationFields,
          savedBankSnapshot,
        ),
      );
    }
  }, [
    edit.bankInformation,
    employeeData,
    bankInformationFields,
    savedBankSnapshot,
    form,
  ]);

  const getFieldValidation = (fieldName: string) => {
    return (
      mergedFields?.find((field: any) => field?.fieldName === fieldName)
        ?.fieldValidation ?? null
    );
  };

  const handleEditChange = (editKey: keyof EditState) => {
    setEdit(editKey);
  };

  const handleBankSave = (values: Record<string, unknown>) => {
    setSavedBankSnapshot(values);
    handleSaveChanges('bankInformation', values, {
      onSuccess: () => setSavedBankSnapshot(values),
      onError: () => setSavedBankSnapshot(null),
    });
  };

  const titleMap: Record<string, string> = {
    bankName: 'Bank Name',
    accountNumber: 'Account Number',
    tinNumber: 'TIN Number',
    branch: 'Branch',
    accountName: 'Account Name',
  };

  const getDisplayValue = (key: string, val: unknown): string => {
    if (val === null || val === undefined || val === '') return '-';
    const str = String(val);
    if (dayjs(str, ['YYYY-MM-DD', 'DD/MM/YYYY'], true).isValid()) {
      return dayjs(str).format('DD MMMM, YYYY');
    }
    return str;
  };

  const getLabel = (key: string, customLabel?: string): string => {
    if (customLabel) return customLabel;
    return (
      titleMap[key] ||
      key
        .split(/_|(?=[A-Z])/)
        .map(
          (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(),
        )
        .join(' ')
    );
  };

  const customLabel = (field: any) => field.label || getLabel(field.fieldName);

  const defaultFieldItems = Object.keys(BANK_DEFAULT_FIELDS).map((key) => ({
    label: getLabel(key),
    value: getDisplayValue(key, allFields[key]),
    key,
  }));

  const customFieldItems = customBankFieldsOnly.map((field: any) => ({
    label: customLabel(field),
    value: getDisplayValue(field.fieldName, allFields[field.fieldName]),
    key: field.fieldName,
  }));

  const allItems = [...defaultFieldItems, ...customFieldItems];

  const midPoint = Math.ceil(allItems.length / 2);
  const leftItems = allItems.slice(0, midPoint);
  const rightItems = allItems.slice(midPoint);

  const FieldBlock = ({
    label,
    value,
    dataCy,
  }: {
    label: string;
    value: string;
    dataCy: string;
  }) => (
    <div className="mb-5" id={dataCy} data-cy={dataCy}>
      <p
        className="text-sm text-[#4d4d4d] font-normal m-0 mb-0.5"
        data-cy={`${dataCy}-label`}
      >
        {label}
      </p>
      <p
        className="text-base font-normal text-[#4d4d4d] m-0"
        data-cy={`${dataCy}-value`}
      >
        {value}
      </p>
    </div>
  );

  return (
    <Card
      loading={isLoading}
      title={
        !edit.bankInformation ? (
          <span
            className="text-base font-bold text-[#4d4d4d]"
            data-cy="bank-information-card-title"
          >
            Bank Information
          </span>
        ) : null
      }
      extra={
        !edit.bankInformation ? (
          <AccessGuard
            permissions={[Permissions.UpdateEmployeeDetails]}
            selfShouldAccess
            id={id}
            data-cy="bank-information-edit-guard"
          >
            <button
              onClick={() => handleEditChange('bankInformation')}
              className="w-6 h-6 border-[1px] border-[#D9D9D9] rounded-md"
              id="bank-information-edit-icon"
              data-cy="bank-information-edit-icon"
            >
              <EditOutlinedIcon className="text-sm" />
            </button>
          </AccessGuard>
        ) : null
      }
      className="bank-information-card rounded-lg my-6"
      bordered={false}
      style={{ background: '#F9FAFB', boxShadow: 'none' }}
      id="bank-information-card"
      data-cy="bank-information-card"
      headStyle={{
        borderBottom: 'none',
        paddingLeft: '16px',
        paddingRight: '16px',
        background: '#F9FAFB',
      }}
      bodyStyle={{ padding: '12px 16px 12px 16px', background: '#F9FAFB' }}
    >
      {edit.bankInformation ? (
        <Form
          form={form}
          onFinish={handleBankSave}
          layout="vertical"
          id="bank-information-form"
          data-cy="bank-information-form"
        >
          <Row
            justify="space-between"
            align="middle"
            className="mb-4 w-full"
            style={{ width: '100%' }}
            id="personal-data-update-user-info-header-row"
            data-cy="personal-data-update-user-info-header-row"
          >
            <Col>
              <span
                data-cy="bank-information-form-title"
                className="text-sm font-normal text-black"
              >
                Bank Information
              </span>
            </Col>
            <Col>
              <div
                data-cy="bank-information-form-buttons"
                className="flex items-center gap-2"
              >
                <Button
                  type="default"
                  size="small"
                  onClick={() => {
                    setSavedBankSnapshot(null);
                    setEdit('bankInformation');
                  }}
                  id="bank-information-cancel-btn"
                  data-cy="bank-information-cancel-btn"
                  className="border border-red-500 h-6 w-6"
                >
                  <CloseIcon className="text-red-500 text-[10px]" />
                </Button>
                <Button
                  type="primary"
                  size="small"
                  htmlType="submit"
                  id="bank-information-submit-btn"
                  data-cy="bank-information-submit-btn"
                  className="h-6 w-6"
                >
                  <CheckIcon className="text-white text-[10px]" />
                </Button>
              </div>
            </Col>
          </Row>
          <Row
            gutter={[16, 24]}
            id="bank-information-form-row"
            data-cy="bank-information-form-row"
          >
            <Col
              className="w-full"
              lg={24}
              sm={24}
              xs={24}
              id="bank-information-form-col"
              data-cy="bank-information-form-col"
            >
              {Object.keys(allFields).map((key) => (
                <Form.Item
                  key={key}
                  name={key}
                  label={
                    titleMap[key] ||
                    key
                      .split('_')
                      .map(
                        (word) => word.charAt(0).toUpperCase() + word.slice(1),
                      )
                      .join(' ')
                  }
                  id={`bank-information-${key}-form-item`}
                  data-cy={`bank-information-${key}-form-item`}
                  rules={[
                    {
                      /*  eslint-disable-next-line @typescript-eslint/naming-convention */
                      validator: (_rule: any, value: any) => {
                        /*  eslint-enable-next-line @typescript-eslint/naming-convention */
                        let fieldValidation = getFieldValidation(key);

                        switch (key) {
                          case 'accountNumber':
                            fieldValidation = 'any';
                            break;
                          case 'accountName':
                          case 'branch':
                          case 'bankName':
                            fieldValidation = 'text';
                            break;
                          default:
                            fieldValidation = getFieldValidation(key) || 'any';
                        }

                        const validationError = validateField(
                          key,
                          value,
                          fieldValidation,
                        );
                        if (validationError)
                          return Promise.reject(new Error(validationError));
                        return Promise.resolve();
                      },
                    },
                  ]}
                >
                  <Input
                    placeholder={key.replace(/_/g, ' ')}
                    id={`bank-information-${key}-input`}
                    data-cy={`bank-information-${key}-input`}
                  />
                </Form.Item>
              ))}
            </Col>
          </Row>
        </Form>
      ) : (
        <Row
          gutter={[24, 0]}
          id="bank-information-display-row"
          data-cy="bank-information-display-row"
        >
          <Col
            lg={12}
            id="bank-information-display-col-left"
            data-cy="bank-information-display-col-left"
            className="flex flex-col"
          >
            {leftItems.map((item) => (
              <FieldBlock
                key={item.key}
                label={item.label}
                value={item.value}
                dataCy={`bank-information-display-${item.key}`}
              />
            ))}
          </Col>
          <Col
            lg={12}
            id="bank-information-display-col-right"
            data-cy="bank-information-display-col-right"
            className="flex flex-col"
          >
            {rightItems.map((item) => (
              <FieldBlock
                key={item.key}
                label={item.label}
                value={item.value}
                dataCy={`bank-information-display-${item.key}-right`}
              />
            ))}
          </Col>
        </Row>
      )}
    </Card>
  );
};

