              </div>
            </Col>
          </Row>
          <Row
            gutter={[24, 0]}
            id="job-work-schedule-total-row"
            data-cy="job-work-schedule-total-row"
          >
            <Col
              lg={12}
              id="job-work-schedule-total-col"
