  }) => {
    await updateEmployeeJobInformationMutation.mutateAsync(
      {
        id: empJobInfo?.id,
        values: {
          employementTypeId: values.employmentType,
        },
      },
      {
        onSuccess: () => {
          setShowEmploymentModal(false);
          form.resetFields();
        },
      },
    );
  };

  const handleEmploymentModalCancel = () => {
    setShowEmploymentModal(false);
    form.resetFields();
