      id: t.id,
      taskName: t.taskName,
      weight: parseInt(t.weight),
      evaluator: t.approverId,
      description: t.description,
    }));
    const payload = {
      probationId: targetForTaskEdit?.id,
      createdBy: userId,
      tasks: normalizedTasks,
