            >
              <StepCompetencyDefinition positionId={role.positionId} />
            </div>
            <div
              className="w-full flex flex-col-reverse sm:flex-row justify-between items-stretch sm:items-center gap-2 mt-4"
              data-cy="manage-competencies-nav"
            >
              <Popconfirm
