export interface CompetencyEvaluation {
  /**
   * Backend competency-criteria id. Absent while a role is being built in the
   * wizard (criteria have no ids yet); present on anything loaded from the API,
   * where it addresses the criterion for evaluator assignment and scoring.
   */
  competencyCriteriaId?: string;
  competencyName: string;
  category: RoleCompetency['category'];
  importance: CompetencyImportance;
  weight?: number;
  evaluatorId: string;
  evaluatorName: string;
  /** Whether the evaluator has completed this competency assessment */
  status?: 'Evaluated' | 'Pending';
  /**
   * Weighted result points (0–weight). Derived from rating × weight / 100.
   * Must never exceed the competency weight.
   */
  score?: number;
  /** Raw evaluator rating on a 0–100 scale before weight conversion */
  rating?: number;
  /** Optional notes from the evaluator */
  comment?: string;
}

/** Convert a 0–100 rating into weighted points, capped at the criterion weight. */
export const toWeightedScore = (rating: number, weight = 0): number => {
  const w = Math.max(0, Number(weight) || 0);
  const r = Math.min(100, Math.max(0, Number(rating) || 0));
  return Math.round((r / 100) * w * 10) / 10;
};

/** Recover a 0–100 rating from a stored weighted score (for edit forms). */
export const ratingFromWeightedScore = (score: number, weight = 0): number => {
  const w = Number(weight) || 0;
  if (w <= 0) return 0;
  return Math.round((Number(score) / w) * 100 * 10) / 10;
};

/** Sum weighted criterion scores (prototype total out of 100). */
export const sumWeightedScores = (
  evaluations: Array<{ score?: number } | undefined> | undefined,
): number =>
  Math.round(
    (evaluations ?? []).reduce((sum, e) => sum + Number(e?.score ?? 0), 0) * 10,
  ) / 10;

/** Achievement % of a criterion relative to its weight (for color coding). */
export const scoreAchievementPercent = (score: number, weight = 0): number => {
  const w = Number(weight) || 0;
  if (w <= 0) return 0;
  return Math.min(100, Math.round((Number(score) / w) * 100));
};

/** Stable key for a competency within evaluationAssignments form map */
export const competencyKey = (c: Pick<RoleCompetency, 'name' | 'category'>) =>
  `${c.name.trim()}__${c.category}`;

/** Flat form field key — one evaluator slot per employee × criterion */
export const evaluationFieldKey = (
  employeeId: string,
  competencyIndex: number,
) => `${employeeId}::${competencyIndex}`;

/**
 * Build the form map of evaluator assignments from persisted successor
 * evaluations. Keys always use the Core user id so this step can look people
 * up in the employee directory (nomination row ids would never match).
 */
export const buildEvaluationAssignments = (
  successors: Array<
    SuccessorCandidate & { competencyEvaluations?: CompetencyEvaluation[] }
  >,
  competencies: RoleCompetency[],
): Record<string, string> => {
  const map: Record<string, string> = {};
  const live = (competencies ?? []).filter((c) => c?.name?.trim());

  for (const successor of successors ?? []) {
    live.forEach((comp, index) => {
      const evaluation = (successor.competencyEvaluations ?? []).find(
        (e) =>
          (comp.id && e.competencyCriteriaId === comp.id) ||
          (e.competencyName === comp.name && e.category === comp.category),
      );
      if (evaluation?.evaluatorId) {
        map[evaluationFieldKey(successorPersonId(successor), index)] =
          evaluation.evaluatorId;
      }
    });
  }
  return map;
};

/**
 * Resolve the people shown on this step.
 *
 * Wizard `successorIds` are employee ids. After a role is saved they may be
 * nomination ids — `nominatedSuccessors` (from the API) covers that case and
 * also keeps successors visible if `/users` has not loaded yet.
 */
export const resolveSelectedSuccessors = (
  successorIds: string[],
  employees: SuccessorCandidate[],
  nominatedSuccessors: SuccessorCandidate[] = [],
): SuccessorCandidate[] => {
  const ids =
    successorIds.length > 0
      ? successorIds
      : nominatedSuccessors.map(successorPersonId);

  const employeeById = new Map(
    employees.map((employee) => [employee.id, employee]),
  );

  return ids
    .map((id) => {
      const nominated = nominatedSuccessors.find(
        (successor) => successor.userId === id || successor.id === id,
      );
      const fromDirectory =
        employeeById.get(id) ??
        (nominated?.userId ? employeeById.get(nominated.userId) : undefined);

      if (nominated) {
        const personId = successorPersonId(nominated);
        return {
          ...fromDirectory,
          ...nominated,
          id: personId,
          userId: personId,
          name: nominated.name || fromDirectory?.name || 'Employee',
          jobTitle:
            nominated.jobTitle ||
            nominated.currentPosition ||
            fromDirectory?.jobTitle ||
            '—',
          department: nominated.department || fromDirectory?.department || '—',
        };
      }

      return fromDirectory;
    })
    .filter((successor): successor is SuccessorCandidate => Boolean(successor));
};

