    );
  }

  if (competencies.length === 0) {
    return (
      <Empty
        image={Empty.PRESENTED_IMAGE_SIMPLE}
        description={
          <span
            className="text-gray-400 text-sm"
            data-cy="step-evaluator-no-competencies"
