import React, { useEffect } from 'react';
import { Modal, Form, Input, DatePicker, Select, Switch, Button } from 'antd';
import { CalendarOutlined } from '@ant-design/icons';
import { useFetchUsers } from '@/store/server/features/feedback/category/queries';
import { useUpdateForm } from '@/store/server/features/feedback/form/mutation';
import { CategoriesManagementStore } from '@/store/uistate/features/feedback/categories';
import dayjs from 'dayjs';
import { useGetFormsByID } from '@/store/server/features/feedback/form/queries';

const { TextArea } = Input;
const { Option } = Select;
interface EditFormModalProps {
  id: string;
}
const EditFormsModal: React.FC<EditFormModalProps> = ({ id }) => {
  const [formInstance] = Form.useForm();
  const {
    isEditModalVisible,
    setIsEditModalVisible,
    selectedFormId,
    searchUserParams,
  } = CategoriesManagementStore();

  const { data: employees } = useFetchUsers(searchUserParams?.user_name);
  const { mutate: updateForm, isLoading } = useUpdateForm();

  const { data: formDataByID } = useGetFormsByID(selectedFormId);
  const handleSubmit = async () => {
    const values = await formInstance.validateFields();

    const updatedData = {
      ...values,
      formCategoryId: id,
      startDate: values.surveyStartDate.toISOString(),
      endDate: values.surveyEndDate.toISOString(),
      isAnonymous: values.isAnonymous,
      formPermissions: values.users.map((userId: string) => ({ userId })),
    };
    delete updatedData.surveyStartDate;
    delete updatedData.surveyEndDate;
    delete updatedData.users;
    updateForm(
      { data: updatedData, id: selectedFormId },
      {
        onSuccess: () => {
          setIsEditModalVisible(false);
        },
        onError: () => {
          setIsEditModalVisible(false);
        },
      },
    );
  };

  useEffect(() => {
    const formValues = {
      name: formDataByID?.name,
      description: formDataByID?.description,
      surveyStartDate: dayjs(formDataByID?.startDate),
      surveyEndDate: dayjs(formDataByID?.endDate),
      isAnonymous: formDataByID?.isAnonymous,
      users: formDataByID?.formPermissions?.map((p: any) => p.userId) || [],
    };

    formInstance.setFieldsValue(formValues);
  }, [isEditModalVisible, formDataByID]);

  return (
    <Modal
      data-cy="edit-form-modal"
      title="Edit Form"
      open={isEditModalVisible}
      onCancel={() => setIsEditModalVisible(false)}
      footer={null}
      width={800}
    >
      <Form
        id="edit-form-form"
        data-cy="edit-form-form"
        form={formInstance}
        layout="vertical"
        onFinish={handleSubmit}
      >
        <Form.Item
          id="edit-form-name-item"
          data-cy="edit-form-name-item"
          name="name"
          label="Form Name"
        >
          <Input id="edit-form-name-input" data-cy="edit-form-name-input" />
        </Form.Item>
        <Form.Item
          id="edit-form-description-item"
          data-cy="edit-form-description-item"
          name="description"
          label="Description"
          rules={[{ required: true, message: 'Please input the description!' }]}
        >
          <TextArea
            id="edit-form-description-textarea"
            data-cy="edit-form-description-textarea"
            rows={4}
          />
        </Form.Item>
        <Form.Item
          id="edit-form-start-date-item"
          data-cy="edit-form-start-date-item"
          name="surveyStartDate"
          label="Start Date"
          rules={[{ required: true, message: 'Please select start date!' }]}
        >
          <DatePicker
            id="edit-form-start-date-picker"
            data-cy="edit-form-start-date-picker"
            style={{ width: '100%' }}
            format="YYYY-MM-DD"
            suffixIcon={
              <CalendarOutlined
                id="edit-form-start-date-icon"
                data-cy="edit-form-start-date-icon"
              />
            }
          />
        </Form.Item>
        <Form.Item
          id="edit-form-end-date-item"
          data-cy="edit-form-end-date-item"
          name="surveyEndDate"
          label="End Date"
          rules={[{ required: true, message: 'Please select end date!' }]}
        >
          <DatePicker
            id="edit-form-end-date-picker"
            data-cy="edit-form-end-date-picker"
            style={{ width: '100%' }}
            format="YYYY-MM-DD"
            suffixIcon={
              <CalendarOutlined
                id="edit-form-end-date-icon"
                data-cy="edit-form-end-date-icon"
              />
            }
          />
        </Form.Item>
        <Form.Item
          id="edit-form-users-item"
          data-cy="edit-form-users-item"
          name="users"
          label="Users"
        >
          <Select
            id="edit-form-users-select"
            data-cy="edit-form-users-select"
            mode="multiple"
            placeholder="Select users"
            value={
              formDataByID?.formPermissions?.map((p: any) => p.userId) || []
            }
            showSearch
            optionFilterProp="children"
            filterOption={(input, option) => {
              return (option?.children ?? '')
                .toString()
                .toLowerCase()
                .includes(input.toLowerCase());
            }}
          >
            {employees?.items.map((employee: any) => (
              <Option
                id={`edit-form-user-option-${employee.id}`}
                data-cy={`edit-form-user-option-${employee.id}`}
                key={employee.id}
                value={employee.id}
              >
                {`${employee?.firstName} ${employee?.middleName} ${employee?.lastName}`}
              </Option>
            ))}
          </Select>
        </Form.Item>
        <Form.Item
          id="edit-form-anonymous-item"
          data-cy="edit-form-anonymous-item"
          name="isAnonymous"
          label="Allow Anonymous"
          valuePropName="checked"
        >
          <Switch
            id="edit-form-anonymous-switch"
            data-cy="edit-form-anonymous-switch"
          />
        </Form.Item>
        <Form.Item id="edit-form-submit-item" data-cy="edit-form-submit-item">
          <Button
            id="edit-form-submit-button"
            data-cy="edit-form-submit-button"
            type="primary"
            htmlType="submit"
            loading={isLoading}
          >
            Update Form
          </Button>
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default EditFormsModal;

import React, { useEffect } from 'react';
import { Checkbox, Collapse } from 'antd';
import { useFetchQuestionTemplate } from '@/store/server/features/feedback/settings/queries';
import { useDynamicFormStore } from '@/store/uistate/features/feedback/dynamicForm';
import { FieldType } from '@/types/enumTypes';
import MultipleChoiceField from '../../survey/[slug]/_components/questions/multipleChoiceField';
import ParagraphField from '../../survey/[slug]/_components/questions/paragraphField';
import CheckboxField from '../../survey/[slug]/_components/questions/checkboxField';
import ShortTextField from '../../survey/[slug]/_components/questions/shortTextField';

const CustomQuestionTemplate = () => {
  const {
    pageSize,
    current,
    selectedQuestions,
    setSelectedQuestions,
    setFilteredQuestions,
  } = useDynamicFormStore();
  const { data: QuestionTemplate, isLoading: isQuestionTemplateLoading } =
    useFetchQuestionTemplate(pageSize, current);

  const handleSelectQuestion = (questionId: string, e: React.MouseEvent) => {
    e.stopPropagation();

    const updatedQuestions = selectedQuestions.includes(questionId)
      ? selectedQuestions.filter((id) => id !== questionId)
      : [...selectedQuestions, questionId];

    setSelectedQuestions(updatedQuestions);
  };

  useEffect(() => {
    if (QuestionTemplate) {
      const filtered = QuestionTemplate?.items?.filter((question: any) =>
        selectedQuestions.includes(question?.id),
      );
      setFilteredQuestions(filtered);
    }
  }, [selectedQuestions, QuestionTemplate]);

  if (isQuestionTemplateLoading)
    return (
      <div
        className="text-center my-5"
        data-cy="custom-question-template-loading"
      >
        {' '}
        No custom question available.
      </div>
    );
  return (
    <>
      <div
        className="flex items-center justify-start gap-1 mb-3"
        data-cy="custom-question-template-header"
        id="custom-question-template-header"
      >
        <p
          className="text-sm font-normal text-gray-400"
          data-cy="custom-question-template-header-text"
          id="custom-question-template-header-text"
        >
          Choose your Custom field
        </p>
        <span
          className="text-red-500 "
          data-cy="custom-question-template-header-required-indicator"
          id="custom-question-template-header-required-indicator"
        >
          *
        </span>
      </div>
      <Collapse
        defaultActiveKey={['1']}
        data-cy="custom-question-template-collapse"
      >
        <Collapse.Panel
          header="Custom Question Templates"
          key="0"
          data-cy="custom-question-template-panel"
          id="custom-question-template-panel"
        >
          <div
            className="flex flex-col"
            data-cy="custom-question-template-list"
            id="custom-question-template-list"
          >
            {QuestionTemplate?.items?.map((question: any, index: number) => (
              <div
                key={index}
                className="my-2 mx-4"
                data-cy="custom-question-template-item"
                id="custom-question-template-item"
              >
                <Collapse
                  key={question?.id}
                  defaultActiveKey={question?.id}
                  data-cy="custom-question-template-collapse-item"
                >
                  <Collapse.Panel
                    header={
                      <div
                        className="flex items-center"
                        data-cy="custom-question-template-header-item"
                        id="custom-question-template-header-item"
                      >
                        <Checkbox
                          checked={selectedQuestions?.includes(question?.id)}
                          onClick={(e) => handleSelectQuestion(question?.id, e)}
                          data-cy={`custom-question-template-checkbox-${question?.id}`}
                        />
                        <span
                          className="ml-2"
                          data-cy="custom-question-template-header-text-item"
                          id="custom-question-template-header-text-item"
                        >
                          {question?.question ?? '-'}
                        </span>
                      </div>
                    }
                    key={question?.id}
                    data-cy="custom-question-template-panel-item"
                    id="custom-question-template-panel-item"
                  >
                    {question?.fieldType === FieldType.MULTIPLE_CHOICE && (
                      <MultipleChoiceField
                        choices={question?.field}
                        selectedAnswer={[]}
                        data-cy="custom-question-template-multiple-choice-field"
                      />
                    )}
                    {question?.fieldType === FieldType.SHORT_TEXT && (
                      <ShortTextField data-cy="custom-question-template-short-text-field" />
                    )}
                    {question?.fieldType === FieldType.CHECKBOX && (
                      <CheckboxField
                        options={question?.field}
                        data-cy="custom-question-template-checkbox-field"
                      />
                    )}
                    {question?.fieldType === FieldType.PARAGRAPH && (
                      <ParagraphField data-cy="custom-question-template-paragraph-field" />
                    )}
                  </Collapse.Panel>
                </Collapse>
              </div>
            ))}
          </div>
        </Collapse.Panel>
      </Collapse>
    </>
  );
};

export default CustomQuestionTemplate;

import React, { useEffect } from 'react';
import {
  Form,
  Input,
  Button,
  DatePicker,
  TimePicker,
  Select,
  Checkbox,
  Popconfirm,
} from 'antd';
import { CgClose } from 'react-icons/cg';
import { TiPlusOutline } from 'react-icons/ti';
import dayjs from 'dayjs';
import { useOrganizationalDevelopment } from '@/store/uistate/features/organizationalDevelopment';
import { ConversationStore } from '@/store/uistate/features/conversation';
import { ConversationStore as ConversationStoreCopy } from '@/store/uistate/features/feedback/conversation';

const { Option } = Select;

interface StepOneFormProps {
  allUserData?: any;
  initialValues?: any;
  isEdit?: boolean;
  form: any;
  allDepartmentWithData: any[];
  onUserChange: (values: string[]) => void;
  onDepartmentChange: (values: string[]) => void;
  handleContinue?: () => void;
}

const ConversationInstanceForm: React.FC<StepOneFormProps> = ({
  allUserData,
  initialValues,
  isEdit = false,
  form,
  allDepartmentWithData,
  onUserChange,
  onDepartmentChange,
  handleContinue,
}) => {
  const {
    agendaItems,
    setAgendaItems,
    setSelectedDepartments,
    selectedDepartments,
    selectedUsers,
  } = useOrganizationalDevelopment();
  const { setOfUser, setSetOfUser, setOpen } = ConversationStore();

  const { setOpenModal } = ConversationStoreCopy();
  const handleAgendaChange = (value: string, index: number) => {
    const updatedAgenda = [...agendaItems];
    updatedAgenda[index] = value;
    setAgendaItems(updatedAgenda);
  };
  const addAgendaItem = () => {
    setAgendaItems([...agendaItems, '']); // Add a new empty agenda item
  };
  const removeAgendaItem = (index: number) => {
    /* eslint-disable @typescript-eslint/naming-convention */
    const updatedAgenda = agendaItems.filter((_, idx) => idx !== index);
    /* eslint-enable @typescript-eslint/naming-convention */
    setAgendaItems(updatedAgenda);
  };
  useEffect(() => {
    if (form && initialValues) {
      setAgendaItems(initialValues?.agenda ?? ['']);
      setSelectedDepartments(initialValues?.departmentId);
      // Combine the date and time into a single DateTime for the form

      form.setFieldsValue({
        name: initialValues?.name,
        departmentId: initialValues?.departmentId,
        agenda: initialValues?.agenda,

        // Set dateOfMeeting and timeOfMeeting separately for the form
        dateOfMeeting: initialValues?.dateOfMeeting
          ? dayjs(initialValues?.dateOfMeeting).isValid()
            ? dayjs(initialValues?.dateOfMeeting)
            : null
          : null,

        timeOfMeeting: initialValues?.timeOfMeeting
          ? dayjs(initialValues?.timeOfMeeting, 'HH:mm:ss').isValid()
            ? dayjs(initialValues?.timeOfMeeting, 'HH:mm:ss')
            : null
          : null,

        userId: initialValues?.userId,
      });
    }
  }, [form, initialValues]);

  useEffect(() => {
    if (selectedDepartments?.length === 0) {
      setSetOfUser([]); // Clear the setOfUser if no departments are selected
    } else {
      const usersInSelectedDepartments = allUserData?.items?.filter(
        (user: any) => {
          const departmentId = user.employeeJobInformation?.find(
            (job: any) => job?.departmentId && job?.isPositionActive === true,
          )?.departmentId;

          return departmentId && selectedDepartments?.includes(departmentId);
        },
      );
      setSetOfUser(usersInSelectedDepartments);
    }
  }, [selectedDepartments, selectedDepartments, allUserData?.items]); // Trigger effect when selectedDepartmentIds or allUserData changes

  return (
    <>
      <Form.Item
        name="name"
        label={
          <span
            className="text-black text-xs font-semibold"
            data-cy="conversation-instance-form-meeting-name-label"
          >
            Bi-weekly Meeting Name
          </span>
        }
        rules={[
          {
            required: true,
            message: 'Please enter the bi-weekly meeting name',
          },
        ]}
      >
        <Input
          name="name"
          placeholder="Enter the meeting name"
          className="text-black text-xs font-semibold"
          data-cy="conversation-instance-form-meeting-name-input"
        />
      </Form.Item>

      <div
        className="flex gap-4"
        data-cy="conversation-instance-form-date-time-container"
      >
        <Form.Item
          name="dateOfMeeting"
          label={
            <span
              className="text-black text-xs font-semibold"
              data-cy="conversation-instance-form-date-label"
            >
              Date of Meeting
            </span>
          }
          rules={[
            {
              required: true,
              message: 'Please select the date of the meeting',
            },
          ]}
          style={{ flex: 1 }}
        >
          <DatePicker
            style={{ width: '100%', font: '10px' }}
            data-cy="conversation-instance-form-date-picker"
          />
        </Form.Item>

        <Form.Item
          name="timeOfMeeting"
          label={
            <span
              className="text-black text-xs font-semibold"
              data-cy="conversation-instance-form-time-label"
            >
              Time of Meeting
            </span>
          }
          rules={[
            {
              required: true,
              message: 'Please select the time of the meeting',
            },
          ]}
          style={{ flex: 1 }}
        >
          <TimePicker
            format="HH:mm"
            style={{ width: '100%', font: '10px' }}
            minuteStep={5}
            showNow={false}
            data-cy="conversation-instance-form-time-picker"
          />
        </Form.Item>
      </div>

      <Form.Item
        name="departmentId"
        label={
          <span
            className="text-black text-xs font-semibold"
            data-cy="conversation-instance-form-department-label"
          >
            Department
          </span>
        }
        rules={[
          { required: true, message: 'Please select at least one department' },
        ]}
      >
        <Select
          mode="multiple"
          placeholder="Select a department"
          className="text-black text-xs font-semibold"
          onChange={onDepartmentChange}
          data-cy="conversation-instance-form-department-select"
        >
          {allDepartmentWithData?.map((dep) => (
            <Option
              key={dep.id}
              value={dep.id}
              data-cy={`conversation-instance-form-department-option-${dep.id}`}
            >
              <span
                className="text-xs font-semibold text-black"
                data-cy={`conversation-instance-form-department-option-text-${dep.id}`}
              >
                {dep.name}
              </span>
            </Option>
          ))}
        </Select>
      </Form.Item>

      <Form.Item
        name="userId"
        label={
          <span
            className="text-black text-xs font-semibold"
            data-cy="conversation-instance-form-users-label"
          >
            Users
          </span>
        }
        rules={[{ required: true, message: 'Please select at least one user' }]}
      >
        <Select
          mode="multiple"
          placeholder="Select users"
          className="text-black text-xs font-semibold"
          value={selectedUsers}
          showSearch
          onChange={onUserChange}
          optionLabelProp="label"
          filterOption={(input, option: any) =>
            option.label?.toLowerCase().includes(input.toLowerCase())
          }
          data-cy="conversation-instance-form-users-select"
        >
          {setOfUser?.map((user) => (
            <Option
              key={user.id}
              value={user.id}
              label={`${user?.firstName} ${user?.middleName} ${user?.lastName}`}
              data-cy={`conversation-instance-form-user-option-${user.id}`}
            >
              <Checkbox
                checked={selectedUsers.includes(user.id)}
                onClick={(e) => e.stopPropagation()}
                data-cy={`conversation-instance-form-user-checkbox-${user.id}`}
              >
                {user?.firstName} ${user?.middleName} {user?.lastName}
              </Checkbox>
            </Option>
          ))}
        </Select>
      </Form.Item>

      <div data-cy="conversation-instance-form-agenda-container">
        <span
          className="text-gray-950 font-semibold text-xs"
          data-cy="conversation-instance-form-agenda-title"
        >
          Meeting Agenda
        </span>
        {agendaItems.map((item, index) => (
          <div
            key={index}
            className="flex items-center mt-2"
            data-cy={`conversation-instance-form-agenda-item-${index}`}
          >
            <Form.Item
              name={['agenda', index]}
              label={null}
              className="flex-grow"
            >
              <Input
                value={item}
                onChange={(e) => handleAgendaChange(e.target.value, index)}
                placeholder={`Agenda item ${index + 1}`}
                className="text-black font-semibold text-xs"
                data-cy={`conversation-instance-form-agenda-input-${index}`}
              />
            </Form.Item>

            <Button
              type="text"
              icon={<CgClose />}
              onClick={() => removeAgendaItem(index)}
              disabled={agendaItems.length === 1}
              className="ml-2"
              data-cy={`conversation-instance-form-agenda-remove-button-${index}`}
            />
          </div>
        ))}
      </div>

      <Button
        type="dashed"
        onClick={addAgendaItem}
        className="flex items-center text-sm font-semibold mt-2"
        icon={<TiPlusOutline />}
        data-cy="conversation-instance-form-agenda-add-button"
      >
        Add Agenda Item
      </Button>

      <div
        className="w-full bg-[#fff] absolute bottom-8 flex justify-center space-x-5"
        data-cy="conversation-instance-form-actions"
      >
        <Popconfirm
          title="Are you sure you want to cancel and reset the form?"
          onConfirm={() => {
            setOpenModal(false);
            setOpen(false);
            form.resetFields();
          }}
          okText="Yes"
          cancelText="No"
        >
          <Button
            style={{ marginRight: 8 }}
            data-cy="conversation-instance-form-cancel-button"
          >
            Cancel
          </Button>
        </Popconfirm>

        {isEdit ? (
          <Button
            htmlType="submit"
            type="primary"
            data-cy="conversation-instance-form-edit-button"
          >
            Edit
          </Button>
        ) : (
          <Button
            type="primary"
            onClick={handleContinue}
            data-cy="conversation-instance-form-continue-button"
          >
            Continue
          </Button>
        )}
      </div>
    </>
  );
};

export default ConversationInstanceForm;

import React, { useEffect } from 'react';
import { Table, Button, Popconfirm, Form } from 'antd';
import type { TableColumnsType } from 'antd';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import {
  useGetDepartments,
  useGetDepartmentsWithUsers,
} from '@/store/server/features/employees/employeeManagment/department/queries';
import dayjs from 'dayjs';
import { useOrganizationalDevelopment } from '@/store/uistate/features/organizationalDevelopment';
import CustomDrawerLayout from '@/components/common/customDrawer';
import ConversationInstanceForm from '../conversationInstanceForm';
import { ConversationStore } from '@/store/uistate/features/conversation';
import {
  useDeleteConversationInstancesById,
  useUpdateConversationInstancesById,
} from '@/store/server/features/CFR/conversation/conversation-instance/mutations';
import {
  useGetAllConversationInstancesById,
  useGetAllConversationInstancesByQuestionSetId,
} from '@/store/server/features/CFR/conversation/conversation-instance/queries';
import { useRouter } from 'next/navigation';
import EmployeeSearchComponent from '@/components/common/search/searchComponent';
import { TableSkeleton } from '@/components/tableSkeleton';

const MettingDataTable = ({
  conversationTypeId,
  slug,
}: {
  conversationTypeId: string;
  slug: string;
}) => {
  const {
    setOpen,
    open,
    setSelectedUsers,
    selectedInstance,
    setSelectedInstances,
    selectedDepartments,
    setSelectedDepartments,
  } = useOrganizationalDevelopment();
  const {
    setSetOfUser,
    userId,
    setUserId,
    setDepartmentId,
    departmentId,
    searchField,
    pageSize,
    setPageSize,
    page,
    setPage,
    updateFieldOptions,
  } = ConversationStore();
  const [form] = Form.useForm();
  const router = useRouter();

  const { data: allUserData } = useGetAllUsers();
  const {
    data: conversationInstances,
    isLoading: getInstanceLoading,
    refetch: refetchConversationInstances,
  } = useGetAllConversationInstancesByQuestionSetId(
    slug,
    userId,
    departmentId,
    page,
    pageSize,
  );

  // Fetch data for a single conversation instance
  const { data: singleConvestionInstance } =
    useGetAllConversationInstancesById(selectedInstance);

  // Effect to handle changes in userId or departmentId
  useEffect(() => {
    refetchConversationInstances();
  }, [userId, departmentId, refetchConversationInstances]);

  const { data: departmentData } = useGetDepartments();
  const { mutate: deleteConversationInstance } =
    useDeleteConversationInstancesById();
  const { mutate: updateConversationInstance } =
    useUpdateConversationInstancesById();

  const { data: allDepartmentWithData } = useGetDepartmentsWithUsers();

  const getEmployeeData = (employeeId: string) => {
    const employeeDataDetail = allUserData?.items?.find(
      (emp: any) => emp?.id === employeeId,
    );
    return employeeDataDetail || {}; // Return an empty object if employeeDataDetail is undefined
  };

  const getDepartmentId = (selectedDepartmentId: string) => {
    const department = (departmentData ?? []).find(
      (dep: any) => dep.id === selectedDepartmentId,
    );
    return department?.name ?? '-'; // Return an empty object if no matching department is found
  };
  const columns: TableColumnsType<any> = [
    {
      title: 'Held Date',
      dataIndex: 'createdAt',
      /* eslint-disable @typescript-eslint/naming-convention */
      render: (_, record) =>
        record.createdAt ? dayjs(record.createdAt).format('YYYY-MM-DD') : '-',
      /* eslint-enable @typescript-eslint/naming-convention */
      sorter: (a, b) =>
        new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
    },
    {
      title: 'Name',
      dataIndex: 'name',
      sorter: (a, b) => a.name.localeCompare(b.name),
    },
    {
      title: 'Department',
      dataIndex: 'departmentId',
      render: (
        notused, // Keep `_` as the name
        record,
      ) =>
        record.departmentId?.map((id: any) => getDepartmentId(id)).join(', ') ??
        '-',
    },
    {
      title: 'Created By',
      dataIndex: 'createdBy',
      render: (notused, record) =>
        record.createdBy ? getEmployeeData(record.createdBy)?.firstName : '-',
    },
    {
      title: 'Attendees',
      dataIndex: 'userId',
      render: (notused, record) => (
        <div data-cy={`meeting-table-attendees-${record.id}`}>
          {record.userId
            ?.map((id: string) => getEmployeeData(id)?.firstName)
            .join(', ') ?? '-'}
        </div>
      ),
    },

    {
      title: 'Action',
      dataIndex: 'action',
      width: 100,
      render: (notused, record) => (
        <div
          className="flex space-x-2"
          data-cy={`meeting-table-action-${record.id}`}
        >
          <Button
            type="primary"
            onClick={(e) => {
              e.stopPropagation();
              handleEdit(record.id);
            }}
            data-cy={`meeting-table-edit-button-${record.id}`}
          >
            Edit
          </Button>
          <Popconfirm
            title="Are you sure you want to delete this item?"
            description="This action cannot be undone."
            onConfirm={(e: any) => {
              e.stopPropagation();
              handleDelete(record.id);
            }}
            okText="Yes"
            cancelText="No"
            data-cy={`meeting-table-delete-popconfirm-${record.id}`}
          >
            <Button
              type="primary"
              danger
              onClick={(e) => e.stopPropagation()}
              data-cy={`meeting-table-delete-button-${record.id}`}
            >
              Delete
            </Button>
          </Popconfirm>
        </div>
      ),
    },
  ];

  const handleEdit = (key: string) => {
    setSelectedInstances(key);
    setOpen(true);
  };

  const handleDelete = (key: string) => {
    deleteConversationInstance(key);
  };
  const handleSearchChange = (value: { key: string; value: any }) => {
    if (value.key === 'department') {
      setDepartmentId(value.value);
    } else if (value.key === 'employee') {
      setUserId(value.value);
    } else {
      return;
    }
  };

  const handleEditConversationResponse = (values: any) => {
    selectedInstance &&
      updateConversationInstance(
        { selectedInstance, values },
        {
          onSuccess: () => {
            setSelectedInstances(null);
            setOpen(false);
          },
        },
      );
  };
  useEffect(() => {
    if (allUserData) {
      const userOptions = allUserData.items?.map((user: any) => ({
        key: user.id,
        value: `${user?.firstName} ${user?.middleName} ${user?.lastName}`,
      }));
      updateFieldOptions('employee', userOptions);
    }
  }, [allUserData, updateFieldOptions]);

  useEffect(() => {
    if (departmentData) {
      const departmentOptions = departmentData.map((dep: any) => ({
        key: dep.id,
        value: dep.name,
      }));
      updateFieldOptions('department', departmentOptions);
    }
  }, [departmentData, updateFieldOptions]);

  useEffect(() => {
    if (selectedDepartments?.length === 0) {
      setSetOfUser([]); // Clear the setOfUser if no departments are selected
    } else {
      const usersInSelectedDepartments = allUserData?.items?.filter(
        (user: any) => {
          const departmentId = user.employeeJobInformation?.find(
            (job: any) => job?.departmentId && job?.isPositionActive === true,
          )?.departmentId;

          return departmentId && selectedDepartments?.includes(departmentId);
        },
      );
      setSetOfUser(usersInSelectedDepartments);
    }
  }, [selectedDepartments, allUserData?.items]); // Trigger effect when selectedDepartmentIds or allUserData changes

  const onUserChange = (selectedUserIds: string[]) => {
    setSelectedUsers(selectedUserIds); // Update selected users in the form
  };
  const handleRowClick = (record: any) => {
    router.push(`/feedback/conversation/${conversationTypeId}/${record.id}`);
  };
  return (
    <div className="overflow-x-auto" data-cy="meeting-table-container">
      <EmployeeSearchComponent
        fields={searchField}
        onChange={handleSearchChange}
      />
      {getInstanceLoading ? (
        <TableSkeleton columns={columns} />
      ) : (
        <Table<any>
          columns={columns}
          dataSource={conversationInstances?.items ?? []}
          pagination={{
            total: conversationInstances?.meta?.total ?? 0, // Total number of items
            current: page, // Current page
            pageSize: pageSize, // Items per page
            showSizeChanger: true, // Enable page size changer
            onChange: (page, pageSize) => {
              setPage(page); // Update current page
              setPageSize(pageSize); // Update page size
            },
          }}
          scroll={{ x: 800 }} // Enable horizontal scrolling
          className="cursor-pointer"
          onRow={(record) => ({
            onClick: () => handleRowClick(record), // Add click handler
          })}
        />
      )}
      <CustomDrawerLayout
        open={open}
        onClose={() => {
          setSelectedInstances(null);
          setOpen(false);
          setSelectedDepartments([]);
        }}
        modalHeader={'Edit Conversation Instance'}
        width="40%"
        data-cy="meeting-table-edit-drawer"
      >
        <Form
          form={form}
          name="editConversationInstance"
          autoComplete="off"
          layout="vertical"
          onFinish={handleEditConversationResponse}
          style={{ maxWidth: '100%' }}
          className="text-black"
          data-cy="meeting-table-edit-form"
        >
          <ConversationInstanceForm
            initialValues={singleConvestionInstance}
            form={form}
            isEdit={true}
            allDepartmentWithData={allDepartmentWithData}
            onUserChange={onUserChange}
            onDepartmentChange={(value) => setSelectedDepartments(value)}
            allUserData={allUserData}
          />
        </Form>
      </CustomDrawerLayout>
    </div>
  );
};

export default MettingDataTable;

'use client';
import TabLandingLayout from '@/components/tabLanding';
import React, { useEffect } from 'react';
import { Button, Card, Col, Row, Skeleton, Tabs } from 'antd';
import CollapsibleCardList from './_components/collapsableCard';
import ActionPlans from './_components/actionPlans';
import { useOrganizationalDevelopment } from '@/store/uistate/features/organizationalDevelopment';
import { useGetAllConversationInstancesById } from '@/store/server/features/CFR/conversation/conversation-instance/queries';
import ConversationInstanceDetail from './_components/biWeeklyDetail';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import { ConversationStore } from '@/store/uistate/features/conversation';
import CreateActionPlans from './_components/createActionPlans';
import CustomDrawerLayout from '@/components/common/customDrawer';
import { useAddActionPlan } from '@/store/server/features/CFR/conversation/action-plan/mutation';
import dayjs from 'dayjs';
import { useRouter } from 'next/navigation';
import { useForm } from 'antd/es/form/Form';
interface Params {
  slug: string;
}
interface ConversationInstanceDetailProps {
  params: Params;
}
const Index = ({ params: { slug } }: ConversationInstanceDetailProps) => {
  const { setOpen, open } = useOrganizationalDevelopment();
  const { selectedUserId, setActiveTab, activeTab } = ConversationStore();

  const { data: conversationInstance, isLoading } =
    useGetAllConversationInstancesById(slug);
  const { data: allUserData } = useGetAllUsers();
  const { mutate: addActionPlan } = useAddActionPlan();
  const router = useRouter();
  const [form2] = useForm();

  useEffect(() => {
    if (selectedUserId !== null && selectedUserId !== '') {
      setActiveTab('2');
    }
  }, [selectedUserId]);
  const getEmployeeData = (employeeId: string) => {
    const employeeDataDetail = allUserData?.items?.find(
      (emp: any) => emp?.id === employeeId,
    );
    return employeeDataDetail || {}; // Return an empty object if employeeDataDetail is undefined
  };

  const getQuestionResponse = (questionId: string) => {
    const questionResponse = conversationInstance?.conversationResponse?.find(
      (response: any) =>
        response?.questionId === questionId &&
        (selectedUserId ? response?.userId === selectedUserId : true),
    );
    if (questionResponse) {
      const employeeData = getEmployeeData(questionResponse?.userId);

      return {
        ...questionResponse,
        employeeDetail:
          `${employeeData?.firstName || ''} ${employeeData?.middleName || ''} ${employeeData?.lastName || ''}`.trim(),
      };
    }

    return {}; // Return an empty object if no match is found
  };

  const filteredData =
    conversationInstance?.questionSet?.conversationsQuestions?.map(
      (conversationQuestion: any) => ({
        id: conversationQuestion?.id,
        questionTitle: conversationQuestion,
        responseData: getQuestionResponse(conversationQuestion?.id),
      }),
    );
  const handleRedirectback = () => {
    router.back();
  };

  const handleCreateActionPlan = (values: any) => {
    const updatedData = {
      ...values,
      deadline: values.deadline
        ? dayjs(values.deadline).format('YYYY-MM-DD')
        : null,
    };
    addActionPlan(updatedData, {
      onSuccess: () => {
        setOpen(false);
        form2.resetFields();
      },
    });
  };

  const items = [
    {
      key: '1',
      label: 'All',
      children: (
        <CollapsibleCardList
          isLoading={isLoading}
          filteredData={filteredData}
        />
      ),
    },
    {
      key: '2',
      label: 'Individual',
      children: (
        <CollapsibleCardList
          isLoading={isLoading}
          filteredData={filteredData}
        />
      ),
    },
    {
      key: '3',
      label: 'Action Plans',
      children: <ActionPlans slug={slug} />,
    },
  ];

  const modalHeader = (
    <div
      className="flex justify-center text-xl font-extrabold text-gray-800 p-4"
      data-cy="feedback-conversation-id-slug-page-div-modal-header"
      id="feedback-conversation-id-slug-page-div-modal-header"
    >
      Add Action Plan
    </div>
  );

  return (
    <TabLandingLayout
      buttonTitle="Add Action Plan"
      id="conversationLayoutId"
      data-cy="feedback-conversation-id-slug-page-tab-landing-layout"
      onClickHandler={() => setOpen(true)}
      title={
        <div
          data-cy="feedback-conversation-id-slug-page-div-title"
          id="feedback-conversation-id-slug-page-div-title"
        >
          {' '}
          <Button
            type="link"
            onClick={() => handleRedirectback()}
            data-cy="feedback-conversation-id-slug-page-button-back"
            id="feedback-conversation-id-slug-page-button-back"
          >
            ←
          </Button>{' '}
          <span
            data-cy="feedback-conversation-id-slug-page-span-details"
            id="feedback-conversation-id-slug-page-span-details"
          >
            Details
          </span>
        </div>
      }
      subtitle=""
    >
      <Row
        gutter={[16, 24]}
        data-cy="feedback-conversation-id-slug-page-row"
        id="feedback-conversation-id-slug-page-row"
      >
        <Col
          lg={8}
          md={10}
          xs={24}
          data-cy="feedback-conversation-id-slug-page-col-detail"
          id="feedback-conversation-id-slug-page-col-detail"
        >
          {isLoading ? (
            /* eslint-disable @typescript-eslint/naming-convention */
            Array.from({ length: 2 }).map(
              (
                _ /* eslint-disable @typescript-eslint/naming-convention */,
                index,
              ) => (
                <Skeleton
                  key={index}
                  active
                  paragraph={{ rows: 4 }}
                  avatar
                  data-cy={`feedback-conversation-id-slug-page-skeleton-${index}`}
                />
              ),
            )
          ) : (
            /* eslint-enable @typescript-eslint/naming-convention */
            <ConversationInstanceDetail
              conversationInstance={conversationInstance}
            />
          )}
        </Col>
        <Col
          lg={16}
          md={14}
          xs={24}
          data-cy="feedback-conversation-id-slug-page-col-tabs"
          id="feedback-conversation-id-slug-page-col-tabs"
        >
          <Card
            data-cy="feedback-conversation-id-slug-page-card-tabs"
            id="feedback-conversation-id-slug-page-card-tabs"
          >
            <Tabs
              items={items}
              activeKey={activeTab}
              tabBarGutter={16}
              size="small"
              onChange={(active: string) => setActiveTab(active)}
              tabBarStyle={{ textAlign: 'center' }}
              data-cy="feedback-conversation-id-slug-page-tabs"
              id="feedback-conversation-id-slug-page-tabs"
            />
          </Card>
        </Col>
      </Row>
      <CustomDrawerLayout
        open={open}
        onClose={() => setOpen(false)}
        modalHeader={modalHeader}
        width="40%"
        data-cy="feedback-conversation-id-slug-page-drawer"
      >
        <CreateActionPlans
          slug={slug}
          onFinish={(values) => handleCreateActionPlan(values)}
          form2={form2}
          data-cy="feedback-conversation-id-slug-page-create-action-plans"
        />
      </CustomDrawerLayout>
    </TabLandingLayout>
  );
};

export default Index;

import React, { useEffect } from 'react';
import { Modal, Input, Button, Form } from 'antd';
import { MdClose, MdOutlineEdit } from 'react-icons/md';

import { useMeetingStore } from '@/store/uistate/features/conversation/meeting';
import {
  useCreateMeetingAgendaBulk,
  useUpdateMeetingAgenda,
} from '@/store/server/features/CFR/meeting/agenda/mutations';
import { meetingFormRequiredMark } from '../../_component/meetingFormRequiredMark';

interface AgendaModalProps {
  visible: boolean;
  onClose: () => void;
  meetingId: string;
  meetingAgenda: any;
}

const AgendaModal: React.FC<AgendaModalProps> = ({
  visible,
  onClose,
  meetingId,
  meetingAgenda,
}) => {
  const { mutate: createMeetingAgenda, isLoading: createLoading } =
    useCreateMeetingAgendaBulk();
  const { mutate: updateMeetingAgenda, isLoading: updateLoading } =
    useUpdateMeetingAgenda();

  const [form] = Form.useForm();
  const { setMeetingAgenda } = useMeetingStore();
  const agendaItems = Form.useWatch('agendaItems', form) ?? [];

  const handleClose = () => {
    setMeetingAgenda(null);
    form.resetFields();
    onClose();
  };

  const onFinish = (values: any) => {
    const finalValue = (values.agendaItems || []).map((item: any) => ({
      ...item,
      meetingId,
    }));

    const finalEditValue = { ...values?.agendaItems[0], meetingId };

    if (meetingAgenda == null) {
      createMeetingAgenda(finalValue, {
        onSuccess: handleClose,
      });
    } else {
      updateMeetingAgenda(finalEditValue, {
        onSuccess: handleClose,
      });
    }
  };

  useEffect(() => {
    if (meetingAgenda) {
      form.setFieldsValue({
        agendaItems: [meetingAgenda],
      });
    } else {
      form.setFieldsValue({
        agendaItems: [{ agenda: '' }],
      });
    }
  }, [meetingAgenda]);

  const loading = createLoading || updateLoading;
  const modalTitle = meetingAgenda == null ? 'Meeting Agenda' : 'Edit agenda';

  const footer = (
    <div
      className="flex justify-end gap-2"
      data-cy="feedback-meeting-components-addagenda-div-footer"
      id="feedback-meeting-components-addagenda-div-footer"
    >
      <Button
        loading={loading}
        className="flex h-[32px] items-center justify-center rounded-[8px] !border !border-solid !border-[#D9D9D9] bg-white px-[15px] py-0 text-[14px] font-normal text-[#595959] hover:text-[#262626]"
        onClick={handleClose}
        data-cy="feedback-meeting-components-addagenda-button-cancel"
        id="feedback-meeting-components-addagenda-button-cancel"
      >
        Cancel
      </Button>
      <Button
        loading={loading}
        className="flex h-[32px] items-center justify-center rounded-[8px] border-none bg-[#1E40AF] px-[15px] py-0 text-[14px] font-normal hover:bg-[#1e3a8a]"
        type="primary"
        onClick={() => form.submit()}
        data-cy="feedback-meeting-components-addagenda-button-submit"
        id="feedback-meeting-components-addagenda-button-submit"
      >
        {meetingAgenda == null ? 'Create' : 'Update'}
      </Button>
    </div>
  );

  return (
    <Modal
      title={
        <span
          className="text-[16px] font-bold text-black/70"
          data-cy="feedback-meeting-components-addagenda-header"
        >
          {modalTitle}
        </span>
      }
      open={visible}
      onCancel={handleClose}
      width={675}
      footer={footer}
      closeIcon={<MdClose size={16} className="text-[#8c8c8c]" />}
      className="okr-settings-modal meeting-agenda-modal"
      data-cy="feedback-meeting-components-addagenda-modal"
    >
      <style
        jsx
        global
        data-cy="feedback-meeting-components-addagenda-modal-global-styles"
      >{`
        .okr-settings-modal .ant-modal-content {
          padding: 0 !important;
        }
        .okr-settings-modal .ant-modal-header {
          padding: 20px 24px 8px 24px !important;
          border-bottom: none !important;
          margin-bottom: 0 !important;
        }
        .okr-settings-modal .ant-modal-body {
          padding: 12px 24px !important;
        }
        .okr-settings-modal .ant-modal-footer {
          padding: 1px 24px 20px 24px !important;
          border-top: none !important;
          margin-top: 0 !important;
        }
        .meeting-agenda-modal .ant-input {
          height: 40px !important;
          min-height: 40px !important;
        }
      `}</style>
      <Form
        form={form}
        layout="vertical"
        className="meeting-form-field-spacing"
        requiredMark={meetingFormRequiredMark}
        onFinish={onFinish}
        data-cy="feedback-meeting-components-addagenda-form"
        id="feedback-meeting-components-addagenda-form"
      >
        <Form.List
          name="agendaItems"
          data-cy="feedback-meeting-components-addagenda-list"
        >
          {(fields, { add, remove }) => (
            <>
              {fields.map(({ key, name, fieldKey, ...restField }, index) => {
                if (index === 0) {
                  return (
                    <div
                      key={key}
                      className="mb-2"
                      data-cy={`feedback-meeting-components-addagenda-item-${key}`}
                      id={`feedback-meeting-components-addagenda-item-${key}`}
                    >
                      <Form.Item
                        {...restField}
                        name={[name, 'agenda']}
                        fieldKey={[fieldKey ?? 0, 'agenda']}
                        rules={[
                          {
                            required: true,
                            message: 'Meeting agenda is required',
                          },
                        ]}
                        className="w-full"
                        label="Meeting Agenda"
                        data-cy={`feedback-meeting-components-addagenda-form-item-${key}`}
                        id={`feedback-meeting-components-addagenda-form-item-${key}`}
                      >
                        <Input
                          placeholder="Input"
                          data-cy={`feedback-meeting-components-addagenda-input-${key}`}
                          id={`feedback-meeting-components-addagenda-input-${key}`}
                        />
                      </Form.Item>
                    </div>
                  );
                }

                const agendaText = agendaItems?.[name]?.agenda || '';
                return (
                  <div
                    key={key}
                    className="mb-2 flex items-center justify-between rounded-md border border-[#d9d9d9] bg-white px-3 py-2"
                    data-cy={`feedback-meeting-components-addagenda-item-${key}`}
                    id={`feedback-meeting-components-addagenda-item-${key}`}
                  >
                    <span
                      className="min-w-0 flex-1 truncate pr-2 text-[14px] font-normal text-[#262626]"
                      data-cy={`feedback-meeting-components-addagenda-item-text-${key}`}
                    >
                      {agendaText}
                    </span>
                    <div
                      className="flex items-center gap-2"
                      data-cy={`feedback-meeting-components-addagenda-item-actions-${key}`}
                    >
                      <button
                        type="button"
                        className="flex h-[22px] w-[22px] items-center justify-center rounded-[4px] border border-[#D9D9D9] bg-white text-[#667085] hover:bg-[#FAFAFA]"
                        onClick={() => {
                          form.setFieldValue(
                            ['agendaItems', 0, 'agenda'],
                            agendaText,
                          );
                          remove(name);
                        }}
                        aria-label="Edit agenda"
                        data-cy={`feedback-meeting-components-addagenda-item-edit-${key}`}
                      >
                        <MdOutlineEdit size={16} />
                      </button>
                      <button
                        type="button"
                        className="flex h-[22px] w-[22px] items-center justify-center rounded-[4px] border border-[#FF4D4F] bg-white text-[#FF4D4F] hover:bg-[#FFF1F0]"
                        onClick={() => remove(name)}
                        aria-label="Remove agenda"
                        data-cy={`feedback-meeting-components-addagenda-item-remove-${key}`}
                      >
                        <MdClose size={16} />
                      </button>
                    </div>
                  </div>
                );
              })}
              {meetingAgenda == null && (
                <div
                  className="mb-2 flex justify-center"
                  data-cy="feedback-meeting-components-addagenda-div-add-button"
                  id="feedback-meeting-components-addagenda-div-add-button"
                >
                  <Button
                    className="h-[34px] min-w-[96px] rounded-[8px] border-none bg-[#1E40AF] px-4 text-[14px] font-normal hover:bg-[#1e3a8a]"
                    type="primary"
                    onClick={async () => {
                      const current = form.getFieldValue([
                        'agendaItems',
                        0,
                        'agenda',
                      ]);
                      if (!current || !String(current).trim()) {
                        await form.validateFields([
                          ['agendaItems', 0, 'agenda'],
                        ]);
                        return;
                      }
                      add({ agenda: String(current).trim() });
                      form.setFieldValue(['agendaItems', 0, 'agenda'], '');
                    }}
                    data-cy="feedback-meeting-components-addagenda-button-add-entry"
                    id="feedback-meeting-components-addagenda-button-add-entry"
                  >
                    Add Agenda
                  </Button>
                </div>
              )}
            </>
          )}
        </Form.List>
      </Form>
    </Modal>
  );
};

