};

type CommentComponentProps = {
  meetingId: string;
  commentData: any;
  canEditComment: boolean;
};

const CommentComponent: React.FC<CommentComponentProps> = ({
  meetingId,
  commentData,
  canEditComment,
}) => {
  const [form] = Form.useForm();
  const { comments, setComments, commentUpdate, setCommentUpdate } =
    useMeetingStore() as {
      comments: string;
      setComments: (c: string) => void;
      commentUpdate: any | null;
      setCommentUpdate: (c: any | null) => void;
    };
  const { mutate: createComment, isLoading: createLoading } =
    useCreateComments();
  const { mutate: updateComment, isLoading: updateLoading } =
    useUpdateComments();
  const { mutate: deleteComment, isLoading: deleteLoading } =
    useDeleteComments();
  const { userId } = useAuthenticationStore();

  const handleSubmit = () => {
    if (commentUpdate) {
      if (comments == '' || comments == '<p></p>') {
        NotificationMessage.warning({
          message: 'Warning',
          description: 'Please add Comment first',
        });
      } else {
        updateComment(
          { comments: comments, userId, id: commentUpdate.id },
          {
            onSuccess() {
              setComments('');
              setCommentUpdate(null);
            },
          },
        );
      }
    } else {
      if (comments == '' || comments == '<p></p>') {
        NotificationMessage.warning({
          message: 'Warning',
          description: 'Please add Comment first',
        });
      } else {
        createComment(
          { meetingId, comments: comments, userId },
          {
            onSuccess() {
              setComments('');
            },
          },
        );
      }
    }
  };

  const handleUpdate = (comment: any) => {
    setCommentUpdate(comment);
    setComments(comment.comments);
  };

  const { data: attendeesData, isLoading: loadingAttendees } =
    useGetMeetingAttendees(meetingId);
  const { data: employeeData } = useGetAllUsers();

  const getEmployeeData = (id: string) => {
    return employeeData?.items?.find((emp: any) => emp?.id === id) || {};
  };

  // 🧠 Memoize attendees
  const attendees = useMemo(() => {
    if (!attendeesData?.items || !employeeData?.items) return [];

    return attendeesData.items
      .filter((item: any) => item.userId)
      .map((item: any) => {
        const user = getEmployeeData(item.userId);
        return {
          id: item.userId,
          label:
            user?.firstName + ' ' + user?.middleName + ' ' + user?.lastName,
          profileImage: user?.profileImage,
        };
      });
  }, [attendeesData, employeeData]);

  const editor = useEditor(
    {
      extensions: [
        StarterKit,
        Underline,
        TextStyle,
        TextAlign.configure({ types: ['heading', 'paragraph'] }),
        Placeholder.configure({
          placeholder: 'Type @ to mention attendees...',
        }),
        createMentionExtension(attendees),
      ],
      content: comments,
      // editable: canEdit,
    },
    [loadingAttendees, attendees],
  );

  // Update editor content when content from store changes
  useEffect(() => {
    if (editor && comments !== undefined) {
      const currentContent = editor.getHTML();
      if (currentContent !== comments) {
        editor.commands.setContent(comments);
      }
    }
  }, [editor, comments]);

  // Set up editor update listener
  useEffect(() => {
    if (!editor) return;

    const handleUpdate = () => {
      const html = editor.getHTML();
      setComments(html);
    };

    editor.on('update', handleUpdate);

    return () => {
      editor.off('update', handleUpdate);
    };
  }, [editor, setComments]);

  function handleDelete(id: string) {
    deleteComment(id);
  }
  return (
    <div
      className="w-full"
      data-cy="feedback-meeting-components-comments-div"
      id="feedback-meeting-components-comments-div"
    >
      {commentData?.map((comment: any) => (
        <Row
          key={comment.id}
          justify="space-between"
          align="middle"
          className="w-full p-2 border-b-2"
          data-cy={`feedback-meeting-components-comments-row-${comment.id}`}
          id={`feedback-meeting-components-comments-row-${comment.id}`}
        >
          <div
            className="grid grid-cols-[auto_1fr_auto] items-center gap-2"
            data-cy={`feedback-meeting-components-comments-grid-${comment.id}`}
            id={`feedback-meeting-components-comments-grid-${comment.id}`}
          >
            <EmployeeDetails
              type="all"
              empId={comment.userId}
              data-cy={`feedback-meeting-components-comments-employee-details-${comment.id}`}
            />

            <div
              className="text-gray-700 font-semibold text-[12px]"
              dangerouslySetInnerHTML={{ __html: comment.comments }}
              data-cy={`feedback-meeting-components-comments-text-${comment.id}`}
              id={`feedback-meeting-components-comments-text-${comment.id}`}
            />
            {comment.userId == userId &&
              (!deleteLoading ? (
                <CommentActionMenu
                  onEdit={() => handleUpdate(comment)}
                  onDelete={() => handleDelete(comment.id)}
                  data-cy={`feedback-meeting-components-comments-action-menu-${comment.id}`}
                />
              ) : (
                <LoadingOutlined
                  className="text-gray-500"
                  id={`feedback-meeting-components-comments-loading-icon-${comment.id}`}
                  data-cy={`feedback-meeting-components-comments-loading-icon-${comment.id}`}
                />
              ))}
          </div>
        </Row>
      ))}
      {canEditComment && (
        <Form
          form={form}
          layout="inline"
          className="w-full mt-4"
          data-cy="feedback-meeting-components-comments-form"
        >
          <div
            className="w-full flex flex-col gap-2"
            id="feedback-meeting-components-comments-div-editor"
            data-cy="feedback-meeting-components-comments-div-editor"
          >
            <EditorContent
              className="min-h-20 border rounded-md px-2 py-1 focus:outline-none"
              editor={editor}
              data-cy="feedback-meeting-components-comments-editor"
            />

            <div
              className="flex  justify-end mr-0"
              data-cy="feedback-meeting-components-comments-div-submit"
              id="feedback-meeting-components-comments-div-submit"
            >
              <Button
                loading={createLoading || updateLoading}
                type="primary"
                onClick={() => handleSubmit()}
                className="w-24"
                data-cy="feedback-meeting-components-comments-button-send"
              >
                Send
              </Button>
            </div>
          </div>
        </Form>
      )}
    </div>
  );
};

export default CommentComponent;

