    isEmp,
    guest,
    id,
    attendanceStatus,
    absentismReason,
    lateBy,
    compact = false,
    avatarOnly = false,
    popTrigger = 'click',
  }: {
    empId: string;
    isEmp: boolean;
    guest: any;
