'use client';

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Input, Select, DatePicker, Button, Popover } from 'antd';
import { CloseOutlined, SearchOutlined } from '@ant-design/icons';
import { MdClose, MdOutlineFilterAlt } from 'react-icons/md';
import dayjs, { type Dayjs } from 'dayjs';
import { useMeetingStore } from '@/store/uistate/features/conversation/meeting';
import { useGetUserDepartment } from '@/store/server/features/okrplanning/okr/department/queries';
import { useGetAllMeetingType } from '@/store/server/features/CFR/meeting/type/queries';
import { useDebounce } from '../../../../../../utils/useDebounce';
import { MeetingFormOptionsMultiSelect } from './meetingFormAssigneeStyleSelects';
import './meetingListFiltersDropdown.css';
import filterStyles from './meetingListFilters.module.css';

const { RangePicker } = DatePicker;

type LabelValueOption = { value: string; label: string };

export default function MeetingListFilters() {
  const {
    setDepartmentId,
    departmentId,
    meetingTypeId,
    setMeetingTypeId,
    startAt,
    setStartAt,
    endAt,
    setEndAt,
    setTitle,
  } = useMeetingStore();

  const [filterOpen, setFilterOpen] = useState(false);
  const [draftMeetingTypeId, setDraftMeetingTypeId] = useState<string | null>(
    null,
  );
  const [draftDepartmentIds, setDraftDepartmentIds] = useState<string[]>([]);
  const [draftRange, setDraftRange] = useState<
    [Dayjs | null, Dayjs | null] | null
  >(null);

  const { data: Departments } = useGetUserDepartment();
  const { data: meetTypes } = useGetAllMeetingType();

  const departmentOptions: LabelValueOption[] =
    Departments?.map((i) => ({
      value: String(i.id),
      label: String(i?.name ?? ''),
    })) ?? [];
  const meetingOptions: LabelValueOption[] | undefined = meetTypes?.items?.map(
    (i: { id: string; name: string }) => ({
      value: i.id,
      label: i.name,
    }),
  );

  const appliedDepartmentIds = useMemo(() => {
    if (!departmentId) return [] as string[];
    return Array.isArray(departmentId)
      ? departmentId.map((x) => String(x))
      : [String(departmentId)];
  }, [departmentId]);

  const appliedFilterChips = useMemo(() => {
    type Chip = { key: string; label: string; onRemove: () => void };
    const chips: Chip[] = [];

    if (meetingTypeId) {
      const label =
        meetingOptions?.find((o) => String(o.value) === String(meetingTypeId))
          ?.label ?? String(meetingTypeId);
      chips.push({
        key: `meeting-type-${meetingTypeId}`,
        label,
        onRemove: () => setMeetingTypeId(null),
      });
    }

    appliedDepartmentIds.forEach((id) => {
      const label =
        departmentOptions.find((o) => String(o.value) === String(id))?.label ??
        id;
      chips.push({
        key: `dept-${id}`,
        label,
        onRemove: () => {
          const next = appliedDepartmentIds.filter((x) => x !== id);
          setDepartmentId(next.length ? (next as unknown as string) : null);
        },
      });
    });

    if (startAt && endAt) {
      const a = dayjs(startAt).format('DD MMM YYYY');
      const b = dayjs(endAt).format('DD MMM YYYY');
      chips.push({
        key: 'date-range',
        label: `${a} – ${b}`,
        onRemove: () => {
          setStartAt('');
          setEndAt('');
        },
      });
    }

    return chips;
  }, [
    meetingTypeId,
    appliedDepartmentIds,
    startAt,
    endAt,
    meetingOptions,
    departmentOptions,
    setMeetingTypeId,
    setDepartmentId,
    setStartAt,
    setEndAt,
  ]);

  const syncDraftFromStore = useCallback(() => {
    setDraftMeetingTypeId(meetingTypeId ?? null);
    setDraftDepartmentIds(
      !departmentId
        ? []
        : Array.isArray(departmentId)
          ? departmentId.map((x) => String(x))
          : [String(departmentId)],
    );
    setDraftRange(
      startAt && endAt
        ? ([dayjs(startAt), dayjs(endAt)] as [Dayjs, Dayjs])
        : null,
    );
  }, [meetingTypeId, departmentId, startAt, endAt]);

  useEffect(() => {
    if (filterOpen) {
      syncDraftFromStore();
    }
  }, [filterOpen, syncDraftFromStore]);

  const handleResetDraft = () => {
    setDraftMeetingTypeId(null);
    setDraftDepartmentIds([]);
    setDraftRange(null);
  };

  const handleApplyFilters = () => {
    setMeetingTypeId(draftMeetingTypeId);
    setDepartmentId(
      draftDepartmentIds.length
        ? (draftDepartmentIds as unknown as string)
        : null,
    );
    if (draftRange?.[0] && draftRange?.[1]) {
      setStartAt(draftRange[0] as unknown as string);
      setEndAt(draftRange[1] as unknown as string);
    } else {
      setStartAt('');
      setEndAt('');
    }
    setFilterOpen(false);
  };

  const handleTitleChange = (value: string) => {
    setTitle(value);
  };
  const onSearchChange = useDebounce(handleTitleChange, 2000);
  const handleSearchInput = (value: string) => {
    onSearchChange(value);
  };

  const filterPanel = (
    <div
      className={`flex w-[min(100vw-1.5rem,520px)] max-w-[520px] flex-col overflow-hidden rounded-xl bg-white shadow-lg ${filterStyles.panel}`}
      onMouseDown={(e) => e.preventDefault()}
      data-cy="feedback-meeting-filters-popover"
    >
      <div
        className="flex items-start justify-between gap-3 px-4 pb-0 pt-4"
        data-cy="feedback-meeting-filters-popover-header-row"
      >
        <div
          className="min-w-0"
          data-cy="feedback-meeting-filters-popover-header-text-wrap"
        >
          <h3
            className="m-0 text-base font-semibold leading-tight text-[#030712]"
            data-cy="feedback-meeting-filters-title"
          >
            Filter
          </h3>
          <p
            className="mb-0 mt-1 text-sm font-normal leading-snug text-black/45"
            data-cy="feedback-meeting-filters-subtitle"
          >
            Select all filters that apply
          </p>
        </div>
        <button
          type="button"
          className="flex size-6 shrink-0 items-center justify-center rounded-md border-0 bg-transparent text-gray-600 transition-colors hover:bg-black/[0.04] hover:text-gray-800"
          aria-label="Close filters"
          onClick={() => setFilterOpen(false)}
          data-cy="feedback-meeting-filters-close"
        >
          <MdClose size={14} aria-hidden />
        </button>
      </div>

      <div
        className="flex flex-col gap-4 p-4"
        data-cy="feedback-meeting-filters-popover-body"
      >
        <div
          className="flex min-w-0 flex-col gap-1.5"
          data-cy="feedback-meeting-filters-field-meeting-type"
        >
          <span
            className="text-[14px] font-normal leading-none text-[#030712]"
            data-cy="feedback-meeting-filters-label-meeting-type"
          >
            Meeting type
          </span>
          <Select
            showSearch
            placeholder="Select"
            allowClear
            filterOption={(input: string, option) =>
              (option?.label ?? '')
                .toString()
                .toLowerCase()
                .includes(input.toLowerCase())
            }
            options={meetingOptions}
            className="w-full"
            value={draftMeetingTypeId ?? undefined}
            onChange={(value) => setDraftMeetingTypeId(value ?? null)}
            data-cy="feedback-meeting-component-meetinglist-select-meeting-type"
            id="feedback-meeting-component-meetinglist-select-meeting-type"
          />
        </div>

        <div
          className="flex min-w-0 flex-col gap-1.5"
          data-cy="feedback-meeting-filters-field-department"
        >
          <span
            className="text-[14px] font-normal leading-none text-[#030712]"
            data-cy="feedback-meeting-filters-label-department"
          >
            Department
          </span>
          <div
            className={filterStyles.filterSelectScope}
            data-cy="feedback-meeting-filters-department-select-scope"
          >
            <MeetingFormOptionsMultiSelect
              value={draftDepartmentIds}
              onChange={setDraftDepartmentIds}
              options={departmentOptions}
              hint="Select"
              dropdownClassName="meeting-list-filter-dept-dropdown"
              data-cy="feedback-meeting-component-meetinglist-select-department"
            />
          </div>
        </div>

        <div
          className="flex min-w-0 flex-col gap-1.5"
          data-cy="feedback-meeting-filters-field-date-range"
        >
          <span
            className="text-[14px] font-normal leading-none text-[#030712]"
            data-cy="feedback-meeting-filters-label-meeting-date"
          >
            Meeting date
          </span>
          <RangePicker
            value={draftRange}
            onChange={(values) => setDraftRange(values)}
            format="DD MMM YYYY"
            className="w-full"
            placeholder={['Select date', 'Select date']}
            data-cy="feedback-meeting-component-meetinglist-range-picker"
            id="feedback-meeting-component-meetinglist-range-picker"
          />
        </div>
      </div>

      <div
        className="flex flex-wrap items-center justify-end gap-3 px-4 pb-3 pt-0"
        data-cy="feedback-meeting-filters-popover-footer"
      >
        <Button
          type="default"
          onClick={handleResetDraft}
          className="!h-8 !min-h-8 rounded-lg !border !border-solid !border-[#D9D9D9] !bg-white !px-[15px] text-[14px] font-normal !text-[#030712] shadow-none hover:!border-[#D9D9D9] hover:!bg-[#fafafa] hover:!text-[#030712]"
          data-cy="feedback-meeting-filters-reset"
        >
          Reset
        </Button>
        <Button
          type="primary"
          onClick={handleApplyFilters}
          className="!h-8 !min-h-8 rounded-lg !border-none !bg-[#1E40AF] !px-[15px] text-[14px] font-normal !text-white shadow-none hover:!bg-[#1e3a8a] hover:!text-white"
          data-cy="feedback-meeting-filters-save"
        >
          Save filter
        </Button>
      </div>
    </div>
  );

  return (
    <div
      className="flex w-full min-w-0 flex-wrap items-center justify-between gap-3"
      data-cy="feedback-meeting-component-meetinglist-div-filters"
      id="feedback-meeting-component-meetinglist-div-filters"
    >
      <div
        className="flex h-8 w-[310px] max-w-full shrink-0 items-center overflow-hidden rounded-lg border border-[#D9D9D9] bg-white"
        data-cy="feedback-meeting-search-group"
      >
        <Input
          allowClear
          variant="borderless"
          onChange={(e) => handleSearchInput(e.target.value)}
          placeholder="Search meeting"
          rootClassName="!flex !h-8 min-w-0 flex-1 !items-center"
          className="rounded-none border-0 bg-transparent text-sm shadow-none"
          classNames={{
            input: '!h-8 !min-h-0 !py-0 !leading-8 text-sm align-middle',
            suffix: '!flex !items-center',
          }}
          data-cy="feedback-meeting-component-meetinglist-input-search"
          id="feedback-meeting-component-meetinglist-input-search"
        />
        <div
          className="w-px shrink-0 self-stretch bg-[#D9D9D9]"
          aria-hidden
          data-cy="feedback-meeting-filters-search-divider"
        />
        <button
          type="button"
          className="flex h-8 w-8 shrink-0 items-center justify-center border-0 bg-white text-gray-600 hover:bg-gray-50"
          aria-label="Search"
          data-cy="feedback-meeting-search-icon-button"
        >
          <SearchOutlined className="text-base" />
        </button>
      </div>

      <div
        className="flex min-w-0 flex-1 flex-wrap items-center justify-end gap-2"
        data-cy="feedback-meeting-applied-filters-row"
      >
        {appliedFilterChips.map(({ key, label, onRemove }) => (
          <span
            key={key}
            className="inline-flex !h-[22px] !min-h-[22px] max-w-[min(100%,240px)] shrink-0 items-center gap-1.5 rounded-md border border-solid border-[#D9D9D9] bg-[rgba(0,0,0,0.02)] px-2 py-0 text-[12px] font-normal leading-none text-black/70"
            data-cy={`feedback-meeting-applied-filter-chip-${key}`}
          >
            <button
              type="button"
              className="m-0 flex size-4 shrink-0 items-center justify-center border-0 bg-transparent p-0 text-black/60 hover:text-black/80"
              onClick={onRemove}
              aria-label={`Remove filter ${label}`}
              data-cy={`feedback-meeting-applied-filter-chip-remove-${key}`}
            >
              <CloseOutlined className="text-[10px]" />
            </button>
            <span
              className="min-w-0 truncate"
              title={label}
              data-cy={`feedback-meeting-applied-filter-chip-label-${key}`}
            >
              {label}
            </span>
          </span>
        ))}

        <Popover
          open={filterOpen}
          onOpenChange={setFilterOpen}
          trigger="click"
          placement="bottomRight"
          arrow={false}
          styles={{ body: { padding: 0 } }}
          content={filterPanel}
        >
          <Button
            type="default"
            className="!h-8 shrink-0 flex min-h-8 items-center gap-2 rounded-lg border-[#D9D9D9] px-3 text-sm font-normal leading-none text-[#030712] shadow-none hover:border-[#D9D9D9] hover:text-[#030712]"
            icon={<MdOutlineFilterAlt className="text-base" aria-hidden />}
            data-cy="feedback-meeting-filters-menu-button"
          >
            Filter
          </Button>
        </Popover>
      </div>
    </div>
  );
}

import React, { useEffect } from 'react';
import {
  Form,
  Input,
  Button,
  Select,
  Checkbox,
  Space,
  Switch,
  Popconfirm,
} from 'antd';
import { MinusCircleOutlined, PlusOutlined } from '@ant-design/icons';
import { v4 as uuidv4 } from 'uuid';
import { FieldType } from '@/types/enumTypes';
import { ConversationStore } from '@/store/uistate/features/conversation';
import {
  useAddQuestionSetOnConversationType,
  useUpdateQuestionSetWithQuestionsOnConversationType,
} from '@/store/server/features/CFR/conversation/mutation';
import { useConversationTypes } from '@/store/server/features/conversation/queries';
import { ConversationTypeItems } from '@/store/server/features/CFR/conversation/action-plan/interface';
import CustomDrawerLayout from '@/components/common/customDrawer';

const { Option } = Select;
const QuestionSetForm = () => {
  const {
    activeTab,
    editableData,
    setEditableData,
    setOpen,
    questions,
    setQuestions,
  } = ConversationStore();
  const { open } = ConversationStore();

  const [form] = Form.useForm();
  const { mutate: createConversationQuestionSet, isLoading: createIsLoading } =
    useAddQuestionSetOnConversationType();
  const { mutate: updateConversationQuestionSet, isLoading: updateIsLoading } =
    useUpdateQuestionSetWithQuestionsOnConversationType();
  const { data: getAllConversationType } = useConversationTypes();

  const handleAddQuestion = () => {
    const currentQuestions = questions;

    const updatedQuestions = [
      ...currentQuestions,
      {
        id: uuidv4(),
        conversationTypeId: activeTab,
        question: '',
        fieldType: FieldType.SHORT_TEXT,
        field: [],
        required: false,
        action: null,
      },
    ];
    setQuestions(updatedQuestions);
  };

  const handleRemoveQuestion = (id: any) => {
    const filteredQuestions = questions.filter((q: any) => q.id !== id);
    setQuestions(filteredQuestions);
  };

  const handleChangeQuestion = (id: any, key: any, value: any) => {
    const currentQuestions = questions;
    const updatedQuestions = currentQuestions.map((q: any) => {
      if (q.id === id) {
        const requiresOptions = [
          FieldType.DROPDOWN,
          FieldType.MULTIPLE_CHOICE,
          FieldType.CHECKBOX,
          FieldType.RADIO,
          ,
        ].includes(value);

        // If switching to a field type that requires options, add two empty options
        if (
          key === 'fieldType' &&
          requiresOptions &&
          (!q.field || q.field.length === 0)
        ) {
          return {
            ...q,
            [key]: value,
            field: [
              { id: uuidv4(), value: '' },
              { id: uuidv4(), value: '' },
            ],
          };
        }
        return { ...q, [key]: value };
      }
      return q;
    });
    setQuestions(updatedQuestions);
  };

  const activeTabName =
    getAllConversationType?.items?.find(
      (item: ConversationTypeItems) => item.id === activeTab,
    )?.name || '';

  const handleAddOption = (questionId: any) => {
    const currentQuestions = questions;
    const updatedQuestions = currentQuestions.map((q: any) =>
      q.id === questionId
        ? {
            ...q,
            field: [...q.field, { id: uuidv4(), value: '' }],
          }
        : q,
    );
    setQuestions(updatedQuestions);
  };

  const handleChangeOption = (questionId: any, optionId: any, value: any) => {
    const currentQuestions = questions;
    const updatedQuestions = currentQuestions.map((q: any) =>
      q.id === questionId
        ? {
            ...q,
            field: q.field.map((opt: any) =>
              opt.id === optionId ? { ...opt, value } : opt,
            ),
          }
        : q,
    );
    setQuestions(updatedQuestions);
  };

  const handleRemoveOption = (questionId: any, optionId: any) => {
    const currentQuestions = questions;
    const question = currentQuestions.find((q: any) => q.id === questionId);

    // Prevent removing if only 2 options remain
    if (question?.field?.length <= 2) {
      return;
    }

    const updatedQuestions = currentQuestions.map((q: any) =>
      q.id === questionId
        ? {
            ...q,
            field: q.field.filter((opt: any) => opt.id !== optionId),
          }
        : q,
    );
    setQuestions(updatedQuestions);
  };

  const modalHeader = (
    <div
      className="flex justify-center text-xl font-extrabold text-gray-800 p-4"
      data-cy="question-set-form-header"
      id="questionSetFormHeader"
    >
      Add New {activeTabName}
    </div>
  );

  const handleSubmit = (values: any) => {
    const payload = { ...values, conversationTypeId: activeTab, questions };
    if (editableData !== null) {
      updateConversationQuestionSet(payload, {
        onSuccess: () => {
          setEditableData(null);
          setQuestions([]);
          form.resetFields();
        },
      });
    } else {
      createConversationQuestionSet(payload, {
        onSuccess: () => {
          form.resetFields();
          setQuestions([]);
          setOpen(false);
        },
      });
    }
  };

  useEffect(() => {
    if (!editableData) {
      form.resetFields();
      setQuestions([]);
      return;
    }
    if (editableData !== null) {
      setQuestions(editableData.conversationsQuestions || []);
      form.setFieldsValue({
        name: editableData.name || '',
        id: editableData.id || '',
        active: editableData.active ?? true,
        conversationTypeId: editableData.conversationTypeId || '',
        conversationsQuestions: editableData.conversationsQuestions || [],
      });
    }

    setQuestions(editableData.conversationsQuestions || []);

    form.setFieldsValue({
      name: editableData.name || '',
      id: editableData.id || '',
      active: editableData.active ?? true,
      conversationTypeId: editableData.conversationTypeId || '',
      conversationsQuestions: editableData.conversationsQuestions || [],
    });
  }, [editableData, form]);

  const checkQuestions = () => {
    if (questions && questions.length > 0) {
      const hasEmptyQuestion = questions.some((q: any) => !q.question.trim());
      if (hasEmptyQuestion) {
        return Promise.reject(new Error('Question text cannot be empty.'));
      }

      // Check if options are required and present (at least 2)
      const hasInvalidOptions = questions.some((q: any) => {
        const requiresOptions = [
          FieldType.DROPDOWN,
          FieldType.MULTIPLE_CHOICE,
          FieldType.RADIO,
        ].includes(q.fieldType);

        return requiresOptions && (!q.field || q.field.length < 2);
      });

      if (hasInvalidOptions) {
        return Promise.reject(
          new Error(
            'Questions with Dropdown, Multiple Choice, or Radio types must have at least two options.',
          ),
        );
      }

      return Promise.resolve();
    }
    return Promise.reject(new Error('You must add at least one question.'));
  };

  // Add this section where the options are rendered
  const renderOptionsSection = (q: any) => {
    const requiresOptions = [
      FieldType.DROPDOWN,
      FieldType.CHECKBOX,
      FieldType.MULTIPLE_CHOICE,
      FieldType.RADIO,
    ].includes(q.fieldType);

    if (!requiresOptions) return null;

    return (
      <div
        style={{ marginTop: '8px' }}
        data-cy={`question-set-form-question-options-${q.id}`}
        id={`questionSetFormQuestionOptions${q.id}`}
      >
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}
          data-cy={`question-set-form-question-options-header-${q.id}`}
          id={`questionSetFormQuestionOptionsHeader${q.id}`}
        >
          <p
            data-cy={`question-set-form-question-options-label-${q.id}`}
            id={`questionSetFormQuestionOptionsLabel${q.id}`}
          >
            Options:
          </p>
          {q.field?.length < 2 && (
            <p
              style={{ color: 'red', fontSize: '12px', margin: 0 }}
              data-cy={`question-set-form-question-options-warning-${q.id}`}
              id={`questionSetFormQuestionOptionsWarning${q.id}`}
            >
              At least 2 options are required
            </p>
          )}
        </div>
        {q?.field?.map((opt: any) => (
          <Space
            key={opt.id}
            align="baseline"
            style={{ marginBottom: '8px' }}
            data-cy={`question-set-form-question-option-${q.id}-${opt.id}`}
            id={`questionSetFormQuestionOption${q.id}${opt.id}`}
          >
            <Input
              placeholder="Enter option value"
              required
              value={opt.value}
              onChange={(e) => handleChangeOption(q.id, opt.id, e.target.value)}
              data-cy={`question-set-form-question-option-input-${q.id}-${opt.id}`}
              id={`questionSetFormQuestionOptionInput${q.id}${opt.id}`}
            />
            <MinusCircleOutlined
              onClick={() => handleRemoveOption(q.id, opt.id)}
              style={{
                color: 'red',
                cursor: q.field.length <= 2 ? 'not-allowed' : 'pointer',
              }}
              disabled={q.field.length <= 2}
              data-cy={`question-set-form-question-option-remove-${q.id}-${opt.id}`}
              id={`questionSetFormQuestionOptionRemove${q.id}${opt.id}`}
            />
          </Space>
        ))}
        <Button
          type="dashed"
          onClick={() => handleAddOption(q.id)}
          icon={<PlusOutlined />}
          style={{ marginTop: '8px', display: 'inline-block' }}
          data-cy={`question-set-form-question-add-option-button-${q.id}`}
          id={`questionSetFormQuestionAddOptionButton${q.id}`}
        >
          Add Option
        </Button>
      </div>
    );
  };

  return (
    <CustomDrawerLayout
      rootClassName="cfr-feedback-settings-drawer"
      open={open && activeTabName !== ''}
      onClose={() => setOpen(false)}
      modalHeader={modalHeader}
      footer={
        <Form.Item
          data-cy="question-set-form-footer"
          id="questionSetFormFooter"
        >
          <div
            className="w-full bg-[#fff] absolute flex justify-center space-x-5 mt-5"
            data-cy="question-set-form-actions"
            id="questionSetFormActions"
          >
            <Popconfirm
              title="Are you sure you want to reset the form?"
              onConfirm={() => {
                setQuestions([]);
                setEditableData(null);
                form.resetFields();
              }}
              okText="Yes"
              cancelText="No"
              data-cy="question-set-form-reset-confirm"
              id="questionSetFormResetConfirm"
            >
              <Button
                type="default"
                data-cy="question-set-form-reset-button"
                id="questionSetFormResetButton"
              >
                Reset
              </Button>
            </Popconfirm>
            {editableData === null ? (
              <Button
                type="primary"
                loading={createIsLoading}
                onClick={() => form.submit()}
                data-cy="question-set-form-submit-button"
                id="questionSetFormSubmitButton"
              >
                Submit
              </Button>
            ) : (
              <Button
                type="primary"
                loading={updateIsLoading}
                onClick={() => form.submit()}
                data-cy="question-set-form-update-button"
                id="questionSetFormUpdateButton"
              >
                Update
              </Button>
            )}
          </div>
        </Form.Item>
      }
      width="40%"
      data-cy="question-set-form-drawer"
    >
      <Form
        layout="vertical"
        form={form}
        onFinish={handleSubmit}
        requiredMark={false}
        data-cy="question-set-form"
        id="questionSetForm"
      >
        <Form.Item
          label={
            <span data-cy="question-set-form-name-label">
              Name{' '}
              <span
                style={{ color: 'red' }}
                data-cy="question-set-form-name-required"
              >
                *
              </span>
            </span>
          }
          name="name"
          rules={[{ required: true, message: 'Please enter a name' }]}
          data-cy="question-set-form-name-field"
          id="questionSetFormNameField"
        >
          <Input
            data-cy="question-set-form-name-input"
            id="questionSetFormNameInput"
          />
        </Form.Item>
        {editableData !== null && (
          <>
            <Form.Item
              hidden
              name="id"
              rules={[{ required: true, message: 'Please enter a name' }]}
              data-cy="question-set-form-id-field"
              id="questionSetFormIdField"
            >
              <Input />
            </Form.Item>
            <Form.Item
              hidden
              name="conversationTypeId"
              rules={[{ required: true, message: 'Please enter a name' }]}
              data-cy="question-set-form-conversation-type-id-field"
              id="questionSetFormConversationTypeIdField"
            >
              <Input
                data-cy="question-set-form-conversation-type-id-input"
                id="questionSetFormConversationTypeIdInput"
              />
            </Form.Item>
          </>
        )}

        <Form.Item
          label={
            <span data-cy="question-set-form-active-label">
              Is Active{' '}
              <span
                style={{ color: 'red' }}
                data-cy="question-set-form-active-required"
              >
                *
              </span>
            </span>
          }
          name="active"
          initialValue={true}
          rules={[
            {
              required: true,
              message:
                'Please check if you want to activate this question set.',
            },
          ]}
          data-cy="question-set-form-active-field"
          id="questionSetFormActiveField"
        >
          <Switch
            data-cy="question-set-form-active-switch"
            id="questionSetFormActiveSwitch"
          />
        </Form.Item>

        <Form.Item
          label={
            <span data-cy="question-set-form-questions-label">
              Questions{' '}
              <span
                style={{ color: 'red' }}
                data-cy="question-set-form-questions-required"
              >
                *
              </span>
            </span>
          }
          name="questions"
          required
          rules={[{ validator: checkQuestions }]}
          data-cy="question-set-form-questions-field"
          id="questionSetFormQuestionsField"
        >
          {questions?.map((q: any) => (
            <div
              key={q.id}
