                ? 'Cancel'
                : 'Back'}
            </Button>

            {!isLastWizardStep ? (
              <Button
                type="primary"
                disabled={
                  !createCategory &&
                  currentStep === 1 &&
                  showFormulaStep &&
                  selectedCriteria?.length > 0 &&
                  totalWeight !== 1
                }
                onClick={async () => {
                  if (createCategory) {
                    form.submit();
                    return;
                  }
                  if (currentStep === 0) {
                    if (!isEditingRecognition) {
                      if (bulkRecognitionItems.length === 0) {
                        setBulkListError(
                          'Please add at least one recognition type',
                        );
                        return;
                      }
                      setBulkListError('');
                      form.setFieldsValue({
                        name: bulkRecognitionItems[0].name,
                        description: bulkRecognitionItems[0].description ?? '',
                      });
                      await form.validateFields(['frequency', 'departmentId']);
                    } else {
                      await form.validateFields([
                        'name',
                        'description',
                        'frequency',
                        'departmentId',
                      ]);
                    }
                    setCurrentStep(1);
                    return;
                  }
                  if (currentStep === 1 && showFormulaStep) {
                    await form.validateFields();
                    setCurrentStep(2);
                  }
                }}
                data-cy="create-recognition-wizard-continue"
              >
                Continue
              </Button>
            ) : (
              <Button
                loading={
                  selectedRecognitionType !== ''
                    ? updateWithCriteriaLoading ||
                      updateFormulaLoading ||
                      updateRecognitionCriteriaLoading
                    : createLoading || createFormulaLoading
                }
                disabled={
                  (isCriteriaOnlyEdit && criteriaOnlyIndex < 0) ||
                  (!createCategory &&
                    !isCriteriaOnlyEdit &&
                    currentStep === 1 &&
                    !showFormulaStep &&
                    selectedCriteria?.length > 0 &&
                    totalWeight !== 1) ||
                  (showFormulaStep && currentStep === 2 && !!formulaError)
                }
                type="primary"
                onClick={() => {
                  if (showFormulaStep && currentStep === 2) {
                    handleWizardFinalSubmit();
                  } else {
                    form.submit();
                  }
                }}
                data-cy="create-recognition-wizard-submit"
              >
                {createCategory
                  ? 'Continue'
                  : selectedRecognitionType !== ''
                    ? 'Update'
                    : 'Create'}
              </Button>
            )}
          </div>
        </Form>
      </Modal>
    </div>
  );
};

