import { useConversationTypes } from '@/store/server/features/CFR/conversation/queries';
import { ConversationTypeItems } from '@/store/server/features/CFR/conversation/action-plan/interface';

const Page = () => {
  const { setOpen, activeTab, setActiveTab } = ConversationStore();
  const { data: getAllConversationType } = useConversationTypes();

  const onChange = (key: string) => {
    setActiveTab(key);
  };
  useEffect(() => {
    setActiveTab(getAllConversationType?.items[0]?.id);
  }, [getAllConversationType]);

  const activeTabName =
    getAllConversationType?.items?.find(
      (item: ConversationTypeItems) => item.id === activeTab,
    )?.name || '';

  // const modalHeader = (
  //   <div className="flex justify-center text-xl font-extrabold text-gray-800 p-4">
  //     Add New {activeTabName}
  //   </div>
  // );

  const items: TabsProps['items'] = getAllConversationType?.items?.map(
    (item: ConversationTypeItems) => ({
      key: item?.id,
      label: item?.name,
      children: <ConversationTypeDetail id={item?.id} />,
    }),
  );

  return (
    <div
      className="p-5 rounded-2xl bg-white h-full"
      data-cy="settings-define-questions-page"
      id="settingsDefineQuestionsPage"
    >
      <div
        className="flex justify-between"
        data-cy="settings-define-questions-header"
        id="settingsDefineQuestionsHeader"
      >
        <span
          className="font-bold text-lg"
          data-cy="settings-define-questions-title"
          id="settingsDefineQuestionsTitle"
        >
          Questions
        </span>
        <AccessGuard
          permissions={[Permissions.createConversationSet]}
          data-cy="settings-define-questions-access-guard"
          id="settingsDefineQuestionsAccessGuard"
        >
          {activeTab !== '' && (
            <Button
              icon={<FaPlus />}
              onClick={() => setOpen(true)}
              type="primary"
              className="h-10 text-xs"
              data-cy="settings-define-questions-add-button"
              id="settingsDefineQuestionsAddButton"
            >
              <span
                className="hidden md:inline"
                data-cy="settings-define-questions-add-button-text"
                id="settingsDefineQuestionsAddButtonText"
              >
                Add new {activeTabName} question-set
              </span>
            </Button>
          )}
        </AccessGuard>
      </div>
      <Tabs
        defaultActiveKey={getAllConversationType?.items[0]?.id}
        items={items}
        onChange={onChange}
        data-cy="settings-define-questions-tabs"
        id="settingsDefineQuestionsTabs"
      />
      <QuestionSetForm data-cy="settings-define-questions-form" />
    </div>
  );
};

export default Page;

import { Col, Modal, Row, Select } from 'antd';
import React from 'react';
import { useDebounce } from '@/utils/useDebounce';
import {
  CalendarData,
  useIncentiveStore,
} from '@/store/uistate/features/incentive/incentive';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import { useFetchIncentiveSessions } from '@/store/server/features/incentive/project/queries';
import {
  useGetActiveFiscalYears,
  useGetAllFiscalYears,
} from '@/store/server/features/organizationStructure/fiscalYear/queries';
import { LuSettings2 } from 'react-icons/lu';
import { useIsMobile } from '@/hooks/useIsMobile';

const IncentiveFilter: React.FC = () => {
  const {
    searchParams,
    setSearchParams,
    selectedSessions,
    setSelectedSessions,
    currentPage,
    pageSize,
    selectedYear,
    setSelectedYear,
    showMobileFilter,
    setShowMobileFilter,
  } = useIncentiveStore();

  const { isMobile, isTablet } = useIsMobile();

  const { data: employeeData } = useGetAllUsers();
  const { data: allSessions } = useFetchIncentiveSessions();
  const { data: activeCalender } = useGetActiveFiscalYears();
  const { data: fiscalYear } = useGetAllFiscalYears(pageSize, currentPage);

  const activeFiscalYearName = activeCalender
    ? activeCalender?.name
    : 'Select Year';

  const handleSearchCategory = async (
    value: string | boolean | any,
    keyValue: keyof typeof searchParams,
  ) => {
    setSearchParams(keyValue, value);
  };

  const onSearchChange = useDebounce(handleSearchCategory, 2000);
  const onSelectChange = handleSearchCategory;

  const handleSearchInput = (
    value: string,
    keyValue: keyof typeof searchParams,
  ) => {
    const trimmedValue = value?.trim();
    onSearchChange(trimmedValue, keyValue);
  };

  const handleCreatedByMonth = (value: string) => {
    onSelectChange(value, 'byMonth');
  };
  const handleCreatedByYear = (yearId: string) => {
    setSelectedYear(yearId);

    const selectedFiscalYear = fiscalYear?.items?.find(
      (year: any) => year?.id === yearId,
    );

    if (selectedFiscalYear) {
      const sessionIds =
        selectedFiscalYear?.sessions?.map((session: any) => session?.id) || [];

      setSelectedSessions(sessionIds);
      onSelectChange(sessionIds, 'bySession');
    } else {
      setSelectedSessions([]);
      onSelectChange([], 'bySession');
    }

    onSelectChange(yearId, 'byYear');
  };

  const handleCreatedBySession = (value: any) => {
    const sessionIds = Array.isArray(value) ? value : [value];
    setSelectedSessions(sessionIds);
    onSelectChange(value, 'bySession');
  };

  const selectedSessionMonths = allSessions?.items
    ?.filter((session: CalendarData) => selectedSessions?.includes(session?.id))
    .flatMap((session: CalendarData) => session?.months);

  React.useEffect(() => {
    if (activeCalender?.sessions?.length) {
      const defaultSessionIds = activeCalender?.sessions?.map(
        (session: any) => session?.id,
      );
      setSelectedSessions(defaultSessionIds);
      onSelectChange(defaultSessionIds, 'bySession');
    }
    if (!selectedYear) {
      onSelectChange('', 'byMonth');
    }
  }, [activeCalender]);

  const Filters = (
    <>
      <Row
        id="incentive-filter-row"
        data-cy="incentive-filter-row"
        gutter={[16, 10]}
        justify="space-between"
      >
        {!(isMobile || isTablet) && (
          <Col
            id="incentive-filter-employee-col"
            data-cy="incentive-filter-employee-col"
            xs={24}
            sm={24}
            md={24}
            lg={10}
            xl={10}
          >
            <Select
              id="incentive-filter-employee-select"
              data-cy="incentive-filter-employee-select"
              onChange={(value) => handleSearchInput(value, 'employee_name')}
              placeholder="Search Employee"
              allowClear
              showSearch
              className="w-full h-14"
              optionFilterProp="children"
              filterOption={(input: any, option: any) =>
                option?.children
                  ?.toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
            >
              {employeeData?.items?.map((items: any) => (
                <Select.Option
                  id={`incentive-filter-employee-option-${items?.id}`}
                  data-cy={`incentive-filter-employee-option-${items?.id}`}
                  key={items?.id}
                  value={items?.id}
                >
                  {items?.firstName + ' ' + items?.middleName}
                </Select.Option>
              ))}
            </Select>
          </Col>
        )}
        <Col
          id="incentive-filter-date-col"
          data-cy="incentive-filter-date-col"
          xs={24}
          sm={24}
          md={24}
          lg={14}
          xl={14}
        >
          <Row
            id="incentive-filter-date-row"
            data-cy="incentive-filter-date-row"
            gutter={[8, 16]}
          >
            <Col
              id="incentive-filter-year-col"
              data-cy="incentive-filter-year-col"
              xs={24}
              sm={24}
              md={24}
              lg={8}
              xl={8}
            >
              <Select
                id="incentive-filter-year-select"
                data-cy="incentive-filter-year-select"
                allowClear
                placeholder={activeFiscalYearName}
                className="w-full h-14"
                onChange={handleCreatedByYear}
              >
                {fiscalYear?.items?.map((year: any) => (
                  <Select.Option
                    id={`incentive-filter-year-option-${year.id}`}
                    data-cy={`incentive-filter-year-option-${year.id}`}
                    key={year.id}
                    value={year.id}
                  >
                    {year?.name}
                  </Select.Option>
                ))}
              </Select>
            </Col>
            <Col
              id="incentive-filter-session-col"
              data-cy="incentive-filter-session-col"
              xs={24}
              sm={24}
              md={24}
              lg={8}
              xl={8}
            >
              <Select
                id="incentive-filter-session-select"
                data-cy="incentive-filter-session-select"
                mode="multiple"
                allowClear
                placeholder="Select Session"
                className="w-full h-14"
                onChange={(value) =>
                  handleCreatedBySession(Array.isArray(value) ? value : [value])
                }
                disabled={!selectedYear}
              >
                {selectedYear &&
                  fiscalYear?.items
                    ?.find((year: any) => year.id === selectedYear)
                    ?.sessions?.map((session: any) => (
                      <Select.Option
                        id={`incentive-filter-session-option-${session.id}`}
                        data-cy={`incentive-filter-session-option-${session.id}`}
                        key={session.id}
                        value={session.id}
                      >
                        {session.name}
                      </Select.Option>
                    ))}
              </Select>
            </Col>
            <Col
              id="incentive-filter-month-col"
              data-cy="incentive-filter-month-col"
              xs={24}
              sm={24}
              md={24}
              lg={8}
              xl={8}
            >
              <Select
                id="incentive-filter-month-select"
                data-cy="incentive-filter-month-select"
                allowClear
                placeholder="Select Month "
                className="w-full h-14"
                onChange={handleCreatedByMonth}
                disabled={!selectedSessionMonths?.length}
              >
                {selectedSessionMonths?.map((month: any) => (
                  <Select.Option
                    id={`incentive-filter-month-option-${month?.id}`}
                    data-cy={`incentive-filter-month-option-${month?.id}`}
                    key={month?.id}
                    value={month?.id}
                  >
                    {month?.name}
                  </Select.Option>
                ))}
              </Select>
            </Col>
          </Row>
        </Col>
      </Row>
    </>
  );

  return (
    <div
      id="incentive-filter-container"
      data-cy="incentive-filter-container"
      className="my-7 mx-1"
    >
      {isMobile || isTablet ? (
        <div
          id="incentive-filter-mobile-wrapper"
          data-cy="incentive-filter-mobile-wrapper"
          className="flex justify-end m-2 space-x-4"
        >
          <Select
            id="incentive-filter-mobile-employee-select"
            data-cy="incentive-filter-mobile-employee-select"
            onChange={(value) => handleSearchInput(value, 'employee_name')}
            placeholder="Search Employee"
            allowClear
            showSearch
            className="w-full h-14"
            optionFilterProp="children"
            filterOption={(input: any, option: any) =>
              option?.children
                ?.toString()
                .toLowerCase()
                .includes(input.toLowerCase())
            }
          >
            {employeeData?.items?.map((items: any) => (
              <Select.Option
                id={`incentive-filter-mobile-employee-option-${items?.id}`}
                data-cy={`incentive-filter-mobile-employee-option-${items?.id}`}
                key={items?.id}
                value={items?.id}
              >
                {items?.firstName + ' ' + items?.middleName}
              </Select.Option>
            ))}
          </Select>
          <div
            id="incentive-filter-mobile-settings-wrapper"
            data-cy="incentive-filter-mobile-settings-wrapper"
            className="flex items-center justify-center rounded-lg border-[1px] border-gray-200 p-3"
          >
            <LuSettings2
              id="incentive-filter-mobile-settings-icon"
              data-cy="incentive-filter-mobile-settings-icon"
              onClick={() => setShowMobileFilter(true)}
              className="text-lg cursor-pointer"
            />
          </div>
          <Modal
            data-cy="incentive-filter-mobile-modal"
            centered
            title="Filter"
            open={showMobileFilter}
            onCancel={() => setShowMobileFilter(false)}
            modalRender={(modal) => (
              <div
                id="incentive-filter-mobile-modal-content"
                data-cy="incentive-filter-mobile-modal-content"
                style={{ maxHeight: '70vh', overflowY: 'auto' }}
              >
                {modal}
              </div>
            )}
            footer={null}
          >
            {Filters}
          </Modal>
        </div>
      ) : (
        Filters
      )}
    </div>
  );
};

export default IncentiveFilter;

import React, { useEffect, useState, useRef } from 'react';
import ExcelJS from 'exceljs';
import { Button, Popover } from 'antd';
import { useExcelHeaders } from '@/store/server/features/incentive/all/queries';
import { useIncentiveStore } from '@/store/uistate/features/incentive/incentive';
import { useRecognitionByParentId } from '@/store/server/features/incentive/other/queries';
import { capitalizeInitials } from '@/helpers/capitalizeInitals';
import NotificationMessage from '@/components/common/notification/notificationMessage';
import { fetchExcelHeaders } from '@/store/server/features/incentive/all/queries';

const DownloadExcelButton: React.FC = () => {
  const { selectedRecognitionTypeId, activeKey } = useIncentiveStore();

  const [loadingItems, setLoadingItems] = useState<{ [key: string]: boolean }>(
    {},
  );
  const [popoverVisible, setPopoverVisible] = useState(false);
  const [pendingDownloadId, setPendingDownloadId] = useState<string | null>(
    null,
  );

  const { data: excelHeaders, isLoading: templateResponseLoading } =
    useExcelHeaders(selectedRecognitionTypeId);

  const { data: childRecognitionData, isLoading: responseLoading } =
    useRecognitionByParentId(activeKey !== '1' ? activeKey : '');

  const warningTimeout = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    // Clear any previous timeout
    if (warningTimeout.current) {
      clearTimeout(warningTimeout.current);
    }

    // Only run if loading is active for the current recognition type
    if (selectedRecognitionTypeId && loadingItems[selectedRecognitionTypeId]) {
      // Set a timeout to check for headers after 5 seconds
      warningTimeout.current = setTimeout(() => {
        if (!excelHeaders || excelHeaders.length === 0) {
          setLoadingItems((prev) => ({
            ...prev,
            [selectedRecognitionTypeId]: false,
          }));
          NotificationMessage.warning({
            message: 'No headers found. Please try again.',
          });
        }
      }, 5000); // 5 seconds
    }

    // If headers arrive and are non-empty, clear loading
    if (selectedRecognitionTypeId && excelHeaders && excelHeaders.length > 0) {
      setLoadingItems((prev) => ({
        ...prev,
        [selectedRecognitionTypeId]: false,
      }));
      if (warningTimeout.current) {
        clearTimeout(warningTimeout.current);
      }
    }

    // Cleanup on unmount or change
    return () => {
      if (warningTimeout.current) {
        clearTimeout(warningTimeout.current);
      }
    };
  }, [excelHeaders, selectedRecognitionTypeId, templateResponseLoading]);

  // Download logic in useEffect, triggered when headers for pendingDownloadId are available
  useEffect(() => {
    const doDownload = async () => {
      if (
        pendingDownloadId &&
        selectedRecognitionTypeId === pendingDownloadId &&
        excelHeaders &&
        excelHeaders.length > 0
      ) {
        try {
          // Create a new workbook and worksheet
          const workbook = new ExcelJS.Workbook();
          const worksheet = workbook.addWorksheet('My Sheet');

          // Define Excel headers dynamically from props
          const columns = excelHeaders.map((header: any) => ({
            header: capitalizeInitials(header?.criterionKey),
            key: header?.id,
            width: 20,
          }));

          worksheet.columns = columns || [];
          const buffer = await workbook.xlsx.writeBuffer();

          // Create a Blob and download using native APIs
          const blob = new Blob([buffer], {
            type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          });

          // Generate a download link and programmatically click it
          const url = URL.createObjectURL(blob);
          const link = document.createElement('a');
          link.href = url;
          link.download = 'IncentiveImportTemplate.xlsx';
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          URL.revokeObjectURL(url);

          // Close the popover after successful download
          setPopoverVisible(false);

          NotificationMessage.success({
            message: 'Template downloaded successfully!',
          });
        } catch (error) {
          NotificationMessage.error({
            message: 'Failed to download template. Please try again.',
          });
        } finally {
          setPendingDownloadId(null);
        }
      }
    };
    doDownload();
  }, [excelHeaders, pendingDownloadId, selectedRecognitionTypeId]);

  const handleTemplateDownload = async (recognitionId: string) => {
    setLoadingItems({ ...loadingItems, [recognitionId]: true });

    try {
      const headers = await fetchExcelHeaders(recognitionId);

      if (!headers || headers.length === 0) {
        NotificationMessage.warning({
          message: 'No headers found. Please try again.',
        });
        setLoadingItems({ ...loadingItems, [recognitionId]: false });
        return;
      }

      // ....proceed with ExcelJS logic using headers
      const workbook = new ExcelJS.Workbook();
      const worksheet = workbook.addWorksheet('My Sheet');
      const columns = headers.map((header: any) => ({
        header: capitalizeInitials(header?.criterionKey),
        key: header?.id,
        width: 20,
      }));
      worksheet.columns = columns || [];
      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'IncentiveImportTemplate.xlsx';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setPopoverVisible(false);

      NotificationMessage.success({
        message: 'Template downloaded successfully!',
      });
    } catch (error) {
      NotificationMessage.error({
        message: 'Failed to download template. Please try again.',
      });
    } finally {
      setLoadingItems({ ...loadingItems, [recognitionId]: false });
    }
  };

  // Check if the current recognition type is loading
  const isCurrentRecognitionLoading = loadingItems[selectedRecognitionTypeId];

  return childRecognitionData?.length > 0 ? (
    <Popover
      id="download-excel-button-popover"
      data-cy="download-excel-button-popover"
      content={
        <div
          id="download-excel-button-popover-content"
          data-cy="download-excel-button-popover-content"
        >
          {childRecognitionData?.map((item: any) => (
            <div
              id={`download-excel-button-popover-item-${item?.id}`}
              data-cy={`download-excel-button-popover-item-${item?.id}`}
              key={item?.id}
              onClick={() => {
                // Only prevent click if this specific item is loading
                if (!loadingItems[item?.id]) {
                  handleTemplateDownload(item?.id || '');
                }
              }}
              className={`flex flex-col border-[1px] w-32 sm:w-60 my-2 rounded-xl border-gray-300 p-2 cursor-pointer hover:bg-gray-100 transition ${
                loadingItems[item?.id]
                  ? 'opacity-70 cursor-not-allowed bg-gray-50 border-blue-300'
                  : ''
              }`}
            >
              <div
                id={`download-excel-button-popover-item-content-${item?.id}`}
                data-cy={`download-excel-button-popover-item-content-${item?.id}`}
                className="flex items-center justify-between"
              >
                <span
                  id={`download-excel-button-popover-item-name-${item?.id}`}
                  data-cy={`download-excel-button-popover-item-name-${item?.id}`}
                  className="flex-1"
                >
                  {item?.name}
                </span>
                {loadingItems[item?.id] && (
                  <div
                    id={`download-excel-button-popover-item-spinner-${item?.id}`}
                    data-cy={`download-excel-button-popover-item-spinner-${item?.id}`}
                    className="flex-shrink-0 w-6 h-6 flex items-center justify-center ml-2"
                  >
                    <div
                      id={`download-excel-button-popover-item-spinner-inner-${item?.id}`}
                      data-cy={`download-excel-button-popover-item-spinner-inner-${item?.id}`}
                      className="w-6 h-6 border-4 border-blue-800 border-t-transparent rounded-full animate-spin shadow-sm"
                    ></div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      }
      trigger="click"
      open={popoverVisible}
      onOpenChange={setPopoverVisible}
    >
      <Button
        id="download-excel-button-popover-trigger"
        data-cy="download-excel-button-popover-trigger"
        loading={templateResponseLoading || responseLoading}
        style={{
          padding: '10px 20px',
          backgroundColor: '#B2B2FF',
          color: '#3636F0',
          border: 'none',
          borderRadius: '10px',
          cursor: 'pointer',
          fontSize: '12px',
          height: '30px',
        }}
      >
        Download Format
      </Button>
    </Popover>
  ) : (
    <Button
      id="download-excel-button"
      data-cy="download-excel-button"
      loading={templateResponseLoading || responseLoading}
      style={{
        padding: '10px 20px',
        backgroundColor: '#B2B2FF',
        color: '#3636F0',
        border: 'none',
        borderRadius: '10px',
        cursor: 'pointer',
        fontSize: '12px',
        height: '30px',
      }}
      onClick={() => {
        // Only prevent click if the current recognition type is loading
        if (!isCurrentRecognitionLoading) {
          handleTemplateDownload(activeKey);
        }
      }}
    >
      Download Format
    </Button>
  );
};

export default DownloadExcelButton;

'use client';
import { useParentRecognition } from '@/store/server/features/incentive/other/queries';
import { Button, Skeleton, Tabs } from 'antd';
import { TabsProps } from 'antd/lib';
