}

const AppreciationEditDrawer: React.FC<AppDrawerProps> = ({
  appLog,
  onClose,
  open,
}) => {
  const { data: allUsers } = useGetAllUsers();
  const { data: appTypes } = useGetAppreciationType();

  const renderEmployeeOption = (option: any) => (
    <div
      style={{ display: 'flex', alignItems: 'center' }}
      data-cy={`appreciation-edit-drawer-employee-option-${option.id}`}
    >
      <Avatar size={20} icon={<UserOutlined />} />
      {option.firstName}
    </div>
  );

  const customTagRender = (props: any) => {
    const { label, closable, onClose } = props;
    return (
      <div
        className="flex gap-1 items-center bg-gray-100 p-2 rounded-lg mx-1 my-1"
        data-cy="appreciation-edit-drawer-tag-container"
      >
        <Avatar size={20} icon={<UserOutlined />} />
        <span data-cy="appreciation-edit-drawer-tag-label">{label}</span>
        {closable && (
          <span
            onClick={onClose}
            className="text-black text-xs"
            data-cy="appreciation-edit-drawer-tag-close"
          >
            ✖
          </span>
        )}
      </div>
    );
  };

  const [form] = Form.useForm();
  const { mutate: updateAppLog } = useUpdateAppLog();
  const { userId } = useAuthenticationStore();

  const onFinish = (values: any) => {
    const value = { ...values, issuerId: userId };
    updateAppLog(
      { ...value, id: appLog?.id },
      {
        onSuccess: () => {
          handleDrawerClose();
        },
      },
    );
  };

  const handleDrawerClose = () => {
    form.resetFields(); // Reset all form fields
    onClose();
  };
  const cc = appLog?.carbonCopies?.map((copy: any) => copy.copyUserId) || [];

  const appreciationLog = { ...appLog, cc };
  useEffect(() => {
    if (appLog) {
      form.setFieldsValue(appreciationLog); // Set form fields with appType values
    } else {
      form.resetFields(); // Reset form if appType is null
    }
  }, [appLog, form]);
  const modalHeader = (
    <div
      className="flex justify-center text-xl font-extrabold text-gray-800 p-4"
      data-cy="appreciation-edit-drawer-modal-header"
