  );

  const footer = (
    <div
      className="w-full flex justify-center items-center gap-4 pt-8"
      data-cy="appreciation-edit-drawer-footer"
    >
      <CustomButton
        type="default"
        title="Cancel"
        onClick={handleDrawerClose}
        style={{ marginRight: 8 }}
      />
      <CustomButton
        title={'Add'}
        type="primary"
        htmlType="submit" // Add this line
        onClick={() => form.submit()} // Trigger form submission
      />
    </div>
  );

  return (
    <CustomDrawerLayout
      open={open}
      onClose={handleDrawerClose}
      modalHeader={modalHeader}
      footer={footer}
    >
      <Form
        form={form}
        name="reprimandForm"
        layout="vertical"
        onFinish={onFinish}
        autoComplete="off"
      >
        {/* Select Employee */}
        <Form.Item
          name="recipientId"
          label="Select Employee"
          rules={[{ required: true, message: 'Please select employees' }]}
        >
          <Select
            allowClear
            placeholder="Select Employees"
            optionLabelProp="label"
            tagRender={customTagRender}
          >
            {allUsers?.items.map((option: any) => (
              <Select.Option
                key={option.id}
                value={option.id}
                label={option.firstName}
              >
                {renderEmployeeOption(option)}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        {/* Select Type */}
        <Form.Item
          name="typeId"
          label="Select Type"
          rules={[{ required: true, message: 'Please select a type' }]}
        >
          <Select placeholder="Select Reprimand Type">
            {appTypes?.items?.map((item) => (
              <Select.Option key={item?.id} value={item?.id}>
                {item?.name}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        {/* Reason */}
        <Form.Item
          name="action"
          label="Reason"
          rules={[{ required: true, message: 'Please enter the reason' }]}
        >
          <Input.TextArea rows={4} placeholder="Enter reason here..." />
        </Form.Item>

        {/* CC */}
        <Form.Item name="cc" label="CC">
          <Select
            mode="multiple"
            allowClear
            placeholder="Select Employees"
            optionLabelProp="label"
            tagRender={customTagRender}
          >
            {allUsers?.items.map((option: any) => (
              <Select.Option
                key={option.id}
                value={option.id}
                label={option.firstName}
              >
                {renderEmployeeOption(option)}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>
      </Form>
    </CustomDrawerLayout>
  );
};

