                </Form.Item>
              </div>
            </div>
          </Form>
        )}

        {/* Metric type pill selector – same as Create OKR modal (Advanced only) */}
        {!isBasic && showMetricSelector && (
          <div
            id="okr-edit-objective-metric-selector"
