'use client';
import { Button, Spin, Tabs } from 'antd';
import type { RenderTabBar } from 'rc-tabs/es/interface';
import React, { useEffect, useMemo, useState } from 'react';
import ObjectiveCard from '../objectivecard';
import ObjectiveBasic from '../objectiveBasic';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import { useIsBasicOkr } from '../../../_utils/okrMode';
import {
  useGetCompanyObjective,
  useGetTeamObjective,
  useGetUserObjective,
} from '@/store/server/features/okrplanning/okr/objective/queries';
import { useOKRStore } from '@/store/uistate/features/okrplanning/okr';
import { useGetUserDepartment } from '@/store/server/features/okrplanning/okr/department/queries';
import { useGetEmployee } from '@/store/server/features/employees/employeeDetail/queries';
import { EmptyImage } from '@/components/emptyIndicator';
import ObjectiveCardSkeleton from '@/components/okr/objectiveCardSkeleton';
import AccessGuard from '@/utils/permissionGuard';
import { Permissions } from '@/types/commons/permissionEnum';
import EmployeeOKRTable from '../EmployeeOkr';
import CustomPagination from '@/components/customPagination';
import { CustomMobilePagination } from '@/components/customPagination/mobilePagination';
import { useIsMobile } from '@/hooks/useIsMobile';
import {
  OKR_STATUS_PILLS,
  toKeyResultDeadlineFilter,
} from '../../../_constants/okrStatusPills';

const TAB_CONFIG = [
  { key: '1', label: 'My OKR' },
  { key: '2', label: 'Team OKR' },
  { key: '3', label: 'Company OKR' },
  { key: '4', label: 'All Employees OKR' },
];

interface OkrTabProps {
  filterComponent?: React.ReactNode;
  'data-cy'?: string;
}

export default function OkrTab({
  filterComponent,
  'data-cy': dataCy,
}: OkrTabProps) {
  const [isMounted, setIsMounted] = useState(false);
  const [activeKey, setActiveKey] = useState<string>('1');
  const { userId } = useAuthenticationStore();
  const { data: departmentUsers } = useGetUserDepartment();
  const { data: userData } = useGetEmployee(userId);
  const isBasicOkr = useIsBasicOkr();
  const departmentId = userData?.employeeJobInformation?.[0]?.departmentId;
  const users =
    departmentUsers
      ?.find((i: any) => i.id === departmentId)
      ?.users?.map((user: any) => user.id) || [];

  const {
    pageSize,
    setPageSize,
    currentPage,
    setCurrentPage,
    searchObjParams,
    fiscalYearId,
    sessionIds,
    setTeamCurrentPage,
    setTeamPageSize,
    teamCurrentPage,
    teamPageSize,
    setCompanyCurrentPage,
    setCompanyPageSize,
    companyCurrentPage,
    companyPageSize,
    okrTab,
    setOkrTab,
    okrStatusPillId,
    setOkrStatusPillId,
  } = useOKRStore();
  const { isMobile, isTablet } = useIsMobile();
  const usersInDepartment =
    departmentUsers
      ?.find((i: any) => i.id == searchObjParams?.departmentId)
      ?.users?.map((user: any) => user.id) || [];

  const keyResultDeadlineFilter = useMemo(
    () =>
      String(okrTab) === '1'
        ? toKeyResultDeadlineFilter(okrStatusPillId)
        : undefined,
    [okrStatusPillId, okrTab],
  );

  useEffect(() => {
    if (String(okrTab) !== '1') {
      setOkrStatusPillId(null);
    }
  }, [okrTab, setOkrStatusPillId]);

  const {
    data: userObjectives,
    isLoading,
    refetch: userRefetch,
  } = useGetUserObjective(
    userId,
    pageSize,
    currentPage,
    searchObjParams?.metricTypeId,
    fiscalYearId,
    sessionIds,
    keyResultDeadlineFilter,
    { enabled: String(activeKey) === '1' },
  );
  const {
    data: teamObjective,
    isLoading: teamLoading,
    refetch,
  } = useGetTeamObjective(
    teamPageSize,
    teamCurrentPage,
    users,
    searchObjParams.userId || userId, // Use current userId if searchObjParams.userId is empty
    searchObjParams?.metricTypeId || '', // Provide empty string as fallback
    fiscalYearId,
    sessionIds,
    undefined,
    { enabled: String(activeKey) === '2' },
  );

  const {
    data: companyObjective,
    isLoading: companyLoading,
    refetch: CompanyRefetch,
  } = useGetCompanyObjective(
    userId,
    companyPageSize,
    companyCurrentPage,
    usersInDepartment,
    searchObjParams.userId,
    searchObjParams?.metricTypeId,
    fiscalYearId,
    sessionIds,
    undefined,
    { enabled: String(activeKey) === '3' },
  );

  const isUserLoading = isLoading;
  const isTeamLoading = teamLoading;
  const isCompanyLoading = companyLoading;

  const canVieTeamOkr = AccessGuard.checkAccess({
    permissions: [Permissions.ViewTeamOkr],
  });
  const canVieCompanyOkr = AccessGuard.checkAccess({
    permissions: [Permissions.ViewCompanyOkr],
  });

  useEffect(() => {
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (isMounted && String(activeKey) === '1') {
      userRefetch();
    }
  }, [pageSize, currentPage, isMounted, activeKey]);

  useEffect(() => {
    if (isMounted && String(activeKey) === '2') {
      refetch();
    }
  }, [teamPageSize, teamCurrentPage, isMounted, activeKey]);

  // Refetch Team OKR when year/session filters change
  useEffect(() => {
    if (isMounted && String(activeKey) === '2') {
      refetch();
    }
  }, [fiscalYearId, sessionIds, isMounted, activeKey]);

  useEffect(() => {
    if (isMounted && String(activeKey) === '3') {
      CompanyRefetch();
    }
  }, [companyPageSize, companyCurrentPage, isMounted, activeKey]);

  useEffect(() => {
    setActiveKey(String(okrTab));
  }, [okrTab]);

  // Return null or loading state during SSR
  if (!isMounted) {
    return (
      <div
        className="mt-6 flex justify-center items-center min-h-[200px]"
        data-cy="okr-tab-loading-container"
      >
        <Spin size="large" />
      </div>
    );
  }

  const handleTabChange = (key: string) => {
    setOkrTab(key);
    setActiveKey(key);
  };

  const visibleTabs = TAB_CONFIG.filter((tab) => {
    if (tab.key === '2' && !canVieTeamOkr) return false;
    if ((tab.key === '3' || tab.key === '4') && !canVieCompanyOkr) return false;
    return true;
  });

  const tabContent = [
    {
      key: '1',
      label: 'My OKR',
      children: (
        <div id="my-okr-tab-content" data-cy="okr-my-okr-tab-content">
          {isUserLoading ? (
            <ObjectiveCardSkeleton
              data-cy="okr-my-okr-loading-skeleton"
              count={Math.min(Number(pageSize || 3), 6)}
              showAssignee={false}
            />
          ) : null}
          {userObjectives?.items?.length !== 0 && (
            <div
              id="my-okr-objectives-list"
              data-cy="okr-my-okr-objectives-list"
            >
              {userObjectives?.items?.map((obj: any) =>
                isBasicOkr ? (
                  <ObjectiveBasic
                    data-cy={`okr-my-okr-objective-basic-card-${obj?.id}`}
                    key={obj.id}
                    myOkr={true}
                    objective={obj}
                  />
                ) : (
                  <ObjectiveCard
                    data-cy={`okr-my-okr-objective-card-${obj?.id}`}
                    key={obj.id}
                    myOkr={true}
                    objective={obj}
                  />
                ),
              )}
              {isMobile || isTablet ? (
                <CustomMobilePagination
                  data-cy="okr-my-okr-mobile-pagination"
                  totalResults={userObjectives?.meta?.totalItems ?? 0}
                  pageSize={pageSize}
                  currentPage={currentPage}
                  onChange={(page, pageSize) => {
                    setCurrentPage(page);
                    setPageSize(pageSize);
                  }}
                  onShowSizeChange={(size) => {
                    setPageSize(size);
                  }}
                />
              ) : (
                <CustomPagination
                  current={userObjectives?.meta?.currentPage || 1}
                  total={userObjectives?.meta?.totalItems || 1}
                  pageSize={pageSize}
                  onChange={(page, pageSize) => {
                    setCurrentPage(page);
                    setPageSize(pageSize);
                  }}
                  onShowSizeChange={(size) => {
                    setPageSize(size);
                    setCurrentPage(1);
                  }}
                />
              )}
            </div>
          )}
          {userObjectives?.items?.length === 0 && (
            <div
              id="my-okr-empty-state"
              data-cy="okr-my-okr-empty-state"
              className="flex justify-center"
            >
              <EmptyImage />
            </div>
          )}
        </div>
      ),
    },
    ...(canVieTeamOkr
      ? [
          {
            key: '2',
            label: 'Team OKR',
            children: (
              <div id="team-okr-tab-content" data-cy="okr-team-okr-tab-content">
                {isTeamLoading ? (
                  <ObjectiveCardSkeleton
                    data-cy="okr-team-okr-loading-skeleton"
                    count={Math.min(Number(teamPageSize || 3), 6)}
                    showAssignee={true}
                  />
                ) : null}
                {teamObjective?.items?.length !== 0 && (
                  <div
                    id="team-okr-objectives-list"
                    data-cy="okr-team-okr-objectives-list"
                  >
                    {teamObjective?.items?.map((obj: any) =>
                      isBasicOkr ? (
                        <ObjectiveBasic
                          key={obj.id}
                          myOkr={false}
                          objective={obj}
                        />
                      ) : (
                        <ObjectiveCard
                          key={obj.id}
                          myOkr={false}
                          objective={obj}
                        />
                      ),
                    )}
                    {isMobile || isTablet ? (
                      <CustomMobilePagination
                        data-cy="okr-team-okr-mobile-pagination"
                        totalResults={teamObjective?.meta?.totalItems ?? 0}
                        pageSize={teamPageSize}
                        currentPage={teamCurrentPage}
                        onChange={(page, pageSize) => {
                          setTeamCurrentPage(page);
                          setTeamPageSize(pageSize);
                        }}
                        onShowSizeChange={(size) => {
                          setTeamPageSize(size);
                        }}
                      />
                    ) : (
                      <CustomPagination
                        data-cy="okr-team-okr-pagination"
                        current={teamObjective?.meta?.currentPage || 1}
                        total={teamObjective?.meta?.totalItems || 1}
                        pageSize={teamPageSize}
                        onChange={(page, pageSize) => {
                          setTeamCurrentPage(page);
                          setTeamPageSize(pageSize);
                        }}
                        onShowSizeChange={(size) => {
                          setTeamPageSize(size);
                          setTeamCurrentPage(1);
                        }}
                      />
                    )}
                  </div>
                )}
                {teamObjective?.items?.length === 0 && (
                  <div
                    id="team-okr-empty-state"
                    data-cy="okr-team-okr-empty-state"
                    className="flex justify-center"
                  >
                    <EmptyImage data-cy="okr-team-okr-empty-image" />
                  </div>
                )}
              </div>
            ),
          },
        ]
      : []),
    ...(canVieCompanyOkr
      ? [
          {
            key: '3',
            label: 'Company OKR',
            children: (
              <div
                id="company-okr-tab-content"
                data-cy="okr-company-okr-tab-content"
              >
                {isCompanyLoading ? (
                  <ObjectiveCardSkeleton
                    data-cy="okr-company-okr-loading-skeleton"
                    count={Math.min(Number(companyPageSize || 3), 6)}
                    showAssignee={true}
                  />
                ) : null}
                {companyObjective?.items?.length !== 0 && (
                  <div
                    id="company-okr-objectives-list"
                    data-cy="okr-company-okr-objectives-list"
                  >
                    {companyObjective?.items?.map((obj: any) =>
                      isBasicOkr ? (
                        <ObjectiveBasic
                          data-cy={`okr-company-okr-objective-basic-card-${obj?.id}`}
                          key={obj.id}
                          myOkr={false}
                          objective={obj}
                        />
                      ) : (
                        <ObjectiveCard
                          data-cy={`okr-company-okr-objective-card-${obj?.id}`}
                          key={obj.id}
                          myOkr={false}
                          objective={obj}
                        />
                      ),
                    )}
                    {isMobile || isTablet ? (
                      <CustomMobilePagination
                        data-cy="okr-company-okr-mobile-pagination"
                        totalResults={companyObjective?.meta?.totalItems ?? 0}
                        pageSize={companyPageSize}
                        currentPage={companyCurrentPage}
                        onChange={(page, pageSize) => {
                          setCompanyCurrentPage(page);
                          setCompanyPageSize(pageSize);
                        }}
                        onShowSizeChange={(size) => {
                          setCompanyPageSize(size);
                        }}
                      />
                    ) : (
                      <CustomPagination
                        data-cy="okr-company-okr-pagination"
                        current={companyObjective?.meta?.currentPage || 1}
                        total={companyObjective?.meta?.totalItems || 1}
                        pageSize={companyPageSize}
                        onChange={(page, pageSize) => {
                          setCompanyCurrentPage(page);
                          setCompanyPageSize(pageSize);
                        }}
                        onShowSizeChange={(size) => {
                          setCompanyPageSize(size);
                          setCompanyCurrentPage(1);
                        }}
                      />
                    )}
                  </div>
                )}
                {companyObjective?.items?.length === 0 && (
                  <div
                    id="company-okr-empty-state"
                    data-cy="okr-company-okr-empty-state"
                    className="flex justify-center"
                  >
                    <EmptyImage data-cy="okr-company-okr-empty-image" />
                  </div>
                )}
              </div>
            ),
          },
          {
            key: '4',
            label: 'All Employees OKR',
            children: (
              <div
                id="all-employee-okr-tab-content"
                data-cy="okr-all-employee-okr-tab-content"
              >
                <EmployeeOKRTable data-cy="okr-all-employee-okr-table" />
              </div>
            ),
          },
        ]
      : []),
  ];

  const contentByKey = new Map(
    tabContent.map((entry) => [entry.key, entry.children]),
  );

  const tabItems = visibleTabs.map((tab) => ({
    key: tab.key,
    label: (
      <div
        className={`text-base font-normal m-0 ${
          activeKey === tab.key
            ? 'text-okr-primary font-semibold'
            : 'text-gray-800'
        }`}
        data-cy={`okr-tab-${tab.key}`}
        id={`okr-tab-label-${tab.key}`}
      >
        {tab.label}
      </div>
    ),
    children: contentByKey.get(tab.key) ?? null,
  }));

  const statusPillButtons = OKR_STATUS_PILLS.map((pill) => {
    const isSelected = okrStatusPillId === pill.id;
    return (
      <Button
        key={pill.id}
        type="default"
        size="small"
        data-cy={`okr-status-pill-${pill.id}`}
        onClick={() =>
          setOkrStatusPillId(okrStatusPillId === pill.id ? null : pill.id)
        }
        className={
          isSelected
            ? '!rounded-lg !h-7 !min-h-0 !px-2 !py-0 !leading-none border-okr-primary text-okr-primary !bg-[#FAFAFA] hover:!bg-[#FAFAFA] hover:!border-okr-primary hover:!text-okr-primary'
            : '!rounded-lg !h-7 !min-h-0 !px-2 !py-0 !leading-none border-[#D9D9D9] text-gray-700 !bg-[#FAFAFA] hover:!bg-[#F0F0F0] hover:!border-[#D9D9D9] hover:!text-gray-800'
        }
      >
        {pill.label}
      </Button>
    );
  });

  const isCompactTabBar = isMobile || isTablet;

  /** Mobile/tablet: same pattern as employee settings — scrollable tabs + filter only in `right` extra (always visible). */
  const compactTabBarExtra =
    activeKey !== '4' && filterComponent ? (
      <div className="ml-4 flex shrink-0" data-cy="okr-filter-inline-container">
        {filterComponent}
      </div>
    ) : null;

  const tabBarExtraContent = isCompactTabBar ? (
    compactTabBarExtra ? (
      { right: compactTabBarExtra }
    ) : undefined
  ) : (
    <div
      className="flex max-w-full flex-wrap items-center justify-end gap-1"
      data-cy="okr-tab-bar-extra"
    >
      {activeKey === '1' ? (
        <div
          className="flex flex-wrap items-center gap-2"
          data-cy="okr-status-pills-row"
        >
          {statusPillButtons}
        </div>
      ) : null}
      {activeKey !== '4' ? (
        <div className="flex-shrink-0" data-cy="okr-filter-inline-container">
          {filterComponent}
        </div>
      ) : null}
    </div>
  );

  const tabsClassName = [
    '[&_.ant-tabs-tab]:py-4 [&_.ant-tabs-tab-btn]:py-2 [&_.ant-tabs-nav]:mb-0 [&_.ant-tabs-nav-wrap]:!px-0 [&_.ant-tabs-nav-list]:!px-0 [&_.ant-tabs-nav-wrap]:before:!left-0 [&_.ant-tabs-nav-wrap]:after:!right-0 [&_.ant-tabs-content-holder]:mt-6',
    isCompactTabBar
      ? '[&_.ant-tabs-nav]:min-w-0 [&_.ant-tabs-nav-wrap]:min-w-0 [&_.ant-tabs-nav-list]:!flex-nowrap [&_.ant-tabs-nav-wrap]:overflow-x-auto [&_.ant-tabs-nav-wrap]:scrollbar-none [&_.ant-tabs-extra-content]:!shrink-0'
      : '',
  ]
    .filter(Boolean)
    .join(' ');
  //eslint-disable-next-line
  const compactRenderTabBar: RenderTabBar = (tabBarProps, DefaultTabBar) => {
    const TabNavList = DefaultTabBar;
    return (
      <div className="w-full min-w-0" data-cy="okr-mobile-tab-bar-stack">
        <TabNavList {...tabBarProps} />
      </div>
    );
  };

  const renderTabBar: RenderTabBar | undefined = isCompactTabBar
    ? compactRenderTabBar
    : undefined;

  return (
    <div
      id="okr-tab-container"
      data-cy={dataCy || 'okr-tab-container'}
      className={isCompactTabBar ? 'min-w-0 w-full' : undefined}
    >
      <Tabs
        activeKey={activeKey}
        onChange={handleTabChange}
        items={tabItems}
        moreIcon={false}
        tabBarStyle={{
          marginBottom: 0,
          marginLeft: 0,
          paddingLeft: 0,
          paddingRight: 0,
        }}
        tabBarExtraContent={tabBarExtraContent}
        renderTabBar={renderTabBar}
        className={tabsClassName}
        data-cy="okr-tabs"
        id="okr-tabs"
        destroyInactiveTabPane
      />
    </div>
  );
}

import React, { useEffect, useState, useRef } from 'react';
import { Select, Modal, Button, Popover } from 'antd';
import { OKR_STATUS_PILLS } from '../../../_constants/okrStatusPills';
import { SearchOutlined, CloseOutlined } from '@ant-design/icons';
import { useGetUserDepartment } from '@/store/server/features/okrplanning/okr/department/queries';
import { useGetMetrics } from '@/store/server/features/okrplanning/okr/metrics/queries';
import { useGetAllUsers } from '@/store/server/features/okrplanning/okr/users/queries';
import {
  useGetActiveFiscalYears,
  useGetAllFiscalYears,
} from '@/store/server/features/organizationStructure/fiscalYear/queries';
import {
  useOKRStore,
  useSearchFilterStore,
} from '@/store/uistate/features/okrplanning/okr';
import CustomButton from '@/components/common/buttons/customButton';
import { useIsMobile } from '@/hooks/useIsMobile';
import FilterAltOutlinedIcon from '@mui/icons-material/FilterAltOutlined';

const { Option } = Select;

export type OkrSearchProps = {
  embedded?: boolean;
  'data-cy'?: string;
  /** When true, filter layout matches "All Employee OKR" (multi-session, user & department; no metric). */
  allEmployeeLayout?: boolean;
  /**
   * When true with `allEmployeeLayout`, desktop shows employee search + a Filter popover
   * (fiscal year, session, department). Does not change filter state behavior.
   */
  filterInPopover?: boolean;
};

const OkrSearch: React.FC<OkrSearchProps> = ({
  embedded = false,
  'data-cy': dataCy,
  allEmployeeLayout = false,
  filterInPopover = false,
}) => {
  const {
    isFilterModalOpen: isModalOpen,
    openFilterModal,
    closeFilterModal,
    setFilterModalOpen,
  } = useSearchFilterStore();
  const [filterPopoverOpen, setFilterPopoverOpen] = useState(false);
  const { isMobile, isTablet } = useIsMobile();
  const {
    searchObjParams,
    setSearchObjParams,
    okrTab,
    setFiscalYearId,
    fiscalYearId,
    setSessionIds,
    sessionIds,
    okrStatusPillId,
    setOkrStatusPillId,
  } = useOKRStore();

  const isMyOkrTab = String(okrTab) === '1';
  const treatAsAllEmployeeTab = allEmployeeLayout || okrTab == 4;
  /** Send all FY sessions only for OKR tab 4 / legacy all-employee toolbar. Performance employees (`filterInPopover`) uses the active session only. */
  const useAllSessionsForEmployeeOkr =
    (allEmployeeLayout && !filterInPopover) || okrTab == 4;
  const showUserAndDepartmentFilters = allEmployeeLayout || okrTab != 1;
  const showMetricTypeFilter = !allEmployeeLayout && okrTab != 4;

  const { data: getAllFiscalYears, isLoading: fyLoading } =
    useGetAllFiscalYears();
  const { data: getActiveFisicalYear } = useGetActiveFiscalYears();
  const { data: Metrics } = useGetMetrics();
  const { data: allUsers } = useGetAllUsers();
  const { data: Departments } = useGetUserDepartment();

  // Use refs to track previous values and prevent infinite loops
  const prevFiscalYearIdRef = useRef<string>(fiscalYearId);
  const prevOkrTabRef = useRef<number | string>(okrTab);
  const initializedRef = useRef<boolean>(false);

  // Only sync fiscal year and sessions on mount or when okrTab/fiscalYearId changes
  // This prevents infinite loops by checking if values actually changed
  useEffect(() => {
    // Skip if data isn't loaded yet
    if (!getAllFiscalYears?.items && !getActiveFisicalYear) {
      return;
    }

    // Check if fiscalYearId was changed externally (by user selection)
    const fiscalYearChangedExternally =
      prevFiscalYearIdRef.current !== fiscalYearId;
    const okrTabChanged = prevOkrTabRef.current !== okrTab;

    // If fiscal year was changed externally, update sessions for that fiscal year
    if (fiscalYearChangedExternally && fiscalYearId) {
      const selectedFiscalYear = getAllFiscalYears?.items?.find(
        (i) => i?.id == fiscalYearId,
      );

      if (selectedFiscalYear) {
        if (useAllSessionsForEmployeeOkr) {
          const allSessionIds =
            selectedFiscalYear?.sessions?.map((item: any) => item.id) || [];
          setSessionIds(allSessionIds);
        } else {
          const activeSessionId = selectedFiscalYear?.sessions?.find(
            (s: any) => s?.active,
          )?.id;
          const fallbackFirstSessionId = selectedFiscalYear?.sessions?.[0]?.id;
          const chosen = activeSessionId || fallbackFirstSessionId || '';
          setSessionIds(chosen ? [chosen] : []);
        }
      }
      // Update refs after handling the change
      prevFiscalYearIdRef.current = fiscalYearId;
      prevOkrTabRef.current = okrTab;
      return;
    }

    // Only initialize default fiscal year if not already initialized and no fiscal year is set
    if (!initializedRef.current && !fiscalYearId) {
      const selectedFiscalYear = getActiveFisicalYear;

      if (!selectedFiscalYear) {
        initializedRef.current = true;
        return;
      }

      const newFiscalYearId = selectedFiscalYear?.id || '';

      if (useAllSessionsForEmployeeOkr) {
        const allSessionIds =
          selectedFiscalYear?.sessions?.map((item: any) => item.id) || [];
        setSessionIds(allSessionIds);
      } else {
        const activeSessionId = selectedFiscalYear?.sessions?.find(
          (s: any) => s?.active,
        )?.id;
        const fallbackFirstSessionId = selectedFiscalYear?.sessions?.[0]?.id;
        const chosen = activeSessionId || fallbackFirstSessionId || '';
        setSessionIds(chosen ? [chosen] : []);
      }

      setFiscalYearId(newFiscalYearId);
      prevFiscalYearIdRef.current = newFiscalYearId;
      prevOkrTabRef.current = okrTab;
      initializedRef.current = true;
      return;
    }

    // If okrTab changed, update sessions for current fiscal year
    if (okrTabChanged && fiscalYearId) {
      const selectedFiscalYear = getAllFiscalYears?.items?.find(
        (i) => i?.id == fiscalYearId,
      );

      if (selectedFiscalYear) {
        if (useAllSessionsForEmployeeOkr) {
          const allSessionIds =
            selectedFiscalYear?.sessions?.map((item: any) => item.id) || [];
          setSessionIds(allSessionIds);
        } else {
          const activeSessionId = selectedFiscalYear?.sessions?.find(
            (s: any) => s?.active,
          )?.id;
          const fallbackFirstSessionId = selectedFiscalYear?.sessions?.[0]?.id;
          const chosen = activeSessionId || fallbackFirstSessionId || '';
          setSessionIds(chosen ? [chosen] : []);
        }
      }
      // Update ref after handling the change
      prevOkrTabRef.current = okrTab;
    }
  }, [
    getAllFiscalYears?.items,
    getActiveFisicalYear,
    okrTab,
    allEmployeeLayout,
    filterInPopover,
    fiscalYearId,
    setFiscalYearId,
    setSessionIds,
  ]);

  const DepartmentWithUsers = Departments?.filter(
    (i: any) => i.users?.length > 0,
  );

  const handleFilter = (value: string, key: keyof typeof searchObjParams) => {
    setSearchObjParams(key, value);
  };

  const handleReset = () => {
    setFiscalYearId('');
    setSessionIds([]);
    setOkrStatusPillId(null);
    handleFilter('', 'metricTypeId');
    handleFilter('', 'userId');
    handleFilter('', 'departmentId');
  };

  const MobileFilterContent = ({
    showStatusPills = false,
  }: {
    showStatusPills?: boolean;
  }) => (
    <div
      id="mobile-filter-content"
      data-cy="okr-mobile-filter-content"
      className="flex flex-col gap-4"
    >
      {showStatusPills && (
        <div
          className="flex w-full min-w-0 flex-wrap gap-2"
          data-cy="okr-status-pills-row"
        >
          {OKR_STATUS_PILLS.map((pill) => {
            const isSelected = okrStatusPillId === pill.id;
            return (
              <Button
                key={pill.id}
                type="default"
                size="small"
                data-cy={`okr-status-pill-${pill.id}`}
                onClick={() =>
                  setOkrStatusPillId(
                    okrStatusPillId === pill.id ? null : pill.id,
                  )
                }
                className={
                  isSelected
                    ? '!rounded-lg !h-7 !min-h-0 !px-2 !py-0 !leading-none border-okr-primary text-okr-primary !bg-white hover:!bg-[#FAFAFA] hover:!border-okr-primary hover:!text-okr-primary'
                    : '!rounded-lg !h-7 !min-h-0 !px-2 !py-0 !leading-none border-gray-200 text-gray-700 !bg-white hover:!bg-gray-50 hover:!border-gray-300 hover:!text-gray-800'
                }
              >
                {pill.label}
              </Button>
            );
          })}
        </div>
      )}
      {/* Employee – full width, label above (same fields as desktop) */}
      {showUserAndDepartmentFilters && (
        <div
          id="mobile-employee-field"
          data-cy="okr-mobile-employee-field"
          className="flex flex-col gap-2"
        >
          <label
            id="mobile-employee-label"
            data-cy="okr-mobile-employee-label"
            className="text-sm font-medium text-gray-700"
          >
            Employee{' '}
            <span
              className="text-red-500"
              data-cy="okr-mobile-employee-required"
            >
              *
            </span>
          </label>
          <Select
            id="mobile-employee-select"
            data-cy="okr-mobile-employee-select"
            showSearch
            placeholder="Input"
            className="w-full h-12 rounded-lg"
            allowClear
            getPopupContainer={(node) => node.parentElement ?? document.body}
            value={searchObjParams.userId}
            onChange={(value) => handleFilter(value, 'userId')}
            filterOption={(input: any, option: any) =>
              (option?.label ?? '')?.toLowerCase().includes(input.toLowerCase())
            }
            options={allUsers?.items?.map((item: any) => ({
              ...item,
              value: item?.id,
              label:
                item?.firstName + ' ' + item?.middleName + ' ' + item?.lastName,
            }))}
          />
        </div>
      )}

      {/* Department – full width (same as desktop when tab != 1) */}
      {showUserAndDepartmentFilters && (
        <div
          id="mobile-department-field"
          data-cy="okr-mobile-department-field"
          className="flex flex-col gap-2"
        >
          <label
            id="mobile-department-label"
            data-cy="okr-mobile-department-label"
            className="text-sm font-medium text-gray-700"
          >
            Department{' '}
            <span
              className="text-red-500"
              data-cy="okr-mobile-department-required"
            >
              *
            </span>
          </label>
          <Select
            id="mobile-department-select"
            data-cy="okr-mobile-department-select"
            placeholder="Select"
            className="w-full h-12 rounded-lg"
            allowClear
            showSearch
            value={searchObjParams.departmentId}
            onChange={(value) => handleFilter(value, 'departmentId')}
            filterOption={(input, option) =>
              (option?.children as any)
                ?.toLowerCase()
                .includes(input.toLowerCase())
            }
          >
            {DepartmentWithUsers?.map((dept: any) => (
              <Option
                data-cy={`okr-mobile-department-select-option-${dept?.id}`}
                key={dept.id}
                value={dept.id}
              >
                {dept.name}
              </Option>
            ))}
          </Select>
        </div>
      )}

      {/* Fiscal Year – full width */}
      <div
        id="mobile-fiscal-year-field"
        data-cy="okr-mobile-fiscal-year-field"
        className="flex flex-col gap-2"
      >
        <label
          id="mobile-fiscal-year-label"
          data-cy="okr-mobile-fiscal-year-label"
          className="text-sm font-medium text-gray-700"
        >
          Fiscal Year{' '}
          <span
            className="text-red-500"
            data-cy="okr-mobile-fiscal-year-required"
          >
            *
          </span>
        </label>
        <Select
          loading={fyLoading}
          value={fiscalYearId}
          id="mobile-fiscal-year-select"
