'use client';

import React, { useEffect, useMemo } from 'react';
import { Form, InputNumber, Modal, Select } from 'antd';
import { CloseOutlined, PlusOutlined } from '@ant-design/icons';
import CustomButton from '@/components/common/buttons/customButton';
import { useGetAllPositions } from '@/store/server/features/employees/positions/queries';
import {
  useGetBscCycles,
  useGetBscPerspectiveCatalog,
  useGetBscRolePerspectives,
} from '@/store/server/features/bsc/queries';
import { useSaveBscRolePerspectives } from '@/store/server/features/bsc/mutation';
import { useBscUiStore } from '@/store/uistate/features/bsc';
import { CycleStatus } from '@/types/bsc';
import {
  MAX_PERSPECTIVE_WEIGHT,
  validatePerspectiveWeights,
} from '@/utils/bsc/scoring';

function asList(data: any): any[] {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  if (Array.isArray(data.items)) return data.items;
  return [];
}

type WeightRow = {
  name?: string;
  weight?: number | null;
};

export default function AssignPerspectivesModal() {
  const [form] = Form.useForm<{
    positionId?: string;
    rows: WeightRow[];
  }>();
  const { assignModalOpen, closeAssignModal, selectedConfigId } =
    useBscUiStore();
  const { data: configs } = useGetBscCycles();
  const { data: catalog } = useGetBscPerspectiveCatalog();
  const { data: allocations } = useGetBscRolePerspectives();
  const { data: positionsData } = useGetAllPositions();
  const savePerspectives = useSaveBscRolePerspectives();

  const evaluationConfigId = useMemo(() => {
    if (selectedConfigId && configs?.some((c) => c.id === selectedConfigId)) {
      return selectedConfigId;
    }
    const open = (configs || []).find((c) => c.status === CycleStatus.Open);
    return open?.id || configs?.[0]?.id || '';
  }, [configs, selectedConfigId]);

  const positionOptions = asList(positionsData).map((p: any) => ({
    value: String(p.id),
    label: p.name || p.positionName || 'Position',
    departmentName: p.departmentName || p.department?.name || null,
  }));
  const catalogNames = (catalog || []).map((item) => item.name);

  const watchedPositionId = Form.useWatch('positionId', form);
  const watchedRows: WeightRow[] = Form.useWatch('rows', form) || [];
  const selectedNames = useMemo(
    () => new Set(watchedRows.map((row) => row?.name).filter(Boolean)),
    [watchedRows],
  );
  const weights = useMemo(() => {
    const map: Record<string, number> = {};
    for (const row of watchedRows) {
      if (!row?.name) continue;
      map[row.name] = Number(row.weight || 0);
    }
    return map;
  }, [watchedRows]);
  const validation = useMemo(
    () => validatePerspectiveWeights(weights),
    [weights],
  );

  useEffect(() => {
    if (!assignModalOpen) return;
    form.resetFields();
    form.setFieldsValue({
      rows: [{ name: undefined, weight: undefined }],
    });
  }, [assignModalOpen, form]);

  useEffect(() => {
    if (!assignModalOpen || !evaluationConfigId || !watchedPositionId) return;
    const position = asList(positionsData).find(
      (p: any) => String(p.id) === watchedPositionId,
    );
    const title = position?.name || position?.positionName || '';
    const existing = (allocations || []).find((row) => {
      if (row.evaluationConfigId !== evaluationConfigId) return false;
      if (row.positionId && row.positionId === watchedPositionId) return true;
      return row.positionTitle.toLowerCase() === title.toLowerCase();
    });
    const rows = existing?.weights
      ? Object.entries(existing.weights)
          .filter(([, weight]) => Number(weight) > 0)
          .map(([name, weight]) => ({ name, weight }))
      : [];
    form.setFieldsValue({
      rows: rows.length ? rows : [{ name: undefined, weight: undefined }],
    });
  }, [
    assignModalOpen,
    evaluationConfigId,
    watchedPositionId,
    allocations,
    positionsData,
    form,
  ]);

  const handleClose = () => {
    form.resetFields();
    closeAssignModal();
  };

  const handleSubmit = async () => {
    if (!evaluationConfigId) return;
    const values = await form.validateFields();
    const nextWeights: Record<string, number> = {};
    for (const row of values.rows || []) {
      if (!row?.name) continue;
      nextWeights[row.name] = Number(row.weight);
    }
    const check = validatePerspectiveWeights(nextWeights);
    if (!check.valid) {
      form.setFields([
        { name: 'rows', errors: [check.message || 'Invalid weights'] },
      ]);
      return;
    }

    const position = positionOptions.find((p) => p.value === values.positionId);
    const positionTitle = position?.label || '';
    const cycle = (configs || []).find((c) => c.id === evaluationConfigId);

    await savePerspectives.mutateAsync({
      evaluationConfigId,
      positionId: values.positionId || null,
      positionTitle,
      departmentName:
        position?.departmentName || cycle?.departmentNames?.[0] || null,
      weights: nextWeights,
    });

    handleClose();
  };

  return (
    <Modal
      open={assignModalOpen}
      onCancel={handleClose}
      footer={null}
      centered
      width={640}
      closeIcon={<CloseOutlined />}
      title="Assign perspectives to a role"
      destroyOnClose
      data-cy="bsc-assign-perspectives-modal"
    >
      <Form form={form} layout="vertical" className="mt-2">
        <Form.Item
          name="positionId"
          label="Role"
          rules={[{ required: true, message: 'Select a role' }]}
        >
          <Select
            placeholder="Select any role from the organization"
            options={positionOptions}
            showSearch
            optionFilterProp="label"
            data-cy="bsc-assign-role"
          />
        </Form.Item>

        <p
          data-cy="settings-bsc-perspective-assignment-components-assignperspectivesmodal-tsx-assignperspectivesmodal-p-180"
          className="mb-2 text-[13px] font-medium text-[#161A2C]"
        >
          Perspectives
        </p>
        <Form.List name="rows">
          {(fields, { add, remove }) => (
            <>
              <div
                data-cy="settings-bsc-perspective-assignment-components-assignperspectivesmodal-tsx-assignperspectivesmodal-div-186"
                className="flex flex-col gap-2"
              >
                {fields.map((field) => {
                  const currentName = watchedRows[field.name]?.name;
                  const available = catalogNames.filter(
                    (name) => name === currentName || !selectedNames.has(name),
                  );
                  return (
                    <div
                      key={field.key}
                      className="flex items-start gap-2"
                      data-cy={`bsc-assign-row-${field.key}`}
                    >
                      <Form.Item
                        name={[field.name, 'name']}
                        className="mb-0 flex-1"
                        rules={[
                          { required: true, message: 'Select a perspective' },
                        ]}
                      >
                        <Select
                          placeholder="Perspective"
                          options={available.map((name) => ({
                            value: name,
                            label: name,
                          }))}
                          data-cy={`bsc-assign-perspective-${field.name}`}
                        />
                      </Form.Item>
                      <Form.Item
                        name={[field.name, 'weight']}
                        className="mb-0"
                        rules={[
                          { required: true, message: 'Weight is required' },
                        ]}
                      >
                        <InputNumber
                          min={1}
                          max={MAX_PERSPECTIVE_WEIGHT}
                          placeholder="%"
                          className="w-[88px]"
                          data-cy={`bsc-assign-weight-${field.name}`}
                        />
                      </Form.Item>
                      {fields.length > 1 && (
                        <button
                          data-cy="settings-bsc-perspective-assignment-components-assignperspectivesmodal-tsx-assignperspectivesmodal-button-230"
                          type="button"
                          className="mt-1 border-none bg-transparent text-[#8F94A3] cursor-pointer"
                          onClick={() => remove(field.name)}
                        >
                          Remove
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
              <button
                type="button"
                onClick={() => add({ name: undefined, weight: undefined })}
                disabled={selectedNames.size >= catalogNames.length}
                className="mt-3 inline-flex items-center gap-1.5 border-none bg-transparent p-0 text-[13px] font-semibold text-[#574CFF] cursor-pointer hover:text-[#3236e6] disabled:opacity-40"
                data-cy="bsc-assign-add-row"
              >
                <PlusOutlined className="text-[12px]" />
                Add perspective
              </button>
            </>
          )}
        </Form.List>

        <p
          data-cy="settings-bsc-perspective-assignment-components-assignperspectivesmodal-tsx-assignperspectivesmodal-p-256"
          className="mt-3 mb-0 text-[12px] text-[#8F94A3]"
        >
          Weights must total 100%. A single perspective may use the full 100%.
          {!validation.valid && watchedRows.some((r) => r?.weight) ? (
            <span
              data-cy="settings-bsc-perspective-assignment-components-assignperspectivesmodal-tsx-assignperspectivesmodal-span-260"
              className="block mt-1 text-[#DC2626]"
            >
              {validation.message}
            </span>
          ) : null}
        </p>

        <div
          data-cy="settings-bsc-perspective-assignment-components-assignperspectivesmodal-tsx-assignperspectivesmodal-div-266"
          className="flex justify-end gap-3 mt-6"
        >
          <CustomButton
            type="default"
            title="Cancel"
            onClick={handleClose}
            className="h-10 px-6 rounded-lg"
          />
          <CustomButton
            title="Assign"
            onClick={handleSubmit}
            loading={savePerspectives.isLoading}
            className="h-10 px-8 rounded-lg bg-[#2b54ad] hover:bg-[#3d66c2]"
          />
        </div>
      </Form>
    </Modal>
  );
}

'use client';

import React, { useEffect, useMemo } from 'react';
import { Button, Form, InputNumber, Select, Tooltip, message } from 'antd';
import {
  CloseCircleFilled,
  LeftOutlined,
  PlusOutlined,
} from '@ant-design/icons';
import { useParams, useRouter } from 'next/navigation';
import {
  useGetBscCycles,
  useGetBscKpiLibrary,
  useGetBscPerspectiveCatalog,
  useGetBscRolePerspective,
  useGetBscRolePerspectives,
} from '@/store/server/features/bsc/queries';
import { useSaveBscRolePerspectives } from '@/store/server/features/bsc/mutation';
import {
  MAX_PERSPECTIVE_WEIGHT,
  validatePerspectiveWeights,
} from '@/utils/bsc/scoring';
import {
  buildRoleList,
  decodeRoleSlug,
} from '../../../bsc-setup/_utils/roleList';

type WeightRow = {
  name?: string;
  weight?: number | null;
};

export default function BscPerspectiveAssignmentRolePage() {
  const [form] = Form.useForm<{ rows: WeightRow[] }>();
  const params = useParams();
  const router = useRouter();
  const roleKey = String(params?.roleKey || '');

  const { data: catalog, isLoading: catalogLoading } =
    useGetBscPerspectiveCatalog();
  const { data: configs } = useGetBscCycles();
  const { data: allKpis, isLoading: kpisLoading } = useGetBscKpiLibrary();
  const { data: allocations } = useGetBscRolePerspectives();
  const savePerspectives = useSaveBscRolePerspectives();

  const roles = useMemo(
    () => buildRoleList(configs || [], allKpis || [], allocations || []),
    [configs, allKpis, allocations],
  );

  const role = useMemo(
    () =>
      roles.find((r) => r.key === roleKey) ||
      roles.find(
        (r) =>
          r.positionTitle.toLowerCase() ===
          decodeRoleSlug(roleKey).toLowerCase(),
      ),
    [roles, roleKey],
  );

  const roleTitle = role?.positionTitle || decodeRoleSlug(roleKey);

  const configId = useMemo(
    () =>
      role?.evaluationConfigId ||
      configs?.find((c) =>
        (c.positionTitles || []).some(
          (t) => t.toLowerCase() === roleTitle.toLowerCase(),
        ),
      )?.id ||
      configs?.[0]?.id ||
      '',
    [role, configs, roleTitle],
  );

  const { data: allocation, isLoading: allocationLoading } =
    useGetBscRolePerspective(configId, role?.positionId || null, roleTitle);

  const watchedRows: WeightRow[] = Form.useWatch('rows', form) || [];
  const selectedNames = useMemo(
    () => new Set(watchedRows.map((row) => row?.name).filter(Boolean)),
    [watchedRows],
  );
  const weights = useMemo(() => {
    const map: Record<string, number> = {};
    for (const row of watchedRows) {
      if (!row?.name) continue;
      map[row.name] = Number(row.weight || 0);
    }
    return map;
  }, [watchedRows]);
  const roundedTotal = Math.round(
    Object.values(weights).reduce((sum, value) => sum + value, 0),
  );
  const validation = useMemo(
    () => validatePerspectiveWeights(weights),
    [weights],
  );
  const weightIncomplete = !validation.valid;
  const weightTone =
    roundedTotal === 100
      ? 'text-[#059669]'
      : roundedTotal > 100
        ? 'text-[#DC2626]'
        : 'text-[#D97706]';

  const loading = kpisLoading || allocationLoading || catalogLoading;
  const catalogNames = (catalog || []).map((item) => item.name);

  useEffect(() => {
    if (loading) return;
    const assigned = allocation?.weights
      ? Object.entries(allocation.weights)
          .filter(([, weight]) => Number(weight) > 0)
          .map(([name, weight]) => ({ name, weight }))
      : [];
    form.setFieldsValue({
      rows: assigned.length
        ? assigned
        : [{ name: undefined, weight: undefined }],
    });
  }, [loading, roleKey, configId, allocation, form]);

  const handleSave = async () => {
    if (weightIncomplete) {
      message.info({
        content:
          validation.message ||
          'Assigned perspective weights must total exactly 100% before you save.',
        duration: 4,
      });
      return;
    }
    const values = await form.validateFields();
    const nextWeights: Record<string, number> = {};
    for (const row of values.rows || []) {
      if (!row?.name) continue;
      nextWeights[row.name] = Number(row.weight);
    }
    await savePerspectives.mutateAsync({
      evaluationConfigId: configId,
      positionId: role?.positionId || null,
      positionTitle: roleTitle,
      departmentName: role?.departmentNames?.[0] || null,
      weights: nextWeights,
    });
  };

  return (
    <div className="w-full" data-cy="bsc-perspective-assignment-detail">
      <div
        data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-div-152"
        className="overflow-hidden rounded-xl border border-[#F1F2F6] bg-white min-h-[400px]"
      >
        <div
          className="flex flex-wrap items-center justify-between gap-3 border-b border-[#F1F2F6] bg-[#FAFBFC] px-4 py-3 md:px-6 md:py-4"
          data-cy="bsc-assignment-header"
        >
          <div
            data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-div-157"
            className="flex min-w-0 items-center gap-2 md:gap-3"
          >
            <button
              type="button"
              onClick={() =>
                router.push('/okr/settings/bsc-perspective-assignment')
              }
              className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg text-[#64748B] transition-colors hover:bg-white hover:text-[#574CFF] hover:shadow-sm"
              aria-label="Back to assignment"
              data-cy="bsc-assignment-back"
            >
              <LeftOutlined className="text-[14px]" />
            </button>
            <div
              data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-div-169"
              className="min-w-0"
            >
              <p
                data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-p-170"
                className="m-0 truncate text-[12px] font-semibold leading-snug text-[#161A2C] md:text-sm"
              >
                {roleTitle}
              </p>
              {!!role?.departmentNames?.length && (
                <p
                  data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-p-174"
                  className="m-0 mt-0.5 truncate text-[11px] text-[#8F94A3]"
                >
                  {role.departmentNames.join(' · ')}
                </p>
              )}
            </div>
          </div>

          <div
            data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-div-181"
            className="flex min-w-0 flex-shrink-0 flex-wrap items-center justify-end gap-2 md:gap-3"
          >
            <span
              className="whitespace-nowrap text-[12px] tabular-nums text-[#475569] md:text-sm"
              data-cy="bsc-assignment-weight-summary"
            >
              <span
                data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-span-186"
                className={`text-[18px] font-extrabold md:text-[20px] ${weightTone}`}
              >
                {roundedTotal}
              </span>
              <span
                data-cy="bsc-perspective-assignment-role-rolekey-page-tsx-page-span-191"
                className="text-[13px] font-medium text-[#94A3B8] md:text-[14px]"
              >
                {' '}
                / 100
              </span>
            </span>
            <Tooltip
              title={
                weightIncomplete
                  ? validation.message ||
                    'Total weight must equal 100 before you can save.'
                  : ''
              }
            >
              <Button
