      await cascadeKpisToScope(
        created.id,
        {
          ...values,
          departmentIds: created.departmentIds?.length
            ? created.departmentIds
            : values.departmentIds,
        },
        measureRows,
      );
      handleClose();
    } finally {
      setSavingAll(false);
    }
  };

