                          KPI {index + 1}
                        </span>
                      </div>

                      <Form.Item name={[field.name, 'id']} hidden>
                        <Input />
                      </Form.Item>

                      <div
                        data-cy="bsc-setup-role-rolekey-page-tsx-page-div-370"
                        className="flex items-center gap-3 w-full"
                      >
                        <Form.Item
                          name={[field.name, 'name']}
                          className="mb-0 flex-1"
                          rules={[
                            {
                              required: true,
                              whitespace: true,
                              message:
                                'Please input a KPI name or delete this field.',
                            },
                          ]}
                          style={{ flex: 1, marginBottom: 0 }}
                        >
                          <Input
                            placeholder="Add your KPI name here"
                            className="text-[12px] h-10 border-gray-200 rounded-lg"
                            data-cy={`bsc-kpi-name-${field.name}`}
                          />
                        </Form.Item>
                        <CloseCircleFilled
                          className="text-[#3D41FF] cursor-pointer hover:text-[#3236e6] transition-colors"
                          style={{ fontSize: 20 }}
                          onClick={() => remove(field.name)}
                          data-cy={`bsc-kpi-remove-${field.name}`}
                        />
                      </div>

                      <div
                        data-cy="bsc-setup-role-rolekey-page-tsx-page-div-398"
                        className="mt-2 flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-end"
                      >
                        <div
                          data-cy="bsc-setup-role-rolekey-page-tsx-page-div-399"
                          className="w-full sm:w-[220px]"
                        >
                          <div
                            data-cy="bsc-setup-role-rolekey-page-tsx-page-div-400"
                            className="mb-1 text-xs flex items-center gap-1.5 text-gray-500"
                          >
                            <span
                              data-cy="bsc-setup-role-rolekey-page-tsx-page-span-401"
                              className="w-1.5 h-1.5 rounded-full bg-[#574CFF] inline-block"
                            />
                            Perspective
                          </div>
                          <Form.Item
                            name={[field.name, 'perspective']}
                            className="mb-0"
                            rules={[
                              {
                                required: true,
                                message: 'Select a perspective',
                              },
                            ]}
                          >
                            <Select
                              placeholder="Select perspective"
                              options={perspectiveNames.map((name) => ({
                                value: name,
                                label: name,
                              }))}
                              className="w-full"
                              data-cy={`bsc-kpi-perspective-${field.name}`}
                            />
                          </Form.Item>
                        </div>
                        <div
                          data-cy="bsc-setup-role-rolekey-page-tsx-page-div-425"
                          className="min-w-0 flex-1"
                        >
                          <div
                            data-cy="bsc-setup-role-rolekey-page-tsx-page-div-426"
                            className="mb-1 text-xs flex items-center gap-1.5 text-gray-500"
                          >
                            <span
                              data-cy="bsc-setup-role-rolekey-page-tsx-page-span-427"
                              className="w-1.5 h-1.5 rounded-full bg-[#574CFF] inline-block"
                            />
                            Description
                          </div>
                          <Form.Item
                            name={[field.name, 'description']}
                            className="mb-0"
                            rules={[
                              {
                                required: true,
                                whitespace: true,
                                message: 'Description is required',
                              },
                            ]}
                          >
                            <Input
                              placeholder="What this KPI measures"
                              className="text-[12px] h-10 border-gray-200 rounded-lg"
                              data-cy={`bsc-kpi-description-${field.name}`}
                            />
                          </Form.Item>
                        </div>
                        <div data-cy="bsc-setup-role-rolekey-page-tsx-page-div-448">
                          <div
                            data-cy="bsc-setup-role-rolekey-page-tsx-page-div-449"
                            className="mb-1 text-xs flex items-center gap-1.5 text-gray-500"
                          >
                            <span
                              data-cy="bsc-setup-role-rolekey-page-tsx-page-span-450"
                              className="w-1.5 h-1.5 rounded-full bg-[#574CFF] inline-block"
                            />
                            Weight
                          </div>
                          <Form.Item
                            name={[field.name, 'weight']}
                            className="mb-0"
                            rules={[
                              {
                                required: true,
                                message: 'Weight is required',
                              },
                              {
                                validator: (rule, value) => {
                                  if (
                                    value !== undefined &&
                                    value !== null &&
                                    value <= 0
                                  ) {
                                    return Promise.reject(
                                      new Error(
                                        'Weight must be greater than 0',
                                      ),
                                    );
                                  }
                                  return Promise.resolve();
                                },
                              },
                            ]}
                          >
                            <InputNumber
                              min={1}
                              max={100}
                              placeholder="0"
                              className="w-[80px] text-xs h-10 [&_.ant-input-number]:h-full [&_.ant-input-number-input-wrap]:h-full [&_.ant-input-number-input-wrap]:flex [&_.ant-input-number-input-wrap]:items-center [&_.ant-input-number-input]:h-full"
                              data-cy={`bsc-kpi-weight-${field.name}`}
                            />
                          </Form.Item>
                        </div>
                      </div>
                    </div>
                  );

                  return (
                    <div
                      data-cy="bsc-setup-role-rolekey-page-tsx-page-div-493"
                      className="flex flex-col gap-6"
                    >
                      {unassignedFields.length > 0 && (
                        <section
                          className="rounded-xl bg-[#F9FAFB] px-3.5 py-3 md:px-4 md:py-4"
                          data-cy="bsc-perspective-section-unassigned"
                        >
                          <div
                            data-cy="bsc-setup-role-rolekey-page-tsx-page-div-499"
                            className="mb-3 flex flex-wrap items-center justify-between gap-2"
                          >
                            <h2
                              data-cy="bsc-setup-role-rolekey-page-tsx-page-h2-500"
                              className="m-0 text-[13px] font-semibold text-[#161A2C]"
                            >
                              New KPI
                            </h2>
                          </div>
                          <div
                            data-cy="bsc-setup-role-rolekey-page-tsx-page-div-504"
                            className="flex flex-col gap-3"
                          >
                            {unassignedFields.map((field, index) =>
                              renderKpiRow(field, index),
                            )}
                          </div>
                        </section>
                      )}
                      {perspectiveNames.map((perspective) => {
                        const sectionFields = fields.filter(
                          (field) => perspectiveOf(field) === perspective,
                        );
                        const sectionWeight = Math.round(
                          weightByPerspective[perspective] || 0,
                        );
                        const allocated =
                          allocation?.weights?.[perspective] ?? 0;
                        const overCap = sectionWeight > allocated;
                        return (
                          <section
                            key={perspective}
                            className="rounded-xl bg-[#F9FAFB] px-3.5 py-3 md:px-4 md:py-4"
                            data-cy={`bsc-perspective-section-${perspective}`}
                          >
                            <div
                              data-cy="bsc-setup-role-rolekey-page-tsx-page-div-527"
                              className="mb-3 flex flex-wrap items-center justify-between gap-2"
                            >
                              <h2
                                data-cy="bsc-setup-role-rolekey-page-tsx-page-h2-528"
                                className="m-0 text-[13px] font-semibold text-[#161A2C]"
                              >
                                {perspective}
                              </h2>
                              <span
                                className={`text-[12px] tabular-nums ${
                                  overCap
                                    ? 'font-semibold text-[#DC2626]'
                                    : 'text-[#64748B]'
                                }`}
                                data-cy={`bsc-perspective-weight-${perspective}`}
                              >
                                {sectionWeight} / {allocated}
                              </span>
                            </div>

                            <div
                              data-cy="bsc-setup-role-rolekey-page-tsx-page-div-543"
                              className="flex flex-col gap-3"
                            >
                              {sectionFields.length === 0 && (
                                <p
                                  data-cy="bsc-setup-role-rolekey-page-tsx-page-p-545"
                                  className="m-0 text-[12px] text-[#94A3B8]"
                                >
                                  Add at least one KPI and select this
                                  perspective.
                                </p>
                              )}
                              {sectionFields.map((field, index) =>
                                renderKpiRow(field, index),
                              )}

                              <button
                                type="button"
                                onClick={() => add(emptyRow(perspective))}
                                className="inline-flex items-center gap-1.5 border-none bg-transparent p-0 text-[13px] font-semibold text-[#574CFF] cursor-pointer hover:text-[#3236e6]"
                                data-cy={`bsc-kpi-add-row-${perspective}`}
                              >
                                <PlusOutlined className="text-[12px]" />
                                Add KPI
                              </button>
                            </div>
                          </section>
                        );
                      })}
                    </div>
                  );
                }}
              </Form.List>

              <div
                className="mt-6 flex flex-wrap items-center justify-end gap-3 border-t border-[#F1F2F6] pt-4"
                data-cy="bsc-kpi-weight-footer"
              >
                <span
                  data-cy="bsc-setup-role-rolekey-page-tsx-page-span-576"
                  className="text-sm font-medium text-[#161A2C] whitespace-nowrap"
                >
                  Weight Point:{' '}
                  <span
                    data-cy="bsc-setup-role-rolekey-page-tsx-page-span-578"
                    className={`font-bold ${weightTone}`}
                  >
                    {roundedTotal}%
                  </span>
                </span>
              </div>
            </Form>
          )}
        </div>
      </div>
    </div>
  );
}

