                    <Tooltip title="Enter the total percentage (0-100).">
                      <QuestionCircleOutlined
                        className="text-[#bfbfbf] text-[14px] ml-1 cursor-help"
                        data-cy="okr-criteria-modal-percentage-tooltip"
                      />
                    </Tooltip>
                  </div>
