                >
                  Weight
                </span>
              </div>
              {selectedCriteria.map((criteria) => (
                <div
                  key={criteria.vpCriteriaId}
                  className="flex gap-4 mb-3"
                  data-cy={`okr-criteria-modal-weight-row-${criteria.vpCriteriaId}`}
                >
