  };

  const businessSizeArray = Object.entries(businessSize).map(
    ([key, value]) => ({
      key: Number(key),
      value,
    }),
  );

  const getBusinessSizeIndex = (value: string): number | undefined => {
    return businessSizeArray.find(({ value: v }) => v === value)?.key;
