};

const renderTreeNodes = (
  data: Department[],
  onEdit: (department: Department) => void,
  onAdd: (parentId: string) => void,
  onDelete: (departmentId: string) => void,
  isRoot = false,
) =>
  data.map((item) => (
    <TreeNode
      key={item.id}
      label={
        <DepartmentNode
          data={item}
          onEdit={() => onEdit(item)}
          onAdd={() => onAdd(item.id)}
          onDelete={() => onDelete(item.id)}
          isRoot={isRoot}
        />
      }
    >
      {item.department &&
        renderTreeNodes(item.department, onEdit, onAdd, onDelete)}
    </TreeNode>
  ));

const OrgChartComponent: React.FC = () => {
  const {
    orgData,
    addDepartment,
    updateDepartment,
    deleteDepartment,
    isFormVisible,
    setIsFormVisible,
    selectedDepartment,
    setSelectedDepartment,
    parentId,
    setParentId,
    isDeleteConfirmVisible,
    setIsDeleteConfirmVisible,
    setOrgData,
    hasManuallyDeletedDepartments,
    setHasManuallyDeletedDepartments,
  } = useOrganizationStore();

  const handleEdit = (department: Department) => {
    setSelectedDepartment(department);
    setIsFormVisible(true);
  };

  const handleAdd = (parentId: string) => {
    setParentId(parentId);
    setSelectedDepartment(null);
    setIsFormVisible(true);
  };

  const handleDelete = (departmentId: string) => {
    setIsDeleteConfirmVisible(true);
    setSelectedDepartment({ id: departmentId } as Department);
  };

  const handleFormSubmit = (values: Department) => {
    if (selectedDepartment?.id === 'root') {
      setOrgData({
        ...orgData,
        name: values.name,
      });
    } else if (selectedDepartment) {
      updateDepartment({ ...selectedDepartment, ...values });
    } else if (parentId) {
      addDepartment(parentId, values);
      // Reset the flag when adding new departments so defaults can be recreated if needed
      setHasManuallyDeletedDepartments(false);
    }
    setIsFormVisible(false);
  };

  const handleDeleteConfirm = () => {
    if (selectedDepartment) {
      deleteDepartment(selectedDepartment.id);
      // Mark that departments have been manually deleted
      setHasManuallyDeletedDepartments(true);
    }
    setIsDeleteConfirmVisible(false);
  };

  const { data: branches } = useGetBranches();

  useEffect(() => {
    // Only create default departments if they haven't been manually deleted before
    if (!orgData.department || orgData.department.length === 0) {
      if (!hasManuallyDeletedDepartments) {
        const defaultDepartments: Department[] = [
          {
            id: uuidv4(),
            name: 'HR',
            department: [],
            branchId: null,
            description: '',
            collapsed: false,
          },
          {
            id: uuidv4(),
            name: 'Marketing',
            department: [],
            branchId: null,
            description: '',
            collapsed: false,
          },
          {
            id: uuidv4(),
            name: 'Finance',
            department: [],
            branchId: null,
            description: '',
            collapsed: false,
          },
        ];

        setOrgData({
          ...orgData,
          name: orgData.name || 'CEO',
          branchId: null,
          department: defaultDepartments,
        });
      }
    }
  }, [branches, orgData.department, hasManuallyDeletedDepartments]);

  const rootDepartment: Department = {
    id: 'root',
    name: orgData?.name || 'CEO',
    department: orgData?.department || [],
    branchId: orgData?.branchId || '',
    description: '',
    collapsed: false,
  };

  return (
    <div
      data-cy="onboarding-components-steper-orgchartcomponent-tsx-orgchartcomponent-div-236"
      className="w-full py-7 overflow-x-auto lg:overflow-x-visible"
    >
      <div
        data-cy="onboarding-components-steper-orgchartcomponent-tsx-orgchartcomponent-div-237"
        className="p-4 sm:p-2 md:p-6 lg:p-8"
      >
        <Tree
          label={
            <DepartmentNode
              data={rootDepartment}
              onEdit={() => handleEdit(rootDepartment)}
              onAdd={() => handleAdd('root')}
              onDelete={() => {}}
              isRoot={true}
            />
          }
          lineWidth={'2px'}
          lineColor={'#722ed1'}
          lineBorderRadius={'10px'}
        >
          {renderTreeNodes(
            orgData?.department || [],
            handleEdit,
            handleAdd,
            handleDelete,
            false,
          )}
        </Tree>
      </div>
      <DepartmentForm
        onClose={() => setIsFormVisible(false)}
        open={isFormVisible}
        submitAction={handleFormSubmit}
        departmentData={selectedDepartment ?? undefined}
        title={
          selectedDepartment?.id === 'root'
            ? 'Edit CEO'
            : selectedDepartment
              ? 'Edit Department'
              : 'Add Department'
        }
      />
      <Modal
        title="Confirm Deletion"
        open={isDeleteConfirmVisible}
        onOk={handleDeleteConfirm}
        onCancel={() => setIsDeleteConfirmVisible(false)}
      >
        <p data-cy="onboarding-components-steper-orgchartcomponent-tsx-orgchartcomponent-p-280">
          Are you sure you want to delete this department?
        </p>
      </Modal>
    </div>
  );
};

