'use client';
import React, { useEffect, useState } from 'react';
import TimezoneComponent from '@/app/(afterLogin)/(timesheetInformation)/timesheet/settings/time-zone/_components/timeZone';
import useStepStore from '@/store/uistate/features/organizationStructure/steper/useStore';
import { Button } from 'antd';

function getBrowserGMTOffset(): string {
  const offsetMinutes = new Date().getTimezoneOffset();
  const totalMinutes = -offsetMinutes;

  const sign = totalMinutes >= 0 ? '+' : '-';
  const absMinutes = Math.abs(totalMinutes);
  const hours = Math.floor(absMinutes / 60)
    .toString()
    .padStart(2, '0');
  const minutes = (absMinutes % 60).toString().padStart(2, '0');

  return `${sign}${hours}:${minutes}`;
}

function TimeZone() {
  const { nextStep } = useStepStore();
  const [detectedTimeZone, setDetectedTimeZone] = useState<string>('');

  useEffect(() => {
    setDetectedTimeZone(getBrowserGMTOffset());
  }, [getBrowserGMTOffset()]);

  return (
    <div
      className="flex flex-col bg-gray-50 p-4 md:p-6 lg:p-8 rounded-lg my-4 md:my-6 lg:my-8 w-full h-full"
      data-cy="onboarding-timezone-container"
    >
      <div
        className="bg-white p-4 md:p-6 lg:p-8 rounded-lg w-full h-full"
        data-cy="onboarding-timezone-content"
      >
        <div
          className="flex flex-col md:flex-row justify-start items-center gap-2 md:gap-4 font-bold text-xl md:text-2xl text-black mt-4 md:mt-8"
          data-cy="onboarding-timezone-title"
        >
          Set up your Timezone
        </div>
        <TimezoneComponent autoDetectedTimeZone={detectedTimeZone} />
        <br data-cy="timezone-stepper-br" />
        <div
          className="text-center"
          data-cy="timezone-stepper-continue-wrapper"
        >
          <Button
            data-cy="timezone-stepper-continue-button"
            onClick={() => nextStep()}
            name="skipButton"
            type="link"
            htmlType="button"
          >
            Skip
          </Button>
        </div>
      </div>
    </div>
  );
}

