};

export default FiscalYearForm;

import React, { useEffect, useCallback, useState, useRef } from 'react';
import { Button, Col, DatePicker, Form, Input, Row, Spin, Popover } from 'antd';
import { FormInstance } from 'antd/lib';
import dayjs from 'dayjs';
import { useFiscalYearDrawerStore } from '@/store/uistate/features/organizations/settings/fiscalYear/useStore';
import { useIsMobile } from '@/hooks/useIsMobile';

const { RangePicker } = DatePicker;

interface SessionDrawerProps {
  form: FormInstance;
  isCreateLoading: boolean;
  isUpdateLoading: boolean;
  isFiscalYear?: boolean;
}

interface SessionData {
  sessionName: string;
  sessionStartDate: dayjs.Dayjs | null;
  sessionEndDate: dayjs.Dayjs | null;
  sessionDescription: string;
}

const SessionDrawer: React.FC<SessionDrawerProps> = ({
  form,
  isCreateLoading,
  isUpdateLoading,
}) => {
  const { isMobile } = useIsMobile();
  // Ref to track last processed fiscal year/calendar state to avoid infinite loops
  const lastProcessedFiscalYearRef = useRef<{
    start: string | null;
    end: string | null;
    calendarType: string | null;
  }>({ start: null, end: null, calendarType: null });

  const {
    calendarType,
    setCurrent,
    fiscalYearEnd,
    fiscalYearStart,
    setSessionFormValues,
    sessionFormValues,
    isEditMode,
    selectedFiscalYear,
    sessionData,
    setSessionData,
  } = useFiscalYearDrawerStore();

  // State to track form errors
  const [hasErrors, setHasErrors] = useState(false);
  const [firstErrorMsg, setFirstErrorMsg] = useState<string | null>(null);

  // Calculate number of sessions based on calendar type
  const getSessionCount = useCallback(() => {
    switch (calendarType) {
      case 'Quarter':
        return 4;
      case 'Semester':
        return 2;
      case 'Year':
        return 1;
      default:
        return 0;
    }
  }, [calendarType]);

  const getOriginalCalendarType = useCallback(() => {
    const sessionCount = selectedFiscalYear?.sessions?.length;
    if (sessionCount === 4) return 'Quarter';
    if (sessionCount === 2) return 'Semester';
    if (sessionCount === 1) return 'Year';
    return '';
  }, [selectedFiscalYear]);

  const normalizeSessionFormValues = useCallback((sessions: any[]) => {
    return sessions.map((session) => ({
      ...session,
      sessionStartDate: session.sessionStartDate
        ? dayjs(session.sessionStartDate)
        : null,
      sessionEndDate: session.sessionEndDate
        ? dayjs(session.sessionEndDate)
        : null,
      sessionDateRange:
        session.sessionDateRange &&
        Array.isArray(session.sessionDateRange) &&
        session.sessionDateRange.length === 2
          ? [
              dayjs(session.sessionDateRange[0]),
              dayjs(session.sessionDateRange[1]),
            ]
          : session.sessionStartDate && session.sessionEndDate
            ? [dayjs(session.sessionStartDate), dayjs(session.sessionEndDate)]
            : null,
    }));
  }, []);

  const mapSessionsFromSelectedFiscalYear = useCallback(() => {
    if (!selectedFiscalYear?.sessions) return [];
    return selectedFiscalYear.sessions.map((session: any) => ({
      id: session?.id,
      sessionName: session.name || '',
      sessionStartDate: session.startDate ? dayjs(session.startDate) : null,
      sessionEndDate: session.endDate ? dayjs(session.endDate) : null,
      sessionDescription: session.description || '',
      sessionDateRange:
        session.startDate && session.endDate
          ? [dayjs(session.startDate), dayjs(session.endDate)]
          : null,
    }));
  }, [selectedFiscalYear]);

  // Generate session data based on fiscal year dates and session count
  const generateSessionData = useCallback((): SessionData[] => {
    if (!fiscalYearStart || !fiscalYearEnd) return [];

    const sessionCount = getSessionCount();
    const sessions: SessionData[] = [];

    if (sessionCount === 0) return sessions;

    const startDate = dayjs(fiscalYearStart);
    const endDate = dayjs(fiscalYearEnd);
    const totalDays = endDate.diff(startDate, 'day');
    const daysPerSession = Math.floor(totalDays / sessionCount);

    for (let i = 0; i < sessionCount; i++) {
      const sessionStartDate =
        i === 0 ? startDate : startDate.add(i * daysPerSession, 'day');
      const sessionEndDate =
        i === sessionCount - 1
          ? endDate
          : startDate.add((i + 1) * daysPerSession - 1, 'day');

      sessions.push({
        sessionName: `Session ${i + 1}`,
        sessionStartDate,
        sessionEndDate,
        sessionDescription: '',
      });
    }

    return sessions;
  }, [fiscalYearStart, fiscalYearEnd, getSessionCount]);

  // Initialize sessions when component mounts or calendar type / dates change
  useEffect(() => {
    if (!calendarType || !fiscalYearStart || !fiscalYearEnd) {
      setSessionData([]);
      form.setFieldsValue({ sessionData: [] });
      return;
    }

    const currentStart = dayjs(fiscalYearStart).format('YYYY-MM-DD');
    const currentEnd = dayjs(fiscalYearEnd).format('YYYY-MM-DD');
    const isFirstInit =
      lastProcessedFiscalYearRef.current.start === null ||
      lastProcessedFiscalYearRef.current.end === null ||
      lastProcessedFiscalYearRef.current.calendarType === null;
    const fyStartChanged =
      !isFirstInit && lastProcessedFiscalYearRef.current.start !== currentStart;
    const fyEndChanged =
      !isFirstInit && lastProcessedFiscalYearRef.current.end !== currentEnd;
    const calendarTypeChanged =
      !isFirstInit &&
      lastProcessedFiscalYearRef.current.calendarType !== calendarType;

    if (
      !isFirstInit &&
      !fyStartChanged &&
      !fyEndChanged &&
      !calendarTypeChanged
    ) {
      return;
    }

    const applySessions = (sessions: any[]) => {
      const normalized = normalizeSessionFormValues(sessions);
      setSessionData(normalized);
      form.setFieldsValue({ sessionData: normalized });
      form.validateFields();
      lastProcessedFiscalYearRef.current = {
        start: currentStart,
        end: currentEnd,
        calendarType,
      };
      setSessionFormValues({
        sessionData: normalized,
        fiscalYearStart,
        fiscalYearEnd,
        lastGeneratedFiscalYearStart: fiscalYearStart,
        lastGeneratedFiscalYearEnd: fiscalYearEnd,
      });
    };

    const expectedCount = getSessionCount();
    const storedSessions = sessionFormValues?.sessionData;
    const storedCount = Array.isArray(storedSessions)
      ? storedSessions.length
      : 0;
    const originalCalendarType = getOriginalCalendarType();
    const structureMatchesOriginal =
      isEditMode &&
      !!originalCalendarType &&
      calendarType === originalCalendarType;

    // Prefer already-edited session values when remounting (e.g. back from months)
    if (
      isFirstInit &&
      storedCount === expectedCount &&
      storedCount > 0 &&
      !fyStartChanged &&
      !fyEndChanged &&
      !calendarTypeChanged
    ) {
      applySessions(storedSessions);
      return;
    }

    // Edit mode with unchanged breakdown: load persisted session names/dates
    if (
      isFirstInit &&
      structureMatchesOriginal &&
      selectedFiscalYear?.sessions?.length
    ) {
      applySessions(mapSessionsFromSelectedFiscalYear());
      return;
    }

    // Create mode, or breakdown/dates changed: regenerate structure
    applySessions(generateSessionData());
  }, [
    calendarType,
    fiscalYearStart,
    fiscalYearEnd,
    isEditMode,
    selectedFiscalYear,
    form,
    setSessionData,
    generateSessionData,
    setSessionFormValues,
    sessionFormValues,
    getSessionCount,
    getOriginalCalendarType,
    mapSessionsFromSelectedFiscalYear,
    normalizeSessionFormValues,
  ]);

  // Session validation function
  const validateSessionStartDate = useCallback(
    (rule: any, value: any) => {
      if (!value) return Promise.resolve();

      const fieldName = rule.field;
      const sessionIndex = parseInt(fieldName.match(/\d+/)?.[0] || '0');
      const currentSession = sessionData[sessionIndex];
      if (!currentSession) return Promise.resolve();

      const startDate = value;
      const endDate = currentSession.sessionEndDate;

      // Start date after end date
      if (startDate && endDate && dayjs(startDate).isAfter(dayjs(endDate))) {
        return Promise.reject(
          new Error('Start date cannot be after end date!'),
        );
      }

      // Start date before fiscal year start
      if (
        fiscalYearStart &&
        startDate &&
        dayjs(startDate).isBefore(dayjs(fiscalYearStart), 'day')
      ) {
        return Promise.reject(
          new Error(
            'Session start date cannot be before fiscal year start date!',
          ),
        );
      }

      // Overlap with previous session
      if (sessionIndex > 0) {
        const previousSession = sessionData[sessionIndex - 1];
        if (
          previousSession?.sessionEndDate &&
          (dayjs(startDate).isBefore(dayjs(previousSession.sessionEndDate)) ||
            dayjs(startDate).isSame(
              dayjs(previousSession.sessionEndDate),
              'day',
            ))
        ) {
          return Promise.reject(
            new Error(
              `Session ${sessionIndex + 1} start date cannot overlap with or be equal to the previous session's end date.`,
            ),
          );
        }
      }

      return Promise.resolve();
    },
    [sessionData, fiscalYearStart],
  );

  const validateSessionEndDate = useCallback(
    (rule: any, value: any) => {
      if (!value) return Promise.resolve();

      const fieldName = rule.field;
      const sessionIndex = parseInt(fieldName.match(/\d+/)?.[0] || '0');
      const currentSession = sessionData[sessionIndex];
      if (!currentSession) return Promise.resolve();

      const startDate = currentSession.sessionStartDate;
      const endDate = value;

      // End date before start date
      if (startDate && endDate && dayjs(startDate).isAfter(dayjs(endDate))) {
        return Promise.reject(
          new Error('End date cannot be before start date!'),
        );
      }

      const end = dayjs(endDate);
      const fyEnd = dayjs(fiscalYearEnd);

      if (fyEnd && end && end.isAfter(fyEnd, 'day')) {
        return Promise.reject(
          new Error('Session end date cannot be after fiscal year end date!'),
        );
      }

      // Overlap with next session
      if (sessionIndex < sessionData.length - 1) {
        const nextSession = sessionData[sessionIndex + 1];
        if (
          nextSession?.sessionStartDate &&
          (dayjs(endDate).isAfter(dayjs(nextSession.sessionStartDate)) ||
            dayjs(endDate).isSame(dayjs(nextSession.sessionStartDate), 'day'))
        ) {
          return Promise.reject(
            new Error(
              `Session ${sessionIndex + 1} end date cannot overlap with or be equal to the next session's start date.`,
            ),
          );
        }
      }

      return Promise.resolve();
    },
    [sessionData, fiscalYearEnd],
  );

  // Handle session field changes
  const handleSessionChange = useCallback(
    (index: number, field: keyof SessionData, value: any) => {
      setSessionData((prev: SessionData[]) => {
        const updated = [...prev];
        updated[index] = {
          ...updated[index],
          [field]: value,
        };
        // Update form values to keep them in sync
        form.setFieldsValue({ sessionData: updated });

        return updated;
      });
    },
    [setSessionData, form],
  );

  // Handle next step
  const handleNext = useCallback(() => {
    form
      .validateFields()
      .then(() => {
        // Save current session form values before going to next step
        const currentSessionValues = form.getFieldsValue();
        setSessionFormValues({
          ...currentSessionValues,
          fiscalYearStart,
          fiscalYearEnd,
          lastGeneratedFiscalYearStart: fiscalYearStart,
          lastGeneratedFiscalYearEnd: fiscalYearEnd,
        });
        setCurrent(2);
      })
      .catch(() => {
        // Do nothing, errors will be shown by the form
      });
  }, [form, setSessionFormValues, setCurrent, fiscalYearStart, fiscalYearEnd]);

  // Handle previous step
  const handlePrevious = useCallback(() => {
    // Store current session form values before going back
    const currentSessionValues = form.getFieldsValue();
    setSessionFormValues({
      ...currentSessionValues,
      fiscalYearStart,
      fiscalYearEnd,
      lastGeneratedFiscalYearStart: fiscalYearStart,
      lastGeneratedFiscalYearEnd: fiscalYearEnd,
    });
    setCurrent(0);
  }, [form, setSessionFormValues, setCurrent, fiscalYearStart, fiscalYearEnd]);

  // Update error state on form changes
  const updateErrorState = useCallback(() => {
    const fieldsError = form.getFieldsError();
    const errorFields = fieldsError.filter((field) => field.errors.length > 0);
    setHasErrors(errorFields.length > 0);
    setFirstErrorMsg(errorFields.length > 0 ? errorFields[0].errors[0] : null);
  }, [form]);

  useEffect(() => {
    updateErrorState();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sessionData]);

  // Render session form items
  const renderSessionForm = useCallback(
    (session: SessionData, index: number) => (
      <div
        key={index}
        className="mb-4"
        data-cy={`org-settings-fiscal-year-session-${index}`}
        id={`org-settings-fiscal-year-session-${index}`}
      >
        <Row gutter={8} align="middle">
          <Col
            span={isMobile ? undefined : 12}
            flex={isMobile ? 'auto' : undefined}
            style={isMobile ? { minWidth: 0 } : undefined}
          >
            <Form.Item
              name={['sessionData', index, 'sessionName']}
              rules={[
                { required: true, message: 'Please input the session name!' },
              ]}
              data-cy={`org-settings-fiscal-year-session-name-${index}`}
              id={`org-settings-fiscal-year-session-name-${index}`}
              className="mb-0"
            >
              <Input
                size="middle"
                className="w-full font-normal text-sm h-8"
                placeholder="Enter session name"
                data-cy={`org-settings-fiscal-year-session-name-input-${index}`}
                id={`org-settings-fiscal-year-session-name-input-${index}`}
              />
            </Form.Item>
          </Col>
          <Col
            span={isMobile ? undefined : 12}
            flex={isMobile ? 'none' : undefined}
          >
            <Form.Item
              name={['sessionData', index, 'sessionDateRange']}
              getValueFromEvent={(dates) => {
                if (dates && dates.length === 2) {
                  handleSessionChange(index, 'sessionStartDate', dates[0]);
                  handleSessionChange(index, 'sessionEndDate', dates[1]);
                  return dates;
                }
                handleSessionChange(index, 'sessionStartDate', null);
                handleSessionChange(index, 'sessionEndDate', null);
                return null;
              }}
              normalize={(value) => {
                // When form values are set programmatically, convert from individual dates to range
                if (!value && sessionData[index]) {
                  const session = sessionData[index];
                  if (session.sessionStartDate && session.sessionEndDate) {
                    return [session.sessionStartDate, session.sessionEndDate];
                  }
                }
                return value;
              }}
              rules={[
                {
                  required: true,
                  message: 'Please select the session date range!',
                },
                {
                  validator: async (unused, value) => {
                    if (!value || !Array.isArray(value) || value.length !== 2) {
                      return Promise.reject(
                        new Error('Please select both start and end dates!'),
                      );
                    }
                    const [startDate, endDate] = value;
                    // Validate start date
                    const startDateError = await validateSessionStartDate(
                      { field: `sessionData.${index}.sessionStartDate` },
                      startDate,
                    ).catch((err) => err);
                    if (startDateError) {
                      return Promise.reject(startDateError);
                    }
                    // Validate end date
                    const endDateError = await validateSessionEndDate(
                      { field: `sessionData.${index}.sessionEndDate` },
                      endDate,
                    ).catch((err) => err);
                    if (endDateError) {
                      return Promise.reject(endDateError);
                    }
                    return Promise.resolve();
                  },
                },
              ]}
              data-cy={`org-settings-fiscal-year-session-date-range-${index}`}
              id={`org-settings-fiscal-year-session-date-range-${index}`}
              className="mb-0"
            >
              <RangePicker
                size="middle"
                format="YYYY-MM-DD"
                className={
                  isMobile
                    ? 'h-10 w-11 min-w-11 px-0 justify-center [&_.ant-picker-input]:hidden [&_.ant-picker-range-separator]:hidden [&_.ant-picker-active-bar]:hidden [&_.ant-picker-suffix]:m-0'
                    : 'w-full h-8 [&_.ant-picker-input]:h-8'
                }
                data-cy={`org-settings-fiscal-year-session-date-range-input-${index}`}
                id={`org-settings-fiscal-year-session-date-range-input-${index}`}
              />
            </Form.Item>
          </Col>
        </Row>
      </div>
    ),
    [validateSessionStartDate, validateSessionEndDate],
  );

  return (
    <div
      className="flex-1 bg-white p-0 items-center w-full h-full"
      data-cy="org-settings-fiscal-year-session-drawer-container"
      id="org-settings-fiscal-year-session-drawer-container"
    >
      <div
        className="px-0 -mt-2"
        data-cy="org-settings-fiscal-year-session-drawer-description-container"
      >
        <p
          className="text-sm text-[rgba(0,0,0,0.45)] mb-4"
          data-cy="org-settings-fiscal-year-session-drawer-description"
        >
          {calendarType === 'Semester' &&
            'For Biannually Selections Fiscal Year months must be separated between 6 months for each session. You can change the fiscal year any time you wish with in the system.'}
          {calendarType === 'Quarter' &&
            'For Quarterly Selections Fiscal Year months must be separated between 3 months for each session. You can change the fiscal year any time you wish with in the system.'}
          {calendarType === 'Year' &&
            'For Yearly Selections Fiscal Year months will be divided throughout 12 months. You can change the fiscal year any time you wish with in the system.'}
        </p>
      </div>

      <Form
        form={form}
        layout="vertical"
        requiredMark={(label, { required }) => (
          <>
            <span data-cy="org-settings-fiscal-year-session-drawer-form-label">
              {label}
            </span>
            {required && (
              <span
                className="text-red-500 ml-1"
                data-cy="org-settings-fiscal-year-session-drawer-form-required-astrix"
              >
                *
              </span>
            )}
          </>
        )}
        onValuesChange={(nonused, allValues) => {
          setSessionData(allValues.sessionData);
          setSessionFormValues({
            ...allValues,
            fiscalYearStart,
            fiscalYearEnd,
            lastGeneratedFiscalYearStart: fiscalYearStart,
            lastGeneratedFiscalYearEnd: fiscalYearEnd,
          });
        }}
        onFieldsChange={updateErrorState}
        data-cy="org-settings-fiscal-year-session-drawer-form"
        id="org-settings-fiscal-year-session-drawer-form"
        className="px-0"
      >
        <div
          className="px-2 py-1 border border-gray-200 rounded-lg"
          data-cy="org-settings-fiscal-year-session-drawer-sessions-container"
        >
          <h3
            className="font-bold text-base mb-4"
            data-cy="org-settings-fiscal-year-session-drawer-sessions-title"
          >
            Sessions
          </h3>
          {sessionData.map((session, index) =>
            renderSessionForm(session, index),
          )}
        </div>

        <Form.Item
          className="mb-0 mt-4"
          data-cy="org-settings-fiscal-year-session-previous-btn-form-item"
          id="org-settings-fiscal-year-session-previous-btn-form-item"
        >
          <div
            className={`flex justify-end w-full pt-2 pb-0  gap-3 shadow-none`}
            data-cy="org-settings-fiscal-year-session-previous-btn-container"
            id="org-settings-fiscal-year-session-previous-btn-container"
          >
            <Button
              type="default"
              onClick={handlePrevious}
              className="flex justify-center text-sm font-normal h-8 !min-h-[32px] px-6 border-gray-300 bg-transparent hover:bg-gray-50"
              data-cy="org-settings-fiscal-year-session-previous-btn"
              id="org-settings-fiscal-year-session-previous-btn"
            >
              Reset
            </Button>
            <Popover
              content={hasErrors && firstErrorMsg ? firstErrorMsg : ''}
              trigger={hasErrors ? 'hover' : undefined}
              placement="top"
              data-cy="org-settings-fiscal-year-session-next-btn-popover"
              id="org-settings-fiscal-year-session-next-btn-popover"
            >
              <span
                data-cy="org-fiscalyear-customdrawer-steps-sessiondrawer-span-3"
                id="org-fiscalyear-customdrawer-steps-sessiondrawer-span-3"
              >
                <Button
                  type="primary"
                  onClick={handleNext}
                  className="flex justify-center text-sm font-normal h-8 !min-h-[32px] px-6 min-w-[100px]"
                  disabled={hasErrors}
                  data-cy="org-settings-fiscal-year-session-next-btn"
                  id="org-settings-fiscal-year-session-next-btn"
                >
                  {isCreateLoading || isUpdateLoading ? (
                    <Spin data-cy="org-settings-fiscal-year-session-next-btn-spinner" />
                  ) : (
                    <span
                      data-cy="org-settings-fiscal-year-session-next-btn-text"
                      id="org-settings-fiscal-year-session-next-btn-text"
                    >
                      Next
                    </span>
                  )}
                </Button>
              </span>
            </Popover>
          </div>
        </Form.Item>
      </Form>
    </div>
  );
};

export default SessionDrawer;

'use client';
import React, {
  useState,
  useMemo,
  useCallback,
  useRef,
  useEffect,
} from 'react';
import { message } from 'antd';
import ReactFlow, { Node, Edge } from 'reactflow';
import 'reactflow/dist/style.css';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
  DragStartEvent,
  DragOverlay,
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { useMergingDepartment } from '@/store/server/features/organizationStructure/mergeDepartments/mutations';
import { useMergeStore } from '@/store/uistate/features/organizationStructure/orgState/mergeDepartmentsStore';
import { useGetDepartments } from '@/store/server/features/employees/employeeManagment/department/queries';
import { useGetOrgCharts } from '@/store/server/features/organizationStructure/organizationalChart/query';
import TeamCard, { Department } from './cards/TeamCard';
import AvailableTeamsPanel from './panels/AvailableTeamsPanel';
import SourceDestinationView from './panels/SourceDestinationView';
import MergeFormModal from './modals/MergeFormModal';
import MergeConfirmationModal from './modals/MergeConfirmationModal';

const MergeDragDrop: React.FC = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [sourceTeam, setSourceTeam] = useState<Department | null>(null);
  const [destinationTeam, setDestinationTeam] = useState<Department | null>(
    null,
  );
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isConfirmationModalOpen, setIsConfirmationModalOpen] = useState(false);
  const [formData, setFormData] = useState<{
    teamLead: string;
    departmentName: string;
  } | null>(null);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [isSourceOver, setIsSourceOver] = useState(false);
  const [isDestinationOver, setIsDestinationOver] = useState(false);

  // Refs for React Flow positioning
  const sourceBoxRef = useRef<HTMLDivElement>(null);
  const destinationBoxRef = useRef<HTMLDivElement>(null);
  const mergeButtonRef = useRef<HTMLDivElement>(null);
  const mergeButtonMobileRef = useRef<HTMLDivElement>(null);
  const [flowNodes, setFlowNodes] = useState<Node[]>([]);
  const [flowEdges, setFlowEdges] = useState<Edge[]>([]);

  const { data: departments, refetch: refetchDepartments } =
    useGetDepartments();
  const { data: orgStructureData } = useGetOrgCharts();
  const { mutate: mergeDepartment, isLoading } = useMergingDepartment();

  const { setMergeData, mergeData } = useMergeStore();

  // Configure sensors for drag and drop
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  // Filter departments based on search
  const filteredDepartments = useMemo(() => {
    if (!departments) return [];
    const query = searchQuery.toLowerCase().trim();
    if (!query) return departments;

    return departments.filter((dept: any) =>
      dept.name?.toLowerCase().includes(query),
    );
  }, [departments, searchQuery]);

  // Department cache for finding departments with children
  const departmentCache: Record<string, any> = {};

  const findDepartmentWithChildren = useCallback(
    (tree: any, id: string): any => {
      if (departmentCache[id]) return departmentCache[id];

      if (tree.id === id) {
        const departmentData = {
          id: tree.id,
          name: tree.name,
          description: tree.description,
          branchId: tree.branchId,
          children: tree.department || [],
        };
        departmentCache[id] = departmentData;
        return departmentData;
      }
      if (tree.department?.length) {
        for (const child of tree.department) {
          const result = findDepartmentWithChildren(child, id);
          if (result) {
            departmentCache[id] = result;
            return result;
          }
        }
      }
      return null;
    },
    [],
  );

  // Compute depth (level) of a department in the org tree; root = 1
  const getDepartmentLevel = useCallback(
    (tree: any, id: string, depth = 1): number => {
      if (!tree) return 1;
      if (tree.id === id) return depth;
      if (tree.department?.length) {
        for (const child of tree.department) {
          const found = getDepartmentLevel(child, id, depth + 1);
          if (found > 0) return found;
        }
      }
      return 0;
    },
    [],
  );

  // Exclude already selected teams from the list
  const availableDepartments = useMemo(() => {
    const selectedIds = [sourceTeam?.id, destinationTeam?.id].filter(
      (id): id is string => Boolean(id),
    );
    const excludedDescendantIds = new Set<string>();

    const collectDescendantIds = (nodes: any[] = []) => {
      nodes.forEach((node) => {
        if (!node?.id) return;
        excludedDescendantIds.add(node.id);
        if (Array.isArray(node.department) && node.department.length > 0) {
          collectDescendantIds(node.department);
        }
      });
    };

    // When a team is selected in either box, hide all of its descendants.
    selectedIds.forEach((id) => {
      const selectedDept = findDepartmentWithChildren(orgStructureData, id);
      if (selectedDept?.children?.length) {
        collectDescendantIds(selectedDept.children);
      }
    });

    return filteredDepartments
      .filter(
        (dept: any) =>
          !selectedIds.includes(dept.id) && !excludedDescendantIds.has(dept.id),
      )
      .map((dept: any) => ({
        id: dept.id,
        name: dept.name,
        branchId: dept.branchId,
        description: dept.description,
      }));
  }, [
    filteredDepartments,
    sourceTeam,
    destinationTeam,
    orgStructureData,
    findDepartmentWithChildren,
  ]);

  // Build merge data
  useEffect(() => {
    if (sourceTeam && destinationTeam && orgStructureData) {
      const destinationDept = findDepartmentWithChildren(
        orgStructureData,
        destinationTeam.id,
      );
      const sourceDept = findDepartmentWithChildren(
        orgStructureData,
        sourceTeam.id,
      );

      if (destinationDept && sourceDept) {
        const level =
          getDepartmentLevel(orgStructureData, destinationTeam.id) || 3;

        // API expects department: []; teamLeader added at submit time
        const mergePayload = {
          id: destinationTeam.id,
          name: destinationTeam.name,
          description: destinationTeam.description || '',
          branchId: destinationTeam.branchId,
          departmentToDelete: [sourceTeam.id],
          department: [],
          level,
        };

        setMergeData(mergePayload);
      }
    }
  }, [
    sourceTeam,
    destinationTeam,
    orgStructureData,
    findDepartmentWithChildren,
    getDepartmentLevel,
    setMergeData,
  ]);

  const handleDragStart = (event: DragStartEvent) => {
    setActiveId(event.active.id as string);
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveId(null);
    setIsSourceOver(false);
    setIsDestinationOver(false);

    if (!over) {
      return;
    }

    const activeId = active.id as string;
    const overId = over.id as string;

    // Find the department being dragged
    let deptData: Department | null = null;

    // Try to find in available departments
    const availableDept = availableDepartments.find(
      (d: Department) => d.id === activeId,
    );
    if (availableDept) {
      deptData = availableDept;
    } else {
      // Try to find in source team
      if (sourceTeam && sourceTeam.id === activeId) {
        deptData = sourceTeam;
      } else if (destinationTeam && destinationTeam.id === activeId) {
        deptData = destinationTeam;
      }
    }

    if (!deptData) return;

    // Handle drop on source-teams droppable area
    if (overId === 'source-teams') {
      setSourceTeam(deptData);
      // Remove from destination if it was there
      if (destinationTeam && destinationTeam.id === activeId) {
        setDestinationTeam(null);
      }
    }
    // Handle drop on destination-team droppable area
    else if (overId === 'destination-team') {
      setDestinationTeam(deptData);
      // Remove from source team if it was there
      if (sourceTeam && sourceTeam.id === activeId) {
        setSourceTeam(null);
      }
    }
    // Handle drop back to available-teams (removes from source/destination)
    else if (overId === 'available-teams') {
      // Remove from source team if it was there
      if (sourceTeam && sourceTeam.id === activeId) {
        setSourceTeam(null);
      }
      // Remove from destination if it was there
      if (destinationTeam && destinationTeam.id === activeId) {
        setDestinationTeam(null);
      }
    }
  };

  // Remove handlers for mobile X buttons
  const handleRemoveSourceTeam = useCallback(() => {
    setSourceTeam(null);
  }, []);

  const handleRemoveDestinationTeam = useCallback(() => {
    setDestinationTeam(null);
  }, []);

  const handleMerge = () => {
    if (!destinationTeam) {
      message.error('Please select a destination team');
      return;
    }
    if (!sourceTeam) {
      message.error('Please select a source team to merge');
      return;
    }
    setIsFormModalOpen(true);
  };

  const handleFormNext = (data: {
    teamLead: string;
    departmentName: string;
  }) => {
    setFormData(data);
    setIsFormModalOpen(false);
    setIsConfirmationModalOpen(true);
  };

  const handleFormCancel = () => {
    setIsFormModalOpen(false);
    setFormData(null);
  };

  const handleConfirmMerge = () => {
    if (!mergeData) {
      message.error('Merge data is not ready');
      setIsConfirmationModalOpen(false);
      return;
    }

    // Update merge data with form values - API expects teamLeader and name from form
    const updatedMergeData = {
      ...mergeData,
      name: formData?.departmentName || mergeData.name,
      teamLeader: formData?.teamLead ?? '',
      level: mergeData.level ?? 3,
    };

    mergeDepartment(updatedMergeData, {
      onSuccess: () => {
        message.success('Departments merged successfully');
        setIsConfirmationModalOpen(false);
        setSourceTeam(null);
        setDestinationTeam(null);
        setMergeData(null);
        setFormData(null);
        refetchDepartments();
      },
      onError: () => {
        setIsConfirmationModalOpen(false);
      },
    });
  };

  const handleConfirmationCancel = () => {
    setIsConfirmationModalOpen(false);
    setFormData(null);
  };

  const getTeamColor = (index: number) => {
    const colors = [
      'bg-[#EEF0F5] border-gray-200 shadow-md',
      'bg-[#F5F1EE] border-gray-200 shadow-md',
      'bg-[#F2EDF1] border-gray-200 shadow-md',
      'bg-[#EEF0F0] border-gray-200 shadow-md',
      'bg-[#F3EDF1] border-gray-200 shadow-md',
    ];
    return colors[index % colors.length];
  };

  // Get active dragged item for overlay
  const activeItem = useMemo(() => {
    if (!activeId) return null;
    return (
      availableDepartments.find((d: Department) => d.id === activeId) ||
      (sourceTeam && sourceTeam.id === activeId ? sourceTeam : null) ||
      (destinationTeam && destinationTeam.id === activeId
        ? destinationTeam
        : null)
    );
  }, [activeId, availableDepartments, sourceTeam, destinationTeam]);

  // Dynamic styling based on items in buckets
  const hasItemsInBuckets = !!(sourceTeam && destinationTeam); // For button border - only when both are present
  const borderColorClass = hasItemsInBuckets
    ? 'border-primary'
    : 'border-gray-400';
  const textColorClass = hasItemsInBuckets ? 'text-primary' : 'text-gray-900';

  // Get primary color value dynamically from Tailwind theme
  const primaryColorValue = useMemo(() => {
    if (typeof window === 'undefined') return '#3636F0'; // Fallback to Tailwind config value
    const tempEl = document.createElement('div');
    tempEl.className = 'bg-primary';
    tempEl.style.position = 'absolute';
    tempEl.style.visibility = 'hidden';
    tempEl.style.pointerEvents = 'none';
    document.body.appendChild(tempEl);
    const computedColor = window.getComputedStyle(tempEl).backgroundColor;
    document.body.removeChild(tempEl);
    return computedColor || '#3636F0';
  }, []);

  // Function to calculate and update node positions
  const updateNodePositions = useCallback(() => {
    // Only show lines on desktop (when desktop button is visible)
    const isDesktop =
      mergeButtonRef.current &&
      window.getComputedStyle(mergeButtonRef.current).display !== 'none';
    const shouldShowLines =
      isDesktop &&
      mergeButtonRef.current &&
      sourceBoxRef.current &&
      destinationBoxRef.current;
    const nodes: Node[] = [];
    const edges: Edge[] = [];

    if (shouldShowLines) {
      const buttonRect = mergeButtonRef.current.getBoundingClientRect();
      const containerRect = mergeButtonRef.current
        .closest('[data-cy="org-settings-merge-container"]')
        ?.getBoundingClientRect();

      if (containerRect && buttonRect) {
        const buttonX =
          buttonRect.left - containerRect.left + buttonRect.width / 2;
        const buttonY = buttonRect.top - containerRect.top;

        // Add merge button node (always add)
        nodes.push({
          id: 'merge-button-node',
          position: { x: buttonX - 10, y: buttonY + 2 },
          data: { label: '' },
          style: { width: 20, height: 20, opacity: 0 },
          draggable: false,
          selectable: false,
        });

        // Always add source box node and edge (even when empty)
        const sourceRect = sourceBoxRef.current.getBoundingClientRect();
        const sourceX =
          sourceRect.left - containerRect.left + sourceRect.width / 2;
        const sourceY = sourceRect.bottom - containerRect.top - 25;

        nodes.push({
          id: 'source-node',
          position: { x: sourceX - 10, y: sourceY },
          data: { label: '' },
          style: { width: 20, height: 20, opacity: 0 },
          draggable: false,
          selectable: false,
        });

        edges.push({
          id: 'source-to-merge',
          source: 'source-node',
          target: 'merge-button-node',
          type: 'straight',
          style: {
            stroke: sourceTeam ? primaryColorValue : '#e5e7eb',
            strokeWidth: 2,
            strokeDasharray: sourceTeam ? 0 : '5 3', // Solid when has item, dashed when empty
          },
          animated: sourceTeam ? true : false,
        });

        // Always add destination box node and edge (even when empty)
        const destinationRect =
          destinationBoxRef.current.getBoundingClientRect();
        const destinationX =
          destinationRect.left - containerRect.left + destinationRect.width / 2;
        const destinationY = destinationRect.bottom - containerRect.top - 25;

        nodes.push({
          id: 'destination-node',
          position: { x: destinationX - 10, y: destinationY },
          data: { label: '' },
          style: { width: 20, height: 20, opacity: 0 },
          draggable: false,
          selectable: false,
        });

        edges.push({
          id: 'destination-to-merge',
          source: 'destination-node',
          target: 'merge-button-node',
          type: 'straight',
          style: {
            stroke: destinationTeam ? primaryColorValue : '#e5e7eb',
            strokeWidth: 2,
            strokeDasharray: destinationTeam ? 0 : '5 3', // Solid when has item, dashed when empty
          },
          animated: destinationTeam ? true : false,
        });

        // Always update if we have nodes
        if (nodes.length > 0) {
          setFlowNodes(nodes);
          setFlowEdges(edges);
        }
      }
    } else {
      // Clear if refs are not available
      setFlowNodes([]);
      setFlowEdges([]);
    }
  }, [sourceTeam, destinationTeam, primaryColorValue]);

  // Update React Flow nodes and edges based on positions
  useEffect(() => {
    // Use requestAnimationFrame and setTimeout to ensure DOM has updated
    let timeoutId: NodeJS.Timeout;
    const rafId = requestAnimationFrame(() => {
      timeoutId = setTimeout(() => {
        updateNodePositions();
      }, 50); // Small delay to ensure DOM is fully updated
    });

    return () => {
      cancelAnimationFrame(rafId);
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [updateNodePositions]);

  // Update positions on window resize and layout changes
  useEffect(() => {
    const handleResize = () => {
      updateNodePositions();
    };

    // Use ResizeObserver to watch for layout changes
    let resizeObserver: ResizeObserver | null = null;
    const container = mergeButtonRef.current?.closest(
      '[data-cy="org-settings-merge-container"]',
    );

    if (container) {
      resizeObserver = new ResizeObserver(() => {
        updateNodePositions();
      });
      resizeObserver.observe(container);
    }

    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
      if (resizeObserver) {
        resizeObserver.disconnect();
      }
    };
  }, [updateNodePositions]);

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onDragOver={({ over }) => {
        setIsSourceOver(over?.id === 'source-teams');
        setIsDestinationOver(over?.id === 'destination-team');
      }}
    >
      <div
        className="bg-white relative"
        data-cy="org-settings-merge-container"
        id="org-settings-merge-container"
      >
        {/* React Flow overlay for connection lines - Desktop only */}
        {flowNodes.length > 0 && (
          <div
            className="hidden lg:block absolute inset-0 pointer-events-none z-30"
            style={{ overflow: 'visible' }}
            data-cy="merge-react-flow-overlay-container"
          >
            <ReactFlow
              nodes={flowNodes}
              edges={flowEdges}
              fitView={false}
              panOnDrag={false}
              zoomOnScroll={false}
              zoomOnPinch={false}
              nodesDraggable={false}
              nodesConnectable={false}
              elementsSelectable={false}
              preventScrolling={false}
              proOptions={{ hideAttribution: true }}
              style={{
                background: 'transparent',
                width: '100%',
                height: '100%',
              }}
              data-cy="merge-react-flow"
            ></ReactFlow>
          </div>
        )}
        <div
          className="flex flex-col lg:flex-row items-start"
          data-cy="merge-main-content-container"
        >
          {/* Left Panel - Available Teams */}
          <AvailableTeamsPanel
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            availableDepartments={availableDepartments}
            getTeamColor={getTeamColor}
          />
          <div
            className="hidden lg:block w-[6%]"
            data-cy="merge-spacer-div"
          ></div>

          {/* Middle Section - Two boxes with button below/between */}
          <SourceDestinationView
            sourceTeam={sourceTeam}
            destinationTeam={destinationTeam}
            availableDepartments={availableDepartments}
            filteredDepartments={filteredDepartments}
            isSourceOver={isSourceOver}
            isDestinationOver={isDestinationOver}
            onRemoveSourceTeam={handleRemoveSourceTeam}
            onRemoveDestinationTeam={handleRemoveDestinationTeam}
            setSourceTeam={setSourceTeam}
            setDestinationTeam={setDestinationTeam}
            handleMerge={handleMerge}
            isLoading={isLoading}
            hasItemsInBuckets={hasItemsInBuckets}
            borderColorClass={borderColorClass}
            textColorClass={textColorClass}
            setIsSourceOver={setIsSourceOver}
            setIsDestinationOver={setIsDestinationOver}
            sourceBoxRef={sourceBoxRef}
            destinationBoxRef={destinationBoxRef}
            mergeButtonRef={mergeButtonRef}
            mergeButtonMobileRef={mergeButtonMobileRef}
          />
        </div>
      </div>

      <DragOverlay data-cy="merge-drag-overlay">
        {activeItem ? (
          <div className="rotate-2" data-cy="merge-drag-overlay-item-container">
            <TeamCard department={activeItem} isOverlay isDragging />
          </div>
        ) : null}
      </DragOverlay>

      <MergeFormModal
        open={isFormModalOpen}
        onNext={handleFormNext}
        onCancel={handleFormCancel}
        sourceTeam={sourceTeam}
        destinationTeam={destinationTeam}
      />
      <MergeConfirmationModal
        open={isConfirmationModalOpen}
        onConfirm={handleConfirmMerge}
        onCancel={handleConfirmationCancel}
        sourceTeams={sourceTeam ? [sourceTeam] : []}
        destinationTeam={destinationTeam}
        loading={isLoading}
      />
    </DndContext>
  );
};

