import React, { useEffect, useState, useRef } from 'react';
import {
  Form,
  Select,
  Button,
  Row,
  Col,
  ConfigProvider,
  Popover,
  Modal,
} from 'antd';
import FilterAltOutlinedIcon from '@mui/icons-material/FilterAltOutlined';
import { X } from 'lucide-react';
import dayjs from 'dayjs';

import { useGetAllFiscalYears } from '@/store/server/features/organizationStructure/fiscalYear/queries';
import {
  useGetActivePayroll,
  useGetPayPeriod,
} from '@/store/server/features/payroll/payroll/queries';
import { useGetDepartments } from '@/store/server/features/employees/employeeManagment/department/queries';
import { useGetLevel1Departments } from '@/store/server/features/employees/employeeManagment/department/queries';
import { useTnaReviewStore } from '@/store/uistate/features/tna/review';
import useEmployeeStore from '@/store/uistate/features/payroll/employeeInfoStore';
import { usePayrollStore } from '@/store/uistate/features/payroll/payroll';
import { useIsMobile } from '@/hooks/useIsMobile';

const { Option } = Select;

interface FilterValues {
  [key: string]: string | undefined;
  yearId?: string;
  sessionId?: string;
  divisionId?: string;
  departmentId?: string;
  payPeriodId?: string;
  monthId?: string;
}

interface FilterPopoverProps {
  onSearch: (filters: { [key: string]: string | undefined | null }) => void;
  defaultValues?: FilterValues;
}

const CustomLabel = ({ title }: { title: string }) => (
  <span
    className="text-[13px] font-normal text-gray-800"
    data-cy="payroll-filter-popover-custom-label"
  >
    {title}
  </span>
);

const FilterPopover: React.FC<FilterPopoverProps> = ({
  onSearch,
  defaultValues,
}) => {
  const [open, setOpen] = useState(false);
  const [form] = Form.useForm<FilterValues>();
  const { isMobile, isTablet } = useIsMobile();

  const { data: getAllFiscalYears } = useGetAllFiscalYears();
  const { data: payPeriodData } = useGetPayPeriod();
  const { data: departmentData } = useGetDepartments();
  const { data: level1Departments } = useGetLevel1Departments();

  const { searchQuery } = useEmployeeStore();
  const { pageSize, currentPage } = usePayrollStore();
  const { data: payroll } = useGetActivePayroll(
    searchQuery,
    pageSize,
    currentPage,
  );

  const [fiscalYears, setFiscalYears] = useState<any[]>([]);
  const [sessions, setSessions] = useState<any[]>([]);
  const [months, setMonths] = useState<any[]>([]);

  const { setMonthId, setYearId, setSessionId } = useTnaReviewStore();
  const initialSearchTriggered = useRef(false);

  useEffect(() => {
    if (getAllFiscalYears) {
      setFiscalYears(getAllFiscalYears.items || []);

      if (
        !form.getFieldValue('yearId') ||
        !form.getFieldValue('sessionId') ||
        !form.getFieldValue('monthId')
      ) {
        const selectedYear =
          getAllFiscalYears.items.find(
            (year: any) => year.id === (defaultValues?.yearId || ''),
          ) || getAllFiscalYears.items.find((year: any) => year.active);

        if (selectedYear) {
          const selectedSession =
            selectedYear.sessions?.find(
              (s: any) => s.id === (defaultValues?.sessionId || ''),
            ) || selectedYear.sessions?.find((s: any) => s.active);

          const selectedMonth =
            selectedSession?.months?.find(
              (m: any) => m.id === (defaultValues?.monthId || ''),
            ) || selectedSession?.months?.find((m: any) => m.active);

          setSessions(selectedYear.sessions || []);
          setMonths(selectedSession?.months || []);

          form.setFieldsValue({
            yearId: selectedYear.id || '',
            sessionId: selectedSession?.id || '',
            monthId: selectedMonth?.id || '',
          });

          if (!initialSearchTriggered.current) {
            const formValues = form.getFieldsValue();
            const sanitizedValues = Object.fromEntries(
              Object.entries(formValues).filter(
                ([, value]) => typeof value === 'string' && value.trim() !== '',
              ),
            ) as { [key: string]: string };
            onSearch(sanitizedValues);
            initialSearchTriggered.current = true;
          }
        }
      }
    }
  }, [getAllFiscalYears]);

  useEffect(() => {
    if (defaultValues?.payPeriodId && !form.getFieldValue('payPeriodId')) {
      form.setFieldsValue({ payPeriodId: defaultValues.payPeriodId });
    }
  }, [defaultValues?.payPeriodId]);

  useEffect(() => {
    if (defaultValues?.payPeriodId) {
      return;
    }
    if (
      payroll?.items &&
      payroll.items.length > 0 &&
      !form.getFieldValue('payPeriodId')
    ) {
      const defaultPayPeriodId = payroll.items[0]?.payPeriodId;
      if (defaultPayPeriodId) {
        form.setFieldsValue({ payPeriodId: defaultPayPeriodId });
        const formValues = form.getFieldsValue();
        const sanitizedValues = Object.fromEntries(
          Object.entries(formValues).filter(
            ([, value]) => typeof value === 'string' && value.trim() !== '',
          ),
        ) as { [key: string]: string };
        onSearch(sanitizedValues);
      }
    } else if (
      payPeriodData &&
      payPeriodData.length > 0 &&
      !form.getFieldValue('payPeriodId')
    ) {
      const activePeriod =
        payPeriodData.find((p: any) => p.status === 'OPEN') || payPeriodData[0];
      if (activePeriod) {
        form.setFieldsValue({ payPeriodId: activePeriod.id });
        const formValues = form.getFieldsValue();
        const sanitizedValues = Object.fromEntries(
          Object.entries(formValues).filter(
            ([, value]) => typeof value === 'string' && value.trim() !== '',
          ),
        ) as { [key: string]: string };
        onSearch(sanitizedValues);
      }
    }
  }, [payroll?.items, payPeriodData]);

  const handleYearChange = (value: string) => {
    const selectedYear = fiscalYears.find((year) => year.id === value);
    setSessions(selectedYear?.sessions || []);
    setMonths([]);
    form.setFieldsValue({ sessionId: undefined, monthId: undefined });
  };

  const handleSessionChange = (value: string) => {
    const selectedSession = sessions.find((s: any) => s.id === value);
    setMonths(selectedSession?.months || []);
    form.setFieldsValue({ monthId: undefined });
  };

  const onFinish = (values: FilterValues) => {
    setMonthId(values.monthId || '');
    setYearId(values.yearId || '');
    setSessionId(values.sessionId || '');

    const sanitizedValues = Object.fromEntries(
      Object.entries(values).filter(
        ([, value]) => typeof value === 'string' && value.trim() !== '',
      ),
    ) as { [key: string]: string };

    onSearch(sanitizedValues);
    setOpen(false);
  };

  const getDefaultActivePayPeriodId = (): string | undefined => {
    if (!payPeriodData?.length) return undefined;
    const openPeriod = payPeriodData.find((p: any) => p.status === 'OPEN');
    return (openPeriod || payPeriodData[0])?.id;
  };

  const onReset = () => {
    const fiscalItems = getAllFiscalYears?.items || [];
    const selectedYear =
      fiscalItems.find(
        (year: any) => year.id === (defaultValues?.yearId || ''),
      ) ||
      fiscalItems.find((year: any) => year.active) ||
      fiscalItems[0];

    if (!selectedYear) {
      form.resetFields();
      onSearch({
        divisionId: undefined,
        departmentId: undefined,
        payPeriodId: undefined,
        monthId: undefined,
      });
      return;
    }

    const selectedSession =
      selectedYear.sessions?.find(
        (s: any) => s.id === (defaultValues?.sessionId || ''),
      ) ||
      selectedYear.sessions?.find((s: any) => s.active) ||
      selectedYear.sessions?.[0];

    const selectedMonth =
      selectedSession?.months?.find(
        (m: any) => m.id === (defaultValues?.monthId || ''),
      ) ||
      selectedSession?.months?.find((m: any) => m.active) ||
      selectedSession?.months?.[0];

    setSessions(selectedYear.sessions || []);
    setMonths(selectedSession?.months || []);

    const defaultPayPeriodId = getDefaultActivePayPeriodId();

    const nextValues: FilterValues = {
      yearId: selectedYear.id || '',
      sessionId: selectedSession?.id || '',
      monthId: selectedMonth?.id || '',
      payPeriodId: defaultPayPeriodId,
      divisionId: undefined,
      departmentId: undefined,
    };

    form.setFieldsValue(nextValues);

    setMonthId(nextValues.monthId || '');
    setYearId(nextValues.yearId || '');
    setSessionId(nextValues.sessionId || '');

    onSearch({
      yearId: nextValues.yearId || undefined,
      sessionId: nextValues.sessionId || undefined,
      monthId: nextValues.monthId || undefined,
      payPeriodId: defaultPayPeriodId,
      divisionId: undefined,
      departmentId: undefined,
    });
  };

  const handleOpenChange = (newOpen: boolean) => {
    setOpen(newOpen);
  };

  const content = (
    <ConfigProvider
      theme={{
        token: {
          fontFamily: 'inherit',
          borderRadius: 6,
          controlHeightLG: 40,
        },
        components: {
          Form: {
            itemMarginBottom: 20,
          },
        },
      }}
      data-cy="payroll-filter-popover-content"
    >
      <div
        className="bg-white rounded-xl p-4 sm:p-6 w-full max-w-[500px] min-w-0 sm:min-w-[320px] md:min-w-[450px] relative max-h-[calc(100vh-160px)] overflow-auto"
        data-cy="payroll-filter-popover-content"
      >
        {/* Close Icon */}
        <button
          className="absolute top-2 right-2 text-gray-400 hover:text-gray-600 transition-colors bg-transparent border-none cursor-pointer"
          onClick={() => setOpen(false)}
          data-cy="payroll-filter-popover-close-btn"
        >
          <X size={20} strokeWidth={1.5} />
        </button>

        {/* Header Section */}
        <div className="mb-6" data-cy="payroll-filter-popover-header">
          <h2
            className="text-[16px] font-normal text-gray-900 m-0 leading-tight"
            data-cy="payroll-filter-popover-header-title"
          >
            Filter
          </h2>
          <p
            className="text-[13px] text-gray-400 m-0 mt-1"
            data-cy="payroll-filter-popover-header-subtitle"
          >
            Select All filters that apply
          </p>
        </div>

        {/* Filter Form */}
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          requiredMark={false}
          data-cy="payroll-filter-popover-form"
        >
          <Row gutter={[16, 16]} data-cy="payroll-filter-popover-form-row">
            <Col xs={12} sm={12} data-cy="payroll-filter-popover-form-col">
              <Form.Item
                name="yearId"
                label={<CustomLabel title="Year" />}
                rules={[{ required: true, message: 'Required' }]}
                data-cy="payroll-filter-popover-year"
              >
                <Select
                  size="large"
                  placeholder="Select Year"
                  onChange={handleYearChange}
                  allowClear
                  data-cy="payroll-filter-popover-year-select"
                >
                  {fiscalYears.map((year) => (
                    <Option
                      key={year.id}
                      value={year.id}
                      data-cy="payroll-filter-popover-year-option"
                    >
                      {year.name}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>

            <Col xs={12} sm={12} data-cy="payroll-filter-popover-session-col">
              <Form.Item
                name="sessionId"
                label={<CustomLabel title="Session" />}
                rules={[{ required: true, message: 'Required' }]}
                data-cy="payroll-filter-popover-session"
              >
                <Select
                  size="large"
                  placeholder="Select Session"
                  onChange={handleSessionChange}
                  allowClear
                  disabled={!form.getFieldValue('yearId')}
                  data-cy="payroll-filter-popover-session-select"
                >
                  {sessions.map((session) => (
                    <Option
                      key={session.id}
                      value={session.id}
                      data-cy="payroll-filter-popover-session-option"
                    >
                      {session.name}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>

          <Row gutter={[16, 16]}>
            <Col xs={12} sm={12} data-cy="payroll-filter-popover-division-col">
              <Form.Item
                name="divisionId"
                label={<CustomLabel title="Division" />}
                data-cy="payroll-filter-popover-division"
              >
                <Select
                  size="large"
                  placeholder="Select Division"
                  allowClear
                  data-cy="payroll-filter-popover-division-select"
                >
                  {level1Departments?.map((division: any) => (
                    <Option
                      key={division.id}
                      value={division.id}
                      data-cy="payroll-filter-popover-division-option"
                    >
                      {division?.name}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>

            <Col
              xs={12}
              sm={12}
              data-cy="payroll-filter-popover-department-col"
            >
              <Form.Item
                name="departmentId"
                label={<CustomLabel title="Department" />}
                data-cy="payroll-filter-popover-department"
              >
                <Select
                  size="large"
                  placeholder="Select Department"
                  allowClear
                  data-cy="payroll-filter-popover-department-select"
                >
                  {departmentData?.map((department: any) => (
                    <Option
                      key={department.id}
                      value={department.id}
                      data-cy="payroll-filter-popover-department-option"
                    >
                      {department?.name}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>

          <Row gutter={[16, 16]}>
            <Col
              xs={12}
              sm={12}
              data-cy="payroll-filter-popover-pay-period-col"
            >
              <Form.Item
                name="payPeriodId"
                label={<CustomLabel title="Pay Period" />}
                data-cy="payroll-filter-popover-pay-period"
              >
                <Select
                  size="large"
                  placeholder="Select Pay Period"
                  allowClear
                  data-cy="payroll-filter-popover-pay-period-select"
                >
                  {payPeriodData?.map((period: any) => (
                    <Option
                      key={period.id}
                      value={period.id}
                      data-cy="payroll-filter-popover-pay-period-option"
                    >
                      {dayjs(period.startDate).format('MMM DD, YYYY')} --{' '}
                      {dayjs(period.endDate).format('MMM DD, YYYY')}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>

            <Col xs={12} sm={12} data-cy="payroll-filter-popover-month-col">
              <Form.Item
                name="monthId"
                label={<CustomLabel title="Month" />}
                rules={[{ required: true, message: 'Required' }]}
                data-cy="payroll-filter-popover-month"
              >
                <Select
                  size="large"
                  placeholder="Select Month"
                  allowClear
                  disabled={!form.getFieldValue('sessionId')}
                  data-cy="payroll-filter-popover-month-select"
                >
                  {months.map((month) => (
                    <Option
                      key={month.id}
                      value={month.id}
                      data-cy="payroll-filter-popover-month-option"
                    >
                      {month.name}
                    </Option>
                  ))}
                </Select>
              </Form.Item>
            </Col>
          </Row>

          {/* Footer Buttons */}
          <div
            className="flex justify-end items-center gap-3 mt-4 pt-2 border-t border-gray-100"
            data-cy="payroll-filter-popover-footer"
          >
            <Button
              type="default"
              htmlType="button"
              size="large"
              onClick={onReset}
              className="!h-9 px-4 w-[120px] sm:w-auto sm:!h-10 sm:px-6 !font-normal !text-[#4D4D4D] border border-solid !border-[#D9D9D9]"
              data-cy="payroll-filter-popover-reset-btn"
            >
              Reset
            </Button>
            <Button
              size="large"
              type="primary"
              htmlType="submit"
              className="bg-[#254ec2] hover:bg-[#1e3e9a] border-none !h-9 px-4 w-[120px] sm:w-auto sm:!h-10 sm:px-6 !font-normal shadow-none"
              data-cy="payroll-filter-popover-save-btn"
            >
              Save Filter
            </Button>
          </div>
        </Form>
      </div>
    </ConfigProvider>
  );

  // Mobile/tablet: use a centered modal so the filter can't be clipped.
  if (isMobile || isTablet) {
    return (
      <>
        <Button
          id="payroll-open-filter-modal-click-button"
          data-cy="payroll-open-filter-modal-click-button"
          className="flex items-center gap-2 h-10 border-gray-200 text-gray-600 rounded-[6px] px-3 md:px-4 font-medium"
          size="large"
          icon={
            <FilterAltOutlinedIcon className="text-gray-600" fontSize="small" />
          }
          onClick={() => setOpen(true)}
        >
          <span
            className="hidden sm:inline"
            data-cy="payroll-filter-popover-button-text"
          >
            Filter
          </span>
        </Button>

        <Modal
          open={open}
          onCancel={() => setOpen(false)}
          footer={null}
          centered
          closable={false}
          width="calc(100vw - 32px)"
          rootClassName="[&_.ant-modal-content]:!rounded-xl [&_.ant-modal-content]:!overflow-hidden"
          styles={{
            body: { padding: 0 },
            content: { padding: 0, borderRadius: 12 },
          }}
          data-cy="payroll-filter-mobile-modal"
        >
          {content}
        </Modal>
      </>
    );
  }

  return (
    <Popover
      content={content}
      trigger="click"
      open={open}
      onOpenChange={handleOpenChange}
      placement="bottomRight"
      overlayClassName="pixel-perfect-popover"
      getPopupContainer={() => document.body}
      data-cy="payroll-filter-popover"
    >
      <Button
        id="payroll-open-filter-modal-click-button"
        data-cy="payroll-open-filter-modal-click-button"
        className="flex items-center gap-2 h-10 border-gray-200 text-gray-600 rounded-[6px] px-3 md:px-4 font-medium"
        size="large"
        icon={
          <FilterAltOutlinedIcon className="text-gray-600" fontSize="small" />
        }
      >
        <span
          className="hidden sm:inline"
          data-cy="payroll-filter-popover-button-text"
        >
          Filter
        </span>
      </Button>
    </Popover>
  );
};

export default FilterPopover;

import React, { useEffect, useState, useRef } from 'react';
import { Col, Row, Select } from 'antd';
import { useGetAllFiscalYears } from '@/store/server/features/organizationStructure/fiscalYear/queries';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import {
  useGetActivePayroll,
  useGetPayPeriod,
} from '@/store/server/features/payroll/payroll/queries';
import dayjs from 'dayjs';
import { useTnaReviewStore } from '@/store/uistate/features/tna/review';
import { useGetDepartments } from '@/store/server/features/employees/employeeManagment/department/queries';
import { useGetLevel1Departments } from '@/store/server/features/employees/employeeManagment/department/queries';
import useEmployeeStore from '@/store/uistate/features/payroll/employeeInfoStore';

const { Option } = Select;

interface FiltersProps {
  onSearch: (filters: { [key: string]: string }) => void;
  disable?: string[];
  oneRow?: boolean;
  defaultValues?: {
    employeeId?: string;
    yearId?: string;
    sessionId?: string;
    monthId?: string;
    departmentId?: string;
    divisionId?: string;
    payPeriodId?: string;
  };
}

const Filters: React.FC<FiltersProps> = ({
  onSearch,
  disable = [],
  // oneRow = false,
  defaultValues,
}) => {
  const { data: getAllFiscalYears } = useGetAllFiscalYears();
  const { data: employeeData } = useGetAllUsers();
  const { data: payPeriodData } = useGetPayPeriod();
  const { data: departmentData } = useGetDepartments();
  const { data: level1Departments } = useGetLevel1Departments();
  const { searchQuery, pageSize, currentPage } = useEmployeeStore();
  const { data: payroll } = useGetActivePayroll(
    searchQuery,
    pageSize,
    currentPage,
  );
  const [searchValue, setSearchValue] = useState<{ [key: string]: string }>({
    ...defaultValues,
  });

  const [fiscalYears, setFiscalYears] = useState<any[]>([]);
  const [sessions, setSessions] = useState<any[]>([]);
  const [months, setMonths] = useState<any[]>([]);
  const { setMonthId, setYearId, setSessionId } = useTnaReviewStore();
  const initialSearchTriggered = useRef(false);

  useEffect(() => {
    setMonthId(searchValue.monthId);
    setYearId(searchValue.yearId);
    setSessionId(searchValue.sessionId);
  }, [searchValue]);
  useEffect(() => {
    if (getAllFiscalYears) {
      setFiscalYears(getAllFiscalYears.items || []);

      // Only set initial values if not already set
      if (
        !searchValue.yearId ||
        !searchValue.sessionId ||
        !searchValue.monthId
      ) {
        const selectedYear =
          getAllFiscalYears.items.find(
            (year: any) => year.id === (defaultValues?.yearId || ''),
          ) || getAllFiscalYears.items.find((year: any) => year.active);

        if (selectedYear) {
          const selectedSession =
            selectedYear.sessions?.find(
              (s: any) => s.id === (defaultValues?.sessionId || ''),
            ) || selectedYear.sessions?.find((s: any) => s.active);

          const selectedMonth =
            selectedSession?.months?.find(
              (m: any) => m.id === (defaultValues?.monthId || ''),
            ) || selectedSession?.months?.find((m: any) => m.active);

          setSessions(selectedYear.sessions || []);
          setMonths(selectedSession?.months || []);

          const newSearchValue = {
            ...searchValue,
            yearId: selectedYear.id || '',
            sessionId: selectedSession?.id || '',
            monthId: selectedMonth?.id || '',
          };

          setSearchValue(newSearchValue);

          // Only trigger onSearch once on mount
          if (!initialSearchTriggered.current) {
            onSearch(newSearchValue);
            initialSearchTriggered.current = true;
          }
        }
      } else {
        // If yearId/sessionId/monthId are already set, update sessions/months for the selected year/session
        const selectedYear = getAllFiscalYears.items.find(
          (year: any) => year.id === searchValue.yearId,
        );
        setSessions(selectedYear?.sessions || []);
        const selectedSession = selectedYear?.sessions?.find(
          (s: any) => s.id === searchValue.sessionId,
        );
        setMonths(selectedSession?.months || []);
      }
    }
  }, [getAllFiscalYears]);

  useEffect(() => {
    if (payroll?.items.length > 0) {
      const defaultPayPeriodId = payroll.items[0]?.payPeriodId;

      const defaultPayPeriod = payPeriodData?.find(
        (period: any) => period.id === defaultPayPeriodId,
      );

      if (defaultPayPeriod) {
        setSearchValue((prev) => ({
          ...prev,
          payPeriodId: defaultPayPeriodId,
        }));
        onSearch({
          ...searchValue,
          payPeriodId: defaultPayPeriodId,
        });
      }
    }
  }, [payroll?.items, payPeriodData]);

  const handleEmployeeSelect = (value: string) => {
    setSearchValue((prev) => {
      const updatedSearchValue = { ...prev, employeeId: value };
      onSearch(updatedSearchValue);
      return updatedSearchValue;
    });
  };

  const handleSelectChange = (key: string, value: string) => {
    if (key === 'yearId') {
      const selectedYear = fiscalYears.find((year) => year.id === value);
      const isDifferentYear = searchValue.yearId !== value;

      setSessions(selectedYear?.sessions || []);
      setMonths([]);

      setSearchValue((prev) => {
        const updated = {
          ...prev,
          yearId: value,
          sessionId: isDifferentYear ? '' : prev.sessionId,
          monthId: '',
        };
        onSearch(updated);
        return updated;
      });
    } else if (key === 'sessionId') {
      const selectedSession = sessions.find((s: any) => s.id === value);
      const isDifferentSession = searchValue.sessionId !== value;

      setMonths(selectedSession?.months || []);

      setSearchValue((prev) => {
        const updated = {
          ...prev,
          sessionId: value,
          monthId: isDifferentSession ? '' : prev.monthId,
        };
        onSearch(updated);
        return updated;
      });
    } else if (key === 'monthId') {
      setSearchValue((prev) => {
        const updated = {
          ...prev,
          monthId: value,
        };
        onSearch(updated);
        return updated;
      });
    } else if (key === 'departmentId') {
      setSearchValue((prev) => {
        const updated = {
          ...prev,
          departmentId: value,
        };
        onSearch(updated);
        return updated;
      });
    } else if (key === 'divisionId') {
      setSearchValue((prev) => {
        const updated = {
          ...prev,
          divisionId: value,
        };
        onSearch(updated);
        return updated;
      });
    } else if (key === 'payPeriodId') {
      setSearchValue((prev) => {
        const updated = {
          ...prev,
          payPeriodId: value,
        };
        onSearch(updated);
        return updated;
      });
    }
  };

  const options =
    employeeData?.items?.map((emp: any) => ({
      value: emp.id,
      label: `${emp?.firstName || ''} ${emp?.middleName} ${emp?.lastName}`, // Full name as label
      employeeData: emp,
    })) || [];

  return (
    <div
      id="payroll-filters-view-container"
      data-cy="payroll-filters-view-container"
      className="mb-6"
    >
      <Row
        id="payroll-filters-layout-view-row"
        data-cy="payroll-filters-layout-view-row"
        gutter={[16, 16]}
        align="middle"
        justify="space-between"
        // style={{
        //   flexWrap: oneRow ? 'nowrap' : 'wrap',
        //   display: 'flex',
        //   overflowX: oneRow ? 'auto' : 'visible',
        //   gap: oneRow ? '4px' : '16px',
        // }}
      >
        {!disable?.includes('name') && (
          <Col
            id="payroll-filters-employee-search-view-column"
            data-cy="payroll-filters-employee-search-view-column"
            // style={{
            //   flex: oneRow ? '0 0 auto' : '1 1 50%',
            //   minWidth: oneRow ? '400px' : '150px',
            // }}
            xs={24}
            sm={24}
            md={6}
            lg={6}
            xl={6}
          >
            <Select
              id="payroll-filters-employee-search-interact-select"
              data-cy="payroll-filters-employee-search-interact-select"
              showSearch
              allowClear
              className="min-h-12 w-full"
              placeholder="Search Employee"
              onChange={(value) => handleEmployeeSelect(value)}
              filterOption={(input, option) => {
                const label = option?.label;
                return (
                  typeof label === 'string' &&
                  label.toLowerCase().includes(input.toLowerCase())
                );
              }}
              options={options}
            />
          </Col>
        )}
        <Col
          id="payroll-filters-secondary-column-view-column"
          data-cy="payroll-filters-secondary-column-view-column"
          xs={24}
          sm={24}
          md={18}
          lg={18}
          xl={18}
        >
          <Row
            id="payroll-filters-secondary-row"
            data-cy="payroll-filters-secondary-row"
            gutter={[16, 16]}
            justify="end"
          >
            {!disable?.includes('year') && (
              <Col xs={24} sm={24} md={4} lg={4} xl={4}>
                <div
                  id="payroll-filters-year-select-view-container"
                  data-cy="payroll-filters-year-select-view-container"
                >
                  <Select
                    id="payroll-filters-year-select-interact-select"
                    data-cy="payroll-filters-year-select-interact-select"
                    placeholder="Year"
                    onChange={(value) => {
                      setYearId(value);
                      handleSelectChange('yearId', value);
                    }}
                    value={searchValue.yearId}
                    allowClear
                    style={{ width: '100%', height: '48px' }}
                  >
                    {fiscalYears.map((year) => (
                      <Option
                        id={`payroll-filters-year-option-select-${year.id}`}
                        data-cy={`payroll-filters-year-option-select-${year.id}`}
                        key={year.id}
                        value={year.id}
                      >
                        {year.name}
                      </Option>
                    ))}
                  </Select>
                </div>
              </Col>
            )}

            {!disable?.includes('session') && (
              <Col xs={24} sm={24} md={4} lg={4} xl={4}>
                <div
                  id="payroll-filters-session-select-view-container"
                  data-cy="payroll-filters-session-select-view-container"
                >
                  <Select
                    id="payroll-filters-session-select-interact-select"
                    data-cy="payroll-filters-session-select-interact-select"
                    placeholder="Session"
                    onChange={(value) => {
                      setSessionId(value);
                      handleSelectChange('sessionId', value);
                    }}
                    value={searchValue.sessionId}
                    allowClear
                    style={{ width: '100%', height: '48px' }}
                    disabled={!searchValue.yearId}
                  >
                    {sessions.map((session) => (
                      <Option
                        id={`payroll-filters-session-option-select-${session.id}`}
                        data-cy={`payroll-filters-session-option-select-${session.id}`}
                        key={session.id}
                        value={session.id}
                      >
                        {session.name}
                      </Option>
                    ))}
                  </Select>
                </div>
              </Col>
            )}

            {!disable?.includes('month') && (
              <Col xs={24} sm={24} md={3} lg={3} xl={3}>
                <div
                  id="payroll-filters-month-select-view-container"
                  data-cy="payroll-filters-month-select-view-container"
                >
                  <Select
                    id="payroll-filters-month-select-interact-select"
                    data-cy="payroll-filters-month-select-interact-select"
                    placeholder="Month"
