  useEffect(() => {
    if (activeTab !== 1) {
      resetStatuses();
      resetWeights();
      setInlineReportPlanId(null);
    }
  }, [activeTab, resetStatuses, resetWeights, setInlineReportPlanId]);

  const activePlanningItems = useMemo(() => {
    return transformedData ?? [];
