          </div>
        ) : planSummaries.length > 0 ? (
          isMobile || isTablet ? (
            <div
              data-cy="planning-and-reporting-components-planning-index-tsx-index-div-319"
              className="space-y-6"
            >
              {planSummaries.map((plan: any) => {
                const originalDataItem = transformedData?.find(
                  (item: any) => item.id === plan.id,
                );
                if (!originalDataItem) return null;
                return (
                  <PlanCard
                    key={plan.id}
                    plan={plan}
                    viewMode="planning"
                    activeCadence={currentCadence}
                    onApprove={() =>
                      handleApproveHandler(originalDataItem.id, true)
                    }
                    onOpen={() =>
                      handleApproveHandler(originalDataItem.id, false)
                    }
                    onEdit={() => handleEdit(originalDataItem.id)}
                    canApprove={canApproveSubordinateWork(
                      userId,
                      getEmployeeData(originalDataItem?.userId),
                    )}
                    canEdit={
                      String(userId ?? '') ===
                        String(originalDataItem?.userId ?? '') &&
                      originalDataItem?.isValidated == false &&
                      originalDataItem?.isReported == false &&
                      isDataFromActiveSession(originalDataItem?.createdAt)
                    }
                    isApprovalLoading={isApprovalLoading}
                    dateLabel={getDateLabel(originalDataItem?.createdAt ?? '')}
                    planningPeriodId={planningPeriodId}
                    onSubmitReport={
                      originalDataItem?.userId === userId &&
                      originalDataItem?.isReported == false
                        ? () => {
                            resetStatuses();
                            resetWeights();
                            setInlineReportPlanId(originalDataItem.id);
                          }
                        : undefined
                    }
                    showSubmitReport={
                      originalDataItem?.userId === userId &&
                      originalDataItem?.isReported == false &&
                      ownerCanOpenSubmitReport
                    }
                    inlineReportActive={inlineReportPlanId === plan.id}
                    onCloseInlineReport={closeInlineReport}
                    planningPeriodLabel={activeTabName}
                  />
                );
              })}
            </div>
          ) : (
            <PlanningPanelView
              plans={planSummaries}
              transformedData={transformedData}
              cadence={currentCadence}
              userId={userId}
              getEmployeeData={getEmployeeData}
              isDataFromActiveSession={isDataFromActiveSession}
              onApprove={handleApproveHandler}
              onEdit={handleEdit}
              isApprovalLoading={isApprovalLoading}
              getDateLabel={getDateLabel}
              paginationNode={paginationElement}
              planningPeriodId={planningPeriodId}
              onHoverKR={onHoverKR}
              onOpenThread={onOpenThread}
              onStartInlineReport={(planId) => {
                resetStatuses();
                resetWeights();
                setInlineReportPlanId(planId);
              }}
              ownerCanOpenSubmitReport={ownerCanOpenSubmitReport}
              inlineReportPlanId={inlineReportPlanId}
              onCloseInlineReport={closeInlineReport}
              planningPeriodLabel={activeTabName}
            />
          )
        ) : (
          <div
            data-cy="planning-and-reporting-components-planning-index-tsx-index-div-584"
            className="flex min-h-[min(42vh,26rem)] flex-1 flex-col items-center justify-center px-4 py-8 text-center lg:min-h-0"
            role="status"
            aria-live="polite"
          >
            <div
              data-cy="planning-empty-state"
              className="flex w-full max-w-md flex-col items-center justify-center px-6 py-14"
            >
              <div
                data-cy="planning-and-reporting-components-planning-index-tsx-index-div-414"
                className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-[#F1F2F6]"
              >
                <BsClipboard2Check
                  size={26}
                  className="text-[#D1D5DB]"
                  aria-hidden
                />
              </div>
              <p
                data-cy="planning-and-reporting-components-planning-index-tsx-index-p-594"
                className="text-sm font-medium text-[#161A2C]"
              >
                No plans yet
              </p>
              <p
                data-cy="planning-and-reporting-components-planning-index-tsx-index-p-427"
                className="mt-2 text-xs leading-relaxed text-[#8F94A3]"
              >
                {activeTabName
                  ? `There are no planned tasks for ${activeTabName} with the current filters and session.`
                  : 'There are no planned tasks for this period with the current filters and session.'}
              </p>
              <p
                data-cy="planning-and-reporting-components-planning-index-tsx-index-p-432"
                className="mt-2 text-xs leading-relaxed text-[#C4C7CE]"
              >
                {isDesktop
                  ? 'Add tasks from a key result using the + in the left panel.'
                  : 'Add tasks from a key result using + next to a key result.'}
              </p>
            </div>
          </div>
        )}
      </section>

      {!isDesktopPanelView &&
        (isMobile || isTablet
          ? showPlanningPagination && (
              <CustomMobilePagination
                totalResults={totalPlanningItems}
                pageSize={pageSize}
                onChange={(pg, ps) => {
                  setPage(pg);
                  setPageSize(ps);
                }}
                onShowSizeChange={(size) => {
                  setPageSize(size);
                  setPage(1);
                }}
              />
            )
          : paginationElement)}
    </div>
  );
}
export default Planning;

import { useEffect, useMemo } from 'react';
import { useQueryClient } from 'react-query';
import {
  rememberAchievedMilestones,
  useRecentlyAchievedMilestones,
} from '@/utils/recentlyAchievedMilestones';
import { restampSessionAchievedMilestonesInCaches } from '@/utils/invalidateOkrPlanningCaches';
import { useFetchObjectives } from '@/store/server/features/employees/planning/queries';
import { useGetPlanningPeriodsHierarchy } from '@/store/server/features/okrPlanningAndReporting/queries';
import {
  buildPlanningTargetsFromObjectives,
  buildPlanningTargetsFromDailyHierarchy,
  filterPlanningTargetsByBlockedKeyResults,
  indexObjectiveMilestonesByKrId,
  type PlanningTarget,
} from './buildPlanningTargets';

export function usePlanningTargets(
  userId: string,
  planningPeriodId: string | undefined,
  userKeyResultItems: any[] = [],
  /** Plan/panel KRs — often hold milestone titles when objectives omit them */
  planKeyResults: any[] = [],
): {
  targets: PlanningTarget[];
  /** Same milestone rows createPlanObjective uses, keyed by KR id */
  objectiveMilestonesByKrId: Map<string, any[]>;
  /** True only on first load (no cached data yet) — not background refetch. */
  isLoading: boolean;
  isFetching: boolean;
  isDailyPeriod: boolean;
  /** Refresh objective milestone Completed status (e.g. when opening + menu). */
  refetchObjectives: () => void;
} {
  const queryClient = useQueryClient();
  const {
    data: objective,
    isLoading: objLoading,
    isFetching: objFetching,
    refetch: refetchObjectives,
  } = useFetchObjectives(userId, {
    // Keep prior rows while refetching so + / pick / composer do not blank.
    refetchOnMount: true,
    staleTime: 30_000,
    keepPreviousData: true,
    refetchOnWindowFocus: false,
  });
  const {
    data: hierarchy,
    isLoading: hierLoading,
    isFetching: hierFetching,
  } = useGetPlanningPeriodsHierarchy(userId, planningPeriodId || '');

  // Rebuild targets when session achieve/reopen changes (not only when RQ data changes).
  const recentlyAchievedIds = useRecentlyAchievedMilestones((s) => s.ids);
  const reopenedMilestoneIds = useRecentlyAchievedMilestones(
    (s) => s.reopenedMilestoneIds,
  );
  const reopenedKeyResultIds = useRecentlyAchievedMilestones(
    (s) => s.reopenedKeyResultIds,
  );

  const isDailyPeriod = !!hierarchy?.parentPlan;

  const objectiveMilestonesByKrId = useMemo(
    () => indexObjectiveMilestonesByKrId(objective, userKeyResultItems),
    [objective, userKeyResultItems],
  );

  const targets = useMemo(() => {
    if (!planningPeriodId) return [];
    const raw = isDailyPeriod
      ? buildPlanningTargetsFromDailyHierarchy(hierarchy)
      : buildPlanningTargetsFromObjectives(
          objective,
          userKeyResultItems,
          planKeyResults,
        );
    return filterPlanningTargetsByBlockedKeyResults(raw, userKeyResultItems);
  }, [
    planningPeriodId,
    isDailyPeriod,
    hierarchy,
    objective,
    userKeyResultItems,
    planKeyResults,
    recentlyAchievedIds,
    reopenedMilestoneIds,
    reopenedKeyResultIds,
  ]);

  // Seed session memory from authoritative objective/API completed rows so a
  // later stale refetch cannot flip achieved milestones back to selectable.
  useEffect(() => {
    if (!planningPeriodId) return;
    const ids = targets
      .filter((t) => t.milestoneId && t.isCompleted)
      .map((t) => t.milestoneId);
    if (ids.length > 0) rememberAchievedMilestones(ids);
  }, [targets, planningPeriodId]);

  // After browser refresh, re-stamp Completed onto RQ caches from persisted IDs
  // so stale Incomplete API rows cannot re-enable the pick menu.
  useEffect(() => {
    if (!recentlyAchievedIds || recentlyAchievedIds.size === 0) return;
    if (objective == null && userKeyResultItems.length === 0) return;
    restampSessionAchievedMilestonesInCaches(queryClient);
  }, [recentlyAchievedIds, objective, userKeyResultItems, queryClient]);

  // Background invalidation/refetch must not flip buttons or panels into loading.
  const isInitialLoading =
    (objLoading && objective == null) ||
    (!!planningPeriodId && hierLoading && hierarchy == null);

  return {
    targets,
    objectiveMilestonesByKrId,
    isLoading: isInitialLoading,
    isFetching: objFetching || hierFetching,
    isDailyPeriod,
    refetchObjectives: () => {
      void refetchObjectives();
    },
  };
}

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  AllPlanningPeriods,
  useDefaultPlanningPeriods,
  useGetReporting,
} from '@/store/server/features/okrPlanningAndReporting/queries';
import { useGetFiscalYearById } from '@/store/server/features/organizationStructure/fiscalYear/queries';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import dayjs from 'dayjs';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import { PlanningAndReportingStore } from '@/store/uistate/features/planningAndReporting/useStore';
import { BsFileEarmarkText } from 'react-icons/bs';
import { useApprovalReporting } from '@/store/server/features/okrPlanningAndReporting/mutations';
import { CustomMobilePagination } from '@/components/customPagination/mobilePagination';
import { useIsMobile } from '@/hooks/useIsMobile';
import CustomPagination from '@/components/customPagination';
import PlanCard from '../cards/PlanCard';
import PlanCardSkeleton from '../cards/PlanCardSkeleton';
import PlanningPanelView from '../planning/PlanningPanelView';
import {
  useEffectivePlanUserIds,
  usePlanningFilterScopeReady,
} from '../planning/usePlanningData';
import { Cadence } from '../types';
import { canApproveSubordinateWork, formatPlanningReportDate } from '../utils';
import { PlanCardInlineReportForm } from '../createReport/PlanCardInlineReportForm';
import { useRecentReportTaskStatuses } from '@/utils/recentReportTaskStatuses';
import { transformReportToPlanSummary } from '../dataTransformer/vamp';

function Reporting({
  onHoverKR,
  onOpenThread,
}: {
  onHoverKR?: (krId: string | null) => void;
  onOpenThread?: (entityId: string, threadKind: 'plan' | 'report') => void;
}) {
  const {
    activePlanPeriod,
    activeTab,
    pageReporting,
    setPageReporting,
    pageSizeReporting,
    activePlanPeriodId,
    setPageSizeReporting,
    selectedSessionIds,
    selectedFiscalYearId,
    allSessionsOfYear,
    planningDefaultFilterApplied,
  } = PlanningAndReportingStore();
  const { data: employeeData } = useGetAllUsers();
  const { userId } = useAuthenticationStore();
  const { data: planningPeriods } = useDefaultPlanningPeriods();
  const { data: userPlanningPeriods } = AllPlanningPeriods();
  const effectiveSelectedUsers = useEffectivePlanUserIds();
  const { isFilterScopePending } = usePlanningFilterScopeReady();
  const { isMobile, isTablet } = useIsMobile();
  const { data: selectedFiscalYear } = useGetFiscalYearById(
    selectedFiscalYearId || '',
  );

  const { mutate: ReportApproval, isLoading: isApprovalLoading } =
    useApprovalReporting();
  const planningPeriodId =
    activePlanPeriodId || userPlanningPeriods?.[activePlanPeriod - 1]?.id;

  const {
    data: allReporting,
    isLoading: isReportingQueryLoading,
    isFetching: isReportingQueryFetching,
  } = useGetReporting(
    {
      userId: effectiveSelectedUsers,
      planPeriodId: planningPeriodId ?? '',
      pageReporting,
      pageSizeReporting,
      sessionId:
        selectedSessionIds.length > 0
          ? selectedSessionIds
          : allSessionsOfYear.length > 0
            ? allSessionsOfYear
            : [],
    },
    {
      enabled:
        activeTab === 2 &&
        !!planningPeriodId &&
        planningDefaultFilterApplied &&
        effectiveSelectedUsers.length > 0,
    },
  );

  const getReportLoading =
    isFilterScopePending ||
    isReportingQueryLoading ||
    (isReportingQueryFetching && allReporting === undefined);

  const getPlanningPeriodDetail = (id: string) => {
    return planningPeriods?.items?.find((p: any) => p?.id === id) || {};
  };

  const activeTabName = getPlanningPeriodDetail(planningPeriodId ?? '')?.name;

  useEffect(() => {
    setPageReporting(1);
    setPageSizeReporting(10);
  }, [activeTab, setPageReporting, setPageSizeReporting]);

  const getEmployeeData = (id: string) => {
    return employeeData?.items?.find((emp: any) => emp?.id === id) || {};
  };

  const handleApproveHandler = (id: string, value: boolean) => {
    ReportApproval({ id, value });
  };

  const isDataFromActiveSession = (createdAt: string): boolean => {
    if (!selectedFiscalYearId || !selectedFiscalYear?.sessions) return true;
    const dataDate = dayjs(createdAt);
    return !!selectedFiscalYear.sessions.find((session) => {
      const start = dayjs(session.startDate);
      const end = dayjs(session.endDate);
      return (
        session.active &&
        (dataDate.isAfter(start) || dataDate.isSame(start)) &&
        (dataDate.isBefore(end) || dataDate.isSame(end))
      );
    });
  };

  const getDateLabel = (createdAt: string): string => {
    return formatPlanningReportDate(createdAt);
  };

  const cadence = (activeTabName?.toLowerCase() as Cadence) || 'weekly';
  const isDesktop = !isMobile && !isTablet;
  const [inlineEditingReport, setInlineEditingReport] = useState<{
    reportId: string;
    planId: string;
  } | null>(null);

  const closeInlineEditReport = useCallback(() => {
    setInlineEditingReport(null);
  }, []);

  const startInlineEditReport = useCallback(
    (reportId: string) => {
      const row = allReporting?.items?.find(
        (item: any) => item.id === reportId,
      );
      const resolvedPlanId =
        row?.planId || row?.plan?.id || row?.plan?.planId || '';
      if (!resolvedPlanId) return;
      setInlineEditingReport({ reportId, planId: resolvedPlanId });
    },
    [allReporting?.items],
  );

  const reportTaskOverrides = useRecentReportTaskStatuses((s) => s.byReport);

  const reportSummaries = useMemo(() => {
    if (!allReporting?.items) return [];
    return allReporting?.items?.map((dataItem: any) =>
      transformReportToPlanSummary(dataItem, cadence, employeeData),
    );
  }, [allReporting?.items, cadence, employeeData, reportTaskOverrides]);

  const totalReportingItems = allReporting?.meta?.totalItems ?? 0;
  const showReportingPagination =
    !getReportLoading && totalReportingItems > pageSizeReporting;

  const paginationNode = !showReportingPagination ? null : isMobile ||
    isTablet ? (
    <CustomMobilePagination
      totalResults={totalReportingItems}
      pageSize={pageSizeReporting}
      onChange={(page, pageSize) => {
        setPageReporting(page);
        setPageSizeReporting(pageSize);
      }}
      onShowSizeChange={(size) => {
        setPageSizeReporting(size);
        setPageReporting(1);
      }}
    />
  ) : (
    <CustomPagination
      total={totalReportingItems}
      current={pageReporting}
      pageSize={pageSizeReporting}
      onShowSizeChange={(size) => {
        setPageSizeReporting(size);
        setPageReporting(1);
      }}
      onChange={(page, pageSize) => {
        setPageReporting(page);
        setPageSizeReporting(pageSize);
      }}
      data-cy="reporting-list-pagination"
    />
  );

  return (
    <div
      data-cy="planning-and-reporting-components-reporting-index-tsx-index-div-358"
      className="flex w-full min-h-0 min-w-0 max-w-full flex-col lg:min-h-0 lg:flex-1"
    >
      <section
        data-cy="planning-and-reporting-components-reporting-index-tsx-index-section-449"
        className="mt-0 flex min-h-0 flex-1 flex-col"
      >
