function formatLevelLabel(level: unknown): string {
  const n = typeof level === 'number' ? level : Number(level);
  if (!Number.isFinite(n)) return 'Level';
  if (n === 1) return '1st Level';
  if (n === 2) return '2nd Level';
  if (n === 3) return '3rd Level';
  return `${n}th Level`;
}

