  selectedRowKeys,
  setSelectedRowKeys,
}) => {
  const [tableData, setTableData] = useState<any[]>([]);
  const pathname = usePathname();
  const { orderBy, orderDirection, setOrderBy, setOrderDirection } =
    usePagination(1, 10);

  const {
    currentPage,
    pageSize,
    setCurrentPage,
    setPageSize,
    resetPagination,
  } = useMyTimesheetStore();

  useEffect(() => {
    resetPagination();
  }, [pathname]);

  const {
    setEmployeeId,
    setIsShowEmployeeAttendanceSidebar,
    setEmployeeAttendanceId,
    setAttendanceRecordDate,
  } = useEmployeeAttendanceStore();
  const { filter, setFilter } = useEmployeeAttendanceStore();
  const { employeeId: linkedEmployee } = useNotificationDeepLink();

  useEffect(() => {
    if (!linkedEmployee) return;
