              data-cy={`time-attendance-employee-attendance-row-clock-in-div-${record.key}-missed-break-clock-in`}
              className={MISSED_BREAK_BADGE_CLASS}
            >
              Missed Break Clock In
            </div>
          )
        ) : (
          formatAttendanceCellTime(date)
