                title="Leave Balance"
                subtitle="Time and Attendance / Leave Balance"
                titleExtra={
                  <Space
                    size={20}
                    id="time-attendance-leave-management-header-actions"
                    data-cy="time-attendance-leave-management-header-actions"
                  >
                    <div
                      className="mb-2 flex justify-between"
                      id="time-attendance-leave-balance-header-row"
                      data-cy="time-attendance-leave-balance-header-row"
                    >
                      <div
                        id="time-attendance-leave-balance-download-container"
                        data-cy="time-attendance-leave-balance-download-container"
                      >
                        <DownloadLeaveBalance data-cy="time-attendance-leave-balance-download-button" />
                      </div>
                    </div>
                  </Space>
                }
              />
            )}
          </div>
          <Tabs
            activeKey={activeTabKey}
            onChange={setActiveTabKey}
            items={[
              {
                key: '1',
                label: (
                  <span
                    data-cy="time-attendance-leave-management-tab-label"
                    className={`${
                      activeTabKey === '1'
                        ? 'font-bold text-base'
                        : 'font-normal text-base'
                    }`}
                  >
                    Leave Management
                  </span>
                ),
                children: (
                  <LeaveManagementTable
                    data-cy="time-attendance-leave-management-table"
                    setBodyRequest={setBodyRequest}
                    selectedRowKeys={selectedRowKeys}
                    setSelectedRowKeys={setSelectedRowKeys}
                  />
                ),
              },
              {
                key: '2',
                label: (
                  <span
                    data-cy="time-attendance-leave-balance-tab-label"
                    className={`${
                      activeTabKey === '2'
                        ? 'font-bold text-base'
                        : 'font-normal text-base'
                    }`}
                  >
                    Leave Balance
                  </span>
                ),
                children: <LeaveBalance />,
              },
            ]}
          />
          {/* <LeaveManagementTable
            data-cy="time-attendance-leave-management-table"
            setBodyRequest={setBodyRequest}
            selectedRowKeys={selectedRowKeys}
            setSelectedRowKeys={setSelectedRowKeys}
          /> */}
        </BlockWrapper>
      </div>

      <Modal
        open={emailNotificationModalOpen}
        onCancel={() => setEmailNotificationModalOpen(false)}
        title={
          <div data-cy="time-attendance-leave-management-email-notification-modal-title-wrapper">
            <div
              className="text-base font-bold text-gray-900"
              data-cy="time-attendance-leave-management-email-notification-modal-title"
            >
              Notification
            </div>
            <div
              className="text-sm text-gray-500 font-normal mt-0.5"
              data-cy="time-attendance-leave-management-email-notification-modal-subtitle"
            >
              Leave Approval Notification
            </div>
          </div>
        }
        closeIcon={
          <CloseOutlined data-cy="time-attendance-leave-management-email-notification-modal-close" />
        }
        footer={
          <div
            className="flex justify-end gap-2"
            data-cy="time-attendance-leave-management-email-notification-modal-footer"
          >
            <Button
              onClick={() => setEmailNotificationModalOpen(false)}
              data-cy="time-attendance-leave-management-email-notification-modal-cancel"
              className="border-gray-300 text-gray-700"
            >
              Cancel
            </Button>
            <Button
              type="primary"
              onClick={() => {
                const selectedIds =
                  selectedRowKeys.length > 0
                    ? selectedRowKeys.map((key) => key.toString())
                    : undefined;
                sendNotification(
                  { leaveRequestIds: selectedIds },
                  {
                    onSuccess: () => setEmailNotificationModalOpen(false),
                  },
                );
              }}
              loading={isLoading}
              data-cy="time-attendance-leave-management-email-notification-modal-send"
              className="bg-[#3636F0] hover:!bg-[#2d2dbf] border-none"
            >
              Send Email
            </Button>
          </div>
        }
        width={500}
        centered
        className="rounded-xl"
        data-cy="time-attendance-leave-management-email-notification-modal"
      >
        <p
          className="text-gray-700 text-sm mb-0"
          data-cy="time-attendance-leave-management-email-notification-modal-body"
        >
          This will send an email notification to the approver for all pending
          leave requests. Do you want to continue?
        </p>
      </Modal>

      <LeaveManagementDeepLink />
      <LeaveRequestDetailModal data-cy="time-attendance-leave-request-detail-modal" />
      <LeaveRequestSidebar data-cy="time-attendance-leave-management-request-sidebar" />
    </>
  );
};

export default LeaveManagement;

import React, { useEffect, useMemo, useState } from 'react';
import { useGetApprovalLeaveRequestAllStatus } from '@/store/server/features/timesheet/leaveRequest/queries';
import { useGetWorkFromHomeApprovalAllStatus } from '@/store/server/features/timesheet/workFromHome/queries';
import { useGetShiftSwapApprovalAllStatus } from '@/store/server/features/timesheet/shiftSwap/queries';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import { TableColumnsType } from '@/types/table/table';
import {
  Button,
  Input,
  Popconfirm,
  Table,
  Skeleton,
  Card,
  Select,
  Tag,
} from 'antd';
import { LeaveRequestStatus } from '@/types/timesheet/settings';
import { useApprovalStore } from '@/store/uistate/features/approval';
import {
  useSetAllApproveLeaveRequest,
  useSetAllFinalApproveLeaveRequest,
  useSetApproveLeaveRequest,
  useSetFinalApproveLeaveRequest,
  useSetRejectLeaveRequest,
} from '@/store/server/features/timesheet/leaveRequest/mutation';
import { useSetFinalWorkFromHomeRequest } from '@/store/server/features/timesheet/workFromHome/mutation';
import {
  usePeerApproveShiftSwap,
  usePeerRejectShiftSwap,
  useSetFinalShiftSwapRequest,
} from '@/store/server/features/timesheet/shiftSwap/mutation';
import { useGetSimpleEmployee } from '@/store/server/features/employees/employeeDetail/queries';
import { useCurrentLeaveApprovalStore } from '@/store/uistate/features/timesheet/myTimesheet/currentApproval';
import { useAllCurrentLeaveApprovedStore } from '@/store/uistate/features/timesheet/myTimesheet/allCurentApproved';
import { AllLeaveRequestApproveData } from '@/store/server/features/timesheet/leaveRequest/interface';
import dayjs from 'dayjs';
import CustomPagination from '@/components/customPagination';
import { usePathname, useSearchParams } from 'next/navigation';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import { TableSkeleton } from '@/components/tableSkeleton';

type ApprovalTypeFilter = 'Leave' | 'WorkFromHome' | 'ShiftSwap';

const DATE_DISPLAY_FORMAT = 'MMM D, YYYY';

/** Min width for horizontal scroll on narrow viewports (aligned with leave table pattern). */
const APPROVAL_TABLE_SCROLL_X_LEAVE = 960;
const APPROVAL_TABLE_SCROLL_X_SHIFT_SWAP = 1480;

const ApprovalTable = () => {
  const { pageSize, userCurrentPage, setUserCurrentPage, setPageSize } =
    useCurrentLeaveApprovalStore();
  const { allPageSize, allUserCurrentPage } = useAllCurrentLeaveApprovedStore();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const tenantId = useAuthenticationStore.getState().tenantId;
  const { userId } = useAuthenticationStore();
  const userRollId = useAuthenticationStore.getState().userData.roleId;
  const { rejectComment, setRejectComment } = useApprovalStore();
  const { mutate: editApprover, isLoading: isLoadingEditApprover } =
    useSetApproveLeaveRequest();
  const { mutate: finalApprover } = useSetFinalApproveLeaveRequest();
  const { mutate: finalWorkFromHomeApprover } =
    useSetFinalWorkFromHomeRequest();
  const { mutate: finalShiftSwapApprover } = useSetFinalShiftSwapRequest();
  const { mutate: peerApproveShiftSwap, isLoading: isPeerApproving } =
    usePeerApproveShiftSwap();
  const { mutate: peerRejectShiftSwap, isLoading: isPeerRejecting } =
    usePeerRejectShiftSwap();
  const { mutate: allApprover, isLoading: allApproveIsLoading } =
    useSetAllApproveLeaveRequest();
  const { mutate: allReject, isLoading: allRejectIsLoading } =
    useSetRejectLeaveRequest();
  const { mutate: finalAllApproval } = useSetAllFinalApproveLeaveRequest();

  const [searchEmployee, setSearchEmployee] = useState<string>('');
  const [filterStatus, setFilterStatus] = useState<string>('');
  const [approvalTypeFilter, setApprovalTypeFilter] =
    useState<ApprovalTypeFilter>('Leave');
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);

  const { data: allUsersData } = useGetAllUsers();
  const userOptions = useMemo((): Array<{ label: string; value: string }> => {
    return (allUsersData?.items ?? []).map((user: any) => ({
      label: [user?.firstName, user?.middleName, user?.lastName]
        .filter(Boolean)
        .join(' '),
      value: user?.id ?? '',
    }));
  }, [allUsersData?.items]);

  const statusFilterOptions = [
    { label: 'Pending', value: LeaveRequestStatus.PENDING },
    { label: 'Approved', value: LeaveRequestStatus.APPROVED },
    { label: 'Rejected', value: LeaveRequestStatus.DECLINED },
  ];
  const approvalTypePills: Array<{
    id: ApprovalTypeFilter;
    label: string;
  }> = [
    { id: 'Leave', label: 'Leave' },
    { id: 'WorkFromHome', label: 'Work From Home' },
    { id: 'ShiftSwap', label: 'Shift Swap' },
  ];

  useEffect(() => {
    setUserCurrentPage(1);
    setPageSize(10);
  }, [pathname]);

  useEffect(() => {
    const type = (searchParams.get('type') ?? '').replace(/[-_]/g, '');
    if (/^workfromhome$/i.test(type) || /^wfh$/i.test(type)) {
      setApprovalTypeFilter('WorkFromHome');
    } else if (/^shiftswap$/i.test(type) || /^swap$/i.test(type)) {
      setApprovalTypeFilter('ShiftSwap');
    } else if (/^leave$/i.test(type)) {
      setApprovalTypeFilter('Leave');
    }

    const linkedEmployee =
      searchParams.get('employeeId') || searchParams.get('userId') || '';
    if (linkedEmployee && linkedEmployee !== userId) {
      setSearchEmployee(linkedEmployee);
    }
  }, [searchParams, userId]);

  const {
    data: leaveApprovalData,
    isLoading: isLoadingLeaveApproval,
    refetch: refetchLeave,
  } = useGetApprovalLeaveRequestAllStatus(
    userId ?? '',
    userCurrentPage,
    pageSize,
    searchEmployee || undefined,
    filterStatus || undefined,
  );
  const {
    data: workFromHomeApprovalData,
    isLoading: isLoadingWorkFromHomeApproval,
    refetch: refetchWorkFromHome,
  } = useGetWorkFromHomeApprovalAllStatus(
    userId ?? '',
    userCurrentPage,
    pageSize,
    searchEmployee || undefined,
    filterStatus || undefined,
    approvalTypeFilter === 'WorkFromHome',
  );
  const {
    data: shiftSwapApprovalData,
    isLoading: isLoadingShiftSwapApproval,
    refetch: refetchShiftSwap,
  } = useGetShiftSwapApprovalAllStatus(
    userId ?? '',
    userCurrentPage,
    pageSize,
    searchEmployee || undefined,
    filterStatus || undefined,
    approvalTypeFilter === 'ShiftSwap',
  );

  // Reset to page 1 when filters change
  useEffect(() => {
    setUserCurrentPage(1);
    setSelectedRowKeys([]);
  }, [searchEmployee, filterStatus, approvalTypeFilter]);

  /**
   * Use only initial-loading state for table skeleton.
   * Keeping refetch (`isFetching`) out of this prevents action buttons/popconfirms
   * from getting disabled mid-interaction (seen on WFH approve flow).
   */
  const isApprovalListLoading =
    approvalTypeFilter === 'WorkFromHome'
      ? isLoadingWorkFromHomeApproval
      : approvalTypeFilter === 'ShiftSwap'
        ? isLoadingShiftSwapApproval
        : isLoadingLeaveApproval;

  // Normalize response: support both { items, meta } and { data: { items, meta } }
  const approvalData =
    approvalTypeFilter === 'WorkFromHome'
      ? workFromHomeApprovalData
      : approvalTypeFilter === 'ShiftSwap'
        ? shiftSwapApprovalData
        : leaveApprovalData;
  const payload = approvalData?.data ?? approvalData;
  const rawItems = payload?.items ?? approvalData?.items ?? [];
  const isWorkFromHome = approvalTypeFilter === 'WorkFromHome';
  const isShiftSwap = approvalTypeFilter === 'ShiftSwap';
  const requestLabel = isWorkFromHome
    ? 'work from home request'
    : isShiftSwap
      ? 'shift swap request'
      : 'leave request';
  const refetchCurrent = () => {
    if (isWorkFromHome) refetchWorkFromHome();
    else if (isShiftSwap) refetchShiftSwap();
    else refetchLeave();
  };
  const finalApproval = (
    e: {
      leaveRequestId?: string;
      workFromHomeRequestId?: string;
      shiftSwapRequestId?: string;
      status: 'approved' | 'declined';
    },
    options?: { onSuccess?: () => void },
  ) => {
    if (isWorkFromHome) {
      finalWorkFromHomeApprover(
        {
          workFromHomeRequestId: e.workFromHomeRequestId || '',
          status: e.status,
        },
        { onSuccess: () => options?.onSuccess?.() },
      );
    } else if (isShiftSwap) {
      finalShiftSwapApprover(
        {
          shiftSwapRequestId: e.shiftSwapRequestId || '',
          status: e.status,
        },
        { onSuccess: () => options?.onSuccess?.() },
      );
    } else {
      finalApprover(
        {
          leaveRequestId: e.leaveRequestId || '',
          status: e.status,
        },
        { onSuccess: () => options?.onSuccess?.() },
      );
    }
  };
  const reject: any = (e: {
    approvalWorkflowId: string;
    stepOrder: any;
    requestId: string;
    approvedUserId: string;
    approverRoleId: string;
    action: string;
    tenantId: string;
    comment: { comment: string; commentedBy: string; tenantId: string };
  }) => {
    editApprover(e, {
      onSuccess: () => {
        setRejectComment('');
        // Shift swap decline is synced by approval-module → T&A escalate.
        // A second frontend escalate fails once status is no longer PENDING_APPROVAL.
        if (isShiftSwap) {
          refetchCurrent();
          return;
        }
        finalApproval(
          isWorkFromHome
            ? { workFromHomeRequestId: e.requestId, status: 'declined' }
            : { leaveRequestId: e.requestId, status: 'declined' },
          {
            onSuccess: () => refetchCurrent(),
          },
        );
      },
    });
  };

  const confirm: any = (e: {
    approvalWorkflowId: string;
    stepOrder: any;
    requestId: string;
    approvedUserId: string;
    approverRoleId: string;
    action: string;
    tenantId: string;
  }) => {
    editApprover(e, {
      onSuccess: (data) => {
        // Shift swap finalization is synced by approval-module → T&A escalate.
        // Calling escalate again after COMPLETED returns 400.
        if (isShiftSwap) {
          refetchCurrent();
          return;
        }
        if (data?.last === true) {
          finalApproval(
            isWorkFromHome
              ? { workFromHomeRequestId: e.requestId, status: 'approved' }
              : { leaveRequestId: e.requestId, status: 'approved' },
            {
              onSuccess: () => refetchCurrent(),
            },
          );
        } else {
          refetchCurrent();
        }
      },
    });
  };

  const cancel: any = () => {};
  const isPeerPendingItem = (item: any) =>
    !!item?.isPeerApproval ||
    item?.status === 'PENDING_PEER' ||
    String(item?.status || '').toLowerCase() === 'pending_peer';
  const isPending = (item: any) => {
    if (isPeerPendingItem(item)) {
      return (
        item?.peerUserId === userId ||
        (item?.nextApprover || []).some((a: any) => a?.userId === userId)
      );
    }
    return (item?.nextApprover || []).some((a: any) => a?.userId === userId);
  };
  const allFilterData = useMemo(
    () =>
      rawItems.map((item: any, index: number) => {
        const pending = isPending(item);
        const peerPending = isPeerPendingItem(item);
        const typeLabel = isWorkFromHome
          ? 'Work From Home'
          : isShiftSwap
            ? peerPending
              ? 'Shift Swap (Peer)'
              : 'Shift Swap'
            : item?.leaveType?.title;
        return {
          key: item?.id ?? index,
          id: item?.id,
          userId: item?.userId || item?.requesterUserId,
          peerUserId: item?.peerUserId,
          requesterUserId: item?.requesterUserId,
          requesterShiftId: item?.requesterShiftId,
          targetShiftId: item?.targetShiftId,
          peerShiftId: item?.peerShiftId,
          requesterShiftLabel: item?.requesterShiftLabel,
          targetShiftLabel: item?.targetShiftLabel,
          peerShiftLabel: item?.peerShiftLabel,
          reason: item?.reason,
          startAt: item?.startAt || item?.startDate,
          endAt: item?.endAt || item?.endDate,
          days:
            item?.days ??
            (isShiftSwap &&
            (item?.startAt || item?.startDate) &&
            (item?.endAt || item?.endDate)
              ? dayjs(item?.endAt || item?.endDate).diff(
                  dayjs(item?.startAt || item?.startDate),
                  'day',
                ) + 1
              : undefined),
          leaveType: typeLabel,
          status: item?.status,
          action: (
            <div
              className="flex gap-4"
              id={`time-attendance-approval-table-row-${index}-actions-container`}
              data-cy={`time-attendance-approval-table-row-${index}-actions-container`}
            >
              {pending ? (
                <>
                  <Popconfirm
                    title="Approve Request"
                    description={`Are you sure to approve this ${requestLabel}?`}
                    onConfirm={() => {
                      if (peerPending) {
                        peerApproveShiftSwap(
                          { id: item?.id },
                          { onSuccess: () => refetchCurrent() },
                        );
                        return;
                      }
                      confirm({
                        approvalWorkflowId: item?.approvalWorkflowId,
                        stepOrder: item?.nextApprover?.[0]?.stepOrder,
                        requestId: item?.id,
                        approvedUserId: userId,
                        approverRoleId: userRollId,
                        action: 'Approved',
                        tenantId: tenantId,
                      });
                    }}
                    onCancel={cancel}
                    okText="Approve"
                    cancelText="Cancel"
                    disabled={
                      isApprovalListLoading ||
                      isLoadingEditApprover ||
                      isPeerApproving ||
                      isPeerRejecting ||
                      allApproveIsLoading ||
                      allRejectIsLoading
                    }
                    data-cy={`time-attendance-approval-table-row-${index}-approve-popconfirm`}
                  >
                    <Button
                      type="primary"
                      id={`time-attendance-approval-table-row-${index}-approve-button`}
                      data-cy={`time-attendance-approval-table-row-${index}-approve-button`}
                    >
                      Approve
                    </Button>
                  </Popconfirm>
                  <Popconfirm
                    title="Reject Request"
                    description={
                      <>
                        <p data-cy="my-timesheet-components-approvaltable-index-tsx-index-p-166">
                          {`Are you sure you want to reject this ${requestLabel}?`}
                        </p>
                        <Input
                          placeholder="Add a comment"
                          value={rejectComment}
                          onChange={(e) => setRejectComment(e.target.value)}
                          style={{ marginTop: 8 }}
                          id={`time-attendance-approval-table-row-${index}-reject-comment-input`}
                          data-cy={`time-attendance-approval-table-row-${index}-reject-comment-input`}
                        />
                      </>
                    }
                    onConfirm={() => {
                      if (peerPending) {
                        peerRejectShiftSwap(
                          { id: item?.id, comment: rejectComment },
                          {
                            onSuccess: () => {
                              setRejectComment('');
                              refetchCurrent();
                            },
                          },
                        );
                        return;
                      }
                      reject({
                        approvalWorkflowId: item?.approvalWorkflowId,
                        stepOrder: item?.nextApprover?.[0]?.stepOrder,
                        requestId: item?.id,
                        approvedUserId: userId,
                        approverRoleId: userRollId,
                        action: 'Rejected',
                        tenantId: tenantId,
                        comment: {
                          comment: rejectComment,
                          commentedBy: userId,
                          tenantId: tenantId,
                        },
                      });
                    }}
                    onCancel={cancel}
                    okText="Reject"
                    cancelText="Cancel"
                    okButtonProps={{ disabled: !rejectComment }}
                    disabled={
                      isApprovalListLoading ||
                      isLoadingEditApprover ||
                      isPeerApproving ||
                      isPeerRejecting ||
                      allApproveIsLoading ||
                      allRejectIsLoading
                    }
                    data-cy={`time-attendance-approval-table-row-${index}-reject-popconfirm`}
                  >
                    <Button
                      danger
                      id={`time-attendance-approval-table-row-${index}-reject-button`}
                      data-cy={`time-attendance-approval-table-row-${index}-reject-button`}
                    >
                      Reject
                    </Button>
                  </Popconfirm>
                </>
              ) : (
                <Tag
                  color={
                    item?.status === LeaveRequestStatus.APPROVED ||
                    item?.status === 'APPROVED' ||
                    item?.status === 'approved' ||
                    item?.status === 'COMPLETED' ||
                    item?.status === 'completed'
                      ? 'success'
                      : 'error'
                  }
                  id={`time-attendance-approval-table-row-${index}-status-tag`}
                  data-cy={`time-attendance-approval-table-row-${index}-status-tag`}
                >
                  {item?.status === LeaveRequestStatus.APPROVED ||
                  item?.status === 'APPROVED' ||
                  item?.status === 'approved' ||
                  item?.status === 'COMPLETED' ||
                  item?.status === 'completed'
                    ? 'Approved'
                    : item?.status === LeaveRequestStatus.DECLINED ||
                        item?.status === 'declined' ||
                        item?.status === 'DECLINED' ||
                        item?.status === 'rejected' ||
                        item?.status === 'REJECTED' ||
                        item?.status === 'PEER_REJECTED' ||
                        item?.status === 'APPROVAL_REJECTED'
                      ? 'Rejected'
                      : String(item?.status || 'Rejected').replace(/_/g, ' ')}
                </Tag>
              )}
            </div>
          ),
        };
      }),
    [
      rawItems,
      userId,
      userRollId,
      tenantId,
      rejectComment,
      isWorkFromHome,
      isShiftSwap,
      requestLabel,
      isApprovalListLoading,
      isLoadingEditApprover,
      isPeerApproving,
      isPeerRejecting,
      allApproveIsLoading,
      allRejectIsLoading,
      peerApproveShiftSwap,
      peerRejectShiftSwap,
      refetchLeave,
      refetchWorkFromHome,
      refetchShiftSwap,
    ],
  );
  const EmpRender = ({ userId }: any) => {
    const fromDirectory = userOptions.find((u) => u.value === userId)?.label;
    const {
      isLoading,
      data: employeeData,
      isError,
    } = useGetSimpleEmployee(fromDirectory ? '' : userId);

    if (fromDirectory) {
      return (
        <div
          className="text-sm text-gray-900"
          id={`time-attendance-approval-table-employee-${userId}-container`}
          data-cy={`time-attendance-approval-table-employee-${userId}-container`}
        >
          {fromDirectory}
        </div>
      );
    }

    if (isLoading)
      return (
        <div data-cy="time-attendance-approval-table-employee-loading">
          <span data-cy="time-attendance-approval-table-employee-loading-placeholder">
            ...
          </span>
        </div>
      );
    if (isError)
      return (
        <span data-cy="time-attendance-approval-table-employee-error">-</span>
      );

    return employeeData ? (
      <div
        className="text-sm text-gray-900"
        id={`time-attendance-approval-table-employee-${userId}-container`}
        data-cy={`time-attendance-approval-table-employee-${userId}-container`}
      >
        {employeeData?.firstName || '-'} {employeeData?.middleName || '-'}{' '}
        {employeeData?.lastName || '-'}
      </div>
    ) : (
      '-'
    );
  };
  const rowCellPadding = { paddingTop: 8, paddingBottom: 8 };
  const rowCellClass = 'text-sm py-2 text-gray-900';

  const columns: TableColumnsType<any> = useMemo(() => {
    const base: TableColumnsType<any> = [
      {
        title: isShiftSwap ? 'Requester' : 'Employee',
        dataIndex: 'userId',
        key: 'userId',
        width: 200,
        ellipsis: true,
        onCell: () => ({ style: rowCellPadding }),
        render: (text: string) => <EmpRender userId={text} />,
      },
    ];

    if (isShiftSwap) {
      base.push({
        title: 'Swap With',
        dataIndex: 'peerUserId',
        key: 'peerUserId',
        width: 200,
        ellipsis: true,
        onCell: () => ({ style: rowCellPadding }),
        render: (peerId: string) =>
          peerId ? <EmpRender userId={peerId} /> : '-',
      });
      base.push({
        title: 'Shifts',
        key: 'shifts',
        width: 260,
        ellipsis: true,
        onCell: () => ({ style: rowCellPadding }),
        render: (unusedValue: unknown, row: any) => {
          void unusedValue;
          const from =
            row?.requesterShiftLabel || row?.requesterShiftId || null;
          const to =
            row?.targetShiftLabel ||
            row?.peerShiftLabel ||
            row?.targetShiftId ||
            null;
          if (!from && !to) {
            return (
              <span
                className={rowCellClass}
                data-cy="time-attendance-approval-table-cell-shifts"
              >
                -
              </span>
            );
          }
          return (
            <div
              className={`${rowCellClass} leading-snug`}
              data-cy="time-attendance-approval-table-cell-shifts"
            >
              <div data-cy="time-attendance-approval-table-cell-shifts-from">
                {from || '-'}
              </div>
              <div
                className="text-xs text-gray-500"
                data-cy="time-attendance-approval-table-cell-shifts-to"
              >
                ↔ {to || '-'}
              </div>
            </div>
          );
        },
      });
      base.push({
        title: 'Reason',
        dataIndex: 'reason',
        key: 'reason',
        width: 160,
        ellipsis: true,
        onCell: () => ({ style: rowCellPadding }),
        render: (reason: string) => (
          <span
            className={`${rowCellClass}`}
            data-cy="time-attendance-approval-table-cell-swap-reason"
          >
            {reason || '-'}
          </span>
        ),
      });
    }

    base.push(
      {
        title: 'Type',
        dataIndex: 'leaveType',
        key: 'leaveType',
        width: isShiftSwap ? 140 : 180,
        ellipsis: true,
        onCell: () => ({ style: rowCellPadding }),
      },
      {
        title: 'Start Date',
        dataIndex: 'startAt',
        key: 'startAt',
        width: 128,
        onCell: () => ({ style: rowCellPadding }),
        render: (val: string) => (
          <span
            className={`${rowCellClass} whitespace-nowrap`}
            data-cy="time-attendance-approval-table-cell-start-date"
          >
            {val ? dayjs(val).format(DATE_DISPLAY_FORMAT) : '-'}
          </span>
        ),
      },
      {
        title: 'End Date',
        dataIndex: 'endAt',
        key: 'endAt',
        width: 128,
        onCell: () => ({ style: rowCellPadding }),
        render: (val: string) => (
          <span
            className={`${rowCellClass} whitespace-nowrap`}
            data-cy="time-attendance-approval-table-cell-end-date"
          >
            {val ? dayjs(val).format(DATE_DISPLAY_FORMAT) : '-'}
          </span>
        ),
      },
      {
        title: 'Days',
        dataIndex: 'days',
        key: 'days',
        width: 72,
        onCell: () => ({ style: rowCellPadding }),
        render: (v: number) => (
          <span
            className={`${rowCellClass} whitespace-nowrap`}
            data-cy="time-attendance-approval-table-cell-days"
          >
            {v ?? '-'}
          </span>
        ),
      },
      {
        title: 'Action',
        dataIndex: 'action',
        key: 'action',
        width: 260,
        onCell: () => ({ style: rowCellPadding }),
      },
    );

    return base;
  }, [isShiftSwap, rowCellClass, userOptions]);

  const tableScrollX = isShiftSwap
    ? APPROVAL_TABLE_SCROLL_X_SHIFT_SWAP
    : APPROVAL_TABLE_SCROLL_X_LEAVE;

  const rowSelection = {
    selectedRowKeys,
    onChange: (keys: React.Key[]) => setSelectedRowKeys(keys),
  };
  const onPageChange = (page: number, pageSizeUnused?: number) => {
    void pageSizeUnused;
    setUserCurrentPage(page);
  };
  // Real total from API only (no heuristic) so "Page X of Y" shows the true count
  const meta = payload?.meta ?? approvalData?.meta;
  const totalFromApi =
    approvalData?.totalFromHeader ??
    meta?.totalItems ??
    meta?.total ??
    meta?.totalCount ??
    meta?.itemCount ??
    payload?.totalItems ??
    payload?.total ??
    payload?.totalCount ??
    payload?.totalElements ??
    payload?.totalRecords ??
    payload?.count ??
    payload?.result?.total ??
    payload?.data?.total ??
    approvalData?.totalItems ??
    approvalData?.total ??
    approvalData?.totalCount ??
    approvalData?.totalElements ??
    approvalData?.totalRecords ??
    (meta?.totalPages != null && meta.totalPages > 0
      ? meta.totalPages * pageSize
      : null);
  const totalItems = totalFromApi ?? 0;

  const onAllApproveRequest = () => {
    const body: AllLeaveRequestApproveData = {
      userId: userId,
      roleId: userRollId,
      limit: allPageSize,
      page: allUserCurrentPage,
    };

    allApprover(body, {
      onSuccess: (data) => {
        const transformData = data.items.map(
          ({ requestId }: { requestId: string }) => ({
            leaveRequestId: requestId,
            status: 'approved',
          }),
        );
        finalAllApproval(transformData);
        refetchLeave();
      },
    });
  };
  const onAllRejectRequest = () => {
    const body: AllLeaveRequestApproveData = {
      userId: userId,
      roleId: userRollId,
      limit: allPageSize,
      page: allUserCurrentPage,
    };

    allReject(body, {
      onSuccess: (data) => {
        const transformData = data.items.map(({ id }: { id: string }) => ({
          leaveRequestId: id,
          status: 'declined',
        }));
        finalAllApproval(transformData);
        refetchLeave();
      },
    });
  };
  return (
    <Card
      id="time-attendance-approval-table-card"
      data-cy="time-attendance-approval-table-card"
      className="border-gray-300"
      bodyStyle={{ padding: '0', paddingTop: 16 }}
    >
      <div
        className="mb-3 mx-3 flex flex-col gap-2 min-[400px]:flex-row min-[400px]:flex-wrap min-[400px]:items-center min-[400px]:justify-between min-[400px]:gap-2 sm:gap-3"
        id="time-attendance-approval-table-toolbar"
        data-cy="time-attendance-approval-table-toolbar"
      >
        <Select
          placeholder="Search Employee"
          showSearch
          allowClear
          options={userOptions}
          value={searchEmployee || undefined}
          onChange={(v) => setSearchEmployee(v ?? '')}
          filterOption={(input, option) =>
            (option?.label ?? '')
              .toString()
              .toLowerCase()
              .includes(input.toLowerCase())
          }
          className="h-8 w-full min-w-0 min-[400px]:min-w-[88px] min-[400px]:flex-1 min-[400px]:basis-0 md:flex-none md:basis-auto md:w-[280px] md:min-w-[280px] md:max-w-[280px] [&_.ant-select-selector]:!h-8 [&_.ant-select-selector]:!min-h-8 [&_.ant-select-selector]:!min-w-0"
          id="time-attendance-approval-table-search-employee"
          data-cy="time-attendance-approval-table-search-employee"
        />
        <div
          className="flex w-full min-w-0 flex-wrap items-center gap-2 min-[400px]:w-auto min-[400px]:shrink-0 min-[400px]:justify-end"
          data-cy="time-attendance-approval-table-toolbar-actions"
        >
          <div
            className="flex w-full min-w-0 flex-wrap gap-2 min-[400px]:w-auto"
            data-cy="time-attendance-approval-table-filter-approval-type-pills"
          >
            {approvalTypePills.map((pill) => {
              const isSelected = approvalTypeFilter === pill.id;
              return (
                <Button
                  key={pill.id}
                  type="default"
                  size="small"
                  data-cy={`time-attendance-approval-table-filter-approval-type-pill-${pill.id}`}
                  onClick={() => setApprovalTypeFilter(pill.id)}
                  className={
                    isSelected
                      ? '!rounded-lg !h-7 !min-h-0 !px-2 !py-0 !leading-none border-[#1d4ed8] text-[#1d4ed8] !bg-white hover:!bg-[#FAFAFA] hover:!border-[#1d4ed8] hover:!text-[#1d4ed8]'
                      : '!rounded-lg !h-7 !min-h-0 !px-2 !py-0 !leading-none border-gray-200 text-gray-700 !bg-white hover:!bg-gray-50 hover:!border-gray-300 hover:!text-gray-800'
                  }
                >
                  {pill.label}
                </Button>
              );
            })}
          </div>
          {!isWorkFromHome && !isShiftSwap && selectedRowKeys.length > 0 && (
            <>
              <Popconfirm
                title="All Reject Request"
                description="Are you sure to reject all leave request?"
                onConfirm={() => {
                  onAllRejectRequest();
                }}
                onCancel={cancel}
                okText="Reject All"
                cancelText="Cancel"
                data-cy="time-attendance-approval-table-reject-all-popconfirm"
              >
                <Button
                  disabled={
                    isApprovalListLoading ||
                    isLoadingEditApprover ||
                    allApproveIsLoading ||
                    allRejectIsLoading
                  }
                  danger
                  id="time-attendance-approval-table-reject-all-button"
                  data-cy="time-attendance-approval-table-reject-all-button"
                >
                  <Skeleton
                    active
                    loading={allRejectIsLoading}
                    data-cy="time-attendance-approval-table-reject-all-spin"
                  />
                  Reject All
                </Button>
              </Popconfirm>
              <Popconfirm
                title="All Approve Request"
                description="Are you sure to approve all leave request?"
                onConfirm={() => {
                  onAllApproveRequest();
                }}
                onCancel={cancel}
                okText="Approve All"
                cancelText="Cancel"
                data-cy="time-attendance-approval-table-approve-all-popconfirm"
              >
                <Button
                  disabled={
                    isApprovalListLoading ||
                    isLoadingEditApprover ||
                    allApproveIsLoading ||
                    allRejectIsLoading
                  }
                  type="primary"
                  id="time-attendance-approval-table-approve-all-button"
                  data-cy="time-attendance-approval-table-approve-all-button"
                >
                  <Skeleton
                    active
                    data-cy="time-attendance-approval-table-approve-all-spin"
                    loading={allApproveIsLoading}
                  />
                  Approve All
                </Button>
              </Popconfirm>
            </>
          )}
          <Select
            placeholder="Filter by status"
            allowClear
            options={statusFilterOptions}
            value={filterStatus || undefined}
            onChange={(v) => setFilterStatus(v ?? '')}
            className="h-8 w-full min-w-0 min-[400px]:w-[136px] min-[400px]:min-w-[120px] min-[400px]:shrink-0 sm:min-w-[160px] sm:w-[160px] [&_.ant-select-selector]:!h-8 [&_.ant-select-selector]:!min-h-8 [&_.ant-select-selector]:!min-w-0"
            id="time-attendance-approval-table-filter-status"
            data-cy="time-attendance-approval-table-filter-status"
          />
        </div>
      </div>
      {isApprovalListLoading ? (
        <TableSkeleton columns={columns} />
      ) : (
        <Table
          rowSelection={
            !isWorkFromHome && !isShiftSwap ? rowSelection : undefined
          }
          columns={columns}
          dataSource={allFilterData}
          pagination={false}
          // Single horizontal scroll: only Ant Design’s table body (no outer overflow-x wrapper).
          scroll={{ x: tableScrollX }}
          locale={{
            emptyText: isWorkFromHome
              ? 'No work from home approvals'
              : isShiftSwap
                ? 'No shift swap approvals'
                : 'No leave requests',
          }}
          className="mx-3 [&_.ant-table-thead>tr>th]:bg-[#FAFAFA] [&_.ant-table-thead>tr>th]:text-gray-800 [&_.ant-table-thead>tr>th]:text-base [&_.ant-table-thead>tr>th]:font-semibold [&_.ant-table-thead>tr>th]:before:!bg-transparent [&_tr.my-timesheet-approval-table-row-even>td]:!bg-[#FAFAFA] [&_tr.my-timesheet-approval-table-row-odd>td]:!bg-white"
          rowClassName={(record, index) => {
            void record;
            return index % 2 === 1
              ? 'my-timesheet-approval-table-row-even'
              : 'my-timesheet-approval-table-row-odd';
          }}
          id="time-attendance-approval-table"
          data-cy="time-attendance-approval-table"
        />
      )}
      <div
        className="mx-3"
        data-cy="time-attendance-approval-table-pagination-wrapper"
      >
        <CustomPagination
          current={userCurrentPage}
          total={totalItems}
          pageSize={pageSize}
          onChange={onPageChange}
          onShowSizeChange={(newPageSize) => {
            setPageSize(newPageSize);
            setUserCurrentPage(1);
          }}
          id="time-attendance-approval-table-pagination"
          data-cy="time-attendance-approval-table-pagination"
        />
      </div>
    </Card>
  );
};

export default ApprovalTable;

import React, { useEffect } from 'react';
import { Button, Dropdown, message, Space, Table, Tag } from 'antd';
import { AiOutlineReload } from 'react-icons/ai';
import { GoLocation } from 'react-icons/go';
import dayjs from 'dayjs';
import { DATE_FORMAT } from '@/utils/constants';
import { useIsMobile } from '@/hooks/useIsMobile';
import CustomPagination from '@/components/customPagination';
import { CustomMobilePagination } from '@/components/customPagination/mobilePagination';
import { TableSkeleton } from '@/components/tableSkeleton';

// Types
import { TableColumnsType } from '@/types/table/table';
import { CommonObject } from '@/types/commons/commonObject';
import { AttendanceRecord } from '@/types/timesheet/attendance';

// Components
import AttendanceTableFilter from './tableFilter/index';
import StatusBadge from '@/components/common/statusBadge/statusBadge';

// Store
import { useMyTimesheetStore } from '@/store/uistate/features/timesheet/myTimesheet';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import { useGetAttendances } from '@/store/server/features/timesheet/attendance/queries';
import { AttendanceRequestBody } from '@/store/server/features/timesheet/attendance/interface';
// Utils
import { formatToAttendanceStatuses } from '@/helpers/formatTo';
import {
  AttendanceRecordType,
  AttendanceRecordTypeBadgeTheme,
} from '@/types/timesheet/attendance';
import {
  calculateAttendanceRecordToTotalWorkTime,
  calculateAttendanceRecordToTotalBreakTimeMs,
  timeToHour,
  timeToLastMinute,
} from '@/helpers/calculateHelper';
import { usePathname } from 'next/navigation';
import usePagination from '@/utils/usePagination';
import type { MenuProps } from 'antd';
import { UseExportAttendanceData } from '@/store/server/features/timesheet/attendance/queries';
import { PiExportLight } from 'react-icons/pi';
import { formatAttendanceWallClockTimeOrDash } from '@/helpers/attendanceTimeHelper';

export type AttendanceTableVariant = 'default' | 'myTimesheet';

const ATTENDANCE_STATUS_TAG_COLOR: Record<AttendanceRecordType, string> = {
  [AttendanceRecordType.PRESENT]: 'blue',
  [AttendanceRecordType.LATE]: 'warning',
  [AttendanceRecordType.EARLY]: 'warning',
  [AttendanceRecordType.ABSENT]: 'error',
  [AttendanceRecordType.clockedOut]: 'warning',
};

interface AttendanceTableProps {
  variant?: AttendanceTableVariant;
}

const AttendanceTable = ({ variant = 'default' }: AttendanceTableProps) => {
  // Store hooks
  const { userId } = useAuthenticationStore();

  const { orderBy, orderDirection, setOrderBy, setOrderDirection } =
    usePagination(1, 10);

  const {
    filter,
    setFilter,
    currentPage,
    pageSize,
    setCurrentPage,
    setPageSize,
    resetPagination,
  } = useMyTimesheetStore();

  const pathname = usePathname();

  useEffect(() => {
    resetPagination();
  }, [pathname]);

  const onPageChange = (page: number) => {
    setCurrentPage(page);
  };

  const userFilter: Partial<AttendanceRequestBody['filter']> = {
    userIds: [userId ?? ''],
  };

  // API call
  const { data, isFetching, refetch } = useGetAttendances(
    { page: currentPage, limit: pageSize, orderBy, orderDirection },

    { filter: { ...userFilter, ...filter } },
  );
  const { isMobile, isTablet } = useIsMobile();

  const safeAttendancePageSize = pageSize > 0 ? pageSize : 1;
  const attendanceMetaTotalPages = data?.meta?.totalPages;
  const attendanceResolvedTotalPages = Math.max(
    1,
    typeof attendanceMetaTotalPages === 'number' &&
      !Number.isNaN(attendanceMetaTotalPages) &&
      attendanceMetaTotalPages >= 1
      ? attendanceMetaTotalPages
      : Math.ceil((data?.meta?.totalItems ?? 0) / safeAttendancePageSize),
  );
  const attendanceWrapPaginationManyPages = attendanceResolvedTotalPages > 3;
  const { mutate: exportAttendanceData } = UseExportAttendanceData();

  const handleExport = (exportType: 'PDF' | 'EXCEL') => {
    exportAttendanceData(
      {
        exportType,
        filter: { ...userFilter, ...filter },
      },
      {
        onSuccess: () => {
          message.success('Download completed successfully!');
        },
        onError: () => {
          message.error('Failed to export. Please try again.');
        },
      },
    );
  };

  const exportMenuItems: MenuProps['items'] = [
    { key: 'pdf', label: 'Export as PDF', onClick: () => handleExport('PDF') },
    {
      key: 'excel',
      label: 'Export as Excel',
      onClick: () => handleExport('EXCEL'),
    },
  ];

  // Table columns (default: full set including Location, Over-time)
  const defaultColumns: TableColumnsType<AttendanceRecord> = [
    {
      title: 'Date',
      dataIndex: 'createdAt',
      key: 'createdAt',
      sorter: true,
      render: (date: string) => (
        <div
          id="time-attendance-attendance-table-row-date-div"
          data-cy="time-attendance-attendance-table-row-date-div"
          className="text-sm text-black py-2 whitespace-nowrap"
        >
          {dayjs(date).format(DATE_FORMAT)}
        </div>
      ),
    },
    {
      title: 'Clock In',
      dataIndex: 'startAt',
      key: 'startAt',
      render: (date: string) => (
        <div
          id="time-attendance-attendance-table-row-clock-in-div"
          data-cy="time-attendance-attendance-table-row-clock-in-div"
          className="text-sm text-black py-2"
        >
          {formatAttendanceWallClockTimeOrDash(date)}
        </div>
      ),
    },
    {
      title: 'Location-in',
      dataIndex: 'geolocations',
      key: 'locationIn',
      render: (geolocations: any[]) => (
        <div
          id="time-attendance-attendance-table-row-location-in-div"
          data-cy="time-attendance-attendance-table-row-location-in-div"
          className="text-sm text-black py-2 flex items-center justify-between"
        >
          {geolocations?.[0]?.allowedArea?.title ?? ''} <GoLocation />
        </div>
      ),
    },
    {
      title: 'Clock Out',
      dataIndex: 'endAt',
      key: 'endAt',
      render: (date: string) => (
        <div
          id="time-attendance-attendance-table-row-clock-out-div"
          data-cy="time-attendance-attendance-table-row-clock-out-div"
          className="text-sm text-black py-2"
        >
          {formatAttendanceWallClockTimeOrDash(date)}
        </div>
      ),
    },
    {
      title: 'Location-Out',
      dataIndex: 'geolocations',
      key: 'locationOut',
      render: (geolocations: any[]) => (
        <div
          id="time-attendance-attendance-table-row-location-out-div"
          data-cy="time-attendance-attendance-table-row-location-out-div"
          className="text-sm text-black py-2 flex items-center justify-between"
        >
          {geolocations?.[geolocations.length - 1]?.allowedArea?.title ?? ''}{' '}
          <GoLocation data-cy="time-attendance-attendance-table-row-location-out-icon" />
        </div>
      ),
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (item: AttendanceRecord) => {
        const statuses = formatToAttendanceStatuses(item);
        return (
          <div
            id="time-attendance-attendance-table-row-status-container"
            data-cy="time-attendance-attendance-table-row-status-container"
            className="py-2"
          >
            <Space
              id="time-attendance-attendance-table-row-status-space"
              data-cy="time-attendance-attendance-table-row-status-space"
            >
              {statuses.map((status) => (
                <StatusBadge
                  theme={AttendanceRecordTypeBadgeTheme[status.status]}
                  key={status.status}
                  data-cy={`time-attendance-attendance-table-row-status-badge-${status.status}`}
                >
                  <div
                    id={`time-attendance-attendance-table-row-status-badge-div-${status.status}`}
                    data-cy={`time-attendance-attendance-table-row-status-badge-div-${status.status}`}
                    className="text-center"
                  >
                    <div
                      id={`time-attendance-attendance-table-row-status-badge-status-div-${status.status}`}
                      data-cy={`time-attendance-attendance-table-row-status-badge-status-div-${status.status}`}
                    >
                      {status.status}
                    </div>
                    {status.text && (
                      <div
                        id={`time-attendance-attendance-table-row-status-badge-text-div-${status.status}`}
                        data-cy={`time-attendance-attendance-table-row-status-badge-text-div-${status.status}`}
                        className="font-normal"
                      >
                        {status.text}
                      </div>
                    )}
                  </div>
                </StatusBadge>
              ))}
            </Space>
          </div>
        );
      },
    },
    {
      title: 'Total time',
      dataIndex: 'totalTime',
      key: 'totalTime',
      render: (text, record) => {
        const calcTotal = calculateAttendanceRecordToTotalWorkTime(record);
        return (
          <div
            id="time-attendance-attendance-table-row-total-time-div"
            data-cy="time-attendance-attendance-table-row-total-time-div"
            className="text-sm text-black py-2"
          >
            {record.startAt && record.endAt
              ? `${timeToHour(calcTotal)}:${timeToLastMinute(calcTotal)} hrs`
              : '-'}
          </div>
        );
      },
    },
    {
      title: 'Over-time',
      dataIndex: 'overTimeMinutes',
      key: 'overTime',
      render: (minutes: number) => (
        <div
          id="time-attendance-attendance-table-row-over-time-div"
          data-cy="time-attendance-attendance-table-row-over-time-div"
          className="text-sm text-black py-2"
        >
          {minutes} min
        </div>
      ),
    },
  ];

  // My Timesheet variant: Date, Check In, Check Out, Total Hours, Total Break, Status, Action (no Location, no Over-time)
  const myTimesheetColumns: TableColumnsType<AttendanceRecord> = [
    {
      title: 'Date',
      dataIndex: 'createdAt',
      key: 'createdAt',
      sorter: true,
      render: (date: string) => (
        <div
          className="text-sm text-black py-2 whitespace-nowrap"
          data-cy="time-attendance-attendance-table-row-date-div"
        >
          {dayjs(date).format(DATE_FORMAT)}
        </div>
      ),
    },
    {
      title: 'Check In',
      dataIndex: 'startAt',
      key: 'startAt',
      render: (date: string) => (
        <div
          className="text-sm text-black py-2"
          data-cy="time-attendance-attendance-table-row-clock-in-div"
        >
          {formatAttendanceWallClockTimeOrDash(date)}
        </div>
      ),
    },
    {
      title: 'Check Out',
      dataIndex: 'endAt',
      key: 'endAt',
      render: (date: string) => (
        <div
          className="text-sm text-black py-2"
          data-cy="time-attendance-attendance-table-row-clock-out-div"
        >
          {formatAttendanceWallClockTimeOrDash(date)}
        </div>
      ),
    },
    {
      title: 'Total Hours',
      dataIndex: 'totalTime',
      key: 'totalTime',
      render: (unused: unknown, record: AttendanceRecord) => {
        void unused;
        const calcTotal = calculateAttendanceRecordToTotalWorkTime(record);
        return (
          <div
            className="text-sm text-black py-2"
            data-cy="time-attendance-attendance-table-row-total-time-div"
          >
            {record.startAt && record.endAt
              ? `${timeToHour(calcTotal)}:${timeToLastMinute(calcTotal)}`
              : '-'}
          </div>
        );
      },
    },
    {
      title: 'Total Break',
      key: 'totalBreak',
      render: (unused: unknown, record: AttendanceRecord) => {
        void unused;
        const breakMs = calculateAttendanceRecordToTotalBreakTimeMs(record);
        return (
          <div
            className="text-sm text-black py-2"
            data-cy="time-attendance-attendance-table-row-total-break-div"
          >
            {breakMs > 0
              ? `${timeToHour(breakMs)}:${timeToLastMinute(breakMs)}`
              : '-'}
          </div>
        );
      },
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (unused: unknown, record: AttendanceRecord) => {
        void unused;
        const statuses = formatToAttendanceStatuses(record);
        return (
          <div
            className="py-2"
            data-cy="time-attendance-attendance-table-row-status-container"
          >
            <Space
              wrap
              data-cy="time-attendance-attendance-table-row-status-space"
            >
              {statuses.map((status) => (
                <Tag
                  color={ATTENDANCE_STATUS_TAG_COLOR[status.status]}
                  key={status.status}
                  data-cy={`time-attendance-attendance-table-row-status-badge-${status.status}`}
                >
                  {status.status}
                  {status.text ? ` ${status.text}` : ''}
                </Tag>
              ))}
            </Space>
          </div>
        );
      },
    },
  ];

  const columns =
    variant === 'myTimesheet' ? myTimesheetColumns : defaultColumns;

  const onFilterChange = (val: CommonObject) => {
    const nFilter: Partial<AttendanceRequestBody['filter']> = { ...userFilter };

    const dateRange = val.date as [string, string] | null | undefined;
    if (dateRange?.[0] && dateRange?.[1]) {
      nFilter['date'] = {
        from: dateRange[0],
        to: dateRange[1],
      };
    }

    if (val.location) {
      nFilter['locations'] = [val.location];
    }

    if (val.type) {
      nFilter['type'] = val.type;
    }

    setFilter(nFilter);
  };

  const handleTableChange = (pagination: any, sorter: any) => {
    setCurrentPage(pagination.current ?? 1);
    setPageSize(pagination.pageSize ?? 10);
    setOrderDirection(sorter['order']);
    setOrderBy(sorter['order'] ? sorter['columnKey'] : undefined);
  };

  return (
    <div
      className="bg-white border border-gray-300 rounded-md"
      id="time-attendance-attendance-table-container"
      data-cy="time-attendance-attendance-table-container"
    >
      <div
        className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"
        id="time-attendance-attendance-table-header-container"
        data-cy="time-attendance-attendance-table-header-container"
      >
        <div
          className="flex items-center gap-0.5"
          id="time-attendance-attendance-table-title-container"
          data-cy="time-attendance-attendance-table-title-container"
        >
          {variant === 'default' && (
            <>
              <div
                className="text-sm sm:text-2xl font-bold text-gray-900"
                id="time-attendance-attendance-table-title"
                data-cy="time-attendance-attendance-table-title"
              >
                Attendance
              </div>
              <Button
                type="text"
                size="small"
                icon={<AiOutlineReload size={14} className="text-gray-600" />}
                onClick={() => refetch()}
                id="time-attendance-attendance-table-refresh-button"
                data-cy="time-attendance-attendance-table-refresh-button"
              />
            </>
          )}
        </div>
        {/* Mobile: full-width inline filters (stacked); see tableFilter */}
        <div
          className="w-full sm:hidden"
          id="time-attendance-attendance-table-mobile-filter-container"
          data-cy="time-attendance-attendance-table-mobile-filter-container"
        >
          <AttendanceTableFilter
            onChange={onFilterChange}
            data-cy="time-attendance-attendance-table-mobile-filter"
          />
        </div>
      </div>

      {/* Desktop Filter — px matches card inset so Export is not flush to the border */}
      <div
        className="hidden sm:block px-3 pb-2 sm:px-4 lg:px-5"
        id="time-attendance-attendance-table-desktop-filter-container"
        data-cy="time-attendance-attendance-table-desktop-filter-container"
      >
        <div
          className="flex w-full min-w-0 flex-nowrap items-center justify-between gap-8 lg:gap-12"
          data-cy="time-attendance-attendance-table-desktop-filter-row"
        >
          <div
            className="min-w-0 shrink"
            data-cy="time-attendance-attendance-table-desktop-filter-filters"
          >
            <AttendanceTableFilter
              onChange={onFilterChange}
              data-cy="time-attendance-attendance-table-desktop-filter"
            />
          </div>
          {variant === 'myTimesheet' && (
            <div
              className="shrink-0 pl-4"
              data-cy="time-attendance-attendance-table-desktop-export-wrap"
            >
              <Dropdown
                menu={{ items: exportMenuItems }}
                trigger={['click']}
                placement="bottomRight"
              >
                <Button
                  type="primary"
                  ghost={true}
                  icon={<PiExportLight size={16} />}
                  data-cy="my-timesheet-attendance-export-button"
                  id="my-timesheet-attendance-export-button"
                  className="h-8 border-gray-300 px-3 text-gray-500 font-medium hover:text-primary hover:border-primary"
                >
                  Export
                </Button>
              </Dropdown>
            </div>
          )}
        </div>
      </div>

      <div
        id="time-attendance-attendance-table-content"
        data-cy="time-attendance-attendance-table-content"
      >
        {isFetching ? (
          <TableSkeleton columns={columns} />
        ) : (
          <Table<AttendanceRecord>
            className="mt-3 [&_.ant-table-thead>tr>th]:whitespace-nowrap [&_.ant-table-tbody>tr>td]:whitespace-nowrap [&_.ant-table-thead>tr>th]:bg-[#FAFAFA] [&_.ant-table-thead>tr>th]:text-gray-800 [&_.ant-table-thead>tr>th]:text-base [&_.ant-table-thead>tr>th]:font-semibold [&_.ant-table-thead>tr>th]:before:!bg-transparent [&_tr.time-attendance-table-row-even>td]:!bg-[#FAFAFA] [&_tr.time-attendance-table-row-odd>td]:!bg-white"
            columns={columns}
            dataSource={data?.items}
            pagination={false}
            onChange={handleTableChange}
            scroll={{ x: 'min-content' }}
            id="time-attendance-attendance-table"
            data-cy="time-attendance-attendance-table"
            rowClassName={(record, index) => {
              void record;
              return index % 2 === 1
                ? 'time-attendance-table-row-even'
                : 'time-attendance-table-row-odd';
            }}
          />
        )}
        <div
          className={`mx-1 ${isMobile || isTablet ? 'mt-6' : ''}`}
          data-cy="time-attendance-attendance-table-pagination-wrapper"
        >
          {isMobile || isTablet ? (
            <CustomMobilePagination
              currentPage={currentPage}
              totalResults={data?.meta?.totalItems ?? 0}
              totalPages={data?.meta?.totalPages}
              pageSize={pageSize}
              stackPagerAndGoTo={attendanceWrapPaginationManyPages}
              onChange={(newPage) => onPageChange(newPage)}
              onShowSizeChange={onPageChange}
              data-cy="time-attendance-attendance-table-mobile-pagination"
            />
          ) : variant === 'myTimesheet' ? (
            <CustomPagination
              current={currentPage}
              total={data?.meta?.totalItems ?? 0}
              totalPages={data?.meta?.totalPages}
              pageSize={pageSize}
              wrapMainRow={attendanceWrapPaginationManyPages}
              onChange={onPageChange}
              onShowSizeChange={(size: number) => {
                setPageSize(size);
                setCurrentPage(1);
              }}
              data-cy="time-attendance-attendance-table-pagination"
            />
          ) : (
            <CustomPagination
              current={currentPage}
              total={data?.meta?.totalItems ?? 0}
              totalPages={data?.meta?.totalPages}
              pageSize={pageSize}
              wrapMainRow={attendanceWrapPaginationManyPages}
              onChange={onPageChange}
              onShowSizeChange={(size: number) => {
                setPageSize(size);
                setCurrentPage(1);
              }}
              data-cy="time-attendance-attendance-table-pagination"
            />
          )}
        </div>
      </div>

      {/* View Attendance Sidebar */}

      {/* <Drawer
        title="Filter"
        placement="bottom"
        onClose={() => setIsShowViewSidebar(false)}
        open={isShowViewSidebar}
        height="auto"
        className="rounded-t-2xl"
        maskClosable={true}
        destroyOnHidden
      >
        <div className="p-4">
          <AttendanceTableFilter onChange={onFilterChange} />
        </div>
      </Drawer> */}
    </div>
  );
};

