        <Space
          size={32}
          id="time-attendance-check-controls-breaking-container"
          data-cy="time-attendance-check-controls-breaking-container"
        >
          {workTime && (
            <div
              className="text-[28px] text-primary font-bold"
              id="time-attendance-check-controls-work-time"
              data-cy="time-attendance-check-controls-work-time"
            >
              {workTime} hrs
            </div>
          )}
          <AccessGuard
            data-cy="time-attendance-check-controls-break-check-in-button-access-guard"
            permissions={[Permissions.CheckInRemotely]}
          >
            <RemoteAttendanceActionButton action={{ isSignIn: true }}>
              <Button
                className="h-14 text-base"
                size="large"
                id="time-attendance-check-controls-break-check-in-button"
                data-cy="time-attendance-check-controls-break-check-in-button"
                icon={
                  <CiLogin
                    data-cy="time-attendance-check-controls-break-check-in-button-icon"
                    size={30}
                  />
                }
                loading={loading}
              >
                {isMobile ? '' : 'Check in'}
              </Button>
            </RemoteAttendanceActionButton>
          </AccessGuard>
        </Space>
      );
    case CheckStatus.finished:
      return '';
  }
};

export default CheckControl;

import CustomDrawerLayout from '@/components/common/customDrawer';
import { useMyTimesheetStore } from '@/store/uistate/features/timesheet/myTimesheet';
import { Form, Select } from 'antd';
import type { SelectProps } from 'antd';
import React, { useEffect, useState } from 'react';
import CustomLabel from '@/components/form/customLabel/customLabel';
import CustomDrawerFooterButton, {
  CustomDrawerFooterButtonProps,
} from '@/components/common/customDrawer/customDrawerFooterButton';
import CustomDrawerHeader from '@/components/common/customDrawer/customDrawerHeader';
import { BreakTypeStatus, formatBreakTypeToStatus } from '@/helpers/formatTo';
import StatusBadge from '@/components/common/statusBadge/statusBadge';
import { useSetCurrentAttendance } from '@/store/server/features/timesheet/attendance/mutation';
import NotificationMessage from '@/components/common/notification/notificationMessage';
import { MdKeyboardArrowDown } from 'react-icons/md';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import { useRemoteAttendanceCameraStore } from '@/store/uistate/features/timesheet/remoteAttendanceCamera';

type LabelRender = SelectProps['labelRender'];

interface CustomSelectOption extends BreakTypeStatus {
  label: string;
  value: string;
}

const CheckOutSidebar = () => {
  const [options, setOptions] = useState<CustomSelectOption[]>([]);
  const [selectedType, setSelectedType] = useState<string | null>(null);
  const {
    isShowCheckOutSidebar,
    setIsShowCheckOutSidebar,
    breakTypes,
    currentAttendance,
  } = useMyTimesheetStore();
  const { userId } = useAuthenticationStore();
  const { mutate: setCurrentAttendance, isSuccess } = useSetCurrentAttendance();
  const { capturedAttendancePhotoUrl, setCapturedAttendancePhotoUrl } =
    useRemoteAttendanceCameraStore();

  const [form] = Form.useForm();

  useEffect(() => {
    const nOptions: CustomSelectOption[] = breakTypes.map((item) => {
      return {
        label: item.title,
        value: item.id ?? '',
        ...formatBreakTypeToStatus(item, currentAttendance),
      };
    });

    setOptions(nOptions);
  }, [breakTypes, currentAttendance]);

  const footerModalItems: CustomDrawerFooterButtonProps[] = [
    {
      label: 'Cancel',
      key: 'cancel',
      className: 'h-[40px] sm:h-[56px] text-base px-10',
      size: 'large',
      onClick: () => setIsShowCheckOutSidebar(false),
      id: 'time-attendance-check-out-sidebar-cancel-button',
      'data-cy': 'time-attendance-check-out-sidebar-cancel-button',
    },
    {
      label: 'Check-out',
      key: 'checkOut',
      className: 'h-[40px] sm:h-[56px] text-base px-10',
      size: 'large',
      type: 'primary',
      onClick: () => form.submit(),
      id: 'time-attendance-check-out-sidebar-check-out-button',
      'data-cy': 'time-attendance-check-out-sidebar-check-out-button',
    },
  ];

  const itemClass = 'font-semibold text-xs';
  const controlClass = 'mt-2.5 h-[40px] sm:h-[51px] w-full';

  const selectLabel: LabelRender = (props) => {
    const { value } = props;
    const option = options.find((item) => item.value === value);
    return option ? (
      <div
        data-cy="my-timesheet-components-checkoutsidebar-index-tsx-index-div-81"
        className="font-bold text-gray-900"
      >
        {option.label}
      </div>
    ) : (
      ''
    );
  };
  useEffect(() => {
    if (isSuccess) {
      form.resetFields();
      setIsShowCheckOutSidebar(false);
      setCapturedAttendancePhotoUrl(null);
    }
  }, [isSuccess, setCapturedAttendancePhotoUrl]);

  const onFinish = () => {
    const photo = capturedAttendancePhotoUrl;
    if (!photo) {
      NotificationMessage.error({
        message: 'Photo required',
        description:
          'Please capture your attendance photo before checking out.',
      });
      return;
    }

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const value = form.getFieldsValue();
          setCurrentAttendance({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
            userId: userId,
            isSignIn: false,
            breakTypeId: value.type,
            file: photo,
          });
        },
        () => {
          NotificationMessage.error({
            message: `No access to geolocation`,
            description: `To check-in/check-out we need to have access to geolocation.`,
          });
        },
      );
    } else {
      NotificationMessage.error({
        message: `No access to geolocation`,
        description: `To check-in/check-out we need to have access to geolocation.`,
      });
    }
  };

  return (
    isShowCheckOutSidebar && (
      <CustomDrawerLayout
        open={isShowCheckOutSidebar}
        onClose={() => {
          setIsShowCheckOutSidebar(false);
          setCapturedAttendancePhotoUrl(null);
        }}
        modalHeader={
          <CustomDrawerHeader
            className="px-3"
            data-cy="time-attendance-check-out-sidebar-header"
          >
            Check-out
          </CustomDrawerHeader>
        }
        footer={
          <CustomDrawerFooterButton
            className="w-full bg-[#fff] flex justify-center p-4"
            buttons={footerModalItems}
          />
        }
        width="400px"
        data-cy="time-attendance-check-out-sidebar"
      >
        <Form
          layout="vertical"
          form={form}
          requiredMark={CustomLabel}
          onFinish={onFinish}
          autoComplete="off"
          className="px-3"
          id="time-attendance-check-out-sidebar-form"
          data-cy="time-attendance-check-out-sidebar-form"
        >
          <Form.Item
            name="type"
            label="Checkin type"
            id="time-attendance-check-out-sidebar-type-select"
            data-cy="time-attendance-check-out-sidebar-type-select"
            rules={[{ required: true, message: 'Required' }]}
            className={itemClass}
          >
            <Select
              className={controlClass}
              value={selectedType}
              labelRender={selectLabel}
              suffixIcon={
                <MdKeyboardArrowDown
                  data-cy="time-attendance-check-out-sidebar-type-select-input-icon"
                  size={16}
                  className="text-gray-900"
                />
              }
              onChange={setSelectedType}
              id="time-attendance-check-out-sidebar-type-select-input"
              data-cy="time-attendance-check-out-sidebar-type-select-input"
            >
              {options.map((option, key) => (
                <Select.Option
                  id={`time-attendance-check-out-sidebar-type-option-${key}`}
                  data-cy={`time-attendance-check-out-sidebar-type-option-${key}`}
                  value={option.value}
                  key={option.value}
                  disabled={option.disabled}
                >
                  <div
                    className="p-4 pr-1.5 flex items-center justify-between"
                    id={`time-attendance-check-out-sidebar-type-option-${key}-container`}
                    data-cy={`time-attendance-check-out-sidebar-type-option-${key}-container`}
                  >
                    <div
                      className="flex items-center gap-2"
                      id={`time-attendance-check-out-sidebar-type-option-${key}-label-container`}
                      data-cy={`time-attendance-check-out-sidebar-type-option-${key}-label-container`}
                    >
                      {selectedType === option.value ? (
                        <div
                          className="w-6 h-6 rounded-full border-[7px] border-primary"
                          id={`time-attendance-check-out-sidebar-type-option-${key}-selected-indicator`}
                          data-cy={`time-attendance-check-out-sidebar-type-option-${key}-selected-indicator`}
                        ></div>
                      ) : (
                        <div
                          className="w-6 h-6 rounded-full bg-gray-200 border"
                          id={`time-attendance-check-out-sidebar-type-option-${key}-unselected-indicator`}
                          data-cy={`time-attendance-check-out-sidebar-type-option-${key}-unselected-indicator`}
                        ></div>
                      )}
                      <span
                        className="text-sm font-bold text-gray-900"
                        id={`time-attendance-check-out-sidebar-type-option-${key}-label`}
                        data-cy={`time-attendance-check-out-sidebar-type-option-${key}-label`}
                      >
                        {option.label}
                      </span>
                    </div>
                    <StatusBadge
                      theme={option.status.theme}
                      transparentBg={true}
                      className="p-0"
                      data-cy={`time-attendance-check-out-sidebar-type-option-${key}-status-badge`}
                    >
                      {option.status.text}
                    </StatusBadge>
                  </div>
                </Select.Option>
              ))}
            </Select>
          </Form.Item>
        </Form>
      </CustomDrawerLayout>
    )
  );
};

export default CheckOutSidebar;

import React, { useEffect, useState } from 'react';
import HistoryTableFilter from './tableFilter';
import { TableColumnsType } from '@/types/table/table';
import { Button, Dropdown, Modal, Table, Tag } from 'antd';
import type { MenuProps } from 'antd';
import {
  useGetLeaveRequest,
  useGetSingleApproval,
} from '@/store/server/features/timesheet/leaveRequest/queries';
import { LeaveRequestBody } from '@/store/server/features/timesheet/leaveRequest/interface';
import { CommonObject } from '@/types/commons/commonObject';
import { LeaveRequest, LeaveRequestStatus } from '@/types/timesheet/settings';
import dayjs, { type Dayjs } from 'dayjs';
import { useMyTimesheetStore } from '@/store/uistate/features/timesheet/myTimesheet';
import usePagination from '@/utils/usePagination';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import AccessGuard from '@/utils/permissionGuard';
import { Permissions } from '@/types/commons/permissionEnum';
import { FaPlus } from 'react-icons/fa';
import CustomPagination from '@/components/customPagination';
import { CustomMobilePagination } from '@/components/customPagination/mobilePagination';
import { useIsMobile } from '@/hooks/useIsMobile';
import { TableSkeleton } from '@/components/tableSkeleton';
import { useDeleteLeaveRequest } from '@/store/server/features/timesheet/leaveRequest/mutation';
import { DeleteOutlined, EditOutlined } from '@ant-design/icons';
import { HiOutlineDotsHorizontal } from 'react-icons/hi';

const dotsButtonStyle: React.CSSProperties = {
  height: 24,
  width: 24,
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  borderRadius: 4,
  border: '1px solid #D9D9D9',
  background: '#fff',
};

const HistoryTable = () => {
  const { isMobile, isTablet } = useIsMobile();
  const { userId } = useAuthenticationStore();
  const userFilter: Partial<LeaveRequestBody['filter']> = {
    userIds: [userId ?? ''],
  };
  const {
    setIsShowLeaveRequestDetail: isShowDetail,
    setIsShowLeaveRequestSidebar: isShow,
    setLeaveRequestSidebarWorkflowData,
    leaveRequestSidebarData,
    setLeaveRequestSidebarData,
    isLoading,
    setIsLoading,
  } = useMyTimesheetStore();
  const { mutate: deleteLeaveRequest } = useDeleteLeaveRequest();
  const [tableData, setTableData] = useState<any[]>([]);
  const { page, limit, orderBy, orderDirection, setPage, setLimit } =
    usePagination(1, 5);
  const [filter, setFilter] =
    useState<Partial<LeaveRequestBody['filter']>>(userFilter);
  const { data, isFetching } = useGetLeaveRequest(
    { page, limit, orderBy, orderDirection },
    { filter },
  );
  const { data: approverLog } = useGetSingleApproval(
    leaveRequestSidebarData ?? '',
  );
  useEffect(() => {
    if (isLoading && approverLog) {
      // Allow editing while request status is still pending (even if approvals started).
      // Non-pending requests are blocked inside the leave request sidebar itself.
      isShow(true);
      setIsLoading(false);
    }
  }, [approverLog, isLoading, leaveRequestSidebarData]);
  const DATE_DISPLAY_FORMAT = 'MMM D, YYYY';

  useEffect(() => {
    if (data && data.items) {
      setTableData(() =>
        data.items.map((item) => ({
          key: item.id,
          startAt: item.startAt,
          endAt: item.endAt,
          days: item.days,
          createdAt: item?.createdAt
            ? dayjs(item?.createdAt).format('YYYY-MM-DD')
            : '-',
          leaveType: item.leaveType
            ? typeof item.leaveType === 'string'
              ? ''
              : item.leaveType.title
            : '-',
          reason: item.justificationNote ?? '-',
          justificationDocument: item.justificationDocument,
          status: item.status,
          action: item,
        })),
      );
    }
  }, [data]);

  const statusTagConfig: Record<
    LeaveRequestStatus,
    { color: string; label: string }
  > = {
    [LeaveRequestStatus.PENDING]: { color: 'orange', label: 'Pending' },
    [LeaveRequestStatus.APPROVED]: { color: 'blue', label: 'Approved' },
    [LeaveRequestStatus.DECLINED]: { color: 'red', label: 'Rejected' },
  };

  const openDetail = (item: LeaveRequest) => {
    isShowDetail(true);
    setLeaveRequestSidebarData(item.id);
    setLeaveRequestSidebarWorkflowData(item.approvalWorkflowId ?? null);
  };

  const openEdit = (item: LeaveRequest) => {
    // LeaveRequestSidebar will enforce "pending only" edit.
    setLeaveRequestSidebarData(item.id);
    setLeaveRequestSidebarWorkflowData(item.approvalWorkflowId ?? null);
    setIsLoading(true);
  };

  const confirmDelete = (item: LeaveRequest) => {
    if (item.status !== LeaveRequestStatus.PENDING) return;
    Modal.confirm({
      title: 'Delete leave request',
      content: 'Are you sure you want to delete this leave request?',
      okText: 'Yes, delete',
      cancelText: 'No',
      okButtonProps: { danger: true },
      onOk: () => {
        deleteLeaveRequest(item.id, {
          onSuccess: () => {
            // If the deleted request is currently selected anywhere, clear it.
            if (leaveRequestSidebarData === item.id) {
              setLeaveRequestSidebarData(null);
              setLeaveRequestSidebarWorkflowData(null);
            }
          },
        });
      },
    });
  };

  const rowCellClass = 'text-sm py-2';
  const cellStyle = { paddingTop: 8, paddingBottom: 8 };

  /** Min widths keep cells readable; wrapper scrolls horizontally on narrow viewports. */
  const LEAVE_TABLE_SCROLL_X = 920;

  const columns: TableColumnsType<any> = [
    {
      title: 'Type',
      dataIndex: 'leaveType',
      key: 'leaveType',
      width: 200,
      ellipsis: true,
      onCell: () => ({ style: cellStyle }),
      render: (text: string, record: { action?: LeaveRequest }) => (
        <button
          type="button"
          onClick={() => record.action && openDetail(record.action)}
          className={`${rowCellClass} block max-w-[200px] truncate text-left text-gray-600 hover:text-gray-900 hover:underline cursor-pointer`}
          title={text}
          data-cy="time-attendance-leave-requests-table-type"
        >
          {text}
        </button>
      ),
    },
    {
      title: 'Start Date',
      dataIndex: 'startAt',
      key: 'startAt',
      width: 128,
      onCell: () => ({ style: cellStyle }),
      render: (date: string) => (
        <div
          className={`${rowCellClass} whitespace-nowrap text-gray-900`}
          data-cy="time-attendance-leave-requests-table-start-date"
        >
          {date ? dayjs(date).format(DATE_DISPLAY_FORMAT) : '-'}
        </div>
      ),
    },
    {
      title: 'End Date',
      dataIndex: 'endAt',
      key: 'endAt',
      width: 128,
      onCell: () => ({ style: cellStyle }),
      render: (date: string) => (
        <div
          className={`${rowCellClass} whitespace-nowrap text-gray-900`}
          data-cy="time-attendance-leave-requests-table-end-date"
        >
          {date ? dayjs(date).format(DATE_DISPLAY_FORMAT) : '-'}
        </div>
      ),
    },
    {
      title: 'Days',
      dataIndex: 'days',
      key: 'days',
      width: 72,
      onCell: () => ({ style: cellStyle }),
      render: (text: number) => (
        <div
          className={`${rowCellClass} whitespace-nowrap text-gray-900`}
          data-cy="time-attendance-leave-requests-table-days"
        >
          {text}
        </div>
      ),
    },
    {
      title: 'Reason',
      dataIndex: 'reason',
      key: 'reason',
      width: 200,
      ellipsis: true,
      onCell: () => ({ style: cellStyle }),
      render: (text: string) => (
        <div
          className={`${rowCellClass} max-w-[200px] truncate text-gray-900`}
          data-cy="time-attendance-leave-requests-table-reason"
          title={text}
        >
          {text || '-'}
        </div>
      ),
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      width: 120,
      onCell: () => ({ style: cellStyle }),
      render: (text: LeaveRequestStatus) => {
        const config = statusTagConfig[text] ?? {
          color: 'default',
          label: text,
        };
        return (
          <div
            className={`${rowCellClass}`}
            data-cy="time-attendance-leave-requests-table-status"
          >
            <Tag
              color={config.color}
              data-cy="time-attendance-history-table-row-status-tag"
            >
              {config.label}
            </Tag>
          </div>
        );
      },
    },
    {
      title: 'Action',
      dataIndex: 'action',
      key: 'actionMenu',
      width: 84,
      onCell: () => ({ style: cellStyle }),
      render: (item?: LeaveRequest) => {
        if (!item) return null;
        const isPending = item.status === LeaveRequestStatus.PENDING;

        const menuItems: MenuProps['items'] = [
          {
            key: 'edit',
            label: 'Edit',
            icon: <EditOutlined />,
            disabled: !isPending,
            onClick: () => openEdit(item),
          },
          {
            key: 'delete',
            label: 'Delete',
            icon: <DeleteOutlined />,
            danger: true,
            disabled: !isPending,
            onClick: () => confirmDelete(item),
          },
        ];

        return (
          <div
            className={`${rowCellClass} flex items-center justify-center`}
            data-cy="time-attendance-leave-requests-table-actions"
          >
            <Dropdown
              menu={{ items: menuItems }}
              trigger={['click']}
              placement="bottomRight"
              getPopupContainer={() => document.body}
            >
              <button
                type="button"
                onClick={(e) => e.stopPropagation()}
                style={dotsButtonStyle}
                className="shrink-0 text-gray-600 hover:text-gray-900"
                aria-label="Leave request actions"
                data-cy="time-attendance-leave-requests-table-actions-button"
              >
                <HiOutlineDotsHorizontal size={16} />
              </button>
            </Dropdown>
          </div>
        );
      },
    },
  ];

  const safeHistoryLimit = limit > 0 ? limit : 1;
  const historyMetaTotalPages = data?.meta?.totalPages;
  const historyResolvedTotalPages = Math.max(
    1,
    typeof historyMetaTotalPages === 'number' &&
      !Number.isNaN(historyMetaTotalPages) &&
      historyMetaTotalPages >= 1
      ? historyMetaTotalPages
      : Math.ceil((data?.meta?.totalItems ?? 0) / safeHistoryLimit),
  );
  const historyWrapPaginationManyPages = historyResolvedTotalPages > 3;

  const onFilterChange = (val: CommonObject) => {
    const nFilter: Partial<LeaveRequestBody['filter']> = { ...userFilter };

    const mobileDate = val.date as [unknown, unknown] | undefined;
    const mobileStart = mobileDate?.[0];
    const mobileEnd = mobileDate?.[1];
    const dateRange = val.dateRange as [unknown, unknown] | undefined;

    if (mobileStart && mobileEnd) {
      nFilter['date'] = {
        from: dayjs(mobileStart as Dayjs).format('YYYY-MM-DD'),
        to: dayjs(mobileEnd as Dayjs).format('YYYY-MM-DD'),
      };
    } else if (dateRange?.[0] && dateRange?.[1]) {
      nFilter['date'] = {
        from: dayjs(dateRange[0] as Dayjs).format('YYYY-MM-DD'),
        to: dayjs(dateRange[1] as Dayjs).format('YYYY-MM-DD'),
      };
    }

    if (val.type) {
      nFilter['leaveTypeIds'] = [val.type];
    }

    setFilter(nFilter);
  };

  return (
    <div
      className="bg-white rounded-lg"
      id="time-attendance-history-table-container"
      data-cy="time-attendance-history-table-container"
    >
      <div
        className="mb-4"
        id="time-attendance-history-table-header-container"
        data-cy="time-attendance-history-table-header-container"
      >
        <div
          className="text-sm sm:text-xl font-bold text-gray-900 mb-4"
          id="time-attendance-history-table-title"
          data-cy="time-attendance-history-table-title"
        >
          Leave Requests
        </div>
      </div>

      <div
        className="rounded-lg border border-gray-200 sm:overflow-hidden"
        id="time-attendance-history-table-bordered-wrapper"
        data-cy="time-attendance-history-table-bordered-wrapper"
      >
        {/* Filters + New Request: one filter form; desktop matches attendance (left group / right action + gap). */}
        <div
          className="px-4 py-3 sm:p-0"
          id="time-attendance-history-table-toolbar"
          data-cy="time-attendance-history-table-toolbar"
        >
          <div
            className="flex flex-col gap-3 sm:flex-row sm:flex-nowrap sm:items-center sm:justify-between sm:gap-8 sm:px-4 sm:pb-2 sm:pt-4 lg:gap-12 lg:px-5"
            data-cy="time-attendance-history-table-toolbar-inner"
          >
            <div
              className="min-w-0 w-full sm:w-auto sm:shrink"
              data-cy="time-attendance-history-table-filter-wrapper"
            >
              <HistoryTableFilter
                onChange={onFilterChange}
                data-cy="time-attendance-history-table-filter"
              />
            </div>
            <AccessGuard
              data-cy="time-attendance-history-table-add-button-access-guard"
              permissions={[Permissions.SubmitLeaveRequest]}
            >
              <div
                className="hidden shrink-0 sm:block sm:pl-4"
                data-cy="time-attendance-history-table-new-request-wrap"
              >
                <Button
                  size="large"
                  type="primary"
                  icon={<FaPlus />}
                  className="flex h-10 items-center justify-center"
                  onClick={() => isShow(true)}
                  id="time-attendance-history-table-new-request-button"
                  data-cy="time-attendance-history-table-new-request-button"
                >
                  <span
                    className="inline"
                    data-cy="time-attendance-history-table-new-request-button-label"
                  >
                    New Request
                  </span>
                </Button>
              </div>
            </AccessGuard>
          </div>
        </div>

        <div
          className="border-t border-gray-200 overflow-x-auto overscroll-x-contain [-webkit-overflow-scrolling:touch] [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden"
          data-cy="time-attendance-history-table-container"
        >
          {isFetching ? (
            <TableSkeleton columns={columns} />
          ) : (
            <Table
              className="leave-table [&_.ant-table]:min-w-[920px] [&_.ant-table-thead>tr>th]:whitespace-nowrap [&_.ant-table-tbody>tr>td]:whitespace-nowrap [&_.ant-table-thead>tr>th]:bg-[#FAFAFA] [&_.ant-table-thead>tr>th]:text-gray-800 [&_.ant-table-thead>tr>th]:text-base [&_.ant-table-thead>tr>th]:font-semibold [&_.ant-table-thead>tr>th]:before:!bg-transparent [&_tr.leave-history-table-row-even>td]:!bg-[#FAFAFA] [&_tr.leave-history-table-row-odd>td]:!bg-white"
              columns={columns}
              dataSource={tableData}
              pagination={false}
              scroll={{ x: LEAVE_TABLE_SCROLL_X }}
              rowClassName={(record, index) => {
                void record;
                return index % 2 === 1
                  ? 'leave-history-table-row-even'
                  : 'leave-history-table-row-odd';
              }}
              tableLayout="fixed"
              id="time-attendance-history-table"
              data-cy="time-attendance-history-table"
            />
          )}
          <div
            className={`mx-2 sm:mx-3 ${isMobile || isTablet ? 'mt-6' : ''}`}
            data-cy="time-attendance-history-table-pagination-wrapper"
          >
            {isMobile || isTablet ? (
              <div
                className="[&>div]:border-0 [&>div]:bg-transparent [&>div]:px-0 [&>div]:py-0"
                data-cy="time-attendance-history-table-mobile-pagination-shell"
              >
                <CustomMobilePagination
                  currentPage={page}
                  totalResults={data?.meta?.totalItems ?? 0}
                  totalPages={data?.meta?.totalPages}
                  pageSize={limit}
                  stackPagerAndGoTo={historyWrapPaginationManyPages}
                  onChange={(newPage, newPageSize) => {
                    setPage(newPage);
                    setLimit(newPageSize);
                  }}
                  id="time-attendance-leave-requests-mobile-pagination"
                  data-cy="time-attendance-leave-requests-mobile-pagination"
                />
              </div>
            ) : (
              <CustomPagination
                current={page}
                total={data?.meta?.totalItems ?? 0}
                totalPages={data?.meta?.totalPages}
                pageSize={limit}
                wrapMainRow={historyWrapPaginationManyPages}
                onChange={(newPage) => setPage(newPage)}
                onShowSizeChange={(newPageSize) => {
                  setLimit(newPageSize);
                  setPage(1);
                }}
                id="time-attendance-leave-requests-pagination"
                data-cy="time-attendance-leave-requests-pagination"
              />
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default HistoryTable;

import { useMyTimesheetStore } from '@/store/uistate/features/timesheet/myTimesheet';
import {
  Checkbox,
  Col,
  DatePicker,
  Form,
  Input,
  Modal,
  Row,
  Select,
  Space,
  Skeleton,
} from 'antd';
import CustomLabel from '@/components/form/customLabel/customLabel';
import CustomDrawerFooterButton, {
  CustomDrawerFooterButtonProps,
} from '@/components/common/customDrawer/customDrawerFooterButton';
import { useSetLeaveRequest } from '@/store/server/features/timesheet/leaveRequest/mutation';
import { formatLinkToUploadFile, formatToOptions } from '@/helpers/formatTo';
import { DATE_FORMAT } from '@/utils/constants';
import dayjs from 'dayjs';
import { LeaveRequest, LeaveRequestStatus } from '@/types/timesheet/settings';
import React, { useEffect, useState } from 'react';
import {
  useGetLeaveRequest,
  useGetSingleApproval,
} from '@/store/server/features/timesheet/leaveRequest/queries';
import CustomUpload from '@/components/form/customUpload';
import { InboxOutlined } from '@ant-design/icons';
import { MdKeyboardArrowDown } from 'react-icons/md';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import { useAllApproval } from '@/store/server/features/approver/queries';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import { APPROVALTYPES } from '@/types/enumTypes';
import { useGetLeaveTypes } from '@/store/server/features/timesheet/leaveType/queries';
import { useGetLeaveBalance } from '@/store/server/features/timesheet/leaveBalance/queries';

const LeaveRequestSidebar = () => {
  const {
    filter,
    setFilter,
    isShowLeaveRequestSidebar,
    setIsShowLeaveRequestSidebar,
    leaveRequestSidebarData,
    setLeaveRequestSidebarData,
  } = useMyTimesheetStore();
  const { data: leaveRequestData, refetch } = useGetLeaveRequest(
    { page: '1', limit: '1' },
    { filter },
    false,
    false,
  );
  const { data: approverLog } = useGetSingleApproval(
    leaveRequestSidebarData ?? '',
  );
  const { userId } = useAuthenticationStore();
  const { data: employeeData } = useGetAllUsers();
  const { data: leaveTypesData } = useGetLeaveTypes();
  const { data: leaveBalanceData } = useGetLeaveBalance(userId ?? '', '');
  const userData = employeeData?.items?.find((item: any) => item.id === userId);

  const { data: approvalDepartmentData, refetch: getDepartmentApproval } =
    useAllApproval(
      userData?.employeeJobInformation[0]?.departmentId || '',
      APPROVALTYPES?.LEAVE,
    );

  const { data: approvalUserData, refetch: getUserApproval } = useAllApproval(
    userData?.id || '',
    APPROVALTYPES?.LEAVE,
  );

  useEffect(() => {
    if (userData?.employeeJobInformation[0]?.departmentId) {
      getDepartmentApproval();
    }
  }, [userData]);
  useEffect(() => {
    if (userData?.id) getUserApproval();
  }, [userData]);

  const {
    mutate: updateLeaveRequest,
    isLoading: isLoadingRequest,
    isSuccess: isSuccessUpdate,
  } = useSetLeaveRequest();
  const [leaveRequest, setLeaveRequest] = useState<LeaveRequest>();
  const [isLoading, setIsLoading] = useState(false);
  const [showApproverMessage, setShowApproverMessage] = useState(false);

  const [form] = Form.useForm();

  const selectedLeaveTypeId = Form.useWatch('type', form);
  const leaveBalanceItems =
    leaveBalanceData?.items?.items?.filter((item: any) => item.leaveType) ?? [];
  const selectedBalance = leaveBalanceItems.find(
    (item: any) => item?.leaveType?.id === selectedLeaveTypeId,
  );
  const availableDays =
    selectedBalance != null
      ? (selectedBalance.totalBalance ?? 0).toFixed(1)
      : null;

  const approverLogItems: any[] = Array.isArray(approverLog)
    ? approverLog
    : ((approverLog as any)?.items ?? []);

  const approvalHasApprovedStep = approverLogItems.some(
    (log) => String(log?.action ?? '').toLowerCase() === 'approved',
  );

  // If approval process has started (at least one "Approved" action), only allow editing
  // description + attachment while the leave is still pending.
  const lockCoreFields =
    !!leaveRequest &&
    leaveRequest.status === LeaveRequestStatus.PENDING &&
    approvalHasApprovedStep;

  useEffect(() => {
    if (leaveRequestSidebarData) {
      setFilter({
        leaveRequestsIds: [leaveRequestSidebarData!],
      });
      setIsLoading(true);
    }
  }, [leaveRequestSidebarData]);

  useEffect(() => {
    if (filter && Object.keys(filter).length) {
      refetch({}).finally(() => setIsLoading(false));
    }
  }, [filter]);

  useEffect(() => {
    if (leaveRequestData?.items) {
      setLeaveRequest(leaveRequestData.items[0]);
      setIsLoading(false);
    }
  }, [leaveRequestData]);

  useEffect(() => {
    if (leaveRequest) {
      form.setFieldValue(
        'type',
        typeof leaveRequest?.leaveType !== 'string' &&
          leaveRequest.leaveType?.id,
      );
      form.setFieldValue('isHalfday', leaveRequest.isHalfday);
      form.setFieldValue('startDate', dayjs(leaveRequest.startAt));
      form.setFieldValue('endDate', dayjs(leaveRequest.endAt));
      form.setFieldValue('note', leaveRequest.justificationNote);

      if (leaveRequest.justificationDocument) {
        form.setFieldValue('attachment', [
          formatLinkToUploadFile(leaveRequest.justificationDocument),
        ]);
      }
      if (leaveRequest.delegatee) {
        form.setFieldValue(
          'delegatee',
          typeof leaveRequest?.delegatee !== 'string' &&
            leaveRequest?.delegatee?.id,
        );
      }
    }
  }, [leaveRequest]);

  useEffect(() => {
    if (isSuccessUpdate) {
      onClose();
    }
  }, [isSuccessUpdate]);

  const onClose = () => {
    form.resetFields();
    setLeaveRequest(undefined);
    setFilter({});
    setIsLoading(false);
    setLeaveRequestSidebarData(null);
    setIsShowLeaveRequestSidebar(false);
    setShowApproverMessage(false);
  };

  useEffect(() => {
    // If opening the drawer for "add" (not edit)
    if (isShowLeaveRequestSidebar && !leaveRequestSidebarData) {
      setLeaveRequest(undefined);
      form.resetFields();
      setShowApproverMessage(false);
    }
  }, [isShowLeaveRequestSidebar, leaveRequestSidebarData]);

  useEffect(() => {
    // If the sidebar is open for edit, but the leave request is not editable, close and clear
    if (
      isShowLeaveRequestSidebar &&
      leaveRequestSidebarData && // means it's edit mode
      leaveRequest &&
      leaveRequest.status !== LeaveRequestStatus.PENDING // or whatever status means "editable"
    ) {
      onClose(); // This will clear the form and state
    }
  }, [isShowLeaveRequestSidebar, leaveRequestSidebarData, leaveRequest]);

  const hasNoApprover =
    (approvalUserData?.length ?? 0) < 1 &&
    (approvalDepartmentData?.length ?? 0) < 1;

  const footerModalItems: CustomDrawerFooterButtonProps[] = [
    {
      label: 'Cancel',
      key: 'cancel',
      className:
        'h-10 text-sm !px-4 !py-0 font-normal border-gray-300 text-gray-700',
      size: 'middle',
      onClick: () => onClose(),
      disabled: isLoadingRequest || isLoading,
      id: 'time-attendance-leave-request-sidebar-cancel-button',
      'data-cy': 'time-attendance-leave-request-sidebar-cancel-button',
    },
    {
      label: leaveRequest ? 'Update' : 'Submit Request',
      key: 'create',
      className: 'h-10 text-sm !px-4 !py-0 font-normal',
      size: 'large',
      type: 'primary',
      loading: isLoadingRequest || isLoading,
      disabled: hasNoApprover && !leaveRequest,
      onClick: () => form.submit(),
      id: 'time-attendance-leave-request-sidebar-submit-button',
      'data-cy': 'time-attendance-leave-request-sidebar-submit-button',
      tooltip:
        hasNoApprover && !leaveRequest
          ? 'You lack approver please contact your team lead for more information'
          : undefined,
      tooltipProps:
        hasNoApprover && !leaveRequest
          ? {
              overlayInnerStyle: {
                backgroundColor: 'white',
                color: '#1f2937',
                padding: '12px 16px',
                borderRadius: '8px',
                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
                maxWidth: '300px',
                fontSize: '14px',
                fontWeight: 500,
              },
              color: 'white',
            }
          : undefined,
    },
  ];

  const onFinish = () => {
    // Check if there's no approver assigned
    if (approvalUserData?.length < 1 && approvalDepartmentData?.length < 1) {
      setShowApproverMessage(true);
      return;
    }

    const value = form.getFieldsValue();

    updateLeaveRequest({
      item: {
        ...(leaveRequest && leaveRequest),
        leaveType: value.type,
        delegatee: value.delegatee,
        isHalfday: !!value.isHalfday,
        startAt: dayjs(value.startDate).format('YYYY-MM-DD'),
        endAt: dayjs(value.endDate).format('YYYY-MM-DD'),
        justificationDocument: !!value.attachment?.length
          ? value.attachment[0]['response']
          : null,
        justificationNote: value.note,
        status: LeaveRequestStatus.PENDING,
        approvalWorkflowId:
          approvalUserData?.length > 0
            ? approvalUserData[0]?.id
            : approvalDepartmentData[0]?.id,
        approvalType: 'Leave',
      },
      userId,
    });
  };

  const typeOptions = () =>
    formatToOptions(leaveTypesData?.items ?? [], 'title', 'id');

  const itemClass =
    'text-xs [&_.ant-form-item-label]:mb-1.5 [&_.ant-form-item-label]:font-normal';
  const controlClass = 'w-full';

  const validateDates = () => {
    const startDate = form.getFieldValue('startDate');
    const endDate = form.getFieldValue('endDate');
    if (startDate && endDate) {
      if (dayjs(startDate).isAfter(dayjs(endDate))) {
        return Promise.reject(new Error('Invalid date'));
      }
    }
    return Promise.resolve();
  };

  const handleChange = () => {
    form.validateFields(['startDate', 'endDate']);
  };

  return (
    <Modal
      open={isShowLeaveRequestSidebar}
      onCancel={onClose}
      title={
        <div data-cy="time-attendance-leave-request-sidebar-title-container">
          <div
            className="text-base font-semibold"
            data-cy="time-attendance-leave-request-sidebar-title"
          >
            {leaveRequest ? 'Update Leave Request' : 'New Leave Request'}
          </div>
          {!leaveRequest && (
            <p
              className="text-sm font-normal text-gray-500 mt-1 mb-0"
              data-cy="time-attendance-leave-request-sidebar-description"
            >
              Fill in the details to submit a new leave request.
            </p>
          )}
        </div>
      }
      footer={
        <div
          className="flex justify-end gap-2 !pt-0 [&_.flex]:!py-0"
          id="time-attendance-leave-request-sidebar-footer"
          data-cy="time-attendance-leave-request-sidebar-footer"
        >
          <CustomDrawerFooterButton
            data-cy="time-attendance-leave-request-sidebar-footer-button"
            buttons={footerModalItems}
          />
        </div>
      }
      width={520}
      centered
      destroyOnClose
      data-cy="time-attendance-leave-request-sidebar-container"
      styles={{
        body: { paddingTop: 8 },
        footer: { paddingTop: 0, marginTop: 0 },
      }}
    >
      <Skeleton
        loading={isLoading || isLoadingRequest}
        active
        data-cy="time-attendance-leave-request-sidebar-spin"
      >
        <Form
          layout="vertical"
          requiredMark={CustomLabel}
          form={form}
          autoComplete="off"
          onFinish={onFinish}
          id="time-attendance-leave-request-sidebar-form"
          data-cy="time-attendance-leave-request-sidebar-form"
        >
          <Space.Compact
            direction="vertical"
            className="w-full px-3 sm:px-0 "
            id="time-attendance-leave-request-sidebar-form-fields"
            data-cy="time-attendance-leave-request-sidebar-form-fields"
          >
            <Form.Item
              name="type"
              label="Leave Type"
              rules={[{ required: true, message: 'Required' }]}
              className={itemClass}
              id="time-attendance-leave-request-sidebar-type"
              data-cy="time-attendance-leave-request-sidebar-type"
            >
              <Select
                className={controlClass}
                size="large"
                options={typeOptions()}
                placeholder="Select Leave Type"
                disabled={
                  leaveRequest?.status === LeaveRequestStatus.APPROVED ||
                  lockCoreFields
                }
                suffixIcon={
                  <MdKeyboardArrowDown
                    data-cy="time-attendance-leave-request-sidebar-type-select-icon"
                    size={16}
                    className="text-gray-900"
                  />
                }
                id="time-attendance-leave-request-sidebar-type-select"
                data-cy="time-attendance-leave-request-sidebar-type-select"
              />
            </Form.Item>
            {selectedLeaveTypeId && availableDays != null && (
              <p
                className="text-xs text-gray-500 -mt-1.5 mb-0"
                data-cy="time-attendance-leave-request-sidebar-available-days"
              >
                Available {availableDays} days
              </p>
            )}
            <Form.Item
              name="isHalfday"
              valuePropName="checked"
              className={itemClass}
              id="time-attendance-leave-request-sidebar-half-day"
              data-cy="time-attendance-leave-request-sidebar-half-day"
            >
              <Checkbox
                disabled={
                  leaveRequest?.status === LeaveRequestStatus.APPROVED ||
                  lockCoreFields
                }
                data-cy="time-attendance-leave-request-sidebar-half-day-checkbox"
              >
                Half Date
              </Checkbox>
            </Form.Item>
            <Row
              data-cy="time-attendance-leave-request-sidebar-date-row"
              gutter={16}
            >
              <Col
                data-cy="time-attendance-leave-request-sidebar-start-date-column"
                span={12}
              >
                <Form.Item
                  name="startDate"
                  label="Start Date "
                  rules={[
                    { required: true, message: 'Required' },
                    { validator: validateDates },
                  ]}
                  className={itemClass}
                  id="time-attendance-leave-request-sidebar-start-date"
                  data-cy="time-attendance-leave-request-sidebar-start-date"
                >
                  <DatePicker
                    className={controlClass}
                    size="large"
                    onChange={handleChange}
                    disabled={
                      leaveRequest?.status === LeaveRequestStatus.APPROVED ||
                      lockCoreFields
                    }
                    format={DATE_FORMAT}
                    id="time-attendance-leave-request-sidebar-start-date-picker"
                    data-cy="time-attendance-leave-request-sidebar-start-date-picker"
                  />
                </Form.Item>
              </Col>
              <Col
                span={12}
                data-cy="time-attendance-leave-request-sidebar-end-date-column"
              >
                <Form.Item
                  name="endDate"
                  label="End Date"
                  rules={[
                    { required: true, message: 'Required' },
                    { validator: validateDates },
                  ]}
                  className={itemClass}
                  id="time-attendance-leave-request-sidebar-end-date"
                  data-cy="time-attendance-leave-request-sidebar-end-date"
                >
                  <DatePicker
                    className={controlClass}
                    size="large"
                    onChange={handleChange}
                    disabled={
                      leaveRequest?.status === LeaveRequestStatus.APPROVED ||
                      lockCoreFields
                    }
                    format={DATE_FORMAT}
                    id="time-attendance-leave-request-sidebar-end-date-picker"
                    data-cy="time-attendance-leave-request-sidebar-end-date-picker"
                  />
                </Form.Item>
              </Col>
            </Row>
            <Form.Item
              name="note"
              label="Reason"
              rules={[{ required: true, message: 'Required' }]}
              className={itemClass}
              id="time-attendance-leave-request-sidebar-reason"
              data-cy="time-attendance-leave-request-sidebar-reason"
            >
              <Input.TextArea
                rows={4}
                size="middle"
                className="w-full"
                placeholder="Reason"
                disabled={leaveRequest?.status === LeaveRequestStatus.APPROVED}
                id="time-attendance-leave-request-sidebar-reason-input"
                data-cy="time-attendance-leave-request-sidebar-reason-input"
              />
            </Form.Item>
            <Form.Item
              name="delegatee"
              label="Delegate"
              className={itemClass}
              id="time-attendance-leave-request-sidebar-delegatee"
              data-cy="time-attendance-leave-request-sidebar-delegatee"
            >
              <Select
                showSearch
                size="large"
                placeholder="Select Delegate"
                className={controlClass}
                allowClear
                disabled={lockCoreFields}
                filterOption={(input: any, option: any) =>
                  (option?.label ?? '')
                    .toLowerCase()
                    .includes(input.toLowerCase())
                }
                options={employeeData?.items?.map((item: any) => ({
                  value: item?.id,
                  label:
                    item?.firstName +
                    ' ' +
                    item?.middleName +
                    ' ' +
                    item?.lastName,
                }))}
                id="time-attendance-leave-request-sidebar-delegatee-select"
                data-cy="time-attendance-leave-request-sidebar-delegatee-select"
              />
            </Form.Item>
            <Form.Item
              name="attachment"
              label="Attachment (optional)"
              valuePropName="fileList"
              className={itemClass}
              id="time-attendance-leave-request-sidebar-attachment"
              data-cy="time-attendance-leave-request-sidebar-attachment"
              getValueFromEvent={(e) => {
                return Array.isArray(e) ? e : e && e.fileList;
              }}
            >
              <CustomUpload
                className="w-full"
                accept=".pdf,.docx,.png,.jpeg,.jpg"
                name="attachment"
                mode="draggable"
                maxCount={1}
                icon={
                  <InboxOutlined
                    style={{ fontSize: 40 }}
                    className="text-primary"
                  />
                }
                title="Click or drag file to this area to upload"
                dragTitleClassName="font-normal text-sm text-gray-700"
                dragSubtitleClassName="font-normal text-sm text-gray-500"
                showDragSubtitle={false}
                setIsLoading={setIsLoading}
                data-cy="time-attendance-leave-request-sidebar-attachment-upload"
              />
            </Form.Item>
            {showApproverMessage && (
              <div
                className="mt-6 mb-4 px-5 py-4 bg-white rounded-xl border-2 border-orange-200 shadow-md"
                id="time-attendance-leave-request-sidebar-approver-message"
                data-cy="time-attendance-leave-request-sidebar-approver-message"
              >
                <p
                  className="text-base font-medium text-gray-800 m-0 leading-relaxed"
                  id="time-attendance-leave-request-sidebar-approver-message-text"
                  data-cy="time-attendance-leave-request-sidebar-approver-message-text"
                >
                  You lack approver please contact your team lead for more
                  information
                </p>
              </div>
            )}
          </Space.Compact>
        </Form>
      </Skeleton>
    </Modal>
  );
};

export default LeaveRequestSidebar;

import { useMyTimesheetStore } from '@/store/uistate/features/timesheet/myTimesheet';
import CustomDrawerLayout from '@/components/common/customDrawer';
import React, { useEffect, useState } from 'react';
import UserCard from '@/components/common/userCard/userCard';
import { Col, Row, Skeleton, Space } from 'antd';
import InfoItem from './infoItem';
import StatusBadge from '@/components/common/statusBadge/statusBadge';
import CustomDrawerFooterButton, {
  CustomDrawerFooterButtonProps,
} from '@/components/common/customDrawer/customDrawerFooterButton';
import CustomDrawerHeader from '@/components/common/customDrawer/customDrawerHeader';
import { AttendanceRequestBody } from '@/store/server/features/timesheet/attendance/interface';
import { useGetAttendances } from '@/store/server/features/timesheet/attendance/queries';
import {
  AttendanceBreak,
  AttendanceRecord,
  AttendanceRecordTypeBadgeTheme,
} from '@/types/timesheet/attendance';
import dayjs from 'dayjs';
import { DATE_FORMAT, TIME_FORMAT } from '@/utils/constants';
import {
  calculateAttendanceRecordToTotalWorkTime,
  minuteToHour,
  minuteToLastMinute,
  timeToHour,
  timeToLastMinute,
} from '@/helpers/calculateHelper';
import { formatToAttendanceStatuses } from '@/helpers/formatTo';
import { formatAttendanceWallClockTimeOrDash } from '@/helpers/attendanceTimeHelper';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';

const ViewAttendanceSidebar = () => {
  const {
    isShowViewSidebarAttendance,
    setIsShowViewSidebarAttendance,
    viewAttendanceId,
    setViewAttendanceId,
  } = useMyTimesheetStore();

  const [filter, setFilter] = useState<
    Partial<AttendanceRequestBody['filter']>
  >({});
  const [attendance, setAttendance] = useState<AttendanceRecord>();
  const [totalTime, setTotalTime] = useState(0);

  const { data: allUsers } = useGetAllUsers();

  const getUserName = (id: string) => {
    return allUsers?.items?.find((user: any) => user?.id === id) ?? {};
  };

  const { data, isFetching, refetch } = useGetAttendances(
    { page: '1', limit: '1' },
    { filter },
    false,
    false,
  );

  useEffect(() => {
    if (viewAttendanceId) {
      setFilter({ attendanceRecordIds: [viewAttendanceId] });
    }
  }, [viewAttendanceId]);

  useEffect(() => {
    if (filter) {
      refetch();
    }
  }, [filter]);

  useEffect(() => {
    if (data?.items?.length) {
      setAttendance(data.items[0]);
      const time = calculateAttendanceRecordToTotalWorkTime(data.items[0]);
      setTotalTime(time);
    }
  }, [data]);

  const footerModalItems: CustomDrawerFooterButtonProps[] = [
    {
      label: 'Cancel',
      key: 'cancel',
      className: 'h-[40px] sm:h-[56px] text-base',
      size: 'large',
      onClick: () => onClose(),
      id: 'time-attendance-view-attendance-sidebar-cancel-button',
      'data-cy': 'time-attendance-view-attendance-sidebar-cancel-button',
    },
  ];

  const onClose = () => {
    setViewAttendanceId(null);
    setIsShowViewSidebarAttendance(false);
  };

  const lateInfo = (record: AttendanceRecord | AttendanceBreak) => {
    return (
      <InfoItem
