                      Use Current Location
                    </Button>
                  </div>
                  <div
                    className="mt-2 rounded-lg border border-gray-200 overflow-hidden"
                    id="time-attendance-settings-allowed-areas-sidebar-map-picker-container"
                    data-cy="time-attendance-settings-allowed-areas-sidebar-map-picker-container"
                  >
                    <EnhancedLocationPicker
                      latitude={formValues.latitude}
                      longitude={formValues.longitude}
                      radius={formValues.distance}
                      onLocationChange={handleLocationChange}
                      onRadiusChange={handleRadiusChange}
                      height="400px"
                      data-cy="time-attendance-settings-allowed-areas-sidebar-map-picker"
                    />
                  </div>
                  <Slider
                    min={0.01}
                    max={Math.max(0.5, formValues.distance)}
                    step={0.001}
                    value={formValues.distance}
                    onChange={(value) => {
                      if (typeof value === 'number') {
                        handleRadiusChange(value);
                      }
                    }}
                    marks={{
                      0.01: '10 m',
                      0.05: '50 m',
                      0.1: '100 m',
                      0.2: '200 m',
                      0.3: '300 m',
                      0.4: '400 m',
                      0.5: '500 m',
                    }}
                    id="time-attendance-settings-allowed-areas-sidebar-radius-slider"
                    data-cy="time-attendance-settings-allowed-areas-sidebar-radius-slider"
                    className="mt-4 px-1"
                  />
                </div>

                {/* Hidden form fields for map values */}
                <Form.Item
                  data-cy="time-attendance-settings-allowed-areas-sidebar-latitude-form-item"
                  name="latitude"
                  hidden
                >
                  <Input />
                </Form.Item>
                <Form.Item
                  data-cy="time-attendance-settings-allowed-areas-sidebar-longitude-form-item"
                  name="longitude"
                  hidden
                >
                  <Input />
                </Form.Item>
                {/* Radius (km) — label/input spacing matches latitude / longitude */}
                <div
                  data-cy="time-attendance-settings-allowed-areas-sidebar-radius-container"
                  id="time-attendance-settings-allowed-areas-sidebar-radius-container"
                  className="mt-5 space-y-1"
                >
                  <span
                    data-cy="time-attendance-settings-allowed-areas-sidebar-radius-label"
                    id="time-attendance-settings-allowed-areas-sidebar-radius-label"
                    className="text-sm font-normal text-gray-900"
                  >
                    Radius (km)
                    <span
                      className="ml-1 text-error"
                      data-cy="time-attendance-settings-allowed-areas-sidebar-radius-required"
                    >
                      *
                    </span>
                  </span>
                  <Form.Item
                    data-cy="time-attendance-settings-allowed-areas-sidebar-radius-form-item"
                    name="distance"
                    rules={[
                      { required: true, message: 'Required' },
                      {
                        type: 'number',
                        min: 0.01,
                        message: 'Enter a value of at least 0.01 km (10 m)',
                      },
                    ]}
                    noStyle
                  >
                    <InputNumber
                      min={0.01}
                      step={0.001}
                      precision={3}
                      controls
                      inputMode="decimal"
                      className={controlClass}
                      style={{ width: '100%' }}
                      placeholder="e.g. 0.1"
                      parser={(value) => {
                        const parsed = value?.replace(/[^\d.]/g, '') ?? '';
                        return parsed === ''
                          ? ('' as unknown as number)
                          : Number(parsed);
                      }}
                      formatter={(value) =>
                        value === undefined || value === null
                          ? ''
                          : String(value).replace(/[^\d.]/g, '')
                      }
                      onKeyDown={(e) => {
                        const allowedKeys = [
                          'Backspace',
                          'Delete',
                          'Tab',
                          'ArrowLeft',
                          'ArrowRight',
                          'Home',
                          'End',
                        ];
                        if (
                          allowedKeys.includes(e.key) ||
                          (e.ctrlKey && ['a', 'c', 'v', 'x'].includes(e.key))
                        ) {
                          return;
                        }
                        if (!/^[0-9.]$/.test(e.key)) {
                          e.preventDefault();
                        }
                      }}
                      onChange={(value) => {
                        if (value !== null && value !== undefined) {
                          handleRadiusChange(Number(value));
                        }
                      }}
                      id="time-attendance-settings-allowed-areas-sidebar-radius-input"
                      data-cy="time-attendance-settings-allowed-areas-sidebar-radius-input"
                    />
                  </Form.Item>
                </div>

                {/* Lat / Long — directly below radius */}
                <div
                  data-cy="time-attendance-settings-allowed-areas-sidebar-latitude-longitude-container"
                  id="time-attendance-settings-allowed-areas-sidebar-latitude-longitude-container"
                  className="mt-3 grid grid-cols-1 gap-4 sm:grid-cols-2"
                >
                  <div
                    data-cy="time-attendance-settings-allowed-areas-sidebar-latitude-container"
                    id="time-attendance-settings-allowed-areas-sidebar-latitude-container"
                    className="space-y-1"
                  >
                    <span
                      data-cy="time-attendance-settings-allowed-areas-sidebar-latitude-label"
                      id="time-attendance-settings-allowed-areas-sidebar-latitude-label"
                      className="text-sm font-normal text-gray-900"
                    >
                      Latitude
                    </span>
                    <InputNumber
                      value={formValues.latitude}
                      precision={6}
                      onChange={(value) => {
                        if (value !== null) {
                          handleLocationChange(
                            value as number,
                            formValues.longitude,
                          );
                        }
                      }}
                      className={controlClass}
                      style={{ width: '100%' }}
                      id="time-attendance-settings-allowed-areas-sidebar-latitude-display"
                      data-cy="time-attendance-settings-allowed-areas-sidebar-latitude-display"
                    />
                  </div>
                  <div
                    data-cy="time-attendance-settings-allowed-areas-sidebar-longitude-container"
                    id="time-attendance-settings-allowed-areas-sidebar-longitude-container"
                    className="space-y-1"
                  >
                    <span
                      data-cy="time-attendance-settings-allowed-areas-sidebar-longitude-label"
                      id="time-attendance-settings-allowed-areas-sidebar-longitude-label"
                      className="text-sm font-normal text-gray-900"
                    >
                      Longitude
                    </span>
                    <InputNumber
                      value={formValues.longitude}
                      precision={6}
                      onChange={(value) => {
                        if (value !== null) {
                          handleLocationChange(
                            formValues.latitude,
                            value as number,
                          );
                        }
                      }}
                      className={controlClass}
                      style={{ width: '100%' }}
                      id="time-attendance-settings-allowed-areas-sidebar-longitude-display"
                      data-cy="time-attendance-settings-allowed-areas-sidebar-longitude-display"
                    />
                  </div>
                </div>
                <p
                  data-cy="time-attendance-settings-allowed-areas-sidebar-latitude-longitude-description"
                  id="time-attendance-settings-allowed-areas-sidebar-latitude-longitude-description"
                  className="mt-2 text-center text-xs text-gray-500"
                >
                  You can update the map by changing latitude or longitude.
                </p>

                {/* Global location card */}
                <div
                  data-cy="time-attendance-settings-allowed-areas-sidebar-is-global-container"
                  id="time-attendance-settings-allowed-areas-sidebar-is-global-container"
                  className="mt-6 rounded-xl border border-gray-200 bg-gray-50 px-4 py-3 flex items-center justify-between"
                >
                  <div
                    data-cy="time-attendance-settings-allowed-areas-sidebar-is-global-label-container"
                    id="time-attendance-settings-allowed-areas-sidebar-is-global-label-container"
                    className="flex flex-col gap-0.5"
                  >
                    <span
                      data-cy="time-attendance-settings-allowed-areas-sidebar-is-global-label-text"
                      id="time-attendance-settings-allowed-areas-sidebar-is-global-label-text"
                      className="text-sm font-medium text-gray-900"
                    >
                      Global Location
                    </span>
                    <span
                      data-cy="time-attendance-settings-allowed-areas-sidebar-is-global-label-description"
                      id="time-attendance-settings-allowed-areas-sidebar-is-global-label-description"
                      className="text-xs text-gray-500"
                    >
                      Make this location available globally
                    </span>
                  </div>
                  <Form.Item
                    data-cy="time-attendance-settings-allowed-areas-sidebar-is-global-item"
                    name="isGlobal"
                    valuePropName="checked"
                    noStyle
                  >
                    <Switch
                      defaultChecked
                      onChange={(checked) => setShowUsers(!checked)}
                      id="time-attendance-settings-allowed-areas-sidebar-is-global-switch"
                      data-cy="time-attendance-settings-allowed-areas-sidebar-is-global-switch"
                    />
                  </Form.Item>
                </div>

                {showUsers && (
                  <Form.Item
                    id="time-attendance-settings-allowed-areas-sidebar-users"
                    data-cy="time-attendance-settings-allowed-areas-sidebar-users"
                    label="Select Users"
                    name="allowedUserAccesses"
                  >
                    <Select
                      mode="multiple"
                      showSearch
                      placeholder="Select a person"
                      className="w-full"
                      optionFilterProp="label"
                      options={users?.items?.map((list: any) => ({
                        value: list?.id,
                        label: `${list?.firstName ? list?.firstName : ''} ${list?.middleName ? list?.middleName : ''} ${list?.lastName ? list?.lastName : ''}`,
                      }))}
                      id="time-attendance-settings-allowed-areas-sidebar-users-select"
                      data-cy="time-attendance-settings-allowed-areas-sidebar-users-select"
                    />
                  </Form.Item>
                )}
              </Space.Compact>
            </div>
          </Form>
        </Skeleton>
      </Modal>
    )
  );
};

export default LocationSidebar;

'use client';
import Image from 'next/image';
import { RiDeleteBin6Line } from 'react-icons/ri';
import { Button, Dropdown, Form, Modal, Select, Avatar, Tooltip } from 'antd';
import { FaPencil } from 'react-icons/fa6';
import {
  useApprovalFilter,
  useGetAllApprovalWorkflow,
  useGetAllLeaveRequestByWorkFlowId,
} from '@/store/server/features/approver/queries';
import { useApprovalStore } from '@/store/uistate/features/approval';
import DeleteModal from '@/components/common/deleteConfirmationModal';
import {
  useDeleteApprovalWorkFLow,
  useUpdateLeaverequestApprovalWorkFlow,
} from '@/store/server/features/approver/mutation';
import { useGetAllUsers } from '@/store/server/features/employees/employeeManagment/queries';
import { FaPlus } from 'react-icons/fa';
import { useGetDepartments } from '@/store/server/features/employees/employeeManagment/department/queries';
import AddApprover from '../addApprover';
import { useEffect, useState } from 'react';
import EditWorkFLow from '../editWorkFLow';
import AccessGuard from '@/utils/permissionGuard';
import { Permissions } from '@/types/commons/permissionEnum';
import ApproverListTable from '@/components/Approval/ApprovalListTable';
import { APPROVALTYPES, commonClass } from '@/types/enumTypes';
import {
  DEFAULT_TIMESHEET_APPROVAL_TYPES,
  formatTimesheetApprovalType,
} from '@/utils/approval/timesheetApprovalTypes';
import {
  findDepartmentById,
  isDepartmentEntityType,
  isUserEntityType,
} from '@/utils/approval/departmentHelpers';
import { IoMdSwap } from 'react-icons/io';
import WorkflowModal from '../workflowModal';
import MoreHorizIcon from '@mui/icons-material/MoreHoriz';
import { UserOutlined } from '@ant-design/icons';

const ApprovalListTable = () => {
  const { data: employeeData, isLoading: isEmployeeDataLoading } =
    useGetAllUsers();
  const { data: department, isLoading: isDepartmentLoading } =
    useGetDepartments();
  const {
    userCurrentPage,
    pageSize,
    deleteModal,
    editModal,
    transferModal,
    setTransferModal,
    addModal,
    deletedItem,
    setLevel,
    setDeletedItem,
    setUserCurrentPage,
    setPageSize,
    setDeleteModal,
    setSelectedItem,
    setEditModal,
    setAddModal,
    setWorkflowApplies,
    setApproverType,
    selectedItem,
    setDepartmentApproval,
    approverType,
  } = useApprovalStore();
  const [workflowModal, setWorkflowModal] = useState(false);
  const { searchParams } = useApprovalStore();
  const { data: allFilterData, isLoading: isEmployeeLoading } =
    useApprovalFilter(
      pageSize,
      userCurrentPage,
      searchParams?.entityType ? searchParams.entityType : '',
      searchParams?.entityId ? searchParams.entityId : '',
      searchParams?.name || '',
      searchParams?.approvalType || [...DEFAULT_TIMESHEET_APPROVAL_TYPES],
    );

  // Check if all required data is loaded
  const isDataLoading =
    isEmployeeLoading || isEmployeeDataLoading || isDepartmentLoading;

  const { data: leaveRequestData } =
    useGetAllLeaveRequestByWorkFlowId(deletedItem);

  const { data: approvalWorkflowData } = useGetAllApprovalWorkflow();
  const { mutate: deleteWorkflow, isLoading: deleteLoading } =
    useDeleteApprovalWorkFLow();
  const { mutate: updateWorkflow, isLoading: updateLoading } =
    useUpdateLeaverequestApprovalWorkFlow();

  const getEmployeeInformation = (id: string) => {
    if (!employeeData?.items || isEmployeeDataLoading) return null;
    const user = employeeData.items.find((item: any) => item.id === id);
    return user;
  };
  const getDepartmentInformation = (id: string) => {
    if (!department || isDepartmentLoading) return null;
    return findDepartmentById(department, id);
  };

  const [form] = Form.useForm(); // Form instance
  const onFinish = (values: any) => {
    deleteWorkflow(values.currentWorkFlow, {
      onSuccess: () => {
        // Fix: Pass the correct structure for updateWorkflow
        updateWorkflow(
          {
            currentapprovalWorkflowId: values.currentWorkFlow,
            approvalWorkflowId: values.workflow,
          },
          {
            onSuccess: () => {
              setTransferModal(false);
            },
          },
        );
      },
    });
  };

  const MAX_NAME_LENGTH = 40;
  useEffect(() => {
    if (allFilterData?.items && selectedItem?.id) {
      const foundItem = allFilterData?.items?.find(
        (item: any) => item.id === selectedItem?.id,
      );

      if (foundItem) {
        setSelectedItem(foundItem);
        setLevel(foundItem?.approvers ? foundItem?.approvers?.length : '-');
      }
    }
  }, [allFilterData?.items, selectedItem]);

  useEffect(() => {
    if (transferModal) {
      form.resetFields();
      if (deletedItem) {
        form.setFieldsValue({
          currentWorkFlow: deletedItem,
          workflow: undefined,
        });
      }
    }
  }, [transferModal, deletedItem, form]);

  const groupedWorkflowItems =
    !isDataLoading && allFilterData?.items
      ? Object.values(
          allFilterData.items.reduce((acc: Record<string, any>, item: any) => {
            const key = `${item?.entityType || ''}::${item?.entityId || ''}`;
            const existingGroup = acc[key];
            if (!existingGroup) {
              acc[key] = {
                ...item,
                workflows: [item],
              };
              return acc;
            }
            const existingUpdatedAt = new Date(
              existingGroup?.updatedAt || existingGroup?.createdAt || 0,
            ).getTime();
            const currentUpdatedAt = new Date(
              item?.updatedAt || item?.createdAt || 0,
            ).getTime();
            existingGroup.workflows = [
              ...(existingGroup.workflows || []),
              item,
            ];
            // Keep base group fields from the most recently updated workflow.
            if (currentUpdatedAt >= existingUpdatedAt) {
              acc[key] = {
                ...existingGroup,
                ...item,
                workflows: existingGroup.workflows,
              };
            }

            return acc;
          }, {}),
        )
      : [];

  const data =
    !isDataLoading && groupedWorkflowItems
      ? groupedWorkflowItems.map((item: any, index: number) => {
          const employeeInfo = getEmployeeInformation(item?.entityId);
          const departmentInfo = getDepartmentInformation(item?.entityId);

          let appliedToValue = '-';
          if (item?.entityId) {
            if (isDepartmentEntityType(item?.entityType)) {
              appliedToValue = departmentInfo?.name || '-';
            } else if (isUserEntityType(item?.entityType)) {
              const firstName = employeeInfo?.firstName || '';
              const middleName = employeeInfo?.middleName || '';
              appliedToValue =
                firstName && middleName
                  ? `${firstName} ${middleName}`
                  : firstName || middleName || '-';
            } else {
              appliedToValue = item?.entityId;
            }
          }

          const workflowsForCard =
            Array.isArray(item?.workflows) && item.workflows.length > 0
              ? item.workflows
              : [item];

          const renderApproverPills = (
            workflowItem: any,
            workflowIdx: number,
          ) => {
            const sortedApprovers = [...(workflowItem?.approvers ?? [])].sort(
              (a, b) => a.stepOrder - b.stepOrder,
            );
            const showTimelineConnector =
              workflowItem?.approvalWorkflowType !== 'Parallel';

            return (
              <div
                data-cy={`time-attendance-settings-approvals-table-row-${index}-approval-type-${workflowIdx}-approvers`}
                className="w-full overflow-x-auto"
              >
                <div
                  className="flex min-w-max items-center gap-1.5 py-1"
                  data-cy={`time-attendance-settings-approvals-table-row-${index}-approval-type-${workflowIdx}-approvers-row`}
                >
                  {sortedApprovers?.map((employee: any, empIndex: number) => {
                    const employeeInfo = getEmployeeInformation(
                      employee?.userId,
                    );
                    const firstName = employeeInfo?.firstName || '';
                    const middleName = employeeInfo?.middleName || '';

                    const fullName =
                      firstName && middleName
                        ? `${firstName} ${middleName}`
                        : firstName || middleName || 'Unknown User';

                    const displayName =
                      fullName?.length > MAX_NAME_LENGTH
                        ? fullName.slice(0, MAX_NAME_LENGTH) + '...'
                        : fullName;

                    return (
                      <div
                        key={empIndex}
                        className="flex items-center"
                        data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-flow-item`}
                      >
                        {empIndex > 0 && (
                          <>
                            {showTimelineConnector ? (
                              <div
                                className="mx-0.5 inline-flex h-5 min-w-6 items-center justify-center rounded-full border border-[#E3E7FF] bg-[#F7F8FF] px-1 text-[11px] font-semibold text-[#5B67D9]"
                                data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-connector-arrow`}
                              >
                                →
                              </div>
                            ) : (
                              <div
                                className="mx-0.5 inline-flex h-2 w-2 rounded-full bg-[#D9DEF8]"
                                data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-connector-dot`}
                              />
                            )}
                          </>
                        )}
                        <Tooltip
                          title={displayName}
                          placement="top"
                          data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-tooltip`}
                        >
                          <div
                            className="relative h-9 w-9 rounded-full overflow-hidden ring-2 ring-[#EEF0FF] hover:ring-[#C9D0FF] transition-colors cursor-pointer shadow-[0_1px_2px_rgba(16,24,40,0.08)]"
                            id={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-avatar-container`}
                            data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-avatar-container`}
                          >
                            {(() => {
                              const raw = employeeInfo?.profileImage;
                              let avatarSrc: string | null = null;

                              if (typeof raw === 'string' && raw.trim()) {
                                try {
                                  const parsed = JSON.parse(raw);
                                  if (
                                    parsed?.url &&
                                    typeof parsed.url === 'string' &&
                                    parsed.url.startsWith('http')
                                  ) {
                                    avatarSrc = parsed.url;
                                  }
                                } catch {
                                  if (raw.startsWith('http')) avatarSrc = raw;
                                }
                              }

                              return avatarSrc ? (
                                <Image
                                  unoptimized
                                  src={avatarSrc}
                                  alt={displayName || 'User profile'}
                                  fill
                                  className="object-cover"
                                  data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-avatar`}
                                />
                              ) : (
                                <div
                                  data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-${workflowIdx}-${empIndex}-avatar-default-container`}
                                  className="h-full w-full flex items-center justify-center bg-[#f0f0f0]"
                                >
                                  <Avatar size={30} icon={<UserOutlined />} />
                                </div>
                              );
                            })()}
                          </div>
                        </Tooltip>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          };

          const renderWorkflowAction = (
            workflowItem: any,
            workflowIdx: number,
          ) => {
            const canAdd = AccessGuard.checkAccess({
              permissions: [Permissions.CreateApprover],
            });
            const canEdit = AccessGuard.checkAccess({
              permissions: [Permissions.UpdateApprover],
            });
            const canDelete = AccessGuard.checkAccess({
              permissions: [Permissions.DeleteApprover],
            });

            const menuItems = [
              canAdd
                ? {
                    key: 'add',
                    label: (
                      <span
                        data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-add-approver-label`}
                      >
                        Add Approver
                      </span>
                    ),
                    icon: (
                      <FaPlus
                        data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-add-approver-icon`}
                      />
                    ),
                  }
                : null,
              canEdit
                ? {
                    key: 'edit',
                    label: (
                      <span
                        data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-edit-approver-label`}
                      >
                        Edit Approver
                      </span>
                    ),
                    icon: (
                      <FaPencil
                        data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-edit-approver-icon`}
                      />
                    ),
                  }
                : null,
              canDelete
                ? {
                    key: 'delete',
                    label: (
                      <span
                        data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-delete-approver-label`}
                      >
                        Delete Workflow
                      </span>
                    ),
                    icon: (
                      <RiDeleteBin6Line
                        data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-delete-approver-icon`}
                      />
                    ),
                  }
                : null,
            ].filter(Boolean);

            if (!menuItems.length) {
              return (
                <span
                  data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-no-actions`}
                />
              );
            }

            return (
              <Dropdown
                trigger={['click']}
                placement="bottomRight"
                menu={{
                  items: menuItems as any,
                  onClick: ({ key }) => {
                    if (key === 'add') {
                      setAddModal(true);
                      setSelectedItem(workflowItem);
                      setLevel(1);
                      setApproverType(
                        workflowItem?.approvalWorkflowType
                          ? workflowItem?.approvalWorkflowType
                          : '-',
                      );
                    }

                    if (key === 'edit') {
                      setEditModal(true);
                      setSelectedItem(workflowItem);
                      setLevel(
                        workflowItem?.approvers
                          ? workflowItem?.approvers?.length
                          : '-',
                      );
                      setWorkflowApplies(
                        workflowItem?.entityType
                          ? workflowItem?.entityType
                          : '-',
                      );
                      setApproverType(
                        workflowItem?.approvalWorkflowType
                          ? workflowItem?.approvalWorkflowType
                          : '-',
                      );
                    }

                    if (key === 'delete') {
                      setDeleteModal(true);
                      setDeletedItem(workflowItem?.id);
                    }
                  },
                }}
                data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-actions-dropdown`}
              >
                <Button
                  type="default"
                  className="h-8 w-8 border-0 bg-[#FAFAFA] shadow-none hover:!bg-[#F2F2F2]"
                  data-cy={`time-attendance-settings-approvals-table-row-${index}-workflow-${workflowIdx}-actions-trigger`}
                >
                  <MoreHorizIcon />
                </Button>
              </Dropdown>
            );
          };

          return {
            key: index,
            workflow_name: '',
            applied_to: appliedToValue,

            assigned: (
              <div
                className="flex flex-col gap-3"
                id={`time-attendance-settings-approvals-table-row-${index}-assigned-container`}
                data-cy={`time-attendance-settings-approvals-table-row-${index}-assigned-container`}
              >
                {workflowsForCard.map(
