    if (actionTypesArray.includes(AttendanceActionType.SALARY_DEDUCTION)) {
      const isMinuteBased =
        selectedRule?.ruleType === AttendanceRuleType.LATE &&
        form.getFieldValue('isMinuteBasedSalaryDeduction') === true;

