export default CourseAddLessonSidebar;

'use client';

import { Spin } from 'antd';
import LessonSectionInlineEdit from './lessonSectionInlineEdit';
import InlineAddCourseMaterialWizard from './inlineAddCourseMaterialWizard';
import InlineCreateLessonForm from './inlineCreateLessonForm';
import { useTnaManagementCoursePageStore } from '@/store/uistate/features/tna/management/coursePage';
import {
  type CourseLesson as CourseLessonModel,
  type CourseLessonMaterial,
} from '@/types/tna/course';
import { useEffect, useMemo, useRef, useState } from 'react';
import LessonCard from './lessonCard';
import {
  DndContext,
  DragEndEvent,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { useSetCourseLesson } from '@/store/server/features/tna/lesson/mutation';
import SortableLessonPanel from './sortableLessonPanel';

const CourseLesson = () => {
  const {
    course,
    lesson,
    refetchCourse,
    isShowAddLesson,
    isShowLessonMaterial,
    activeKey,
    setActiveKey,
    setLesson,
    setLessonMaterial,
  } = useTnaManagementCoursePageStore();

  const { mutate: setLessons, isLoading: isReorderingLessons } =
    useSetCourseLesson();

  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [addingMaterialLessonId, setAddingMaterialLessonId] = useState<
    string | null
  >(null);
  const [inlineEditingMaterial, setInlineEditingMaterial] =
    useState<CourseLessonMaterial | null>(null);
  /** Add-from-section vs material-list edit; ref so value survives wizard onClose before onMaterialCreated. */
  const materialWizardFromSectionRef = useRef(false);

  const sortedLessonsFromCourse = useMemo(
    () =>
      [...(course?.courseLessons ?? [])].sort(
        (a, b) => a.order - b.order || a.id.localeCompare(b.id),
      ),
    [course?.courseLessons],
  );

  const [orderedLessons, setOrderedLessons] = useState<CourseLessonModel[]>(
    sortedLessonsFromCourse,
  );

  useEffect(() => {
    setOrderedLessons(sortedLessonsFromCourse);
  }, [sortedLessonsFromCourse]);

  const lessonSensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  useEffect(() => {
    if ((!isShowAddLesson || !isShowLessonMaterial) && refetchCourse) {
      refetchCourse();
    }
  }, [isShowAddLesson, isShowLessonMaterial]);

  // Only expand the first lesson by default on initial load (by sort order)
  const hasSetDefault = useRef(false);
  useEffect(() => {
    const firstId = sortedLessonsFromCourse[0]?.id;
    if (
      !hasSetDefault.current &&
      (!activeKey || (Array.isArray(activeKey) && activeKey.length === 0)) &&
      firstId
    ) {
      setActiveKey(String(firstId));
      hasSetDefault.current = true;
    }
  }, [sortedLessonsFromCourse, activeKey, setActiveKey]);

  const handleLessonDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) {
      return;
    }
    const oldIndex = orderedLessons.findIndex((l) => l.id === active.id);
    const newIndex = orderedLessons.findIndex((l) => l.id === over.id);
    if (oldIndex < 0 || newIndex < 0) {
      return;
    }
    const next = arrayMove(orderedLessons, oldIndex, newIndex);
    setOrderedLessons(next);
    const payload = next.map((l, index) => {
      const { courseLessonMaterials: unusedMaterials, ...rest } = l;
      void unusedMaterials;
      return { ...rest, order: index };
    });
    setLessons(payload, {
      onSuccess: () => {
        void refetchCourse?.();
      },
      onError: () => {
        void refetchCourse?.();
      },
    });
  };

  const toggleLessonPanel = (lessonId: string) => {
    const key = String(lessonId);
    if (String(activeKey) === key) {
      setActiveKey(undefined);
    } else {
      setActiveKey(key);
    }
  };

  const startEditingSection = (lessonId: string) => {
    setEditingLessonId(String(lessonId));
    setActiveKey(String(lessonId));
  };

  const renderLessonBody = (lesson: CourseLessonModel) => {
    const isEditingSection = editingLessonId === String(lesson.id);
    const isAddingMaterial = addingMaterialLessonId === String(lesson.id);
    return (
      <div data-cy="tna-course-lesson-collapse-body">
        {isAddingMaterial ? (
          <InlineAddCourseMaterialWizard
            lesson={lesson}
            editingMaterial={
              inlineEditingMaterial?.courseLessonId === lesson.id
                ? inlineEditingMaterial
                : null
            }
            onClose={() => {
              setAddingMaterialLessonId(null);
              setInlineEditingMaterial(null);
              materialWizardFromSectionRef.current = false;
            }}
            onMaterialCreated={() => {
              if (materialWizardFromSectionRef.current) {
                setEditingLessonId(String(lesson.id));
                const scrollToLessonSection = () => {
                  document
                    .getElementById(
                      `tna-course-lesson-section-edit-${lesson.id}`,
                    )
                    ?.scrollIntoView({
                      behavior: 'smooth',
                      block: 'center',
                    });
                };
                window.requestAnimationFrame(() => {
                  window.requestAnimationFrame(scrollToLessonSection);
                });
              } else {
                setEditingLessonId(null);
                const scrollToMaterials = () => {
                  document
                    .getElementById(`tnaLessonCard${lesson.id}Id`)
                    ?.scrollIntoView({
                      behavior: 'smooth',
                      block: 'start',
                    });
                };
                window.requestAnimationFrame(() => {
                  window.requestAnimationFrame(scrollToMaterials);
                });
              }
              materialWizardFromSectionRef.current = false;
            }}
          />
        ) : isEditingSection ? (
          <LessonSectionInlineEdit
            lesson={lesson}
            onCancel={() => {
              setEditingLessonId(null);
              setAddingMaterialLessonId(null);
              setInlineEditingMaterial(null);
            }}
            onAddCourseMaterial={() => {
              materialWizardFromSectionRef.current = true;
              setLesson(lesson);
              setLessonMaterial(null);
              setInlineEditingMaterial(null);
              setAddingMaterialLessonId(String(lesson.id));
            }}
          />
        ) : null}
        {!isAddingMaterial ? (
          <LessonCard
            lesson={lesson}
            onEditMaterial={(material) => {
              materialWizardFromSectionRef.current = false;
              setActiveKey(String(lesson.id));
              setAddingMaterialLessonId(String(lesson.id));
              setInlineEditingMaterial(material);
            }}
            onAddMaterial={() => {
              materialWizardFromSectionRef.current = false;
              setActiveKey(String(lesson.id));
              setInlineEditingMaterial(null);
              setAddingMaterialLessonId(String(lesson.id));
            }}
          />
        ) : null}
      </div>
    );
  };

  const lessonSortableIds = orderedLessons.map((l) => l.id);
  const showInlineCreateLesson = Boolean(isShowAddLesson && !lesson);
  const hasLessons = orderedLessons.length > 0;
  const showEmptyState = !hasLessons && !showInlineCreateLesson;

  return (
    <div id="tnaCourseLessonContainerId" data-cy="tna-course-lesson-container">
      {showInlineCreateLesson ? <InlineCreateLessonForm /> : null}
      <Spin spinning={isReorderingLessons}>
        {showEmptyState ? (
          <div
            className="flex min-h-[280px] items-center justify-center px-4 py-12 text-center"
            data-cy="tna-course-lesson-empty-state"
          >
            <p
              className="max-w-md font-bold text-gray-800"
              data-cy="tna-course-lesson-empty-state-message"
            >
              You have No Lessons Please add a Lesson to continue
            </p>
          </div>
        ) : hasLessons ? (
          <div
            className="flex flex-col bg-transparent shadow-none"
            data-cy="tna-course-lesson-collapse"
          >
            <div
              className="flex flex-col gap-3 sm:gap-4"
              data-cy="tna-course-lesson-dnd-context"
            >
              <DndContext
                sensors={lessonSensors}
                onDragEnd={handleLessonDragEnd}
              >
                <SortableContext
                  items={lessonSortableIds}
                  strategy={verticalListSortingStrategy}
                >
                  {orderedLessons.map((lesson) => {
                    const isEditingSection =
                      editingLessonId === String(lesson.id);
                    const isAddingMaterial =
                      addingMaterialLessonId === String(lesson.id);
                    return (
                      <SortableLessonPanel
                        key={lesson.id}
                        lesson={lesson}
                        isExpanded={String(activeKey) === String(lesson.id)}
                        onToggle={toggleLessonPanel}
                        isEditingSection={isEditingSection}
                        isAddingMaterial={isAddingMaterial}
                        onStartEditSection={startEditingSection}
                      >
                        {renderLessonBody(lesson)}
                      </SortableLessonPanel>
                    );
                  })}
                </SortableContext>
              </DndContext>
            </div>
          </div>
        ) : null}
      </Spin>
    </div>
  );
};

export default CourseLesson;

'use client';

import { CourseLesson, CourseLessonMaterial } from '@/types/tna/course';
import { FC, useCallback, useEffect, useState } from 'react';
import { Button, Form, Spin } from 'antd';
import CustomLabel from '@/components/form/customLabel/customLabel';
import { useTnaManagementCoursePageStore } from '@/store/uistate/features/tna/management/coursePage';
import { useSetCourseLessonMaterial } from '@/store/server/features/tna/lessonMaterial/mutation';
import { formatLinkToUploadFile } from '@/helpers/formatTo';
import { classNames } from '@/utils/classNames';
import {
  CourseMaterialArticleFormItem,
  CourseMaterialAttachmentsFormItem,
  CourseMaterialDescriptionFormItem,
  CourseMaterialImagesFormItem,
  CourseMaterialReferenceMaterialsFormItem,
  CourseMaterialTimeFormItem,
  CourseMaterialTitleFormItem,
  CourseMaterialVideosFormItem,
  courseMaterialTimeValidationRules,
  courseMaterialVideoUploadIcon,
} from './courseMaterialFormFields';
import { LuGripVertical } from 'react-icons/lu';

const STEP_LABELS = [
  'Material Details',
  'Article',
  'Video',
  'Attachments',
  'References',
  'Images',
] as const;

/** Payload shape for nested `courseLessonMaterials` on lesson create/update. */
export type NestedLessonMaterialDraftPayload = {
  title: string;
  description: string | null;
  article: string | null;
  videos: string[];
  attachments: string[];
  referenceMaterials: string[];
  images: string[];
  order: number;
  timeToFinishMinutes: number;
};

interface InlineAddCourseMaterialWizardProps {
  lesson: CourseLesson;
  /** When set, the wizard updates this material (same stepper as add). */
  editingMaterial?: CourseLessonMaterial | null;
  /** When `draftMode`, pre-fill from a pending nested payload (inline lesson create). */
  editingDraft?: NestedLessonMaterialDraftPayload | null;
  /** With `editingDraft`, commit passes this id to `onDraftMaterialCommit` so the parent can replace the row. */
  draftEditingClientId?: string | null;
  onClose: () => void;
  /** After successful create or update; wizard is closed first. */
  onMaterialCreated?: () => void;
  /**
   * When true, Finish does not call the material API — calls `onDraftMaterialCommit`
   * (e.g. lesson not persisted yet; materials sent with lesson PUT).
   */
  draftMode?: boolean;
  /** `order` values of materials already queued in this draft session (for next order). */
  draftMaterialOrders?: number[];
  /** When editing a pending row, `replaceClientId` is the stable client id for that row. */
  onDraftMaterialCommit?: (
    material: NestedLessonMaterialDraftPayload,
    replaceClientId?: string,
  ) => void;
  /** When `draftMode`: lesson title from the inline create form (may be empty until filled). */
  draftLessonTitle?: string;
}

/** New inline materials sort first in the list (`LessonCard` uses ascending `order`). */
const getNewMaterialOrderForTop = (orders: number[]): number => {
  if (!orders.length) {
    return 0;
  }
  const minOrder = Math.min(...orders);
  if (minOrder > 0) {
    return minOrder / 2;
  }
  if (minOrder === 0) {
    return -1;
  }
  return minOrder - 1;
};

const InlineAddCourseMaterialWizard: FC<InlineAddCourseMaterialWizardProps> = ({
  lesson,
  editingMaterial = null,
  editingDraft = null,
  draftEditingClientId = null,
  onClose,
  onMaterialCreated,
  draftMode = false,
  draftMaterialOrders = [],
  onDraftMaterialCommit,
  draftLessonTitle = '',
}) => {
  const { refetchCourse, isFileUploadLoading } =
    useTnaManagementCoursePageStore();
  const { mutate: setMaterial, isLoading: isSavingMaterial } =
    useSetCourseLessonMaterial();
  const apiLoading = draftMode ? false : isSavingMaterial;
  const [form] = Form.useForm();
  const [step, setStep] = useState(0);

  useEffect(() => {
    form.resetFields();
    setStep(0);
    if (editingMaterial) {
      form.setFieldsValue({
        title: editingMaterial.title,
        description: editingMaterial.description ?? '',
        article: editingMaterial.article ?? '',
        timeToFinishMinutes: editingMaterial.timeToFinishMinutes ?? undefined,
        videos: editingMaterial.videos?.length
          ? editingMaterial.videos.map((v) => formatLinkToUploadFile(v))
          : undefined,
        attachments: editingMaterial.attachments?.length
          ? editingMaterial.attachments.map((a) => formatLinkToUploadFile(a))
          : undefined,
        referenceMaterials: editingMaterial.referenceMaterials?.length
          ? editingMaterial.referenceMaterials.map((r) =>
              formatLinkToUploadFile(r),
            )
          : undefined,
        images: editingMaterial.images?.length
          ? editingMaterial.images.map((i) => formatLinkToUploadFile(i))
          : undefined,
      });
    } else if (editingDraft) {
      form.setFieldsValue({
        title: editingDraft.title,
        description: editingDraft.description ?? '',
        article: editingDraft.article ?? '',
        timeToFinishMinutes: editingDraft.timeToFinishMinutes ?? undefined,
        videos: editingDraft.videos?.length
          ? editingDraft.videos.map((v) => formatLinkToUploadFile(v))
          : undefined,
        attachments: editingDraft.attachments?.length
          ? editingDraft.attachments.map((a) => formatLinkToUploadFile(a))
          : undefined,
        referenceMaterials: editingDraft.referenceMaterials?.length
          ? editingDraft.referenceMaterials.map((r) =>
              formatLinkToUploadFile(r),
            )
          : undefined,
        images: editingDraft.images?.length
          ? editingDraft.images.map((i) => formatLinkToUploadFile(i))
          : undefined,
      });
    }
  }, [lesson.id, editingMaterial, editingDraft, form]);

  const handleFinish = useCallback(() => {
    // `true` = full store; unmounted steps stay out of default getFieldsValue() even with preserve.
    const values = form.getFieldsValue(true);
    const courseLessonMaterials = lesson.courseLessonMaterials ?? [];
    const title = String(values.title ?? '').trim();
    const minutesRaw = values.timeToFinishMinutes;
    const minutesStr = String(minutesRaw ?? '').trim();
    const minutesParsed = minutesStr === '' ? NaN : Number(minutesStr);
    const timeToFinishMinutes =
      Number.isFinite(minutesParsed) &&
      Number.isInteger(minutesParsed) &&
      minutesParsed >= 1
        ? minutesParsed
        : null;

    if (!title || timeToFinishMinutes === null) {
      return;
    }

    const ordersForNew = draftMode
      ? draftMaterialOrders
      : (courseLessonMaterials ?? []).map((m) => m.order);

    const order = editingMaterial
      ? editingMaterial.order
      : editingDraft
        ? editingDraft.order
        : getNewMaterialOrderForTop(ordersForNew);

    const toLinks = (files: { response?: string }[] | undefined): string[] =>
      files
        ?.map((file) => file.response)
        .filter((link): link is string => !!link) ?? [];

    const videos = toLinks(values.videos);
    const attachments = toLinks(values.attachments);
    const referenceMaterials = toLinks(values.referenceMaterials);
    const images = toLinks(values.images);

    if (draftMode) {
      const strOrNull = (v: unknown) => {
        const s = String(v ?? '').trim();
        return s === '' ? null : s;
      };
      onDraftMaterialCommit?.(
        {
          title,
          description: strOrNull(values.description),
          article: strOrNull(values.article),
          timeToFinishMinutes,
          order,
          videos,
          attachments,
          referenceMaterials,
          images,
        },
        draftEditingClientId ?? undefined,
      );
      onMaterialCreated?.();
      onClose();
      return;
    }

    setMaterial(
      [
        {
          ...(editingMaterial ?? {}),
          title,
          description: values.description,
          article: values.article,
          timeToFinishMinutes,
          order,
          courseLessonId: lesson.id,
          videos,
          attachments,
          referenceMaterials,
          images,
        },
      ],
      {
        onSuccess: () => {
          onMaterialCreated?.();
          onClose();
          void refetchCourse?.();
        },
      },
    );
  }, [
    draftMode,
    draftEditingClientId,
    draftMaterialOrders,
    editingDraft,
    editingMaterial,
    lesson.id,
    lesson.courseLessonMaterials,
    onClose,
    onDraftMaterialCommit,
    onMaterialCreated,
    refetchCourse,
    setMaterial,
  ]);

  const handleCancel = () => {
    form.resetFields();
    onClose();
  };

  const fieldGroups: Record<number, string[]> = {
    0: ['title', 'description', 'timeToFinishMinutes'],
    1: ['article'],
    2: ['videos'],
    3: ['attachments'],
    4: ['referenceMaterials'],
    5: ['images'],
  };

  const handleContinue = async () => {
    try {
      await form.validateFields(fieldGroups[step]);
      setStep((s) => Math.min(s + 1, STEP_LABELS.length - 1));
    } catch {
      /* validated */
    }
  };

  const handleCreate = async () => {
    try {
      await form.validateFields();
      handleFinish();
    } catch {
      /* validated */
    }
  };

  const isLastStep = step === STEP_LABELS.length - 1;

  const stepCount = STEP_LABELS.length;
  const lineProgressFraction =
    step >= stepCount - 1 ? 1 : (step + 0.5) / (stepCount - 1);
  /** Dot centers sit midway in each equal column; line runs between first and last center. */
  const stepTrackInsetPct = 100 / (2 * stepCount);
  const stepTrackSpanPct = (100 * (stepCount - 1)) / stepCount;

  const draftLessonTitleTrimmed = String(draftLessonTitle ?? '').trim();
  const draftLessonTitleDisplay = draftLessonTitleTrimmed || 'Untitled lesson';

  return (
    <div
      className="mb-3 rounded-xl bg-[#F9FAFB] p-4"
      data-cy={
        draftMode && draftEditingClientId
          ? `tna-inline-add-material-wizard-draft-edit-${draftEditingClientId}`
          : draftMode
            ? 'tna-inline-add-material-wizard-draft-lesson'
            : editingMaterial
              ? `tna-inline-edit-material-wizard-${editingMaterial.id}`
              : `tna-inline-add-material-wizard-${lesson.id}`
      }
    >
      {draftMode ? (
        <div
          className="mb-4 flex items-start gap-3 border-b border-gray-100 pb-3"
          data-cy="tna-inline-add-material-wizard-lesson-context"
        >
          <div
            className="mt-0.5 inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md border border-gray-200 bg-white text-gray-400"
            aria-hidden
            data-cy="tna-inline-add-material-wizard-lesson-context-grip"
          >
            <LuGripVertical size={16} className="block shrink-0" />
          </div>
          <div
            className={classNames(
              'min-w-0 flex-1 truncate pt-0.5 text-base font-semibold',
              {
                'text-gray-900': !!draftLessonTitleTrimmed,
                'text-black/45': !draftLessonTitleTrimmed,
              },
            )}
            title={draftLessonTitleDisplay}
            data-cy="tna-inline-add-material-wizard-lesson-context-title"
          >
            {draftLessonTitleDisplay}
          </div>
        </div>
      ) : null}
      <nav
        className="mb-6 w-full"
        aria-label="Material setup steps"
        data-cy="tna-inline-add-material-stepper"
      >
        <div
          className="relative mx-auto w-full max-w-[560px] px-1 sm:px-2"
          data-cy="tna-inline-add-material-stepper-inner"
        >
          <div
            className="pointer-events-none absolute top-[4.5px] h-[3px] rounded-full bg-[#E5E5E5] sm:top-[4.5px]"
            style={{
              left: `${stepTrackInsetPct}%`,
              width: `${stepTrackSpanPct}%`,
            }}
            aria-hidden
            data-cy="tna-inline-add-material-stepper-track-bg"
          />
          <div
            className="pointer-events-none absolute top-[4.5px] h-[3px] rounded-full bg-primary transition-[width] duration-300 ease-out sm:top-[4.5px]"
            style={{
              left: `${stepTrackInsetPct}%`,
              width: `${lineProgressFraction * stepTrackSpanPct}%`,
            }}
            aria-hidden
            data-cy="tna-inline-add-material-stepper-track-progress"
          />
          <div
            className="relative z-[1] flex w-full"
            data-cy="tna-inline-add-material-stepper-dots-row"
          >
            {STEP_LABELS.map((name, i) => {
              const canGoToStep = i <= step;
              return (
                <button
                  key={name}
                  type="button"
                  disabled={!canGoToStep}
                  aria-current={i === step ? 'step' : undefined}
                  aria-label={
                    canGoToStep
                      ? `${i === step ? 'Current step: ' : 'Go to step: '}${name}`
                      : `${name} (complete previous steps first)`
                  }
                  onClick={() => {
                    if (canGoToStep) setStep(i);
                  }}
                  className={classNames(
                    'flex min-w-0 flex-1 flex-col items-center gap-3 border-0 bg-transparent p-0 outline-none transition-opacity',
                    {
                      'cursor-pointer hover:opacity-90 focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 rounded-md':
                        canGoToStep,
                      'cursor-not-allowed': !canGoToStep,
                    },
                  )}
                  data-cy={`tna-inline-add-material-step-dot-${i}`}
                >
                  <span
                    className="sr-only"
                    data-cy={`tna-inline-add-material-step-sr-${i}`}
                  >
                    {`${name}${i === step ? ' (current step)' : ''}${i < step ? ', completed' : ''}`}
                  </span>
                  <div
                    className="flex h-3 shrink-0 items-center justify-center"
                    data-cy={`tna-inline-add-material-step-dot-wrap-${i}`}
                  >
                    <span
                      className={classNames(
                        'block shrink-0 rounded-full border-2 border-white transition-colors',
                        {
                          'h-3 w-3 bg-primary': i === step,
                          'h-2.5 w-2.5 bg-primary': i < step,
                          'h-2.5 w-2.5 bg-[#D9D9D9]': i > step,
                        },
                      )}
                      title={name}
                      aria-hidden
                      data-cy={`tna-inline-add-material-step-dot-visual-${i}`}
                    />
                  </div>
                  <span
                    className={classNames(
                      'w-full px-0.5 text-center text-xs leading-tight sm:text-sm',
                      {
                        'font-medium text-primary': i === step,
                        'font-normal text-primary': i < step,
                        'font-normal text-[#BFBFBF]': i > step,
                      },
                    )}
                    data-cy={`tna-inline-add-material-step-label-${i}`}
                  >
                    {name}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      </nav>

      <Form
        layout="vertical"
        form={form}
        preserve
        requiredMark={CustomLabel}
        disabled={apiLoading}
        id={
          draftMode
            ? 'tnaInlineAddMaterialForm-draft-lesson'
            : `tnaInlineAddMaterialForm-${lesson.id}`
        }
        data-cy="tna-inline-add-material-form"
      >
        {step === 0 ? (
          <>
            <CourseMaterialTitleFormItem itemDataCy="tna-inline-add-material-title" />
            <CourseMaterialDescriptionFormItem itemDataCy="tna-inline-add-material-description" />
            <CourseMaterialTimeFormItem
              itemDataCy="tna-inline-add-material-time"
              variant="native"
              rules={courseMaterialTimeValidationRules}
            />
          </>
        ) : null}

        {step === 1 ? (
          <CourseMaterialArticleFormItem
            itemDataCy="tna-inline-add-material-article"
            editorDataCy="tna-inline-add-material-article-editor"
          />
        ) : null}

        {step === 2 ? (
          <Spin spinning={!!isFileUploadLoading?.video}>
            <CourseMaterialVideosFormItem
              itemDataCy="tna-inline-add-material-video"
              uploadClassName="mt-3 w-full"
              uploadTitle="Click or drag file to this area to upload"
              uploadSubtitle="Add one or more videos via upload or link."
              uploadDataCy="tna-inline-add-material-video-upload"
              uploadIcon={courseMaterialVideoUploadIcon}
            />
          </Spin>
        ) : null}

        {step === 3 ? (
          <Spin spinning={!!isFileUploadLoading?.attachment}>
            <CourseMaterialAttachmentsFormItem
              itemDataCy="tna-inline-add-material-attachment"
              uploadClassName="mt-3 w-full"
              uploadTitle="Click or drag file to this area to upload"
              uploadSubtitle="Support for a single or bulk upload."
              uploadDataCy="tna-inline-add-material-attachment-upload"
              uploadIcon={courseMaterialVideoUploadIcon}
            />
          </Spin>
        ) : null}

        {step === 4 ? (
          <Spin spinning={!!isFileUploadLoading?.reference}>
            <CourseMaterialReferenceMaterialsFormItem
              itemDataCy="tna-inline-add-material-reference"
              uploadClassName="mt-3 w-full"
              uploadTitle="Click or drag file to this area to upload"
              uploadSubtitle="Optional. Add reading material, slide decks or external links."
              uploadDataCy="tna-inline-add-material-reference-upload"
              uploadIcon={courseMaterialVideoUploadIcon}
            />
          </Spin>
        ) : null}

        {step === 5 ? (
          <Spin spinning={!!isFileUploadLoading?.image}>
            <CourseMaterialImagesFormItem
              itemDataCy="tna-inline-add-material-image"
              uploadClassName="mt-3 w-full"
              uploadTitle="Click or drag an image to this area to upload"
              uploadSubtitle="Optional. Diagrams or screenshots shown alongside the session."
              uploadDataCy="tna-inline-add-material-image-upload"
              uploadIcon={courseMaterialVideoUploadIcon}
            />
          </Spin>
        ) : null}

        <div
          className="mt-3 flex flex-col gap-2 border-gray-100 pt-2.5 sm:flex-row sm:items-center sm:justify-end"
          data-cy="tna-inline-add-material-form-footer"
        >
          <div
            className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row sm:justify-end"
            data-cy="tna-inline-add-material-form-footer-actions"
          >
            <Button
              size="middle"
              className="w-full !border-[#D9D9D9] !font-normal !text-black/70 hover:!border-[#D9D9D9] hover:!text-black/70 sm:w-auto"
              onClick={handleCancel}
              disabled={apiLoading}
              data-cy="tna-inline-add-material-cancel"
            >
              Cancel
            </Button>
            {isLastStep ? (
              <Button
                type="primary"
                size="middle"
