                  <Form.Item
                    name="thumbnail"
                    label={
                      <span
                        className="text-[14px] font-normal"
                        data-cy="tna-course-sidebar-label-thumbnail"
                      >
                        Thumbnail
                      </span>
                    }
                    id="tnaCourseThumbnailFieldId"
                    data-cy="tna-course-thumbnail-field"
                    className="form-item"
                    valuePropName="fileList"
                    rules={[{ required: true, message: 'Required' }]}
