                    className="form-item"
                    id="tnaCourseSidebarDepartmentItemId"
                    data-cy="tna-course-sidebar-department-item"
                  >
                    <Spin spinning={isDepartmentLoading}>
                      <TreeSelect
                        treeData={departmentTreeData}
                        treeCheckable
                        showCheckedStrategy={TreeSelect.SHOW_CHILD}
                        className="min-h-[40px] [&_.ant-select-selector]:!min-h-[40px] [&_.ant-select-selector]:!border-[#D9D9D9] [&_.ant-select-selector]:!rounded-[8px] [&_.ant-select-selector]:!py-[4px] [&_.ant-select-selector]:!px-[11px] [&_.ant-select-selection-overflow-item]:!hidden [&_.ant-select-selection-overflow-item-suffix]:!hidden"
                        id="tnaCourseSidebarDepartmentSelectId"
                        data-cy="tna-course-sidebar-department-select"
                        value={selectedDepartmentIds}
                        onChange={(value) =>
                          handleDepartmentChange((value as string[]) ?? [])
                        }
                        placeholder="Select"
                        disabled={isDepartmentSelectDisabled}
                        maxTagCount={0}
                        maxTagPlaceholder={() => null}
                      />
                      {selectedDepartmentIds.length > 0 && (
                        <div
                          className="flex flex-wrap gap-1 mt-1.5"
                          data-cy="tna-course-sidebar-department-tags"
                        >
                          {selectedDepartmentIds.map((deptId) => (
                            <span
                              key={deptId}
                              className="inline-flex items-center h-6 px-2 rounded-[4px] border border-[#D9D9D9] bg-black/[0.02] text-[12px] text-black/70 leading-[22px]"
                              data-cy={`tna-course-sidebar-department-tag-${deptId}`}
                            >
                              {departmentTitleMap.get(String(deptId)) ?? deptId}
                              <button
                                type="button"
                                className="ml-1 text-black/70 leading-none"
                                data-cy={`tna-course-sidebar-department-tag-remove-${deptId}`}
                                onClick={() =>
                                  handleRemoveDepartment(String(deptId))
                                }
                              >
                                x
                              </button>
                            </span>
                          ))}
                        </div>
                      )}
                    </Spin>
                  </Form.Item>
                  {selectedDepartmentIds.length > 0 && (
                    <div
                      data-cy="management-components-coursesidebar-index-tsx-index-div-619"
                      className="space-y-[9px] border-t border-[#D9D9D9] pt-4"
                      id="tnaCourseSidebarAssignmentSectionId"
                    >
                      <div
                        data-cy="management-components-coursesidebar-index-tsx-index-div-620"
                        className="flex items-center justify-between"
                      >
                        <div
                          data-cy="management-components-coursesidebar-index-tsx-index-div-621"
                          className="text-[14px] leading-[22px] font-bold text-black"
                        >
                          Employees Selected ({selectedUserIds.length})
                        </div>
                        <div
                          data-cy="management-components-coursesidebar-index-tsx-index-div-624"
                          className="flex gap-2"
                        >
                          <Button
                            type="link"
                            size="small"
                            className="!text-[14px] !font-normal !text-[#1E40AF] hover:!text-[#1E40AF]"
                            onClick={handleSelectAllUsers}
                            disabled={!availableUsers.length}
                          >
                            Select All
                          </Button>
                          <Button
                            type="link"
                            size="small"
                            className="!text-[14px] !font-normal !text-[#1E40AF] hover:!text-[#1E40AF]"
                            onClick={handleClearUsers}
                            disabled={!selectedUserIds.length}
                          >
                            Clear
                          </Button>
                        </div>
                      </div>
                      <Spin spinning={isUsersLoading}>
                        {!isUsersLoading && availableUsers.length === 0 ? (
                          <Empty
                            image={Empty.PRESENTED_IMAGE_SIMPLE}
                            description="No employees found in the selected departments"
                            className="my-6"
                          />
                        ) : availableUsers.length > 0 ? (
                          <div
                            data-cy="management-components-coursesidebar-index-tsx-index-div-662"
                            className="max-h-[126px] overflow-y-auto space-y-[9px]"
                          >
                            <Checkbox.Group
                              value={selectedUserIds}
                              onChange={handleUserSelectionChange}
                              className="flex flex-col gap-[9px]"
                            >
                              {availableUsers.map((user) => (
                                <Checkbox
                                  key={user.id}
                                  value={String(user.id)}
                                  className="w-full m-0 rounded-[6px] bg-black/[0.06] px-3 py-1"
                                >
                                  <div
                                    data-cy="management-components-coursesidebar-index-tsx-index-div-670"
                                    className="flex flex-col leading-[22px]"
                                  >
                                    <span
                                      data-cy="management-components-coursesidebar-index-tsx-index-span-671"
                                      className="text-[14px] font-normal text-black/70"
                                    >
                                      {getEmployeeName(user)}
                                    </span>
                                    {user?.email && (
                                      <span
                                        data-cy="management-components-coursesidebar-index-tsx-index-span-675"
                                        className="text-[14px] text-black/45"
                                      >
                                        {user.email}
                                      </span>
                                    )}
                                  </div>
                                </Checkbox>
                              ))}
                            </Checkbox.Group>
                          </div>
                        ) : (
                          <div
                            className="min-h-[126px]"
                            data-cy="tna-course-sidebar-employees-placeholder"
                          />
                        )}
                      </Spin>
                    </div>
                  )}
                </Form>
              </div>
            </div>
            <div
              className="flex min-h-[52px] shrink-0 items-center justify-between gap-2 px-6 pb-5 pt-0 font-[Calibri,sans-serif] md:pt-2"
              data-cy="tna-course-sidebar-footer-actions"
            >
              <Button
                type="primary"
                htmlType="button"
                id="tnaCourseSubmitButtonId"
                data-cy="tna-course-submit-button"
                loading={isLoading}
                className="h-8 min-h-8 rounded-lg border-[#1E40AF] bg-[#1E40AF] px-4 !text-sm !font-normal leading-[22px] text-white"
                onClick={() => {
                  setIsDraft(true);
                  form.submit();
                }}
              >
                Save Draft
              </Button>
              <div
                className="flex items-center gap-2 md:gap-3"
                data-cy="tna-course-sidebar-footer-right-buttons"
              >
                <Button
                  htmlType="button"
                  className="h-8 min-h-8 rounded-md border-[#D9D9D9] px-[15px] !text-sm !font-normal leading-[22px] text-black/70 shadow-[0px_2px_0px_rgba(0,0,0,0.02)]"
                  data-cy="tna-course-sidebar-cancel-button"
                  onClick={() => onClose()}
                >
                  Cancel
                </Button>
                <Button
                  type="primary"
                  htmlType="button"
                  className="h-8 min-h-8 rounded-lg border-[#1E40AF] bg-[#1E40AF] px-4 !text-sm !font-normal leading-[22px] text-white"
                  data-cy="tna-course-sidebar-save-button"
                  loading={isLoading || isFetching}
                  onClick={() => {
                    setIsDraft(false);
                    form.submit();
                  }}
                >
                  Save
                </Button>
              </div>
            </div>
          </div>
        )}
      </Modal>
    )
  );
};

export default CourseCategorySidebar;

'use client';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Button } from 'antd';
import { LuPlus } from 'react-icons/lu';
import CourseCategorySidebar from './_components/courseSidebar';
import { useTnaManagementStore } from '@/store/uistate/features/tna/management';
import { useGetCourseCategory } from '@/store/server/features/tna/courseCategory/queries';
import {
  useGetCoursesManagement,
  useGetMyCourses,
} from '@/store/server/features/tna/management/queries';
import CourseFilter from '@/app/(afterLogin)/(tna)/tna/management/_components/courseFilter';
import { CommonObject } from '@/types/commons/commonObject';
import { useDebounce } from '@/utils/useDebounce';
import { CourseManagementRequestBody } from '@/store/server/features/tna/management/interface';
import CourseCard from '@/app/(afterLogin)/(tna)/tna/management/_components/courseCard';
import AccessGuard from '@/utils/permissionGuard';
import { Permissions } from '@/types/commons/permissionEnum';
import { localUserID } from '@/utils/constants';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import TnaManagementSkeleton from './_components/tnaManagementSkeleton';
import EmptyState from '@/components/empty';
import CustomBreadcrumb from '@/components/common/breadCramp';
import ExternalTnaCard from '@/app/(afterLogin)/(tna)/tna/management/_components/externalTnaCard';
import MyCommitmentsPanel from '@/app/(afterLogin)/(tna)/tna/management/_components/myCommitmentsPanel';
import { useExternalTrainingStore } from '@/store/uistate/features/tna/externalTraining';
import {
  useGetTrainingRequests,
  useGetTrainingRequestsByUser,
} from '@/store/server/features/tna/externalTraining/queries';
import { useGetTrainingApprovalsAllStatus } from '@/store/server/features/tna/trainingApproval/queries';
import { TnaSourceType } from '@/types/tna/externalTna';

const TnaManagementPage = () => {
  const {
    setIsShowCourseSidebar,
    isShowCourseSidebar,
    setCourseCategory,
    setCourseId,
  } = useTnaManagementStore();
  const {
    sourceTypeFilter,
    setSourceTypeFilter,
    setCreateModalTab,
    setTrainingRequestId,
  } = useExternalTrainingStore();
  const { userId } = useAuthenticationStore();
  const { data: categoryData, isFetching } = useGetCourseCategory({});
  const [filter, setFilter] = useState<Partial<CourseManagementRequestBody>>(
    {},
  );

  // Check if user has ViewAllCourse permission
  const hasViewAllCoursePermission = AccessGuard.checkAccess({
    permissions: [Permissions.ViewAllCourse],
  });

  const canCreateCourse = AccessGuard.checkAccess({
    permissions: [Permissions.CreateCourse],
  });

  // Fetch all courses for users with ViewAllCourse permission
  const {
    data: allCoursesData,
    isLoading: isLoadingAllCourses,
    refetch: refetchAllCourses,
  } = useGetCoursesManagement(filter, true, hasViewAllCoursePermission);

  // Fetch only assigned courses for users without ViewAllCourse permission
  const {
    data: myCoursesData,
    isLoading: isLoadingMyCourses,
    refetch: refetchMyCourses,
  } = useGetMyCourses(userId ?? '', !hasViewAllCoursePermission);
  // Use the appropriate data based on permission
  // Note: /learning/course returns {items: [...]} but /my-courses returns [...] directly
  const isLoading = hasViewAllCoursePermission
    ? isLoadingAllCourses
    : isLoadingMyCourses;
  const refetch = hasViewAllCoursePermission
    ? refetchAllCourses
    : refetchMyCourses;

  // Normalize the data format - handle both {items: [...]} and direct array [...]
  const normalizedCourses = hasViewAllCoursePermission
    ? (allCoursesData?.items ?? [])
    : Array.isArray(myCoursesData)
      ? myCoursesData
      : (myCoursesData?.items ?? []);

  /**
   * External (non-catalogue) TNAs: employees see their own, approvers also see
   * what is routed to them, and anyone who can act on a request org-wide sees
   * everything. Recording payment and confirming are permission-driven rather
   * than tied to the workflow, so those holders need the whole list to reach
   * the requests they are meant to act on.
   */
  const hasViewAllTnaPermission =
    AccessGuard.checkAccess({ permissions: [Permissions.ViewAllTna] }) ||
    AccessGuard.checkAccess({
      permissions: [Permissions.MarkTrainingAsPaid],
    }) ||
    AccessGuard.checkAccess({
      permissions: [Permissions.ConfirmTnaCommitment],
    });

  const canCreateExternalTna = AccessGuard.checkAccess({
    permissions: [Permissions.CreateExternalTna],
  });

  const externalSearch = filter.modifiers?.search
    ? { modifiers: { search: filter.modifiers.search } }
    : {};

  const {
    data: allExternalData,
    isLoading: isLoadingAllExternal,
    refetch: refetchAllExternal,
  } = useGetTrainingRequests(
    { page: 1, limit: 200 },
    externalSearch,
    hasViewAllTnaPermission,
  );

  const {
    data: myExternalData,
    isLoading: isLoadingMyExternal,
    refetch: refetchMyExternal,
  } = useGetTrainingRequestsByUser(userId ?? '', !hasViewAllTnaPermission);

  /**
   * Requests routed to this user as an approver. Approval duty is workflow
   * data, not a permission, so this is the only thing that decides whether an
   * approver may see someone else's external TNA. The all-status feed keeps
   * returning a request after it has been decided, so an approver retains a
   * read-only view of their own decisions.
   */
  const { data: approverExternalData, refetch: refetchApproverExternal } =
    useGetTrainingApprovalsAllStatus(userId ?? '', 1, 200);

  // `by-user` returns a bare array; the paginated list returns `{ items }`.
  const externalItems = useMemo(() => {
    if (hasViewAllTnaPermission) return allExternalData?.items ?? [];

    const own = myExternalData ?? [];
    const toApprove =
      approverExternalData?.data?.items ?? approverExternalData?.items ?? [];

    // A user can be both requester and approver on different requests.
    const byId = new Map<string, any>();
    [...own, ...toApprove].forEach((item: any) => {
      if (item?.id && !byId.has(item.id)) byId.set(item.id, item);
    });
    return Array.from(byId.values());
  }, [
    hasViewAllTnaPermission,
    allExternalData?.items,
    myExternalData,
    approverExternalData,
  ]);
  const isLoadingExternal = hasViewAllTnaPermission
    ? isLoadingAllExternal
    : isLoadingMyExternal;
  // Memoised: an effect below depends on this, so a fresh function identity
  // each render would put it into a refetch loop.
  const refetchExternal = useCallback(() => {
    if (hasViewAllTnaPermission) {
      refetchAllExternal();
      return;
    }
    // Non-admins draw on two feeds — their own requests and the ones they
    // approve — so both have to be refreshed.
    refetchMyExternal();
    refetchApproverExternal();
  }, [
    hasViewAllTnaPermission,
    refetchAllExternal,
    refetchMyExternal,
    refetchApproverExternal,
  ]);

  const displayCourses = useMemo(() => {
    if (sourceTypeFilter === TnaSourceType.EXTERNAL) return [];
    return normalizedCourses.filter((item) => {
      if (hasViewAllCoursePermission) return true;
      if (item.isDraft) return item.preparedBy === localUserID;
      return true;
    });
  }, [normalizedCourses, hasViewAllCoursePermission, sourceTypeFilter]);

  const displayExternalTnas = useMemo(() => {
    if (sourceTypeFilter === TnaSourceType.INTERNAL) return [];
    // Course categories are a catalogue concept, so that filter excludes externals.
    if (filter.filter?.courseCategoryId?.length) return [];
    return externalItems;
  }, [externalItems, sourceTypeFilter, filter.filter?.courseCategoryId]);

  const totalResults = displayCourses.length + displayExternalTnas.length;

  const hasActiveFilters = Boolean(
    filter.modifiers?.search ||
    filter.filter?.courseCategoryId?.length ||
    sourceTypeFilter,
  );

  const openCreateModal = (tab: TnaSourceType) => {
    setCourseId(null);
    setTrainingRequestId(null);
    setCreateModalTab(tab);
    setIsShowCourseSidebar(true);
  };

  useEffect(() => {
    if (!isShowCourseSidebar) {
      refetch();
      refetchExternal();
    }
  }, [isShowCourseSidebar, refetch, refetchExternal]);

  useEffect(() => {
    if (categoryData?.items) {
      setCourseCategory(categoryData.items);
    }
  }, [categoryData, setCourseCategory]);

  const onFilterChange = useDebounce((value: CommonObject) => {
    const nFilter: Partial<CourseManagementRequestBody> = {};

    if (value.search && value.search.trim().length > 0) {
      nFilter['modifiers'] = {
        search: `%${value.search.trim()}%`,
      };
    }

    if (value.courseCategoryId) {
      nFilter['filter'] = {
        courseCategoryId: [value.courseCategoryId],
      };
    }

    setFilter(nFilter);
  }, 500);

  return (
    <div
      className="tna-page-wrap bg-white -mx-2 w-[calc(100%+1rem)] max-w-none sm:-mx-4 sm:w-[calc(100%+2rem)]"
      id="tnaManagementPageId"
      data-cy="tna-management-page"
    >
      <div
        className="flex w-1130 mx-auto flex-col items-center gap-5 px-3 py-6 sm:px-4 md:items-start"
        data-cy="tna-management-page-frame"
      >
        <header
          className="flex w-full max-w-[408px] flex-col items-center gap-4 md:max-w-none"
          data-cy="tna-management-page-header-band"
        >
          <div
            className="min-h-[58px] w-full"
            data-cy="tna-management-page-header-row"
          >
            <div
              className="min-w-0 w-full md:max-w-none"
              data-cy="tna-management-page-header-content"
            >
              <CustomBreadcrumb
                title={
                  <span data-cy="tna-management-page-title">
                    Learning and Growth
                  </span>
                }
                subtitle={
                  <nav
                    className="flex flex-row flex-wrap items-center text-sm leading-[22px] font-[Calibri,sans-serif]"
                    aria-label="Breadcrumb"
                    data-cy="tna-management-page-breadcrumb"
                  >
                    <span
                      className="text-black/45"
                      data-cy="tna-management-page-breadcrumb-segment-first"
                    >
                      Learning and Growth
                    </span>
                    <span
                      className="text-black/45 px-2"
                      data-cy="tna-management-page-breadcrumb-separator"
                    >
                      /
                    </span>
                    <span
                      className="text-black/70"
                      data-cy="tna-management-page-breadcrumb-segment-current"
                    >
                      Learning Management
                    </span>
                  </nav>
                }
                titleExtra={
                  <div
                    id="tnaManagementPageHeaderActionsId"
                    className="shrink-0"
                    data-cy="tna-management-page-header-actions"
                  >
                    <AccessGuard
                      permissions={[
                        Permissions.CreateCourse,
                        Permissions.CreateExternalTna,
                      ]}
                      data-cy="tna-management-create-course-guard"
                      id="tna-management-create-course-guard"
                    >
                      <Button
                        id="tnaAddCourseActionButtonId"
                        data-cy="tna-add-course-action-button"
                        type="primary"
                        size="large"
                        className="!flex !h-10 !w-10 !min-w-10 !items-center !justify-center !rounded-lg !border-none !bg-[#1E40AF] !p-0 !text-white shadow-none md:!h-10 md:!min-w-[135px] md:!w-auto md:!px-[15px] font-[Calibri,sans-serif] [&_.ant-btn-icon]:text-white md:text-base md:font-normal md:leading-6"
                        icon={<LuPlus size={18} className="text-white" />}
                        loading={isFetching}
                        onClick={() =>
                          openCreateModal(
                            canCreateCourse
                              ? TnaSourceType.INTERNAL
                              : TnaSourceType.EXTERNAL,
                          )
                        }
                      >
                        <span
                          className="hidden md:inline"
                          data-cy="tna-management-add-course-button-text"
                        >
                          New Course
                        </span>
                      </Button>
                    </AccessGuard>
                  </div>
                }
              />
            </div>
          </div>
        </header>

        <div
          className="box-border flex w-full max-w-[404px] flex-col gap-4 md:max-w-none"
          data-cy="tna-management-main-panel"
        >
          <MyCommitmentsPanel data-cy="tna-management-my-commitments" />

          <div className="w-full" data-cy="tna-management-filter-wrap">
            <CourseFilter
              onChange={onFilterChange}
              sourceType={sourceTypeFilter}
              onSourceTypeChange={setSourceTypeFilter}
              data-cy="tna-management-filter"
            />
          </div>

          {isLoading || isLoadingExternal ? (
            <div
              className="w-full"
              id="tnaManagementLoadingId"
              data-cy="tna-management-loading"
            >
              <TnaManagementSkeleton />
            </div>
          ) : totalResults === 0 ? (
            <div
              className="w-full"
              data-cy="tna-management-courses-empty"
              id="tnaManagementCoursesEmptyId"
            >
              <EmptyState
                title="No TNAs found"
                description={
                  hasActiveFilters
                    ? 'Try adjusting your search, type or category filter.'
                    : 'When courses and training requests are available, they will appear here.'
                }
                actionText={
                  canCreateCourse || canCreateExternalTna
                    ? 'New TNA'
                    : undefined
                }
                onAction={
                  canCreateCourse || canCreateExternalTna
                    ? () =>
                        openCreateModal(
                          canCreateCourse
                            ? TnaSourceType.INTERNAL
                            : TnaSourceType.EXTERNAL,
                        )
                    : undefined
                }
              />
            </div>
          ) : (
            <div
              className="col-span-12 "
              data-cy="settings-recognition-tabs-container"
              id="settingsRecognitionTabsContainer"
            >
              <div
                className="grid w-full max-w-[380px] grid-cols-1 gap-[32px] md:max-w-none md:grid-cols-2 xl:grid-cols-3"
                data-cy="settings-recognition-grid"
              >
                {displayExternalTnas.map((item) => (
                  <ExternalTnaCard
                    item={item}
                    key={item.id}
                    refetch={refetchExternal}
                    onEdit={(request) => {
                      setTrainingRequestId(request.id);
                      setCreateModalTab(TnaSourceType.EXTERNAL);
                      setIsShowCourseSidebar(true);
                    }}
                  />
                ))}
                {displayCourses.map((item) => (
                  <CourseCard
                    item={item}
                    key={item.id}
                    refetch={refetch}
                    data-cy={`tna-management-course-card-${item.id}`}
                  />
                ))}
              </div>
            </div>
          )}
        </div>

        <CourseCategorySidebar data-cy="tna-management-course-category-sidebar" />
      </div>
    </div>
  );
};

export default TnaManagementPage;

import CustomDrawerFooterButton, {
  CustomDrawerFooterButtonProps,
} from '@/components/common/customDrawer/customDrawerFooterButton';
import CustomDrawerLayout from '@/components/common/customDrawer';
import CustomDrawerHeader from '@/components/common/customDrawer/customDrawerHeader';
import { Button, DatePicker, Flex, Form, Input, Select } from 'antd';
import CustomLabel from '@/components/form/customLabel/customLabel';
import { useTnaReviewStore } from '@/store/uistate/features/tna/review';
import React, { useEffect } from 'react';
import { DATE_FORMAT } from '@/utils/constants';
import CustomUpload from '@/components/form/customUpload';
import { LuPlus } from 'react-icons/lu';
import RemoveFormFieldButton from '@/components/common/formButtons/removeFormFieldButton';
import { useGetTna } from '@/store/server/features/tna/review/queries';
import { trainingNeedAssessmentCertStatusOptions } from '@/types/tna/tna';
import { MdKeyboardArrowDown } from 'react-icons/md';
import { useSetTna } from '@/store/server/features/tna/review/mutation';
import dayjs from 'dayjs';
import { formatLinkToUploadFile } from '@/helpers/formatTo';

const TnaUpdateSidebar = () => {
  const {
    isShowTnaUpdateSidebar: isShow,
    setIsShowTnaUpdateSidebar: setIsShow,
    tnaId,
    searchQuery,
    setTnaId,
  } = useTnaReviewStore();

  const { mutate: updateTna, isLoading, isSuccess } = useSetTna();

  const { data, isFetching, refetch } = useGetTna(
    {
      page: 1,
      limit: 1,
    },
    {
      filter: {
        ...(tnaId && { id: [tnaId] }),
      },
    },
    searchQuery,
    false,
    false,
  );

  const [form] = Form.useForm();

  useEffect(() => {
    if (isSuccess) {
      onClose();
    }
  }, [isSuccess]);

  useEffect(() => {
    if (tnaId) {
      refetch();
    }
  }, [tnaId]);

  useEffect(() => {
    if (tnaId && data?.items?.length) {
      const item = data.items[0];
      form.setFieldValue('title', item.title);
      form.setFieldValue(
        'completedAt',
        item.completedAt ? dayjs(item.completedAt) : null,
      );
      form.setFieldValue('certStatus', item.certStatus);
      if (item.trainingProofs?.length) {
        const attachmentValue = item.trainingProofs.map((item) => ({
          attachmentFile: item.attachmentFile
            ? [formatLinkToUploadFile(item.attachmentFile)]
            : [],
          link: item.link,
        }));
        form.setFieldValue('trainingProofs', attachmentValue);
      }
    }
  }, [data]);

  const footerModalItems: CustomDrawerFooterButtonProps[] = [
    {
      label: 'Cancel',
      key: 'cancel',
      className: 'h-12',
      size: 'large',
      loading: isFetching || isLoading,
      onClick: () => onClose(),
    },
    {
      label: 'Create',
      key: 'create',
      className: 'h-12',
      type: 'primary',
      size: 'large',
      loading: isFetching || isLoading,
      onClick: () => form.submit(),
    },
  ];

  const onFinish = () => {
    const value = form.getFieldsValue();
    const {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      trainingNeedCategory,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      trainingProofs: oldProof,
      ...otherValue
    } = data?.items[0] || {};

    const trainingProofs = value.trainingProofs?.map((item: any) => ({
      attachmentFile: item.attachmentFile?.length
        ? item.attachmentFile[0]['response']
        : null,
      link: item.link || null,
    }));

    updateTna([
      {
        ...otherValue,
        title: value.title,
        certStatus: value.certStatus,
        completedAt: value.completedAt,
        trainingProofs,
      },
    ]);
  };

  const onClose = () => {
    setTnaId(null);
    form.resetFields();
    setIsShow(false);
  };

  return (
    isShow && (
      <CustomDrawerLayout
        open={isShow}
        onClose={() => onClose()}
        data-cy="tna-review-update-drawer"
        modalHeader={
          <CustomDrawerHeader
            className="flex justify-start"
            data-cy="tna-review-update-header"
          >
            TNA Update
          </CustomDrawerHeader>
        }
        footer={
          <CustomDrawerFooterButton
            className="w-full bg-[#fff] flex justify-between space-x-5 p-4"
            buttons={footerModalItems}
            data-cy="tna-review-update-footer"
          />
        }
        width="50%"
      >
        <Form
          layout="vertical"
          form={form}
          requiredMark={CustomLabel}
          onFinish={onFinish}
          disabled={isFetching || isLoading}
          initialValues={{ trainingProofs: [{}] }}
          id="tnaReviewUpdateFormId"
          data-cy="tna-review-update-form"
        >
          <Form.Item
            name="title"
            label="TNA"
            rules={[{ required: true, message: 'Required' }]}
            className="form-item"
            id="tnaReviewUpdateTitleItemId"
            data-cy="tna-review-update-title-item"
          >
            <Input
              className="control h-10"
              id="tnaReviewUpdateTitleInputId"
              data-cy="tna-review-update-title-input"
            />
          </Form.Item>

          <Form.List
            name="trainingProofs"
            data-cy="tna-review-update-proof-list"
          >
            {(fields, { add, remove }) =>
              fields.map(({ key, name, ...restField }) => (
                <React.Fragment
                  key={key}
                  data-cy={`tna-review-update-proof-fragment-${key}`}
                >
                  <Flex
                    gap={10}
                    id={`tnaReviewUpdateProofFlex${key}Id`}
                    data-cy={`tna-review-update-proof-flex-${key}`}
                  >
                    <Form.Item
                      {...restField}
                      name={[name, 'attachmentFile']}
                      label="Attachment"
                      className="form-item flex-1"
                      valuePropName="fileList"
                      id={`tnaReviewUpdateProofItem${key}Id`}
                      data-cy={`tna-review-update-proof-item-${key}`}
                      getValueFromEvent={(e) => {
                        return Array.isArray(e) ? e : e && e.fileList;
                      }}
                    >
                      <CustomUpload
                        id="tnaUpdateCustomUploadFieldId"
                        data-cy="tna-update-custom-upload-field"
                        mode="draggable"
                        className="w-full mt-3"
                        listType="picture"
                        accept="image/*"
                        maxCount={1}
                      />
                    </Form.Item>
                    {fields.length > 1 && (
                      <RemoveFormFieldButton
                        onClick={() => {
                          remove(name);
                        }}
                        data-cy={`tna-review-update-remove-button-${key}`}
                      ></RemoveFormFieldButton>
                    )}
                  </Flex>

                  <Flex
                    gap={10}
                    align="center"
                    id={`tnaReviewUpdateLinkFlex${key}Id`}
                    data-cy={`tna-review-update-link-flex-${key}`}
                  >
                    <Form.Item
                      {...restField}
                      name={[name, 'link']}
                      label="TNA"
                      className="form-item flex-1"
                      rules={[
                        {
                          required: false,
                          type: 'url',
                          message: 'Invalid URL',
                        },
                      ]}
                      id={`tnaReviewUpdateLinkItem${key}Id`}
                      data-cy={`tna-review-update-link-item-${key}`}
                    >
                      <Input
                        id="tnaUpdateLinkUploadFieldId"
                        data-cy="tna-update-link-upload-field"
                        className="control h-10 mb-1"
                      />
                    </Form.Item>
                    <Button
                      icon={<LuPlus />}
                      size="large"
                      type="primary"
                      id="tnaUpdateSubmitLinkButtonId"
                      data-cy="tna-update-submit-link-button"
                      htmlType="button"
                      onClick={add}
                      className="mb-4 self-end h-10"
                    >
                      Add link
                    </Button>
                  </Flex>
                </React.Fragment>
              ))
            }
          </Form.List>

          <Form.Item
            name="completedAt"
            label="Completed Date"
            rules={[{ required: true, message: 'Required' }]}
            className="form-item"
            id="tnaReviewUpdateCompletedDateItemId"
            data-cy="tna-review-update-completed-date-item"
          >
            <DatePicker
              id="tnaUpdateCompletedDateFieldId"
              data-cy="tna-update-completed-date-field"
              className="control h-10"
              format={DATE_FORMAT}
            />
          </Form.Item>
          <Form.Item
            name="certStatus"
            label="Certification Status"
            rules={[{ required: true, message: 'Required' }]}
            className="form-item"
            id="tnaReviewUpdateCertStatusItemId"
            data-cy="tna-review-update-cert-status-item"
          >
            <Select
              className="control h-10"
              id="tnaUpdateCertificationStatusFieldId"
              data-cy="tna-update-certification-status-field"
              suffixIcon={
                <MdKeyboardArrowDown
                  size={16}
                  className="text-gray-900"
                  data-cy="tna-update-certification-status-field-icon"
                />
              }
              options={trainingNeedAssessmentCertStatusOptions}
            />
          </Form.Item>
        </Form>
      </CustomDrawerLayout>
    )
  );
};

export default TnaUpdateSidebar;

'use client';
import BlockWrapper from '@/components/common/blockWrapper/blockWrapper';
import { useParams, useRouter } from 'next/navigation';
import PageHeader from '@/components/common/pageHeader/pageHeader';
import { Button, Spin } from 'antd';
