                    Completed on
                  </div>
                  <div
                    className="flex-1"
                    id="tnaReviewDetailPageCompletedOnValueId"
                    data-cy="tna-review-detail-page-completed-on-value"
                  >
                    {data.items[0].completedAt
                      ? dayjs(data.items[0].completedAt).format(DATE_FORMAT)
                      : '-'}
