import { Form, Input, InputNumber, Select } from 'antd';
import CustomLabel from '@/components/form/customLabel/customLabel';
import { MdKeyboardArrowDown } from 'react-icons/md';
import { formatToOptions } from '@/helpers/formatTo';
import { useSetTna } from '@/store/server/features/tna/review/mutation';
import {
  TrainingNeedAssessmentCertStatus,
  TrainingNeedAssessmentStatus,
} from '@/types/tna/tna';
import {
  useCurrency,
  useGetTnaById,
} from '@/store/server/features/tna/review/queries';
import { useAuthenticationStore } from '@/store/uistate/features/authentication';
import { useAllApproval } from '@/store/server/features/approver/queries';
import { APPROVALTYPES } from '@/types/enumTypes';
import { useGetEmployee } from '@/store/server/features/employees/employeeDetail/queries';
import { useGetTnaCategory } from '@/store/server/features/tna/category/queries';
import Filters from '@/app/(afterLogin)/(payroll)/payroll/_components/filters';
import { useGetDepartments } from '@/store/server/features/employees/employeeManagment/department/queries';
import { AiOutlineDollarCircle } from 'react-icons/ai';
import { useGetActiveFiscalYears } from '@/store/server/features/organizationStructure/fiscalYear/queries';
import NotificationMessage from '@/components/common/notification/notificationMessage';
const { Option } = Select;

const TnaRequestSidebar = () => {
  const {
    isShowTnaReviewSidebar,
    setIsShowTnaReviewSidebar,
    monthId,
    sessionId,
    yearId,
    setSearchQuery,
    tnaId,
    tnaData,
    setData,
    setTnaId,
  } = useTnaReviewStore();
  const { userId } = useAuthenticationStore();

  const { data: employeeData } = useGetEmployee(userId);
  const { data: departmentData } = useGetDepartments();

  const { data: tnaCurrency } = useCurrency();
  const { data: tnaCategoryData } = useGetTnaCategory({});
  const {
    data: singleTnaData,
    refetch: refetchSingleTna,
    isFetching: isTnaFetching,
  } = useGetTnaById(tnaId || '');
  const { data: approvalDepartmentData, refetch: getDepartmentApproval } =
    useAllApproval(
      employeeData?.employeeJobInformation?.[0]?.departmentId || '',
      APPROVALTYPES?.TNA,
    );

  const { data: approvalUserData, refetch: getUserApproval } = useAllApproval(
    userId || '',
    APPROVALTYPES?.TNA,
  );
  const { data: fiscalYearData } = useGetActiveFiscalYears();

  useEffect(() => {
    if (employeeData?.employeeJobInformation?.[0]?.departmentId)
      getDepartmentApproval();
  }, [employeeData?.employeeJobInformation?.[0]?.departmentId]);
  useEffect(() => {
    if (userId) getUserApproval();
  }, [userId]);

  const { mutate: setTna, isLoading } = useSetTna();

  const [form] = Form.useForm();

  useEffect(() => {
    if (tnaId) {
      refetchSingleTna();
    }
  }, [tnaId]);
  useEffect(() => {
    if (singleTnaData && tnaId !== null) {
      const formData = singleTnaData;

      const formattedData = {
        title: formData.title || '',
        departmentId: formData.departmentId || undefined,
        reason: formData.reason || '',
        trainingNeedCategoryId: formData.trainingNeedCategoryId || undefined,
        currencyId: formData.currencyId || undefined,
        trainingPrice: formData.trainingPrice || undefined,
        detail: formData.detail || '',
        sessionId: formData.sessionId || undefined,
        yearId: formData.yearId || undefined,
        monthId: formData.monthId || undefined,
      };
      form.setFieldsValue(formattedData);
    } else {
      form.resetFields();
    }
  }, [singleTnaData, fiscalYearData, tnaId]);

  const onSubmit = (): void => {
    if (approvalUserData?.length < 1 && approvalDepartmentData?.length < 1) {
      NotificationMessage.warning({
        message: `You lack an assigned approver.`,
      });
      return;
    }
    form.submit();
  };

  const footerModalItems: CustomDrawerFooterButtonProps[] = [
    {
      label: 'Cancel',
      key: 'cancel',
      className: 'h-12',
      size: 'large',
      loading: isLoading || isTnaFetching,
      onClick: () => onClose(),
    },
    {
      label: 'Request',
      key: 'request',
      className: 'h-12',
      type: 'primary',
      size: 'large',
      loading: isLoading || isTnaFetching,
      onClick: () => onSubmit(),
    },
  ];

  const onFinish = () => {
    const value = form.getFieldsValue(); // Get form values

    // Merge values with monthId, yearId, and sessionId
    const finalValues = { ...value, monthId, yearId, sessionId };

    // Extract `trainingNeedCategory`, keep `otherData`
    const { ...otherData } = singleTnaData || {};

    const dataValue: any = [
      {
        ...otherData, // Retain existing data from items[0]
        ...finalValues, // Include monthId, yearId, sessionId
        certStatus: TrainingNeedAssessmentCertStatus.IN_PROGRESS,
        status: TrainingNeedAssessmentStatus.PENDING,

        assignedUserId: userId,
        approvalWorkflowId: otherData?.approvalWorkflowId
          ? otherData?.approvalWorkflowId
          : approvalUserData?.length > 0
            ? approvalUserData[0]?.id
            : approvalDepartmentData?.[0]?.id,
      },
    ];

    const filteredData = dataValue?.map((originalData: any) => ({
      approvalWorkflowId: originalData.approvalWorkflowId,
      assignedUserId: originalData.assignedUserId,
      certStatus: originalData.certStatus,
      currencyId: originalData.currencyId,
      departmentId: originalData?.departmentId,
      detail: originalData.detail,
      id: tnaId ?? undefined,
      monthId: originalData.monthId,
      reason: originalData.reason,
      sessionId: originalData.sessionId,
      status: originalData.status,
      title: originalData.title,
      trainingNeedCategoryId: originalData.trainingNeedCategoryId,
      trainingPrice: originalData?.trainingPrice,
      yearId: originalData.yearId,
      trainingProofs: [],
    }));

    setTna(filteredData, { onSuccess: () => onClose() });
  };

  const onClose = () => {
    setTnaId(null);
    setData(null);
    form.resetFields();
    setIsShowTnaReviewSidebar(false);
  };
  const handleSearch = (searchValues: any) => {
    const queryParams = new URLSearchParams();

    if (searchValues?.employeeId) {
      queryParams.append('employeeId', searchValues.employeeId);
    }
    if (searchValues?.monthId) {
      queryParams.append('monthId', searchValues.monthId);
    }

    const searchParams = queryParams.toString()
      ? `?${queryParams.toString()}`
      : '';
    setSearchQuery(searchParams);
    refetchSingleTna();
  };

  return (
    isShowTnaReviewSidebar && (
      <CustomDrawerLayout
        open={isShowTnaReviewSidebar}
        onClose={() => onClose()}
        data-cy="tna-request-sidebar-drawer"
        modalHeader={
          <CustomDrawerHeader
            className="flex justify-start"
            data-cy="tna-request-sidebar-header"
          >
            TNA Request
          </CustomDrawerHeader>
        }
        footer={
          <CustomDrawerFooterButton
            className="w-full bg-[#fff] flex justify-between space-x-5 p-4"
            buttons={footerModalItems}
            data-cy="tna-request-sidebar-footer"
          />
        }
        width="40%"
      >
        <Form
          layout="vertical"
          form={form}
          className="p-2"
          disabled={isLoading || isTnaFetching}
          onFinish={onFinish}
          requiredMark={CustomLabel}
          id="tnaRequestSidebarFormId"
          data-cy="tna-request-sidebar-form"
        >
          <Form.Item
            name="title"
            label="TNA Request Title"
            rules={[{ required: true, message: 'Required' }]}
            className="form-item"
            id="tnaRequestSidebarTitleItemId"
            data-cy="tna-request-sidebar-title-item"
          >
            <Input
              id="tnaRequestTitleFieldId"
              data-cy="tna-request-title-field"
              className="control h-10"
            />
          </Form.Item>

          <Filters
            onSearch={handleSearch}
            disable={['name', 'payPeriod']}
            defaultValues={
              tnaData
                ? {
                    yearId: tnaData?.yearId,
                    sessionId: tnaData.sessionId,
                    monthId: tnaData.monthId,
                    departmentId: tnaData.departmentId,
                  }
                : undefined
            }
            data-cy="tna-request-sidebar-filters"
          />
          <Form.Item
            name="departmentId"
            label="Department"
            className="form-item"
            id="tnaRequestSidebarDepartmentItemId"
            data-cy="tna-request-sidebar-department-item"
          >
            <Select
              placeholder="department data"
              allowClear
              style={{ width: '100%', height: '40px' }}
              id="tnaRequestSidebarDepartmentSelectId"
              data-cy="tna-request-sidebar-department-select"
            >
              {departmentData?.map((department: any) => (
                <Option
                  key={department.id}
                  value={department.id}
                  data-cy={`tna-request-sidebar-department-option-${department.id}`}
                >
                  {department?.name}
                </Option>
              ))}
            </Select>
          </Form.Item>

          <Form.Item
            name="reason"
            label="Reason"
            className="form-item"
            id="tnaRequestSidebarReasonItemId"
            data-cy="tna-request-sidebar-reason-item"
          >
            <Input
              className="control"
              id="tnaRequestSidebarReasonInputId"
              data-cy="tna-request-sidebar-reason-input"
            />
          </Form.Item>
          <Form.Item
            name="trainingNeedCategoryId"
            label="Training Category"
            className="form-item"
            rules={[{ required: true, message: 'Required' }]}
            id="tnaRequestSidebarCategoryItemId"
            data-cy="tna-request-sidebar-category-item"
          >
            <Select
              id="tnaCategoryOptionFieldId"
              data-cy="tna-category-option-field"
              className="control"
              suffixIcon={
                <MdKeyboardArrowDown
                  size={16}
                  className="text-gray-900 h-10"
                  data-cy="tna-request-sidebar-category-suffix-icon"
                  id="tnaRequestSidebarCategorySuffixIconId"
                />
              }
              placeholder="Select"
              options={formatToOptions(
                tnaCategoryData?.items ?? [],
                'name',
                'id',
              )}
            />
          </Form.Item>

          <Form.Item
            name="currencyId"
            label="Currency"
            className="form-item"
            rules={[{ required: true, message: 'Required' }]}
            id="tnaRequestSidebarCurrencyItemId"
            data-cy="tna-request-sidebar-currency-item"
          >
            <Select
              id="currencyId"
              data-cy="tna-request-sidebar-currency-select"
              className="control"
              suffixIcon={
                <MdKeyboardArrowDown
                  size={16}
                  className="text-gray-900 h-10"
                  data-cy="tna-request-sidebar-currency-suffix-icon"
                  id="tnaRequestSidebarCurrencySuffixIconId"
                />
              }
              placeholder="Select"
              options={formatToOptions(tnaCurrency, 'code', 'id')}
            />
          </Form.Item>
          <Form.Item
            name="trainingPrice"
            label="Training Price"
            rules={[{ required: true, message: 'Required' }]}
            className="form-item"
            id="tnaRequestSidebarPriceItemId"
            data-cy="tna-request-sidebar-price-item"
          >
            <InputNumber
              id="tnaTraniningPriceFieldId"
              data-cy="tna-training-price-field"
              min={0}
              suffix={<AiOutlineDollarCircle />}
              className="control-number h-10"
            />
          </Form.Item>
          <Form.Item
            name="detail"
            label="Detail Information"
            className="form-item"
            id="tnaRequestSidebarDetailItemId"
            data-cy="tna-request-sidebar-detail-item"
          >
            <Input.TextArea
              id="tnaDetailInformationFieldId"
              data-cy="tna-detail-information-field"
              className="control-tarea h-24"
              rows={6}
              placeholder="Enter brief reason for your training of choice"
            />
          </Form.Item>
        </Form>
      </CustomDrawerLayout>
    )
  );
};

export default TnaRequestSidebar;

'use client';
import React, { useEffect, useState } from 'react';
import BlockWrapper from '@/components/common/blockWrapper/blockWrapper';
import PageHeader from '@/components/common/pageHeader/pageHeader';
import { Button, DatePicker, Modal, Space, Table } from 'antd';
import { DATE_FORMAT } from '@/utils/constants';
import { LuPlus, LuSettings2 } from 'react-icons/lu';
import { TableColumnsType } from '@/types/table/table';
import dayjs from 'dayjs';
import { formatLinkToUploadFile } from '@/helpers/formatTo';
import StatusBadge from '@/components/common/statusBadge/statusBadge';
import { FiEdit2 } from 'react-icons/fi';
import ActionButton from '@/components/common/actionButton';
import { useTnaReviewStore } from '@/store/uistate/features/tna/review';
import TnaRequestSidebar from '@/app/(afterLogin)/(tna)/tna/review/_components/tnaRequestSidebar';
import { useRouter } from 'next/navigation';
import { useGetTna } from '@/store/server/features/tna/review/queries';
import usePagination from '@/utils/usePagination';
import { TnaRequestBody } from '@/store/server/features/tna/review/interface';
import {
  TrainingNeedAssessment,
  TrainingNeedAssessmentCertStatus,
  TrainingNeedAssessmentCertStatusBadgeTheme,
  TrainingNeedAssessmentStatus,
  TrainingNeedAssessmentStatusBadgeTheme,
  TrainingProof,
} from '@/types/tna/tna';
import FileButton from '@/components/common/fileButton';
import { useDeleteTna } from '@/store/server/features/tna/review/mutation';
import AccessGuard from '@/utils/permissionGuard';
import { Permissions } from '@/types/commons/permissionEnum';
import UserCard from '@/components/common/userCard/userCard';
import { useGetSimpleEmployee } from '@/store/server/features/employees/employeeDetail/queries';
import TnaApprovalTable from './_components/approvalTabel';
import Filters from '@/app/(afterLogin)/(payroll)/payroll/_components/filters';
import { useIsMobile } from '@/hooks/useIsMobile';
import useEmployeeStore from '@/store/uistate/features/payroll/employeeInfoStore';
import { CustomMobilePagination } from '@/components/customPagination/mobilePagination';
import CustomPagination from '@/components/customPagination';
import { TableSkeleton } from '@/components/tableSkeleton';
import { useNotificationDeepLink } from '@/hooks/useNotificationDeepLink';

const TnaReviewPage = () => {
  const [searchQuery, setSearchQuery] = useState('');

  const handleSearch = (searchValues: any) => {
    const queryParams = new URLSearchParams();

    if (searchValues?.sessionId) {
      queryParams.append('sessionId', searchValues.sessionId);
    }
    if (searchValues?.yearId) {
      queryParams.append('yearId', searchValues.yearId);
    }
    if (searchValues?.currencyId) {
      queryParams.append('currencyId', searchValues.currencyId);
    }
    if (searchValues?.departmentId) {
      queryParams.append('departmentId', searchValues.departmentId);
    }
    if (searchValues?.monthId) {
      queryParams.append('monthId', searchValues.monthId);
    }

    const searchParams = queryParams.toString()
      ? `?${queryParams.toString()}`
      : '';
    setSearchQuery(searchParams);
    refetch();
  };

  const EmpRender = ({ userId }: any) => {
    const {
      isLoading,
      data: employeeData,
      isError,
    } = useGetSimpleEmployee(userId);

    if (isLoading) return <div data-cy="loading-indicator">...</div>;
    if (isError) return <div data-cy="error-indicator">-</div>;
    const fullName = `${employeeData?.firstName || '-'} ${employeeData?.middleName || '-'} ${employeeData?.lastName || '-'}`;

    return employeeData ? (
      <div
        className="flex items-center gap-1.5"
        data-cy="employee-card-container"
      >
        <div className="flex-1" data-cy="employee-card-content">
          <UserCard
            data={employeeData}
            name={fullName}
            profileImage={employeeData?.profileImage}
            size="small"
          />
          <div
            data-cy="-tna-tna-review-page-tsx-page-div-93"
            className="text-[10px] leading-4 text-gray-600"
          >
            {employeeData?.email}
          </div>
        </div>
      </div>
    ) : (
      '-'
    );
  };
  const router = useRouter();
  const [tableData, setTableData] = useState<any[]>([]);
  const {
    isShowTnaReviewSidebar,
    setIsShowTnaReviewSidebar,
    setTnaId,
    setData,
    loading,
  } = useTnaReviewStore();
  const {
    page,
    limit,
    orderBy,
    orderDirection,
    setPage,
    setLimit,
    setOrderBy,
    setOrderDirection,
  } = usePagination();
  const [filter, setFilter] = useState<Partial<TnaRequestBody['filter']>>({});
  const { employeeId: linkedEmployee } = useNotificationDeepLink();

  useEffect(() => {
    if (!linkedEmployee) return;
    setFilter((prev) => ({ ...prev, assignedUserId: [linkedEmployee] }));
  }, [linkedEmployee]);
  const { data, isLoading, refetch } = useGetTna(
    { page, limit, orderBy, orderDirection },
    { filter },
    searchQuery,
  );

  const {
    mutate: deleteTna,
    isLoading: isLoadingDelete,
    isSuccess,
  } = useDeleteTna();
  const { isFilterModalOpen, setIsFilterModalOpen } = useEmployeeStore();
  const { isMobile, isTablet } = useIsMobile();

  useEffect(() => {
    if (isSuccess) {
      refetch();
    }
  }, [isSuccess]);

  useEffect(() => {
    if (!isShowTnaReviewSidebar) {
      refetch();
    }
  }, [isShowTnaReviewSidebar]);

  useEffect(() => {
    if (data?.items) {
      setTableData(
        data.items.map((item) => ({
          key: item.id,
          title: item.title,
          createdBy: item.assignedUserId,
          trainingPrice: item.trainingPrice,
          completedAt: item.completedAt,
          attachment: item.trainingProofs,
          status: item.status,
          certStatus: item.certStatus,
          action: item,
        })),
      );
    }
  }, [data]);
  <Filters onSearch={handleSearch} disable={['name', 'payPeriod']} />;
  const onTnaEdit = (item: any) => {
    setTnaId(item.id);
    setData({
      yearId: item.yearId,
      sessionId: item.sessionId,
      monthId: item.monthId,
      departmentId: item.departmentId,
    });
    setIsShowTnaReviewSidebar(true);
  };

  const tableColumns: TableColumnsType<any> = [
    {
      title: 'TNA',
      dataIndex: 'title',
      key: 'title',
      sorter: true,
      render: (text: string) => (
        <div data-cy="-tna-tna-review-page-tsx-page-div-183">{text}</div>
      ),
    },
    {
      title: 'Requested by',
      dataIndex: 'createdBy',
      key: 'createdBy',
      sorter: true,
      render: (text: string) => <EmpRender userId={text} />,
    },
    {
      title: 'price',
      dataIndex: 'trainingPrice',
      key: 'trainingPrice',
      sorter: true,
      render: (text: string) => (
        <div data-cy="-tna-tna-review-page-tsx-page-div-197">{text}</div>
      ),
    },
    {
      title: 'Completed Date',
      dataIndex: 'completedAt',
      key: 'completedAt',
      sorter: true,
      render: (date: string) => (
        <div data-cy="-tna-tna-review-page-tsx-page-div-205">
          {date ? dayjs(date).format(DATE_FORMAT) : '-'}
        </div>
      ),
    },
    {
      title: 'Attachment',
      dataIndex: 'attachment',
      key: 'attachment',
      sorter: (a, b) => {
        const nameA = a.attachment?.[0]?.attachmentFile
          ? formatLinkToUploadFile(a.attachment[0].attachmentFile).name
          : '';
        const nameB = b.attachment?.[0]?.attachmentFile
          ? formatLinkToUploadFile(b.attachment[0].attachmentFile).name
          : '';
        return nameA.localeCompare(nameB);
      },
      render: (trainingProofs: TrainingProof[]) => {
        return (
          <div data-cy="-tna-tna-review-page-tsx-page-div-223">
            {trainingProofs?.map((proof) =>
              proof.attachmentFile ? (
                <FileButton
                  key={proof.id}
                  fileName={formatLinkToUploadFile(proof.attachmentFile).name}
                  link={proof.attachmentFile}
                  className="flex-row-reverse border-0 py-0 px-0 gap-3 justify-between"
                />
              ) : (
                '-'
              ),
            )}
          </div>
        );
      },
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      sorter: true,
      render: (text: TrainingNeedAssessmentStatus) => (
        <StatusBadge theme={TrainingNeedAssessmentStatusBadgeTheme[text]}>
          {text}
        </StatusBadge>
      ),
    },
    {
      title: 'Cert-Status',
      dataIndex: 'certStatus',
      key: 'certStatus',
      sorter: true,
      render: (text: TrainingNeedAssessmentCertStatus) => (
        <StatusBadge theme={TrainingNeedAssessmentCertStatusBadgeTheme[text]}>
          {text}
        </StatusBadge>
      ),
    },
    {
      title: '',
      dataIndex: 'action',
      key: 'action',
      render: (item: TrainingNeedAssessment) => (
        <Space>
          <AccessGuard permissions={[Permissions.UpdateTna]}>
            <Button
              id={`${item.id}tnaShowTnaReviewSidebarButtonId`}
              className="w-[30px] h-[30px]"
              icon={<FiEdit2 size={16} />}
              type="primary"
              disabled={
                item.certStatus === TrainingNeedAssessmentCertStatus.COMPLETED
              }
              onClick={() => {
                onTnaEdit(item);
              }}
            />
          </AccessGuard>
          <AccessGuard
            permissions={[Permissions.UpdateTna, Permissions.DeleteTna]}
          >
            <ActionButton
              onOpen={() => {
                router.push('/tna/review/' + item.id);
              }}
              onDelete={
                item.certStatus !== TrainingNeedAssessmentCertStatus.COMPLETED
                  ? () => {
                      deleteTna([item.id]);
                    }
                  : undefined
              }
              id={item.id ?? null}
            />
          </AccessGuard>
        </Space>
      ),
    },
  ];

  const onPageChange = (page: number, pageSize?: number) => {
    setPage(page);
    if (pageSize) {
      setLimit(pageSize);
    }
  };
  const onPageSizeChange = (pageSize: number) => {
    setLimit(pageSize);
    setPage(1);
  };
  return (
    <div
      className="page-wrap bg-gray-100"
      id="tnaReviewPageId"
      data-cy="tna-review-page"
    >
      <TnaApprovalTable data-cy="tna-approval-table" />
      <BlockWrapper data-cy="tna-review-block-wrapper">
        <PageHeader title="TNA" data-cy="tna-review-page-header">
          <Space
            size={16}
            id="tnaReviewPageHeaderActionsId"
            data-cy="tna-review-page-header-actions"
          >
            <DatePicker.RangePicker
              format={DATE_FORMAT}
              separator="-"
              className="h-[54px]"
              id="tnaReviewDateRangePickerId"
              data-cy="tna-review-date-range-picker"
              onChange={(val) => {
                setFilter(
                  val && val.length >= 2
                    ? {
                        completedAt: {
                          from: val[0]!.format(),
                          to: val[1]!.format(),
                        },
                      }
                    : {},
                );
              }}
            />
            {isMobile && (
              <div
                className="flex justify-between items-center gap-4"
                id="tnaReviewMobileFiltersId"
                data-cy="tna-review-mobile-filters"
              >
                <Button
                  className="p-6 mr-2 border border-gray-300"
                  onClick={() => setIsFilterModalOpen(true)}
                  icon={<LuSettings2 size={20} />}
                  id="tnaReviewMobileFilterButtonId"
                  data-cy="tna-review-mobile-filter-button"
                />
              </div>
            )}
            <AccessGuard
              permissions={[Permissions.CreateTna]}
              data-cy="tna-review-new-button-guard"
              id="tnaReviewNewButtonGuardId"
            >
              <Button
                icon={<LuPlus size={20} />}
                className="h-[50px] w-[50px] sm:w-full"
                type="primary"
                size="large"
                id="tnaReviewNewButtonId"
                data-cy="tna-review-new-button"
                onClick={() => setIsShowTnaReviewSidebar(true)}
              >
                {!isMobile && (
                  <span data-cy="-tna-tna-review-page-tsx-page-span-376">
                    New TNA
                  </span>
                )}
              </Button>
            </AccessGuard>
          </Space>
        </PageHeader>
        {!isMobile && (
          <Filters
            onSearch={handleSearch}
            disable={['name', 'payPeriod', 'department']}
            data-cy="tna-review-filters"
          />
        )}
        {isFilterModalOpen && (
          <Modal
            title="Filters"
