function hexToRgba(hex: string, alpha: number): string {
  const h = hex.replace('#', '');
  if (h.length !== 6) return `rgba(0,0,0,${alpha})`;
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

/** Colored glow under the line (soft drop shadow), tinted per dataset. */
const lineGlowPlugin: Plugin<'line'> = {
  id: 'feedbackLineGlow',
  beforeDatasetDraw(chart, args) {
    const { ctx } = chart;
    const ds = chart.data.datasets[args.index];
    const lineColor =
      typeof ds.borderColor === 'string' ? ds.borderColor : '#1D4ED8';
    ctx.save();
    ctx.shadowColor = hexToRgba(lineColor, 0.45);
    ctx.shadowBlur = 18;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 6;
  },
  afterDatasetDraw(chart) {
    chart.ctx.restore();
  },
};

const dottedGrid = {
  display: true,
  drawOnChartArea: true,
  color: 'rgba(148, 163, 184, 0.55)',
  lineWidth: 1,
  borderDash: [4, 4],
};

const baseLineOptions: ChartOptions<'line'> = {
  responsive: true,
  maintainAspectRatio: false,
  layout: {
    padding: { top: 6, right: 12, bottom: 4, left: 6 },
  },
  interaction: {
    mode: 'index',
    intersect: false,
  },
  plugins: {
    legend: {
      position: 'bottom',
      align: 'center',
      labels: {
        color: '#374151',
        usePointStyle: true,
        boxWidth: 8,
        boxHeight: 8,
        padding: 24,
        font: {
          size: 12,
          family:
            'ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"',
        },
        generateLabels(chart) {
          const { data } = chart;
          if (!data.datasets.length) return [];
          return data.datasets.map((dataset, i) => {
            const stroke =
              typeof dataset.borderColor === 'string'
                ? dataset.borderColor
                : '#6B7280';
            return {
              text: dataset.label ?? '',
              fillStyle: stroke,
              strokeStyle: stroke,
              lineWidth: 0,
              lineDash: [] as number[],
              hidden: !chart.isDatasetVisible(i),
              index: i,
              datasetIndex: i,
              pointStyle: 'rectRounded' as const,
            };
          });
        },
      },
    },
    tooltip: {
      mode: 'index',
      intersect: false,
    },
  },
  scales: {
    x: {
      offset: true,
      grid: {
        ...dottedGrid,
      },
      border: {
        display: true,
        color: '#E5E7EB',
        dash: [4, 4],
        dashOffset: 0,
      },
      ticks: {
        color: '#6B7280',
        font: { size: 12 },
      },
    },
    y: {
      min: 0,
      ticks: {
        color: '#6B7280',
        font: { size: 12 },
      },
      grid: {
        ...dottedGrid,
      },
      border: {
        display: false,
        dash: [4, 4],
        dashOffset: 0,
      },
    },
  },
};

