          <Input.TextArea placeholder="Enter Description" />
        </Form.Item>

        <Form.Item
          className="text-lg font-bold mt-3"
          name="workflowAppliesType"
          label="Workflow Applies Type"
          rules={[
            { required: true, message: 'Please select a workflow option!' },
          ]}
        >
          <Radio.Group onChange={onRadioChange}>
            <Radio value={'Department'}>Department</Radio>
            <Radio disabled value={'Hierarchy'}>
              Hierarchy
            </Radio>
            <Radio value={'User'}>User</Radio>
          </Radio.Group>
        </Form.Item>

        <Form.Item
          className="text-lg font-bold"
          name="workflowAppliesId"
          rules={[
            {
              required: true,
              message: `Please select ${workflowApplies ? workflowApplies : ''}!`,
            },
          ]}
        >
          <Select
            className="w-full h-10 mb-1"
            allowClear
            showSearch
            optionFilterProp="label"
            style={{ width: 120 }}
            placeholder={`Select ${workflowApplies ? workflowApplies : ''} `}
            onChange={handleWorkflowUserChange}
            options={(() => {
              if (workflowApplies === 'Department') {
                return (
                  department?.map((list: Department) => ({
                    value: list.id,
                    label: list.name,
                  })) || []
                );
              } else if (workflowApplies === 'Hierarchy') {
                return (
                  HierarchyList.map((list) => ({
                    value: list.name,
                    label: list.name,
                  })) || []
                );
              } else if (workflowApplies === 'User') {
                return (
                  users?.items?.map((list: User) => ({
                    value: list.id,
                    label:
                      `${list.firstName ? list.firstName : ''} ${list.middleName ? list.middleName : ''} ${list.lastName ? list.lastName : ''}`.trim(),
                  })) || []
                );
              } else {
                return [];
              }
            })()}
          />
        </Form.Item>
        <div
          data-cy="components-approval-approvalworkflowsetting-index-tsx-index-div-212"
          className="font-medium mb-3 text-gray-500"
        >
          Select to which {workflowApplies} this workflow applies to.
        </div>
        <div
          data-cy="components-approval-approvalworkflowsetting-index-tsx-index-div-215"
          className="my-3"
        >
          <div
            data-cy="components-approval-approvalworkflowsetting-index-tsx-index-div-216"
            className="text-lg font-bold "
          >
            Number Of Level
          </div>
          <Select
            showSearch
            optionFilterProp="label"
            className="w-full h-10 m-1"
            style={{ width: 120 }}
            onChange={handleLevelChange}
            defaultValue={1}
            placeholder="Select Levels"
            options={Array.from(
              { length: 9 },
              /* eslint-disable-next-line @typescript-eslint/naming-convention */ (
                _,
                i,
              ) => ({
                value: i + 1,
                label: `${i + 1}`,
              }),
            )}
          />

          <div
            data-cy="components-approval-approvalworkflowsetting-index-tsx-index-div-237"
            className="font-medium mb-3 text-gray-500"
          >
            Select Number of specific approval stage or level within the process
          </div>
        </div>

        {Array.from({ length: level }).map(
          /* eslint-disable-next-line @typescript-eslint/naming-convention */ (
            _,
            index,
          ) => (
            <div
              data-cy="components-approval-approvalworkflowsetting-index-tsx-index-div-247"
              key={index}
              className="px-10 my-1"
            >
              <div data-cy="components-approval-approvalworkflowsetting-index-tsx-index-div-248">
                Level: {index + 1}
              </div>
              <Form.Item
                className="font-semibold text-xs"
                name={`assignedUser_${index}`}
                label={`Assign User `}
                rules={[
                  { required: true, message: 'Please select a user!' },
                  {
                    /* eslint-disable-next-line @typescript-eslint/naming-convention */
                    validator: (_, value) => {
                      /* eslint-enable @typescript-eslint/naming-convention */

                      if (
                        workflowApplies === 'User' &&
                        value === workflowUserId
                      ) {
                        return Promise.reject(
                          'Cannot select the same user as both workflow target and approver',
                        );
                      }
                      return Promise.resolve();
                    },
                  },
                ]}
              >
                <Select
                  className="w-full  my-3"
                  allowClear
                  showSearch
                  optionFilterProp="label"
                  mode={approverType === 'Parallel' ? 'multiple' : undefined}
                  style={{ width: 120 }}
                  onChange={(value) => handleUserChange(value as string, index)}
                  placeholder="Select User"
                  options={users?.items
                    ?.filter(
                      (user: User) =>
                        workflowApplies !== 'User' ||
                        user.id !== workflowUserId,
                    )
                    ?.map((list: User) => ({
                      value: list.id,
                      label:
                        `${list.firstName ? list.firstName : ''} ${list.middleName ? list.middleName : ''} ${list.lastName ? list.lastName : ''}`.trim(),
                    }))}
                />
              </Form.Item>
            </div>
          ),
        )}

        <Form.Item>
          <Row className="flex justify-center gap-3">
            <Button type="primary" htmlType="submit">
              Submit
            </Button>
          </Row>
        </Form.Item>
      </Form>
    </div>
  );
};

export default ApprovalWorkFlowSettingComponent;

'use client';

import React, { useState, useEffect } from 'react';
import { Button, Modal, Card, Space, Typography, Alert } from 'antd';
import {
  DownloadOutlined,
  CloseOutlined,
  MobileOutlined,
  DesktopOutlined,
  ShareAltOutlined,
} from '@ant-design/icons';
import { usePWA } from '@/hooks/usePWA';

const { Title, Text, Paragraph } = Typography;

interface InstallPromptProps {
  showMinimal?: boolean;
  autoShow?: boolean;
  onInstall?: () => void;
  onDismiss?: () => void;
}

export const InstallPrompt: React.FC<InstallPromptProps> = ({
  showMinimal = false,
  autoShow = true,
  onInstall,
  onDismiss,
}) => {
  const {
    isInstallable,
    isInstalled,
    installApp,
    deviceType,
    isStandalone,
    isCheckingInstallStatus,
  } = usePWA();

  const [isVisible, setIsVisible] = useState(false);
  const [isDismissed, setIsDismissed] = useState(false);

  useEffect(() => {
    const dismissed = localStorage.getItem('pwa-install-dismissed');
    if (dismissed) {
      const dismissedTime = parseInt(dismissed);
      const now = Date.now();
      // Reset dismissal after 24 hours
      if (now - dismissedTime > 24 * 60 * 60 * 1000) {
        localStorage.removeItem('pwa-install-dismissed');
        setIsDismissed(false);
      } else {
        setIsDismissed(true);
      }
    }
  }, []);

  useEffect(() => {
    if (
      autoShow &&
      isInstallable &&
      !isInstalled &&
      !isDismissed &&
      !isStandalone &&
      !isCheckingInstallStatus
    ) {
      // Show immediately to make it more visible
      const timer = setTimeout(() => {
        setIsVisible(true);
      }, 1000); // Reduced from 3000ms to 1000ms
      return () => clearTimeout(timer);
    }
  }, [
    autoShow,
    isInstallable,
    isInstalled,
    isDismissed,
    isStandalone,
    isCheckingInstallStatus,
  ]);

  const handleInstall = async () => {
