export interface CustomRadioProps {
  className?: string;
  value?: string | number | boolean;
  label: ReactNode;
  onChange?: (count: boolean) => void;
  isError?: boolean;
  initialValue?: string | number | boolean;
  disabled?: boolean;
}

const CustomRadio: FC<CustomRadioProps> = ({
  className = '',
  value,
  label,
  onChange,
  isError = false,
  initialValue = false,
  disabled = false,
}) => {
  const [isChecked, setIsChecked] = useState<boolean>();

  const radioClass = classNames(
    className,
    {
      'border-gray-200': !isError,
      'border-error': isError,
      'transition-none': disabled,
      'opacity-70': disabled,
      'hover:border-gray-200': disabled,
    },
    [
      'font-semibold',
      'text-sm',
      'text-gray-900',
      'h-[40px]',
      'rounded-lg',
      'border',
      'items-center',
      'justify-between',
      'hover:border-primary',
      'transition-colors',
      'duration-150',
      'px-[11px]',
      'cursor-pointer',
      'w-full',
      'flex-row-reverse',
      'after:content-[none]',
    ],
  );

  const handleChange = () => {
    setIsChecked((prev) => !prev);
  };

  useEffect(() => {
    setIsChecked(!!initialValue);
  }, [initialValue]);

  useEffect(() => {
    if (onChange) {
      onChange(!!isChecked);
    }
  }, [isChecked]);

  return (
    <Radio
      className={radioClass}
      checked={isChecked}
      value={value}
      disabled={disabled}
      onClick={handleChange}
    >
      <div data-cy="components-form-customradio-index-tsx-index-div-77">
