export type PayrollApprovalLevelStatus = {
  stepOrder: number;
  userId: string;
  displayUserId: string;
  status: 'Approved' | 'Rejected' | 'Pending' | 'Waiting';
};

type ApprovalRecord = {
  approverId: string;
  userId: string;
  approvedUserId?: string;
  displayUserId?: string;
  stepOrder: number;
  status: 'Approved' | 'Rejected' | 'Pending';
};

type HistoricalLog = {
  stepOrder: number;
  action: string;
  approvedUserId: string;
  approvalWorkflowId?: string;
};

function normalizeArrayResponse<T>(data: unknown): T[] {
  if (Array.isArray(data)) return data;
  if (
    data &&
    typeof data === 'object' &&
    Array.isArray((data as { items?: T[] }).items)
  ) {
    return (data as { items: T[] }).items;
  }
  return [];
}

function isApprovedAction(action?: string) {
  return String(action || '').toLowerCase() === 'approved';
}

function isRejectedAction(action?: string) {
  return String(action || '').toLowerCase() === 'rejected';
}

function resolveLevelStatus(
  approval: ApprovalRecord,
  historicalRecord?: HistoricalLog,
): PayrollApprovalLevelStatus['status'] {
  const hasHistoricalAction =
    historicalRecord &&
    (isApprovedAction(historicalRecord.action) ||
      isRejectedAction(historicalRecord.action));

  if (hasHistoricalAction) {
    return isApprovedAction(historicalRecord!.action) ? 'Approved' : 'Rejected';
  }

  const apiStatus = String(approval.status || '').toLowerCase();
  if (apiStatus === 'approved') return 'Approved';
  if (apiStatus === 'rejected') return 'Rejected';
  return 'Pending';
}

function buildMergedApprovalLevels(
  workflowApprovers: { stepOrder: number; userId: string }[],
  statusRecords: ApprovalRecord[],
  historicalLogs: HistoricalLog[],
  hasRequestStarted: boolean,
): PayrollApprovalLevelStatus[] {
  const statusByStep = new Map(
    statusRecords.map((record) => [Number(record.stepOrder), record]),
  );

  const sourceApprovers =
    workflowApprovers.length > 0
      ? workflowApprovers
      : statusRecords.map((record) => ({
          stepOrder: record.stepOrder,
          userId: record.userId,
        }));

  return [...sourceApprovers]
    .sort((a, b) => Number(a.stepOrder) - Number(b.stepOrder))
    .map((approver) => {
      const stepOrder = Number(approver.stepOrder);
      const historicalRecord = historicalLogs.find(
        (log) => Number(log.stepOrder) === stepOrder,
      );
      const statusRecord = statusByStep.get(stepOrder);
      const hasHistoricalAction =
        historicalRecord &&
        (isApprovedAction(historicalRecord.action) ||
          isRejectedAction(historicalRecord.action));

      if (hasHistoricalAction) {
        return {
          stepOrder,
          userId: approver.userId,
          displayUserId: historicalRecord!.approvedUserId,
          status: isApprovedAction(historicalRecord!.action)
            ? ('Approved' as const)
            : ('Rejected' as const),
        };
      }

      if (statusRecord) {
        return {
          stepOrder,
          userId: statusRecord.userId,
          displayUserId: statusRecord.userId,
          status: resolveLevelStatus(statusRecord, historicalRecord),
        };
      }

      return {
        stepOrder,
        userId: approver.userId,
        displayUserId: approver.userId,
        status: hasRequestStarted ? ('Pending' as const) : ('Waiting' as const),
      };
    });
}

function getUserFullName(
  users:
    | { items?: { id: string; firstName?: string; middleName?: string }[] }
    | undefined,
  userId: string,
) {
  const user = users?.items?.find((item) => item.id === userId);
  if (!user) return '';
  return `${user.firstName || ''} ${user.middleName || ''}`.trim();
}

function resolvePayrollWorkflowId(
  configuredWorkflows: { id: string }[],
  workflowFromPending?: string,
  workflowFromLogs?: string,
): string | undefined {
  if (!configuredWorkflows.length) {
    return workflowFromPending || workflowFromLogs;
  }

  const knownIds = new Set(configuredWorkflows.map((workflow) => workflow.id));

  if (workflowFromPending && knownIds.has(workflowFromPending)) {
    return workflowFromPending;
  }
  if (workflowFromLogs && knownIds.has(workflowFromLogs)) {
    return workflowFromLogs;
  }

  return configuredWorkflows[0]?.id;
}

export function usePayrollApprovalStatus(payPeriodId?: string) {
  const { data: payrollApproval, isLoading: isPayrollApprovalLoading } =
    useGetPayrollApprovalByPayPeriodId(payPeriodId);
  const { data: pendingApprovals } = useGetPendingPayrollApprovals(
    payPeriodId,
    1,
    10,
  );
  const { data: workflows, isLoading: isWorkflowLoading } = useApprovalFilter(
    100,
    1,
    '',
    '',
    '',
    APPROVALTYPES.PAYROLL,
  );
  const { data: users, isLoading: isUsersLoading } = useGetAllUsers();

  const configuredWorkflowItems = Array.isArray(workflows?.items)
    ? workflows.items
    : [];

  const pendingItem = getPendingApprovalForPeriod(
    pendingApprovals,
    payPeriodId || '',
  );
  const requestId = payrollApproval?.id as string | undefined;

  const { data: approverLog, isLoading: isLogsLoading } =
    useGetPayrollApprovalLogs(requestId);

  const historicalLogsForWorkflow =
    normalizeArrayResponse<HistoricalLog>(approverLog);
  const hasApprovalLogs = historicalLogsForWorkflow.length > 0;
  const workflowFromPending = pendingItem?.approvalWorkflowId as
    | string
    | undefined;
  const workflowFromLogs = historicalLogsForWorkflow.find(
    (log) => log.approvalWorkflowId,
  )?.approvalWorkflowId;

  const workflowId = resolvePayrollWorkflowId(
    configuredWorkflowItems,
    workflowFromPending,
    workflowFromLogs,
  );

  const configuredWorkflow = configuredWorkflowItems.find(
    (item: { id: string }) => item.id === workflowId,
  );
  const workflowApprovers = Array.isArray(configuredWorkflow?.approvers)
    ? configuredWorkflow.approvers
    : [];

  // Status API fails when logs reference a deleted workflow; logs + settings are enough.
  const shouldFetchStatus = Boolean(
    requestId && workflowId && !hasApprovalLogs,
  );

  const { data: statusData, isLoading: isStatusLoading } =
    useGetPayrollApprovalStatus(requestId, workflowId, shouldFetchStatus);

  const isFullyApproved = payrollApproval?.approved === true;

  const approvalLevels = useMemo((): PayrollApprovalLevelStatus[] => {
    const historicalLogs = normalizeArrayResponse<HistoricalLog>(approverLog);
    const statusRecords = normalizeArrayResponse<ApprovalRecord>(statusData);

    let enriched = buildMergedApprovalLevels(
      workflowApprovers,
      statusRecords,
      historicalLogs,
      Boolean(requestId),
    );

    const currentPendingStep = Number(
      pendingItem?.nextApprover?.[0]?.stepOrder || 0,
    );
    if (currentPendingStep > 1) {
      enriched = enriched.map((level) =>
        Number(level.stepOrder) < currentPendingStep &&
        level.status === 'Pending'
          ? { ...level, status: 'Approved' as const }
          : level,
      );
    }

    if (isFullyApproved && enriched.length > 0) {
      return enriched.map((level) => ({
        ...level,
        status: level.status === 'Rejected' ? 'Rejected' : 'Approved',
      }));
    }

    const firstPendingIdx = enriched.findIndex(
      (level) => level.status === 'Pending',
    );
    if (firstPendingIdx < 0) return enriched;

    return enriched.map((level, idx) => {
      if (level.status !== 'Pending') return level;
      if (idx > firstPendingIdx) {
        return { ...level, status: 'Waiting' as const };
      }
      return level;
    });
  }, [
    approverLog,
    isFullyApproved,
    pendingItem,
    requestId,
    statusData,
    workflowApprovers,
  ]);

  const getApproverName = (userId: string) => getUserFullName(users, userId);

  const isLoading =
    isPayrollApprovalLoading ||
    isWorkflowLoading ||
    isUsersLoading ||
    isLogsLoading ||
    (shouldFetchStatus && isStatusLoading);

  return {
    approvalLevels,
    isLoading,
    isFullyApproved,
    hasWorkflow: workflowApprovers.length > 0,
    getApproverName,
  };
}

import dayjs, { Dayjs } from 'dayjs';
import { BscCadence } from '@/types/bsc';

/** Cadences that support a check-in day on the Weights step */
export const KPI_CHECKIN_CADENCES = [
  BscCadence.Weekly,
  BscCadence.BiWeekly,
  BscCadence.Monthly,
] as const;

export type KpiCheckInCadence = (typeof KPI_CHECKIN_CADENCES)[number];

export type CheckInScheduleAnchor = {
  effectiveFrom?: string | Dayjs | null;
  endDate?: string | Dayjs | null;
};

export function isKpiCheckInCadence(
  value: unknown,
): value is KpiCheckInCadence {
  return (
    value === BscCadence.Weekly ||
    value === BscCadence.BiWeekly ||
    value === BscCadence.Monthly
  );
}

/** Monday = 1 … Sunday = 7 */
export const WEEKDAY_OPTIONS = [
  { value: 1, label: 'Monday' },
  { value: 2, label: 'Tuesday' },
  { value: 3, label: 'Wednesday' },
  { value: 4, label: 'Thursday' },
  { value: 5, label: 'Friday' },
  { value: 6, label: 'Saturday' },
  { value: 7, label: 'Sunday' },
];

const CADENCE_MIN_SPAN_DAYS: Record<KpiCheckInCadence, number> = {
  [BscCadence.Weekly]: 7,
  [BscCadence.BiWeekly]: 14,
  [BscCadence.Monthly]: 28,
};

/** Inclusive calendar days between effective date and end date. */
export function scorecardSpanDays(
  effectiveFrom?: string | Dayjs | null,
  endDate?: string | Dayjs | null,
): number | null {
  const start = parseDay(effectiveFrom);
  const end = parseDay(endDate);
  if (!start || !end || end.isBefore(start)) return null;
  return end.diff(start, 'day') + 1;
}

/**
 * KPI check-in cadences that fit a temporary scorecard window.
 * When `endDate` is omitted (permanent), all cadences are allowed.
 */
export function eligibleCheckInCadences(
  effectiveFrom?: string | Dayjs | null,
  endDate?: string | Dayjs | null,
): KpiCheckInCadence[] {
  const end = parseDay(endDate);
  if (!end) return [...KPI_CHECKIN_CADENCES];

  const span = scorecardSpanDays(effectiveFrom, endDate);
  if (span == null) return [];

  return KPI_CHECKIN_CADENCES.filter(
    (cadence) => span >= CADENCE_MIN_SPAN_DAYS[cadence],
  );
}

/** Restrict check-in day choices so the first check-in falls on/before `endDate`. */
export function filterCheckInDayOptions(
  cadence?: BscCadence | null,
  effectiveFrom?: string | Dayjs | null,
  endDate?: string | Dayjs | null,
) {
  const options = checkInDayOptions(cadence);
  const end = parseDay(endDate);
  if (!cadence || !end) return options;

  const start = parseDay(effectiveFrom);
  if (!start) return options;

  return options.filter((opt) => {
    const first = resolveFirstCheckInDate(cadence, opt.value, start);
    return first != null && !first.isAfter(end);
  });
}

export function checkInDayOptions(cadence?: BscCadence | null) {
  if (cadence === BscCadence.Weekly) return WEEKDAY_OPTIONS;
  if (cadence === BscCadence.BiWeekly) {
    return Array.from({ length: 14 }, (_, i) => ({
      value: i + 1,
      label: `Day ${i + 1}`,
    }));
  }
  if (cadence === BscCadence.Monthly) {
    return Array.from({ length: 31 }, (_, i) => ({
      value: i + 1,
      label: `${i + 1}`,
    }));
  }
  return [];
}

export function checkInDayLabel(
  cadence?: BscCadence | null,
  checkInDay?: number | null,
): string | null {
  if (!cadence || checkInDay == null) return null;
  const option = checkInDayOptions(cadence).find((o) => o.value === checkInDay);
  if (!option) return String(checkInDay);
  if (cadence === BscCadence.Weekly) return option.label;
  if (cadence === BscCadence.BiWeekly) return option.label;
  if (cadence === BscCadence.Monthly) return `Day ${option.label}`;
  return option.label;
}

export function cadenceLabel(cadence?: BscCadence | null): string | null {
  if (!cadence) return null;
  if (cadence === BscCadence.BiWeekly) return 'Bi-weekly';
  return cadence;
}

/** ISO weekday Mon=1 … Sun=7 */
function isoWeekday(date: Dayjs): number {
  const d = date.day();
  return d === 0 ? 7 : d;
}

function clampDayOfMonth(day: number, date: Dayjs): number {
  const last = date.daysInMonth();
  return Math.min(Math.max(day, 1), last);
}

function parseDay(value?: string | Dayjs | null): Dayjs | null {
  if (!value) return null;
  const parsed = dayjs(value).startOf('day');
  return parsed.isValid() ? parsed : null;
}

function isAfterEnd(asOf: Dayjs, endDate?: string | Dayjs | null): boolean {
  const end = parseDay(endDate);
  if (!end) return false;
  return asOf.startOf('day').isAfter(end);
}

/**
 * Bi-weekly window without anchor: 14-day blocks from 1970-01-05 (legacy).
 */
function legacyBiWeeklyDayInWindow(date: Dayjs): number {
  const epoch = dayjs('1970-01-05').startOf('day');
  const days = date.startOf('day').diff(epoch, 'day');
  const mod = ((days % 14) + 14) % 14;
  return mod + 1;
}

function anchoredBiWeeklyDayInWindow(date: Dayjs, anchor: Dayjs): number {
  const days = date.startOf('day').diff(anchor.startOf('day'), 'day');
  if (days < 0) return 0;
  return (days % 14) + 1;
}

/**
 * First calendar day a check-in opens, counting from the scorecard effective date.
 */
export function resolveFirstCheckInDate(
  cadence?: BscCadence | null,
  checkInDay?: number | null,
  effectiveFrom?: string | Dayjs | null,
): Dayjs | null {
  if (!cadence || checkInDay == null || Number.isNaN(Number(checkInDay))) {
    return null;
  }
  const effective = parseDay(effectiveFrom) || dayjs().startOf('day');
  const day = Number(checkInDay);

  if (cadence === BscCadence.Weekly) {
    const targetWeekday = Math.min(Math.max(day, 1), 7);
    let cursor = effective.startOf('day');
    for (let i = 0; i < 7; i += 1) {
      if (isoWeekday(cursor) === targetWeekday) return cursor;
      cursor = cursor.add(1, 'day');
    }
    return effective;
  }

  if (cadence === BscCadence.BiWeekly) {
    const due = Math.min(Math.max(day, 1), 14);
    return effective.add(due - 1, 'day').startOf('day');
  }

  if (cadence === BscCadence.Monthly) {
    const dueThisMonth = clampDayOfMonth(day, effective);
    if (effective.date() <= dueThisMonth) {
      return effective.date(dueThisMonth).startOf('day');
    }
    const nextMonth = effective.add(1, 'month').startOf('month');
    return nextMonth.date(clampDayOfMonth(day, nextMonth)).startOf('day');
  }

  return null;
}

export function formatCheckInDate(date?: Dayjs | null): string {
  if (!date?.isValid()) return '';
  return date.format('D MMM YYYY');
}

export function checkInSchedulePreview(
  cadence?: BscCadence | null,
  checkInDay?: number | null,
  effectiveFrom?: string | Dayjs | null,
): string | null {
  const first = resolveFirstCheckInDate(cadence, checkInDay, effectiveFrom);
  if (!first) return null;
  return `First check-in: ${formatCheckInDate(first)}`;
}

/**
 * True when the check-in window for this KPI is open on `asOf`.
 * When `anchor.effectiveFrom` is set, periods count from that date.
 */
export function isCheckInWindowOpen(
  cadence?: BscCadence | null,
  checkInDay?: number | null,
  asOf: Dayjs | Date | string = dayjs(),
  anchor?: CheckInScheduleAnchor,
): boolean {
  if (!cadence || checkInDay == null || Number.isNaN(Number(checkInDay))) {
    return true;
  }

  const day = Number(checkInDay);
  const date = dayjs(asOf).startOf('day');
  const effective = parseDay(anchor?.effectiveFrom);

  if (effective && date.isBefore(effective)) return false;
  if (isAfterEnd(date, anchor?.endDate)) return false;

  if (!effective) {
    if (cadence === BscCadence.Weekly) {
      return isoWeekday(date) >= day;
    }
    if (cadence === BscCadence.BiWeekly) {
      const today = legacyBiWeeklyDayInWindow(date);
      const due = Math.min(Math.max(day, 1), 14);
      return today >= due;
    }
    if (cadence === BscCadence.Monthly) {
      return date.date() >= clampDayOfMonth(day, date);
    }
    return true;
  }

  const first = resolveFirstCheckInDate(cadence, checkInDay, effective);
  if (!first || date.isBefore(first)) return false;

  if (cadence === BscCadence.Weekly) {
    const daysSinceFirst = date.diff(first.startOf('day'), 'day');
    const offsetInPeriod = daysSinceFirst % 7;
    return offsetInPeriod >= 0;
  }

  if (cadence === BscCadence.BiWeekly) {
    const today = anchoredBiWeeklyDayInWindow(date, effective);
    const due = Math.min(Math.max(day, 1), 14);
    return today >= due;
  }

  if (cadence === BscCadence.Monthly) {
    const due = clampDayOfMonth(day, date);
    if (date.date() < due) return false;
    const firstMonth = first.startOf('month');
    return !date.startOf('month').isBefore(firstMonth);
  }

  return true;
}

import ExcelJS from 'exceljs';
import {
  BscCadence,
  KpiImportRowInput,
  KpiImportRowResult,
  TargetLogic,
} from '@/types/bsc';
import {
  METRIC_UNIT_OPTIONS,
  normalizeMeasurementUnit,
} from '@/utils/bsc/measurementUnit';

export const KPI_IMPORT_HEADERS = [
  'Name',
  'Description',
  'Perspective',
  'Unit of Measure',
  'Weight',
  'Target Logic',
  'Default Target',
  'Cadence',
] as const;

function parseTargetLogic(raw: string): TargetLogic | null {
  const value = raw.trim().toLowerCase();
  if (!value) return TargetLogic.HigherBetter;
  if (value.includes('lower')) return TargetLogic.LowerBetter;
  if (value.includes('bound')) return TargetLogic.Bounded;
  if (value.includes('higher')) return TargetLogic.HigherBetter;
  return null;
}

function parseCadence(raw: string): BscCadence | null {
  const value = raw.trim();
  if (!value) return null;
  const match = Object.values(BscCadence).find(
    (cadence) => cadence.toLowerCase() === value.toLowerCase(),
  );
  return match ?? null;
}

function cellText(value: ExcelJS.CellValue): string {
  if (value == null) return '';
  if (typeof value === 'object' && 'text' in value) {
    return String((value as { text?: string }).text ?? '').trim();
  }
  return String(value).trim();
}

export function parseKpiImportWorksheet(
  worksheet: ExcelJS.Worksheet,
): KpiImportRowResult[] {
  const results: KpiImportRowResult[] = [];
  const headerRow = worksheet.getRow(1);
  const headers = KPI_IMPORT_HEADERS.map((header, index) => {
    const cell = cellText(headerRow.getCell(index + 1).value);
    return cell || header;
  });

  worksheet.eachRow((row, rowNumber) => {
    if (rowNumber === 1) return;
    const values = headers.map((_, index) =>
      cellText(row.getCell(index + 1).value),
    );
    if (values.every((value) => !value)) return;

    const [
      name,
      description,
      perspective,
      measurementUnitRaw,
      weightRaw,
      targetLogicRaw,
      defaultTargetRaw,
      cadenceRaw,
    ] = values;

    if (!name) {
      results.push({ row: rowNumber, error: 'Name is required' });
      return;
    }
    if (!perspective) {
      results.push({ row: rowNumber, error: 'Perspective is required' });
      return;
    }
    const measurementUnit = normalizeMeasurementUnit(measurementUnitRaw);
    if (!measurementUnit) {
      results.push({ row: rowNumber, error: 'Unit of measure is required' });
      return;
    }

    const targetLogic = parseTargetLogic(targetLogicRaw);
    if (!targetLogic) {
      results.push({
        row: rowNumber,
        error:
          'Target logic must be Higher is better, Lower is better, or Bounded',
      });
      return;
    }

    const weight = weightRaw ? Number(weightRaw) : 0;
    if (weightRaw && (!Number.isFinite(weight) || weight < 0 || weight > 100)) {
      results.push({
        row: rowNumber,
        error: 'Weight must be between 0 and 100',
      });
      return;
    }

    const defaultTarget = defaultTargetRaw ? Number(defaultTargetRaw) : null;
    if (defaultTargetRaw && !Number.isFinite(Number(defaultTarget))) {
      results.push({
        row: rowNumber,
        error: 'Default target must be a number',
      });
      return;
    }

    const cadence = cadenceRaw ? parseCadence(cadenceRaw) : null;
    if (cadenceRaw && !cadence) {
      results.push({ row: rowNumber, error: 'Invalid cadence value' });
      return;
    }

    results.push({
      row: rowNumber,
      input: {
        name: name.trim(),
        description: description?.trim() || null,
        perspective: perspective.trim(),
        measurementUnit,
        weight,
        targetLogic,
        defaultTarget,
        cadence,
      },
    });
  });

  return results;
}

export async function buildKpiImportTemplateBuffer(): Promise<ArrayBuffer> {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('KPI Import');
  worksheet.columns = KPI_IMPORT_HEADERS.map((header) => ({
    header,
    key: header,
    width: 22,
  }));
  worksheet.addRow([
    'Example KPI Name',
    'What this KPI measures',
    'Customer',
    METRIC_UNIT_OPTIONS[0].value,
    10,
    'Higher is better',
    90,
    BscCadence.Monthly,
  ]);
  return workbook.xlsx.writeBuffer();
}

export async function parseKpiImportFile(
  file: File,
): Promise<KpiImportRowResult[]> {
  const buffer = await file.arrayBuffer();
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(buffer);
  const worksheet = workbook.worksheets[0];
  if (!worksheet) return [];
  return parseKpiImportWorksheet(worksheet);
}

export type ScorecardTab =
  | 'mine'
  | 'team'
  | 'all'
  | 'results'
  | 'kpis'
  | 'bsc'
  | 'checkin';

export type ResultsScope = 'team' | 'all';

export const SCORECARD_BASE_PATH = '/bsc/my-scorecard';
export const BSC_KPI_ADMIN_BASE = '/bsc/kpi';

export type BscKpiAdminTab = 'kpis' | 'bsc';

export function bscKpiAdminHref(tab: BscKpiAdminTab = 'kpis'): string {
  if (tab === 'bsc') return `${BSC_KPI_ADMIN_BASE}/bsc`;
  return BSC_KPI_ADMIN_BASE;
}

export function parseBscKpiAdminTab(pathname: string): BscKpiAdminTab {
  if (pathname.includes(`${BSC_KPI_ADMIN_BASE}/bsc`)) return 'bsc';
  return 'kpis';
}

const SCORECARD_TABS: ScorecardTab[] = [
  'mine',
  'checkin',
  'kpis',
  'bsc',
  'results',
  'team',
  'all',
];

export function isScorecardTab(
  value: string | null | undefined,
): value is ScorecardTab {
  return SCORECARD_TABS.includes(value as ScorecardTab);
}

export function isResultsScope(
  value: string | null | undefined,
): value is ResultsScope {
  return value === 'team' || value === 'all';
}

/** Map legacy team/all tabs onto the merged Results tab. */
export function normalizeScorecardTab(tab: ScorecardTab): ScorecardTab {
  if (tab === 'team' || tab === 'all') return 'results';
  return tab;
}

export function scorecardTabHref(tab: ScorecardTab = 'mine'): string {
  const normalized = normalizeScorecardTab(tab);
  if (normalized === 'mine') return SCORECARD_BASE_PATH;
  if (tab === 'team' || tab === 'all') {
    return scorecardResultsHref(tab);
  }
  if (tab === 'kpis' || tab === 'bsc') {
    return bscKpiAdminHref(tab);
  }
  return `${SCORECARD_BASE_PATH}?tab=${normalized}`;
}

/** @deprecated Use ResultsListPreset */
export type ResultsSubView = 'overview' | 'pep-audit';

export type ResultsListPreset = 'all' | 'needs-audit';

export type ResultsPeriodFilter = 'current' | 'all';

export function scorecardResultsHref(
  scope: ResultsScope = 'team',
  /** @deprecated Results uses a unified current-period employee list */
  _listPreset?: ResultsListPreset,
  /** @deprecated Period history is on the employee detail page */
  _periodFilter?: ResultsPeriodFilter,
): string {
  void _listPreset;
  void _periodFilter;
  const params = new URLSearchParams({
    tab: 'results',
    scope,
  });
  return `${SCORECARD_BASE_PATH}?${params.toString()}`;
}

export function parseResultsListPreset(
  search: string | URLSearchParams | null | undefined,
): ResultsListPreset {
  if (!search) return 'needs-audit';
  const params =
    typeof search === 'string'
      ? new URLSearchParams(search.startsWith('?') ? search.slice(1) : search)
      : search;
  const filter = params.get('resultsFilter');
  if (filter === 'all') return 'all';
  if (filter === 'needs-audit') return 'needs-audit';
  // Legacy sub-tab URL
  if (params.get('resultsView') === 'pep-audit') return 'needs-audit';
  return 'needs-audit';
}

export function parseResultsPeriodFilter(
  search: string | URLSearchParams | null | undefined,
): ResultsPeriodFilter {
  if (!search) return 'current';
  const params =
    typeof search === 'string'
      ? new URLSearchParams(search.startsWith('?') ? search.slice(1) : search)
      : search;
  const period = params.get('resultsPeriod');
  if (period === 'all') return 'all';
  return 'current';
}

/** @deprecated Use parseResultsListPreset */
export function parseResultsSubView(
  search: string | URLSearchParams | null | undefined,
): ResultsSubView {
  return parseResultsListPreset(search) === 'needs-audit'
    ? 'pep-audit'
    : 'overview';
}

export function bscRollupHubHref(resultsScope: ResultsScope = 'all'): string {
  const params = new URLSearchParams({ resultsScope });
  return `/bsc/roll-up?${params.toString()}`;
}

export function bscRollupCompanyDetailHref(
  resultsScope: ResultsScope = 'all',
): string {
  const params = new URLSearchParams({
    resultsScope,
    view: 'company',
  });
  return `/bsc/roll-up?${params.toString()}`;
}

export function bscRollupDepartmentDetailHref(
  departmentName: string,
  resultsScope: ResultsScope = 'all',
): string {
  const params = new URLSearchParams({
    resultsScope,
    view: 'department',
    department: departmentName,
  });
  return `/bsc/roll-up?${params.toString()}`;
}

export function parseRollupView(
  search: string | URLSearchParams | null | undefined,
): 'hub' | 'company' | 'department' {
  if (!search) return 'hub';
  const params =
    typeof search === 'string'
      ? new URLSearchParams(search.startsWith('?') ? search.slice(1) : search)
      : search;
  const view = params.get('view');
  if (view === 'company') return 'company';
  if (view === 'department' || params.has('department')) return 'department';
  return 'hub';
}

export function scorecardPepAuditHref(
  userId: string,
  scorecardId: string,
  scope?: ResultsScope,
): string {
  const params = new URLSearchParams({
    scorecard: scorecardId,
    from: 'results-audit',
  });
  if (scope) params.set('scope', scope);
  return `/bsc/employees/${encodeURIComponent(userId)}/pep-audit?${params.toString()}`;
}

export function parseScorecardTab(
  search: string | URLSearchParams | null | undefined,
): ScorecardTab {
  if (!search) return 'mine';
  const params =
    typeof search === 'string'
      ? new URLSearchParams(search.startsWith('?') ? search.slice(1) : search)
      : search;
  const tab = params.get('tab');
  if (!isScorecardTab(tab)) return 'mine';
  return normalizeScorecardTab(tab);
}

export function parseResultsScope(
  search: string | URLSearchParams | null | undefined,
): ResultsScope {
  if (!search) return 'team';
  const params =
    typeof search === 'string'
      ? new URLSearchParams(search.startsWith('?') ? search.slice(1) : search)
      : search;

  const legacyTab = params.get('tab');
  if (legacyTab === 'team' || legacyTab === 'all') return legacyTab;

  const resultsScope = params.get('resultsScope');
  if (isResultsScope(resultsScope)) return resultsScope;

  const scope = params.get('scope');
  return isResultsScope(scope) ? scope : 'all';
}

/** Split a menu key that may include `?tab=`. */
export function splitMenuKey(key: string): {
  path: string;
  tab: ScorecardTab | null;
} {
  const qIndex = key.indexOf('?');
  if (qIndex === -1) {
    return { path: key, tab: null };
  }
  const path = key.slice(0, qIndex);
  const tab = parseScorecardTab(key.slice(qIndex + 1));
  // Explicit ?tab=mine still counts as mine; path-only keys use tab: null for matching.
  const params = new URLSearchParams(key.slice(qIndex + 1));
  return {
    path,
    tab: params.has('tab') ? tab : null,
  };
}

/**
 * Score how well a menu key matches the current location.
 * Higher is better; negative means no match.
 */
export function menuKeyMatchScore(
  key: string,
  pathname: string,
  search: string,
): number {
  const { path, tab: keyTab } = splitMenuKey(key);
  if (pathname !== path) return -1;

  const currentTab = parseScorecardTab(search);

  if (keyTab) {
    return keyTab === currentTab ? 3 : -1;
  }

  // Path-only "My Scorecard" covers its in-page tabs.
  if (path === SCORECARD_BASE_PATH) {
    return currentTab === 'mine' ||
      currentTab === 'checkin' ||
      currentTab === 'results'
      ? 2
      : -1;
  }

  if (path === BSC_KPI_ADMIN_BASE) {
    return pathname === BSC_KPI_ADMIN_BASE ||
      pathname.startsWith(`${BSC_KPI_ADMIN_BASE}/`)
      ? 2
      : -1;
  }

  return 1;
}

/** Open/active evaluation cycles represent the current reporting cadence. */
export function isCurrentReportingScorecard(
  scorecard: { cycleId: string },
  cycleById?: Map<string, { isActive?: boolean; status?: string }>,
): boolean {
  const cycle = cycleById?.get(scorecard.cycleId);
  if (!cycle) return scorecard.cycleId === 'config-seed-current';
  return cycle.status === 'Open' && cycle.isActive !== false;
}

/** BSC template / program name (e.g. Enterprise Non-Financial Scorecard). */
export function resolveScorecardTemplateName(
  scorecard: { cycleId: string; cycleLabel: string },
  cycleById?: Map<string, { label: string }>,
): string {
  const fromCycle = cycleById?.get(scorecard.cycleId)?.label?.trim();
  if (fromCycle) return fromCycle;
  const fallback = (scorecard.cycleLabel || '')
    .replace(/\s*\([^)]*\)\s*$/, '')
    .trim();
  return fallback || '—';
}
